// [src, qnum, topic, hasImage, stem, options[], answerIndex, explanation]
const Q = [];
function q(src,n,t,img,stem,opts,ans,exp){Q.push({src,n,t,img,stem,opts,ans,exp});}

// ===== DOMAIN 1 — TTE & TEE ECHOCARDIOGRAPHY =====
// 1.1 Views & acquisition
q('Practice',4,'views',0,"A 67-year-old woman in the ICU has dyspnea, leg edema and elevated transaminases. Supine TTE fails to give a quality apical 4-chamber view to assess the tricuspid and mitral valves. Which position change may allow a quality apical 4-chamber view?",["Reverse Trendelenburg","Right lateral decubitus","Knees up","Trendelenburg","Left lateral decubitus"],4,"Left lateral decubitus brings the cardiac apex closer to the chest wall and often dramatically improves the A4C. Probe indicator toward the patient's left (3 o'clock) at the apex in the inframammary crease; all four chambers with the apex at the top of the screen.");
q('Practice',28,'views',1,"What probe manipulation is needed to get from this image to a standard parasternal long-axis image?",["Rock the tail to the patient's left","Slide the probe down one intercostal space","Tilt the tail down","Rotate the probe 90° counter-clockwise"],2,"The RV inflow view is obtained from the PLAX window by tilting (fanning) the tail up to image the inferior heart. Reverse it — tilt the tail down — to return to PLAX. The other moves produce non-standard views.");
q('Practice',30,'views',0,"The recommended method for aortic root measurement is from:",["Leading edge to leading edge in end-systole","Leading edge to leading edge in end-diastole","Inner edge to inner edge in end-diastole","The best visualized interface from the perpendicular long axis"],1,"ASE standard (since 1978): leading edge to leading edge, end-diastole, perpendicular to the aortic long axis; normal values were built on this. End-systole is less reproducible; inner-edge is the CT/MRI convention.");
q('Practice',36,'views',0,"A 48-year-old cyclist has acute severe MR from a flail posterior leaflet with ruptured chord, anteriorly directed jet and asymmetric (right > left) pulmonary edema. From the apical 4-chamber view, which probe movement visualizes the LVOT?",["Tilting the probe down","Rotating counterclockwise 60°","Sliding the probe laterally","Rocking toward the patient's left","Tilting the probe up"],0,"From A4C, tilt the probe down (drop the tail) to aim anteriorly and get the A5C with the LVOT/aortic valve — good alignment for PW LVOT VTI. Counterclockwise 60° gives A2C. Tilting up aims inferiorly (coronary sinus). Note: the anteriorly directed jet of a posterior flail causes asymmetric (often right-sided) edema.");
q('Practice',52,'views',0,"A woman deteriorates after tight ventral hernia repair; TEE shows a dilated, pressure-overloaded RV with systolic septal shift into the LV and severe TR. Acute PE is suspected. Which TEE view would visualize a saddle pulmonary embolus?",["Upper esophageal main pulmonary artery view","RV inflow–outflow view","Midesophageal bicaval view","Deep transgastric view of the aorta"],0,"From the ME AV short-axis view, withdraw the probe (0–30°) to the ME ascending aortic short-axis view, which shows the main PA, its bifurcation and proximal RPA — where a saddle embolus sits; the UE aortic arch short-axis view also shows the PA/pulmonic valve. Bicaval and RV inflow–outflow views show RA/RV clot only.");
q('Practice',101,'views',0,"A 40-year-old woman has rheumatic aortic and mitral stenosis. Which TEE view is most likely to record the highest maximum aortic valve velocity?",["ME at 45°","ME at 105°","Deep transgastric five-chamber view","High esophageal view above the blind spot","Transgastric view just above mitral short axis"],2,"Only the deep transgastric (and transgastric long-axis) view aligns the CW Doppler cursor parallel to aortic outflow. ME views are near-perpendicular and underestimate velocity.");
q('Practice',123,'views',0,"A ventilated man in septic shock is 2 weeks post Ivor-Lewis esophagectomy with a documented anastomotic leak; blood cultures are positive and endocarditis is suspected. What is an absolute contraindication to TEE?",["Septic shock","Recent esophageal surgery","Positive blood cultures","Respiratory failure"],1,"Recent esophageal surgery (and esophageal stricture, TE fistula, esophageal trauma) are absolute contraindications. Use TTE instead (~75% sensitivity for endocarditis vs ~90% TEE); then cardiac CT/MRI or FDG-PET/CT if needed.");
q('Practice',151,'views',0,"Which view demonstrates the posterior tricuspid leaflet?",["A4C RV-focused view","PSAX at aortic valve level","Parasternal RV inflow view","Subcostal 4-chamber view"],2,"The parasternal RV inflow view is the only RV inflow view that shows the posterior TV leaflet (anterior + posterior). A4C/subcostal show septal + anterior (or posterior, variably); PSAX AV level shows septal/anterior.");
q('Practice',155,'views',1,"A clinician places the transducer on the PMI at the inferior margin of the pectoral muscle in a supine patient and gets this image. How can she improve the orientation for an apical 4-chamber view?",["Slide medially in the same space","Move down a rib space","Tilt the tail down","Rotate 60° counter-clockwise"],2,"The apex is seen but the base (LA) is not, so the problem is beam angle, not window. Tilt the tail down to bring the base in. RV apex at top means the probe is already too medial — sliding medially worsens it. Rotating CCW 60° gives a foreshortened A2C.");
q('Post-test',3,'views',0,"The IVC distensibility index can be used to assess intravascular volume status. It is best assessed via which TTE view?",["Apical 4-chamber","LV outflow","RV outflow","Subcostal","Suprasternal"],3,"Subcostal long-axis IVC, measured 1–2 cm from the RA junction (just caudal to the hepatic vein inflow), in 2D or M-mode. Distensibility (passively ventilated) = (Dmax − Dmin)/Dmin; collapsibility (spontaneous breathing) = (Dmax − Dmin)/Dmax.");

// 1.2 LV systolic function & wall motion
q('Practice',5,'lv',1,"A 30-year-old with multiple rib fractures has persistent hypotension after an MVC. An echo is ordered for possible blunt cardiac injury (shown). Which is true?",["Echo should be performed on all blunt chest trauma patients","Blunt cardiac injuries usually involve the LV","This echo does not explain her hypotension","Blunt cardiac injury usually resolves without additional treatment"],3,"Screen BCI with ECG + troponin (EAST); if both negative, no further testing. Echo if abnormal ECG plus new murmur, arrhythmia, HF or persistent shock. The RV is most often injured (anterior). LV dysfunction can explain shock. Most BCI = self-limited wall motion abnormalities; new valve lesions usually need surgery.");
q('Practice',9,'lv',0,"Which echo view assesses all three coronary artery territories?",["Basal PSAX","Distal PSAX","Apical 3-chamber","Apical 2-chamber","Suprasternal 'spider' view"],0,"Mid/basal PSAX shows all six circumferential segments: anterior/anteroseptal (LAD), anterolateral (LAD/LCx), inferolateral (LCx/RCA), inferior and inferoseptal (RCA). Distal (apical) SAX misses RCA. A3C = LAD + LCx. A2C = LAD + RCA (misses LCx). Spider view = pulmonary veins.");
q('Practice',11,'lv',1,"A 72-year-old woman presents in septic shock and receives IV fluid and vasopressors. Based on the echo shown, which etiology of this finding can be ruled out?",["Septic shock","Acute emotional trauma","IV albumin administration","MAOI antidepressants","IV norepinephrine"],2,"Apical ballooning with basal hyperkinesis = Takotsubo. Triggers: emotional/physical stress, sepsis, catecholamines (exogenous norepinephrine), tyramine crisis with MAOIs. Not albumin. Diagnosis requires excluding obstructive CAD.");
q('Practice',17,'lv',1,"The arrow in the video shown points to which segment of the left ventricle?",["Apical anterolateral","Apical lateral","Apical septum","Apical inferior"],1,"In the 17-segment model, the apical level has 4 segments: anterior, septal, inferior, lateral. In A4C the apical segments seen are apical septal and apical lateral (the basal/mid lateral wall is called anterolateral).");
q('Practice',19,'lv',1,"A 48-year-old in respiratory distress with pulmonary and leg edema (image shown). Which finding would still allow EPSS to be a useful surrogate of ventricular function?",["Mitral stenosis","Aortic regurgitation","Dilated cardiomyopathy","Segmental wall motion abnormality"],2,"EPSS <5 mm normal, >7 mm = reduced LV systolic function — valid in global dysfunction (DCM). MS restricts leaflet opening and AR jets push the anterior leaflet (both falsely raise EPSS). With segmental WMA any 1-D measure (EPSS, FS) misrepresents global function.");
q('Practice',27,'lv',1,"A 66-year-old woman recently in Mexico felt ill for a week, then became unresponsive with a thready pulse, was intubated and arrested in the ED; ROSC was obtained. Based on the images, most likely cause of her arrest?",["Pulmonary embolism","Septic cardiomyopathy","Takotsubo","Myocardial infarction","Acute-on-chronic pulmonary hypertension"],3,"Regional (coronary-pattern) akinesis plus a post-infarct VSD = MI with mechanical complication. Pattern doesn't fit Takotsubo or sepsis; mild RV dilation + VSD + RWMA doesn't fit acute-on-chronic PH; no clot in transit.");
q('Practice',47,'lv',1,"A 74-year-old ventilated man after partial colectomy for ischemic colitis needs escalating pressors and doesn't respond to volume. Based on the image shown, how is LV systolic function best described?",["Normal","Moderately dysfunctional","Severely dysfunctional","Hyperdynamic","Akinetic"],2,"Visual EF estimation correlates well with quantitative EF with training. Grade as normal, moderately reduced, severely reduced, hyperdynamic. Look at endocardial excursion, wall thickening, mitral annular excursion toward the apex, and LV size/geometry across all views.");
q('Practice',61,'lv',1,"A 75-year-old woman is transferred to the ICU in shock after an emergent angiogram showed normal coronary arteries. Which option best explains her shock?",["Severe LV systolic dysfunction","Severe RV systolic dysfunction","Tamponade","Functional (dynamic) LV outflow obstruction","Free wall rupture"],3,"Takotsubo + sigmoid septum: hyperkinetic base narrows the LVOT → SAM and dynamic LVOTO → severe hypotension. EF is only mildly–moderately reduced. Treat with fluids, beta-blocker, phenylephrine; reduce/stop inotropes. (RA 'inversion' shown was normal atrial systole.)");
q('Practice',78,'lv',1,"A 38-year-old previously healthy woman in septic shock from UTI receives fluids and norepinephrine. Based on the echo, which is true?",["Elevated troponin is specific for CAD","ST elevation is specific for CAD","Persistent RWMA at 24 h is specific for CAD","Cath is indicated with no other data","RWMA can result purely from septic cardiomyopathy"],4,"Septic cardiomyopathy is common (~1/3 have reduced EF; more have other LV dysfunction). RWMA, troponin, BNP and ST elevation are not specific; abnormalities can persist for days.");
q('Practice',84,'lv',1,"A 72-year-old with cardiomyopathy, worsening edema, paracentesis every 2 weeks, midodrine for hypotension, creatinine 1.7: echo shows restrictive filling (E/e' 28). Based on the images, most likely cause of the cardiomyopathy?",["HOCM","Cardiac amyloidosis","Hypertensive cardiomyopathy","Athlete's heart"],1,"Amyloid: severely reduced GLS with apical sparing ('cherry on top' bullseye); diastolic dysfunction in essentially all. HCM: worst strain in the hypertrophied septum, high septal/posterior ratio. Athlete's heart: normal diastology. Hypertensive: GLS not severely reduced.");
q('Practice',93,'lv',1,"Based on the echocardiographic findings shown, which coronary artery would most likely be abnormal at catheterization?",["Left main","LAD","LCx","RCA"],1,"Anterior + anteroseptal + apex = LAD territory. Lateral (LCx) and inferior (RCA) preserved. Left main would also involve the lateral wall.");
q('Practice',110,'lv',1,"A 48-year-old cocaine user with 3 days of severe chest pain and dyspnea has ST depression in V1\u20133 and raised troponin. Urgent echo images are shown. Most appropriate next step?",["Protein C/S and ID consult","Urgent cardiology consultation","Urgent chest CT","Inotropes","Aggressive IV fluids"],1,"ST depression in V1–3 + inferolateral WMA = posterior MI (STEMI equivalent) → urgent angiography.");
q('Practice',122,'lv',0,"Which wall motion finding is most consistent with an OLD myocardial infarction?",["Basal inferior hypokinesis in A2C","Basal inferoseptal hypokinesis in A4C","Distal septal, anterior, lateral, inferior akinesis in A4C","Basal and mid inferolateral thinning and akinesis in PLAX","Global LV thinning with severely reduced EF"],3,"Wall thinning + akinesis in a coronary distribution (LCx: inferolateral) = old infarct. Mild basal inferior/inferoseptal hypokinesis can be normal variation. Circumferential apical akinesis = Takotsubo (non-coronary). Global thinning = any DCM.");
q('Practice',130,'lv',1,"A 65-year-old woman 48 h after thrombolysed anterior MI has syncope, acute hypotension and sinus tachycardia. Her echo is shown. Most likely diagnosis?",["Ventricular septal rupture","Papillary muscle rupture","Acute pericardial irritation from thrombolysis","Rupture of the ventricular free wall"],3,"Sudden hypotension/syncope days after a thrombolysed MI with new effusion = free wall rupture (risk higher with lysis than primary PCI). VSR/papillary rupture present with a new murmur and pulmonary edema.");
q('Practice',134,'valve',1,"In this patient with shock and hypoxemia during hemodialysis, which M-mode finding is demonstrated?",["Normal mitral valve","Mitral stenosis","Mitral valve prolapse","Systolic anterior motion","Subaortic membrane"],3,"M-mode through the mitral valve shows the anterior leaflet moving toward the septum in systole = SAM → dynamic LVOTO, provoked by hypovolemia (dialysis). Treat with IV fluid, an alpha agonist, possibly a beta-blocker; avoid inotropes.");
q('Post-test',18,'phys',1,"A 59-year-old ventilated for viral pneumonia has bedside echo to estimate function. This image is obtained to measure E-point septal separation. Which imaging modality is used?",["B-mode","M-mode","A-mode","Pulsed-wave Doppler","Continuous-wave Doppler"],1,"M-mode = single scan line over time → highest temporal resolution. Used for EPSS, TAPSE, RV free-wall collapse in tamponade, diaphragm excursion, IVC, and lung (seashore/barcode). B-mode = 2D; A-mode obsolete; PW/CW are Doppler.");

// 1.3 Diastolic function
q('Practice',22,'dia',0,"Which patient allows assessment of LV diastolic function with reasonable accuracy?",["78-year-old with new atrial fibrillation","ESRD with severe mitral annular calcification","SAM with septum 20 mm (HCM)","Recently diagnosed amyloidosis, EF 35%","Heart transplant recipient"],3,"Diastolic assessment is limited in AF, severe MAC, HCM, transplant (and significant MR, MS, prosthetic MV, LBBB/paced). Restrictive cardiomyopathies such as amyloid are actually followed by serial diastolic Doppler parameters.");
q('Practice',26,'dia',0,"A ventilated ESRD patient in septic shock on high-dose pressors has pulmonary edema on CXR. How can echo determine whether the edema is cardiogenic, or whether more volume is safe?",["CVP from IVC collapsibility","Stroke volume from LVOT VTI","Mean PAP from RV acceleration time","Tissue Doppler + PW at the mitral valve for E/e'"],3,"E/e' estimates LAP: E is load-dependent, e' relatively load-independent. Average E/e' <8 suggests normal LAP; >14 suggests elevated LAP → cardiogenic contribution.");
q('Practice',31,'dia',1,"Which of the following is the most likely diagnosis?",["Normal","Impaired relaxation","Pseudo-normal","Restrictive","Indeterminate"],2,"E/A looks normal but low e' unmasks raised filling pressures = pseudonormal (grade II). Tissue Doppler separates normal from pseudonormal.");
q('Practice',44,'dia',0,"The E wave on mitral inflow signifies:",["Isovolumetric relaxation","Rapid (early) filling","Diastasis","Atrial contraction"],1,"E = early passive rapid filling (~80% of filling normally). A = atrial contraction. Diastasis lies between them; IVRT precedes E.");
q('Practice',48,'dia',0,"Per the 2016 ASE/EACVI guideline, which is NOT a recommended threshold for identifying diastolic dysfunction with normal EF?",["Septal e' < 7 cm/s","Peak TR velocity > 2.8 m/s","LA volume index > 34 mL/m²","Average E/e' > 14","E/A < 1"],4,"The four variables: (1) e' septal <7 or lateral <10 cm/s, (2) average E/e' >14 (lateral >13, septal >15 if only one), (3) LAVI >34 mL/m², (4) TR Vmax >2.8 m/s. >50% abnormal = diastolic dysfunction; 50% = indeterminate.");
q('Practice',69,'dia',1,"A 55-year-old man has mitral early inflow velocity of 100 cm/s. What can be inferred from this tissue Doppler image?",["Normal systolic, normal diastolic","Normal systolic, abnormal diastolic","Abnormal systolic, normal diastolic","Abnormal systolic, abnormal diastolic"],3,"s' septal <8 / lateral <10 cm/s implies reduced systolic function (Sm <7 ≈ EF <45%). E/e' far above 20 means high filling pressures. Caveat: s' can be inflated by translation/tethering.");
q('Practice',79,'dia',0,"Besides mitral E and A, which parameters are most important for LV diastolic function and LAP estimation (ASE)?",["DT; pulmonary vein S/D; hepatic veins","Mitral annular e'; max TR velocity; LAVI","GLS; RVSP; Valsalva","e'; LV mass index; RVSP","e' and a'; PV S/D; LAVI"],1,"The ASE algorithm uses mitral E/A, average e' (→E/e'), TR Vmax and LAVI.");
q('Practice',103,'dia',1,"Which of the following is the most likely diagnosis?",["Normal","Impaired relaxation","Pseudo-normal","Restrictive","Indeterminate"],4,"Without tissue velocities, normal cannot be distinguished from pseudonormal → indeterminate.");
q('Practice',107,'dia',0,"A 70-year-old with hypertension, intubated: EF 50%, LAVI 36 mL/m², septal e' 5 cm/s, anterior B-lines. Which finding would confirm diastolic dysfunction?",["TR velocity 3 m/s","E/A 0.7","Average E/e' 10","Lateral e' 11 cm/s"],0,"Two of four criteria are abnormal (LAVI >34, septal e' <7) = indeterminate. A third abnormal (TR >2.8 m/s) makes >50% abnormal → diastolic dysfunction. E/A alone is not a criterion; E/e' 10 and lateral e' 11 are normal.");
q('Practice',154,'dia',1,"Which of the following is the most likely diagnosis?",["Normal","Impaired relaxation","Pseudo-normal","Restrictive","Indeterminate"],1,"E/A ≤0.8 with E ≤50 cm/s = impaired relaxation (grade I) regardless of tissue velocities — LAP normal/low.");
q('Post-test',15,'dia',1,"The Doppler pattern of mitral inflow represents:",["Normal","Impaired relaxation","Pseudonormal","Restrictive"],1,"Reversed E/A with long DT = impaired relaxation (grade I). Restrictive = E/A ≥2 with short DT; pseudonormal needs low e' to identify.");
q('Practice',163,'dia',0,"Which is most consistent with restrictive cardiomyopathy?",["Respirophasic septal shift","Pericardial thickening","Marked reduction in medial mitral e'","Mitral inflow E < A"],2,"Restriction = myocardial disease → low e' (<7 cm/s), no annulus reversus, E >> A with short DT. Septal shift, pericardial thickening and high/preserved medial e' point to constriction.");
// 1.4 RV & pulmonary pressures
q('Practice',20,'rv',1,"Right atrial pressure is 15 mm Hg. What is the estimated systolic PA pressure from the TR interrogations shown?",["50 mm Hg","55 mm Hg","60 mm Hg","69 mm Hg"],3,"Use the highest TR gradient (best alignment): 54 + RAP 15 = 69 mm Hg (normal <35–40).");
q('Practice',34,'rv',1,"This echo is from a 50-year-old woman with dyspnea. How is the RV size characterized?",["Normal","Mildly enlarged","Moderately enlarged","Severely enlarged"],3,"RV:LV EDA >1 = severe enlargement (normal <0.6). Basal RV diameter > 41 mm (ASE/EACVI 2015) is another threshold. Off-axis views can distort size, but a normal RV should never exceed the LV.");
q('Practice',54,'rv',0,"Which statement about echo in evaluation of pulmonary embolism is true?",["Absence of acute cor pulmonale effectively rules out PE as the cause of shock or arrest","In stable patients with Wells >6, TTE should precede CTA","RV/LV EDA >1 plus positive D-dimer is highly sensitive and specific","There is no role for echo in PE"],0,"Echo cannot diagnose or exclude PE, but a PE big enough to cause shock/arrest almost always produces acute cor pulmonale; its absence excludes PE as the cause of shock. Stable high-probability patients → CTA. RV/LV ratio is not a diagnostic test.");
q('Practice',55,'rv',1,"A woman with new scleroderma is hypoxemic and hypotensive after laparotomy; mid-papillary SAX shows a severely enlarged RV relative to the LV. Most likely to help acutely?",["High-dose epinephrine + VA-ECMO consult","IV thrombolysis","Inhaled prostaglandin","Enteral sildenafil","Blood transfusion"],2,"Acute RV failure of unclear (likely pulmonary vascular) cause: optimize RV preload/afterload/contractility — inotropes plus inhaled pulmonary vasodilators (epoprostenol, NO). Lysis only for PE; sildenafil is long-acting and drops SVR; VA-ECMO for refractory cases.");
q('Practice',74,'rv',1,"A 50-year-old with H1N1 ARDS on PEEP 15 and plateau 30 becomes hemodynamically unstable. Which is the most likely explanation for the RV dysfunction shown?",["Volume overload","RV infarction","Acute cor pulmonale from excessive RV afterload","Saddle PE","Tricuspid endocarditis"],2,"ARDS raises PVR (hypoxic/hypercapnic vasoconstriction, high driving pressure); ACP in 22–50%. Pressure overload = septal flattening in systole; volume overload = flattening in diastole.");
q('Practice',82,'rv',1,"A patient with influenza and superimposed MSSA pneumonia has worsening oxygenation with increased PEEP. Echo is shown. Which is the LEAST likely reason for the acute worsening?",["Intracardiac shunt","Lung overdistension","Worsening RV failure","Acute PE","Pneumothorax"],3,"Raising PEEP can overdistend lung (V/Q mismatch), raise RV afterload (ACP), open a PFO (right-to-left shunt) or cause barotrauma. Acute PE is unrelated to the PEEP change.");
q('Practice',87,'rv',1,"This M-mode interrogation demonstrates:",["Poor LV function","Normal LV function","Poor RV function","Normal RV function"],3,"M-mode through the lateral TV annulus = TAPSE. TAPSE ≥17 mm = normal RV longitudinal function.");
q('Practice',89,'rv',0,"A patient with pulmonary hypertension in shock has poor vascular access. Short of a PA catheter, how can PA systolic pressure be determined with the TTE probe?",["PW in the main PA","PW in the hepatic veins","E/e'","Tricuspid regurgitation velocity"],3,"RVSP = 4(V_TR)² + RAP (CW Doppler). Without pulmonic stenosis/RVOT obstruction, RVSP = PASP. E.g. V 3 m/s, RAP 4 → 40 mm Hg.");
q('Practice',104,'rv',0,"What is the threshold for normal RV s' (tricuspid annular tissue Doppler)?",["1.6 cm/s","4 cm/s","8 cm/s","10 cm/s"],3,"RV s' <10 cm/s = RV systolic dysfunction (ASE 2010 used 10; 2015 chamber update uses 9.5). Other RV cutoffs: TAPSE <17 mm, FAC <35%.");
q('Practice',109,'rv',0,"With an excellent TR jet, which patient gives the best PASP estimate using CVP from IVC size and sniff collapse?",["55-year-old with cerebral salt wasting, spontaneously breathing","ARDS on neuromuscular blockade","Asthmatic on NIV","84-year-old with tricuspid stenosis, spontaneously breathing"],0,"IVC-based RAP estimation is validated in spontaneous breathing without positive pressure. Positive-pressure ventilation (invasive or NIV) invalidates it; tricuspid stenosis means RAP ≠ RV diastolic pressure.");
q('Practice',126,'rv',0,"Suspected PH: septal flattening in systole and diastole; IVC 2.5 cm, <50% collapse with sniff; TR Vmax 300 cm/s. Estimated PASP?",["12 mm Hg","30 mm Hg","36 mm Hg","51 mm Hg"],3,"4(3)² = 36 + RAP. IVC > 2.1 cm with < 50% sniff collapse → RAP 15 (range 10–20) → PASP ≈ 51 mm Hg. RAP rules (ASE 2010): IVC ≤ 2.1 + > 50% collapse → 3; > 2.1 + < 50% → 15; mixed → 8.");
q('Practice',138,'rv',1,"An ICU resident's LV short-axis video is shown. Which is responsible for the septal wall motion pattern?",["Normal","LBBB","RV volume overload","RV pressure overload","Coronary disease"],2,"Diastolic septal flattening = RV volume overload (here severe pulmonary regurgitation). Systolic flattening = pressure overload. Chronic disease often flattens throughout the cycle. Severe AR or systemic hypertension can mask the finding.");
q('Practice',148,'rv',1,"A 33-year-old with prior chemo-radiation had a mechanical AVR with annular enlargement for a very small annulus. After VT arrest she is in shock for 10 h (lactate 8) with new bradycardia and inferior ST elevation. Baseline and current images shown. Most likely cause of shock?",["RV ischemia","ACP from high PEEP","ACP from PE","Acute-on-chronic RV failure","LV failure"],0,"Inferior STE + bradycardia + new RV dysfunction without dilation = RCA ischemia (here from annular enlargement/technical issue; treated with RCA stent). No clot, no high PEEP, no chronic RV disease.");
q('Practice',149,'rv',0,"A woman 1 week after a tibial fracture has positive D-dimer. Which echo finding is most consistent with acute PE?",["PAAT 50 ms, TR 3.0 m/s","PAAT 45 ms, TR 4.6 m/s","PAAT 110 ms, TR 2.1 m/s","PAAT 90 ms, TR 4.1 m/s"],0,"60/60 sign: PA acceleration time <60 ms with TR gradient 30–60 mm Hg (TR 3.0 m/s = 36). Gradient >60 (TR >3.9 m/s) suggests chronic disease — a normal RV cannot acutely generate >60 mm Hg.");
q('Practice',152,'rv',0,"After calculating systolic PAP, which structure must be visualized on TTE to determine PA diastolic pressure?",["Mitral valve","Pulmonic valve","Tricuspid valve","Main PA"],1,"PADP = 4(PR end-diastolic velocity)² + RAP, using CW across the pulmonic valve. E.g. 2 m/s → 16 + 4 = 20 mm Hg.");
q('Practice',153,'rv',1,"Two days after an uncomplicated heart transplant, a 65-year-old has oliguria and hypotension despite rising norepinephrine: HR 100, MAP 52, CVP 26, PAP 30/18, SvO2 45%. Most likely:",["RV dysfunction","Dilated LV","Aortic incompetence","Thrombosed pulmonary vein","AV asynchrony"],0,"Primary graft dysfunction, usually RV (ischemic preservation plus recipient's high PVR): high CVP, low output, paradoxically low/normal PA pressure, leftward septal shift, TR.");
q('Practice',160,'rv',1,"The 68-year-old smoker (BP 78/48, HR 110, SpO2 88%) loses pulses; the video was obtained before the arrest. Which is visualized?",["Severely dilated RV","Underfilled LV","McConnell's sign","Severely hypokinetic RV","All of the above"],4,"Acute PE: dilated, hypokinetic RV with apical sparing (McConnell's — specific but not sensitive), underfilled LV.");
q('Practice',167,'rv',1,"After fluids for Gram-negative shock, the IVC measures 2.2 cm. Figure 1 is before and Figure 2 after a sniff (spontaneous breathing). What can be inferred about right atrial pressure?",["< 5 mm Hg","5–10 mm Hg","10–20 mm Hg","Cannot be inferred"],2,"IVC >2.1 cm with <50% sniff collapse → RAP ~15 (10–20) mm Hg.");
q('Post-test',22,'rv',1,"A 30-year-old with pulmonary arterial hypertension is hypoxic; CVP 8 mm Hg. Using the TR Doppler shown, what is her RVSP?",["16 mm Hg","24 mm Hg","64 mm Hg","72 mm Hg","Cannot be calculated"],3,"4(4.0)² = 64 + CVP 8 = 72 mm Hg.");

// 1.5 Valves & prosthetics
q('Practice',1,'valve',0,"An asymptomatic 66-year-old man has a systolic murmur. Which is a valid criterion for severe aortic stenosis?",["AVA index < 0.6 cm²/m²","Vmax > 3.0 m/s","Dimensionless index < 0.5","Systolic doming with LVH","Mean gradient > 30 mm Hg"],0,"Severe AS: Vmax ≥4 m/s, mean gradient ≥40 mm Hg, AVA <1.0 cm², AVAi <0.6 cm²/m², DVI <0.25. Doming occurs even with mild stenosis.");
q('Practice',60,'valve',1,"A 39-year-old with hepatitis C and IVDU is intubated in septic shock on norepinephrine; outside cultures grow Gram-positive cocci in clusters. Echo is shown. Which is a MINOR modified Duke criterion?",["AV vegetation on echo","Paravalvular abscess on echo","Positive blood cultures","Shock","History of IV drug use"],4,"Major: typical organism in 2 cultures; echo evidence (vegetation, abscess, new dehiscence) or new regurgitation. Minor: predisposition (IVDU, prosthetic or abnormal valve), fever, vascular and immunologic phenomena, cultures not meeting major. Shock is not a criterion.");
q('Practice',62,'valve',0,"An IVDU with exertional dyspnea has a mobile mass on the ventricular side of the aortic valve. Which finding is most likely also present?",["Early mitral valve closure","Holodiastolic flow reversal in ascending aorta","Aortic valve fluttering","Early aortic valve closure"],0,"Acute severe AR into a non-dilated LV abruptly raises LVEDP above LAP → premature mitral closure (a marker of severity). Holodiastolic reversal is assessed in the descending/abdominal aorta.");
q('Practice',71,'valve',1,"Based on the images shown, which is the correct diagnosis?",["Bicuspid, mild AS","Bicuspid, severe AS","Tricuspid, mild AS","Tricuspid, severe AS"],1,"A raphe mimics three cusps in diastole; judge cusp number in systole (bicuspid = fish-mouth/oval opening). Severity needs CW Doppler: Vmax ≥ 4 m/s (peak gradient ≥ 64 mm Hg), mean gradient ≥ 40 mm Hg, AVA < 1.0 cm² = severe.");
q('Practice',85,'valve',1,"Given the findings on the echo shown and the initial diagnosis of bicuspid aortic valve, which must also be considered?",["Diastolic MR","Mitral stenosis","Coarctation of the aorta","Aortic abscess","Atrial septal defect"],2,"BAV associations: coarctation, aortopathy (dilation, dissection, rupture), VSD (not ASD), PDA.");
q('Practice',92,'valve',0,"Pacer, catheter or ICD placement can be associated with significant TR. Best management principle?",["TEE is better than TTE for the tricuspid valve","Call cardiology to remove a PPM that perforated the TV","Even with wires, consider RV volume/pressure overload as the cause of TR","Mobile masses on wires are vegetations until proven otherwise"],2,"Secondary (functional) TR is far more common than lead injury, which is rare and usually tolerated. TTE beats TEE for the anterior TV/PV. Thrombi on right-heart hardware are common.");
q('Practice',106,'valve',1,"A 38-year-old IVDU with prior MSSA endocarditis requiring valve surgery a year ago has sepsis, hypotension and a loud systolic and diastolic murmur. 2D and color Doppler clips are shown. Best explanation?",["Normal porcine AVR","Abnormal native AV","Mechanical AVR thrombosis","Mechanical AVR endocarditis","Paravalvular extension of infection"],4,"Bioprosthesis (no disc artifacts) with perivalvular thickening and flow outside the sewing ring into abnormal tissue = abscess/paravalvular extension → surgery. Vegetations are better seen in long axis.");
q('Practice',129,'valve',1,"An 81-year-old man has a systolic murmur. Which aortic valve pattern is associated with this systolic LV outflow CW Doppler signal recorded from the apex?",["Thickening with good excursion","Mid-systolic closure with good leaflet opening","Doming and thickening","Normal motion","Diastolic prolapse"],1,"Late-peaking dagger (concave upstroke) = dynamic LVOT obstruction (SAM/HOCM), which causes mid-systolic AV closure/notching. Valvular AS has a rounded, convex, symmetric envelope.");
q('Practice',132,'valve',1,"A 44-year-old with morbid obesity, sepsis and respiratory failure has a systolic murmur. A TEE image is shown. Best explanation for the murmur?",["Severe acute AR","Mild–moderate AR","Bicuspid aortic valve","Acute endocarditis","VSD"],2,"Systolic murmur from a bicuspid valve. AR causes a diastolic murmur. Screen for coarctation, aortopathy, VSD, PDA.");
q('Practice',145,'valve',1,"A 79-year-old with recent anterior STEMI (LAD stent), recovering from sepsis/ARDS, develops tachycardia, hypertension, chest pain, ST depression and flash pulmonary edema during weaning. Echo 2 days post-MI showed EF 45%, mild apical hypokinesis, mild MR. Current images are shown. Most accurate interpretation?",["Ruptured posterior leaflet","Moderate MR from anterior prolapse","Rheumatic MS + MR","Severe MR from posterior wall ischemia","Severe MR from anterior wall ischemia"],3,"New ischemia in a non-culprit (posterior) territory tethers the posterior leaflet → posteriorly directed jet with 'relative' anterior prolapse. Vena contracta ≥0.7 cm = severe MR.");
q('Practice',146,'valve',1,"A 72-year-old with pre-op abdominal pain, diarrhea, nausea, leg edema and occasional flushing is hypotensive after elective cholecystectomy; BP responded to aggressive fluids. Based on the color Doppler and RV inflow images, most likely diagnosis?",["Normal","Endocarditis","A paraneoplastic syndrome (carcinoid)","Acute PE","Pulmonary hypertension"],2,"Carcinoid heart disease: thickened, retracted, immobile TV (± PV) leaflets with wide-open TR. Severe TR may be laminar (no mosaic) — easy to miss. Serotonin surge with stress causes vasodilation.");
q('Practice',164,'valve',1,"A 72-year-old with a remote bileaflet mechanical MVR fails ventilator weaning after treatment for pneumonia (afebrile, cultures negative, persistent infiltrates). Contrast echo after the last weaning attempt is compared with baseline 5 days earlier. Best explanation?",["One disc fixed closed","One disc fixed open","Severe PH","Constriction"],0,"A stuck-closed leaflet = prosthetic MS; tachycardia shortens diastole → LAP and PVR jump → infiltrates and RV pressure overload. A stuck-open leaflet would cause severe MR (less rate-dependent).");
q('Practice',165,'valve',0,"A man with repaired coarctation has a late-peaking systolic murmur. Which view and phase exclude bicuspid aortic stenosis?",["PLAX diastole","PLAX systole","PSAX diastole","PSAX systole"],3,"Only short axis shows the valve en face. Judge in systole: tricuspid = triangular orifice with 3 cusps; bicuspid = oval orifice with 2 cusps (a raphe can mislead in diastole).");
q('Post-test',4,'hemo',1,"A 75-year-old with urosepsis, hypotensive and tachycardic, with no prior medical care. This echocardiographic finding is most consistent with which scenario?",["Severe MR","Septic cardiomyopathy","Dynamic outflow obstruction","Tamponade","PE"],2,"Late peak = cavity narrowing (hyperdynamic, hypovolemic LV) → dynamic LVOTO. MR has a rounded, earlier-peaking envelope. Confirm by walking PW from apex to LVOT. Peak velocity alone doesn't grade MR.");

// 1.6 Pericardial disease
q('Practice',2,'peri',1,"A 54-year-old man with poorly controlled hypertension collapsed and was hypotensive (60/30); BP 80/40 after 2 L fluid, still hypotensive after another liter, now on dopamine. ECG: non-specific inferior ST changes. A bedside subcostal echocardiogram is shown. Most likely etiology?",["PE","Ascending aortic dissection","Sepsis","Aspiration"],1,"Hemopericardium with coagulum + tamponade complicating type A dissection (~20%). Management: emergency surgery; small controlled pericardiocentesis only as a bridge if survival to surgery is in doubt. Epicardial fat sits in the AV groove/anterior RV and moves with the heart.");
q('Practice',12,'peri',1,"A 65-year-old man, 6 months after CABG, has exertional dyspnea, 2+ leg edema, hepatomegaly with mild ascites and small bilateral effusions. Based on the echo images shown, most likely etiology?",["Constrictive pericarditis","Restrictive cardiomyopathy","Tamponade","HFrEF"],0,"Constriction: respirophasic septal shift (most sensitive), mitral E variation >25% (expiratory increase), TV >40%, annulus reversus (medial e' > lateral), preserved/high medial e' ≥9 cm/s (septal shift + e' ≥9: sens 80%, spec 92%). Restriction: low e' (<7), no reversus. Prior cardiac surgery is a leading cause.");
q('Practice',50,'peri',1,"A febrile lung cancer patient (BP 90/57, HR 85) has a moderate effusion with brief RA inversion, ~20% mitral E variation, normal-size collapsing IVC and normal hepatic vein flow. Best next step?",["Emergent pericardiocentesis","Chest tube","Pericardial window","Fluids, cultures, empiric antibiotics"],3,"No tamponade physiology: RA inversion is sensitive but nonspecific (more specific if >1/3 cycle); RV diastolic collapse is more specific. Tamponade usually shows ≥30% E variation, plethoric IVC and blunted/reversed hepatic diastolic flow. Treat sepsis.");
q('Practice',83,'peri',1,"A 55-year-old woman with melanoma and prior VTE on warfarin presents in shock. Which is true of her condition?",["There is echo evidence of tamponade","An effusion is necessary for tamponade","Tamponade is primarily an echo diagnosis","This effusion likely developed acutely","RV diastolic collapse is the most sensitive sign"],0,"RV diastolic collapse is present. Tamponade is a clinical diagnosis; it can occur without free effusion (hematoma, extrinsic compression). A large effusion usually accumulates slowly. RA collapse and Doppler variation are more sensitive; RV collapse is more specific.");
q('Practice',99,'peri',1,"A 23-year-old treated with doxycycline for pneumonia has dyspnea and a left lung opacity. After 5 L saline, BP 83/36, HR 118. Based on the images, this presentation is most likely due to:",["Tamponade, RV compressed","Tamponade, LV compressed","Tamponade, RA compressed","Cor pulmonale"],1,"Large empyema with mediastinal shift compressing the LV from outside = tamponade physiology. The LV flattening comes from the free-wall side, not from the septum. Non-standard views help.");
q('Practice',128,'peri',1,"A 60-year-old with rheumatic MS becomes progressively hypotensive within 12 h of MVR (surgery complicated by bleeding needing 4 units PRBC). POCUS images are compared with pre-op echo. Most accurate interpretation?",["MVR dehiscence","Pericardial hematoma","PE","MI","LV dysfunction"],1,"Post-cardiotomy clot looks like thickening/fat, not black fluid, and can be localized. Compare with baseline; TEE/CT if unclear; usually return to OR.");
q('Practice',131,'peri',1,"A 39-year-old in an MVC has substernal chest pain. A bedside echo is shown. What do the arrows show?",["Hematoma","Fat pad","Pericardial thickening","Accessory liver lobe","Atelectasis"],1,"Epicardial/pericardial fat: anterior to the RV and in the AV groove, moves synchronously; measure on the RV free wall at end-systole (1–23 mm). Marker of visceral adiposity.");
q('Practice',159,'peri',1,"A 48-year-old woman with exertional dyspnea has pulsus paradoxus and 40% variation in mitral inflow. Tissue Doppler of the medial (septal) mitral annulus is shown. Most likely diagnosis?",["Tamponade","Constrictive pericarditis","Restrictive cardiomyopathy","Effusion without tamponade"],1,"Respirophasic variation + high medial e' = constriction. Tamponade varies but without high annular velocity; restriction has low e'.");
q('Post-test',1,'peri',0,"After CABG with a PA catheter: HR 125, BP 64/42, PAP 26/20, PCWP 19, CVP 20. Which TEE finding is most likely?",["Distended RA","Normal LV contractility","Elevated cardiac index","Prolapsed MV"],1,"Equalized diastolic pressures (CVP ≈ PAD ≈ PCWP ≈ 20) = tamponade: small chambers, preserved contractility, low CI.");
q('Post-test',21,'peri',0,"POD1 after CABG: borderline SBP on multiple pressors, RAP 18, PCWP 15, CI 1.8. TTE is difficult; LV looks normal; no effusion seen. Best next step?",["Stress-dose steroids","Vancomycin","Emergent TEE for focal tamponade","ECMO"],2,"Post-cardiotomy tamponade is often a localized clot compressing the RA/RV and is missed by TTE. Low CI + high RAP after surgery → TEE.");
q('Practice',57,'valve',1,"A 42-year-old man with Marfan syndrome (BP 120/40) has an enlarged aorta without dissection and a holodiastolic murmur. Which continuous-wave Doppler image is most likely? (Figures A–E correspond to the options.)",["A — suprasternal view","B — apical 3-chamber view","C — apical 4-chamber view","D — apical 3-chamber view","E — apical 4-chamber view"],3,"Severe AR: CW across the AV shows dense forward and regurgitant envelopes (both high stroke volumes); forward velocity often raised without stenosis; short pressure half-time (steep slope) as aortic and LV diastolic pressures equalize. Descending aorta shows holodiastolic reversal; diastolic MR may appear when LVEDP exceeds LAP.");
q('Practice',114,'valve',1,"Same Marfan patient with severe AR. Which parasternal M-mode image is most likely a consequence of the severe AR? (Figures A–E correspond to the options.)",["A","B","C","D","E"],1,"M-mode has the highest temporal resolution. Severe AR: dilated LV in diastole, anterior mitral leaflet struggles to open (concave late opening as it receives the AR jet) and may close early when LVEDP is very high. A/D = DCM patterns with a B-bump (high LAP). C = diastolic fluttering of the anterior leaflet (mild–moderate AR). E = dilated aorta, which doesn't answer the question.");
// 1.7 Masses, aorta, variants, shunts & devices
q('Practice',3,'mass',1,"A 72-year-old woman with sepsis has intermittent hypotension despite fluids and vasopressors. A murmur is noted. A zoomed subcostal still is shown. Most likely etiology of the finding (arrow)?",["Myxoma","ASD","Normal closure device","Abnormal closure device","Lipomatous hypertrophy of the atrial septum"],4,"Fatty infiltration sparing the fossa ovalis → dumbbell. Benign, common in elderly/obese; rarely obstructs SVC or causes atrial arrhythmias. Septum best seen subcostally (horizontal to the beam).");
q('Practice',8,'mass',1,"A 64-year-old man with severe emphysema on home oxygen has a hemorrhagic stroke after tPA for a suspected embolic stroke. He is ventilated and stable. An agitated saline bubble study is shown. Which is most correct?",["Large ASD","Large PFO","Severe PH","Hepatopulmonary syndrome","Persistent left SVC"],4,"Persistent left SVC drains into the coronary sinus → markedly dilated CS (larger than raised RAP explains). Confirm with left-arm agitated saline: CS opacifies before RA. Left-sided CVCs may follow an unexpected course.");
q('Practice',14,'mass',1,"A 64-year-old man with a 1-year history of dysphagia, dysphonia and left arm weakness is admitted with respiratory failure from possible aspiration. CT head shows old bilateral infarcts. Blood cultures, coagulation, ANA and anti-dsDNA are negative. Most likely cause of the mass on the aortic valve?",["Infective endocarditis","Marantic endocarditis","Papillary fibroelastoma","Mitral myxoma","Ruptured chordae"],2,"Fibroelastoma: most common valvular tumor; <1 cm, mobile, stalked, 'shimmering/frond-like' edge, embolic strokes. Marantic: small, sessile, non-mobile on the closure line (malignancy). Myxoma: atrial septum with a pedicle.");
q('Practice',37,'mass',0,"Septic shock with AF of unknown duration and rapid ventricular response. TEE shows a large LA, dense spontaneous echo contrast and a possible small LAA clot vs pectinate muscle. Which modality helps decide if clot is present?",["Tissue Doppler","Pulsed-wave Doppler","CW Doppler","M-mode"],1,"PW in the proximal third of the LAA (average 5–10 beats in AF): <40 cm/s → higher stroke risk and SEC; <20 cm/s → high thrombus risk. Low-Nyquist color and contrast also help.");
q('Practice',42,'mass',1,"After lateral STEMI with femoral PCI, a 64-year-old in cardiogenic shock has TEE for ischemic MR. A mass in the aorta is noted (shown). What should be reported?",["Dissection after angiography","Mobile thrombus","The IABP is seen distal to the left subclavian artery","Artifact, no action"],2,"IABPs are well seen on TTE/TEE. To position: find the tip in the descending aortic long axis, withdraw to the UE arch short axis where the left subclavian take-off appears; tip should lie 1–2 cm distal. No flap or true/false lumen.");
q('Practice',65,'mass',1,"A 42-year-old man with acute chest pain and non-specific ST changes has severe pectus excavatum, so TEE is performed (mid-esophageal image shown). Repeat ECG now shows anterior ST elevation. Most important next step?",["Activate cath lab","Urgent CT","Consult cardiothoracic surgery","Antibiotics","Adult congenital team"],2,"Acute type A dissection (~1%/h early mortality) → immediate surgery. The flap intermittently occluding the left main explains STE; PCI or lysis could be disastrous. TEE is diagnostic; CT would only delay. Pectus raises suspicion of Marfan.");
q('Practice',81,'mass',1,"A 48-year-old woman with ARDS from severe pancreatitis has poor TTE windows; the mid-esophageal TEE image is shown. Most appropriate next step?",["Anticoagulate for thrombus in transit","Thrombolyse","Antibiotics","Continue management — anatomic variant"],3,"Chiari network: remnant of the right sinus venosus valve, long, thin, highly mobile, attached near the IVC/SVC. No action. Other mimics: crista terminalis, Eustachian/Thebesian valves, Lambl's excrescences.");
q('Practice',88,'mass',1,"A man with a surgical LVAD is finishing antibiotics for pneumonia (diuretics held, IV fluids given). Urine output is borderline and there are episodic low-flow alarms. Admission and repeat echo images are shown. Best next step?",["Judicious fluids","Increase LVAD speed","Phenylephrine","Judicious diuresis ± low-dose inotrope"],3,"Ideal: neutral septum. Leftward shift = RV failure/overload, low LV preload or over-unloading (suction risk). Here the IVC is plethoric → RV overload → diurese and support the RV. Rightward shift = under-unloading: low speed, pump thrombus, cannula kink, severe AR, high afterload.");
q('Practice',90,'mass',0,"Tearing chest/back pain, BP 195/98 left arm vs 161/40 right, loud diastolic murmur. Best imaging choice?",["TTE for wall motion","TTE for the aorta","TEE for the aorta","FAST"],2,"TEE has ~100% sensitivity for dissection and shows nearly the whole thoracic aorta (blind spot: distal ascending/proximal arch behind the left main bronchus) plus AR mechanism. TTE is a reasonable first look but limited.");
q('Practice',112,'mass',1,"The transesophageal clip is consistent with which LVAD clinical scenario?",["Pump thrombosis","Outflow cannula kink","Severe AR","Suction event"],3,"Suction = inadequate pump preload: hypovolemia, RV failure, tamponade, inflow malposition. Pump thrombosis, outflow kink and severe AR cause LV dilation with the septum bowing right.");
q('Practice',113,'mass',1,"A 70-year-old with AKI, hyperkalemia, a lung mass with liver/adrenal lesions and a paraneoplastic GM-CSF syndrome with eosinophilia has non-specific T-wave changes. Echo is shown. Most likely diagnosis?",["Apical HCM","DCM with apical thrombus","Hypereosinophilic syndrome with endomyocardial fibrosis","MI with apical thrombus"],2,"HES: eosinophilic myocarditis → apical thrombus overlying inflamed myocardium, LV/RV apical obliteration, restrictive physiology, posterior MV leaflet tethering. Apical HCM = spade-shaped thick apex (can pouch).");
q('Practice',115,'mass',0,"A woman with rhinitis, asthma and exertional dyspnea has normal biventricular systolic function but biventricular apical thrombi. Most useful blood test?",["Metabolic panel","CBC with differential","CPK and troponin","ESR"],1,"Loeffler (eosinophilic) endocarditis — think EGPA with asthma/rhinitis. Eosinophil count is key.");
q('Practice',116,'mass',1,"A 36-year-old woman in the ICU with respiratory failure and hypoxemia has an agitated saline injection (shown). Most likely diagnosis?",["PFO","Hepatopulmonary syndrome","Portopulmonary hypertension","PDA","VSD"],0,"Bubbles in the LA within ~3 beats = intracardiac (atrial) shunt, most often PFO. Late (3–5+ beats) = intrapulmonary shunt (HPS). Valsalva can delay a PFO shunt. Bubbles in the LA argue against VSD.");
q('Practice',117,'mass',1,"A 65-year-old has hoarseness and chest pain after an MVC. Based on the admission chest radiograph shown, which test is most appropriate?",["TEE","Lateral decubitus film","Bronchoscopy","Contrast swallow"],0,"Suspected traumatic aortic injury/dissection (widened mediastinum, hoarseness from recurrent laryngeal stretch) → TEE (or CTA).");
q('Practice',137,'mass',1,"Which option best explains the structure identified by the arrow?",["Artifact","Moderator band","Papillary muscle","RV thrombus","Pacemaker lead"],1,"Moderator band: identifies the morphologic RV, carries the right bundle branch, thickens with RVH; often mistaken for a mass.");
q('Practice',139,'mass',1,"A 36-year-old on VV-ECMO via a dual-lumen RIJ cannula (adequately anticoagulated) has decreased circuit flow and 'chattering' tubing. TEE of the cannula is shown. Most likely etiology of the flow alarms?",["Hypovolemia from bleeding","Kinked cannula","Displacement of the distal port","Oxygenator thrombus"],2,"Dual-lumen cannula: drainage ports in SVC and IVC, return jet in the RA aimed across the TV. Distal port migrated into the RV → poor drainage. Pull back into the IVC under TEE.");
q('Practice',144,'mass',1,"Based on the images provided, what is the mass in the left atrium?",["LA thrombus from MS","Lymphoma","LA myxoma","Metastatic lung cancer"],2,"Myxoma: most common primary cardiac tumor, LA, pedunculated from the fossa ovalis region, may prolapse through the MV. Thrombi sit in the LAA/posterior wall with stasis (MS, AF).");
q('Practice',157,'mass',1,"A 53-year-old with lymphoma is asymptomatic with normal vitals after femoral cardiac catheterization (no CAD). This subcostal finding is observed. Most appropriate therapy?",["Anticoagulation ± lysis","Hyperbaric oxygen","Rasburicase and fluids","No therapy"],3,"SEC = slow-moving blood, not thrombus or air. A small effusion with normal vitals is not tamponade. No VTE, tumor lysis or gas embolism.");
q('Practice',161,'mass',1,"A 65-year-old in cardiogenic shock from multivessel CAD has a percutaneous LVAD placed. On 10 L O2 he becomes more dyspneic and hypoxic, then profoundly hypotensive; the device shows a flow alarm. Based on the POCUS images, best next step?",["Increase speed and reposition","Epinephrine","Decrease speed and reposition","Fluid bolus"],2,"Suction event (from acute RV failure/raised PVR with hypoxia). First reduce speed to relieve suction, then confirm inflow position. Fluid worsens RV overload; intubation and oxygen lowered PVR here.");
q('Post-test',7,'mass',1,"A 78-year-old admitted for cellulitis, severe sepsis and dyspnea. POCUS clips are shown. Most likely finding?",["Chiari network","Eustachian valve","RA thrombus","Myxoma"],2,"Thrombus in transit (cast of a deep vein) — associated with PE and high mortality. Chiari = thin, filamentous; Eustachian valve = fixed ridge at IVC; RA myxoma (10–15%) attaches by a stalk to the fossa ovalis.");

// ===== DOMAIN 2 — PHYSICS =====
// 2.1 Principles & instrumentation
q('Practice',16,'phys',1,"An intraoperative TEE (Figure A) was adjusted to better visualize far-field structures, giving Figure B. What was adjusted?",["Decreased gain","Increased depth","Focus","Time gain compensation"],3,"TGC compensates for attenuation by amplifying echoes by depth; raising far-field TGC brightens deep structures without changing near field. Overall gain changes all depths equally.");
q('Practice',63,'phys',0,"Which frequency has the greatest energy loss traveling through tissue at 1,500 m/s?",["15 MHz, fundamental","10 MHz, harmonic","5 MHz, tissue Doppler","3 MHz, color Doppler"],0,"Attenuation rises with frequency (≈0.5 dB/cm/MHz in soft tissue): higher frequency = better resolution, less penetration. The imaging mode does not change attenuation.");
q('Practice',73,'phys',1,"How does decreasing the sector width change this apical 4-chamber view?",["Increases dynamic range","Increases frame rate","Decreases resolution","Decreases frame rate"],1,"Fewer scan lines per frame → more frames per second (better temporal resolution). Wide sectors or deep images force lower frame rate or fewer lines (poorer quality).");
q('Practice',108,'phys',1,"Ultrasound is depicted as a sine wave (shown). What is the wave parameter marked with the arrow?",["Frequency","Amplitude","Propagation velocity","Power","Wavelength"],4,"Wavelength = distance of one cycle; λ = c/f (c ≈ 1540 m/s in soft tissue). Shorter λ (higher f) → better axial resolution. Amplitude = wave size; power relates to amplitude²; propagation speed depends on stiffness and density.");
q('Practice',111,'phys',0,"Which maneuver increases frame rate, improving temporal resolution?",["Read (post-processing) zoom","Increasing depth","Narrowing the sector width","Enlarging the color box"],2,"Frame rate ↑ with less depth, narrower sector, smaller color box, fewer focal zones. Read zoom does not change frame rate; write zoom narrows the scanned region and may increase it.");

// 2.2 Doppler
q('Practice',10,'dop',1,"An asymptomatic 66-year-old man has a systolic murmur. The spectral Doppler shown was obtained. Where was the PW sample volume most likely placed?",["Tricuspid annulus","Tricuspid leaflet tips","Hepatic vein","Fossa ovalis","SVC"],2,"Normal hepatic vein: triphasic S and D (toward heart, below baseline) and A (reversal). Severe TR: blunted/reversed systolic flow and a large antegrade V wave from regurgitant volume reaching the liver. Time phases from the QRS.");
q('Practice',86,'dop',0,"Measuring LVOT VTI from A5C with an insonation angle of about 20°, the measured velocities will show:",["Underestimation of true velocity","An acceptable error ≤ 6%","Both A and B","Neither"],2,"Measured v = true v × cos θ. cos 20° ≈ 0.94 → ~6% underestimation, conventionally acceptable (<20°). At 30° error is ~13%; at 60° 50%.");
q('Practice',96,'dop',0,"The Nyquist limit is increased by:",["Increasing sample volume length","Increasing pulse repetition frequency","Increasing sample depth","Increasing transducer frequency"],1,"Nyquist limit = PRF/2. Greater depth lowers PRF and the limit. In velocity terms the aliasing velocity = c·PRF/(4f₀cosθ): a lower transducer frequency also raises the measurable velocity, but the Nyquist frequency itself is PRF/2. Sample volume length does not change it.");
q('Practice',100,'dop',1,"Comparing Figure A to Figure B, which is most correct?",["Higher Hz in B is due to Nyquist setting","Figure A has a higher PRF than Figure B","Color scale in A is correct for the flow","Figure B will underestimate regurgitation"],1,"Color scale (Nyquist) = PRF/2; a higher scale means higher PRF and less aliasing. ASE 2017: set Nyquist 50–70 cm/s for regurgitant jets; lower it for low-velocity flow (atrial septum, veins). A low Nyquist overestimates jet size.");
q('Practice',147,'dop',0,"Which mode does NOT have a Nyquist limit?",["Color Doppler","Tissue color Doppler","Tissue PW Doppler","Continuous-wave spectral Doppler","PW spectral Doppler"],3,"Aliasing comes from intermittent (pulsed) sampling. CW transmits and receives continuously → no Nyquist limit, but no range resolution.");
q('Practice',162,'dop',0,"When recording high velocities with CW Doppler, which is most accurate?",["Small cursor angle deviations can cause large underestimation of maximal velocity","Lower lateral resolution underestimates Doppler velocity","Higher signal-to-noise overestimates velocity","TGC improves Doppler velocity estimation"],0,"Cos θ error scales with velocity, so the absolute error is largest for high-velocity jets (e.g. AS): align parallel, use multiple windows. Lateral resolution and TGC affect 2D, not spectral velocity. Low SNR causes overestimation; good SNR helps.");

// 2.3 Artifacts
q('Practice',56,'art',1,"Which statement is most correct regarding the structures highlighted by the arrows in this figure?",["Blue arrow = multiple short-path reverberations within the reflector","Yellow arrow = enhancement behind a weakly attenuating surface","White arrow = reduced amplitude behind a highly reflective surface","All are artifacts reduced by contrast","All are real pathology"],2,"White = acoustic shadowing (attenuation artifact) behind a strong reflector. Yellow = comet tail (closely spaced reverberations within a calcified reflector, one scan line). Posterior enhancement occurs behind weakly attenuating fluid.");
q('Practice',68,'art',1,"Which option matches the finding marked by the arrows with its underlying cause?",["Red/pericardial thickening","Yellow/posterior enhancement","Yellow/mirror","White/side lobe","White/mirror artifact"],4,"Mirror image: a strong specular reflector (pleura/diaphragm next to effusion) bounces the beam, so a copy appears deeper than the reflector, as far beyond it as the real structure is in front of it, moving in sync. Yellow = comet-tail reverberation; red = posterior enhancement.");
q('Practice',77,'art',1,"What type of artifact is shown in the video?",["Refraction","Reverberation","Side lobe","Beam width"],0,"Refraction: the beam bends at an interface with different propagation speed (a lens), so a ghost image appears lateral to the true structure. Reverberation copies appear deeper along the same line.");
q('Practice',95,'art',1,"A 51-year-old obese man in septic shock has a right IJ dialysis catheter placed and dialysis started. TEE mid-esophageal long axis shows the video. Most appropriate next step?",["Remove the catheter","Image the SVC and aorta in short axis","CT chest","Pericardiocentesis"],1,"Side-lobe artifact from the SVC catheter (out of plane) projected into the aorta. Confirm in another plane and with color flow before acting on one image; a true flap disturbs flow.");
q('Practice',158,'art',1,"What artifact is seen in these images of the internal jugular (left), lung (right) and subcostal (bottom)?",["Aliasing","Beam width","Refraction","Ring down","Side lobe"],3,"Ring-down: resonance of fluid trapped among tiny air bubbles (bubble tetrahedron) → continuous vertical streak (lung B-lines, venous air, bowel gas). Beam width: off-axis strong reflectors outside focus; side lobe: off-axis reflector displayed in main beam.");
// ===== DOMAIN 3 — OTHER APPLICATIONS =====
// 3.1 Hemodynamics & cardiac output
q('Practice',25,'hemo',0,"Intubated with pneumonia and septic shock, a woman has severe MR and pulmonary edema. How can LAP be estimated quantitatively?",["E/e'","Maximum MR velocity","Pulmonary regurgitation velocity","Left upper pulmonary vein velocity by PW"],1,"With severe MR, E/e' is unreliable. Without AS: LAP = SBP − 4(MR Vmax)².");
q('Practice',38,'hemo',1,"Based on the images shown (HR 95), this patient's cardiac output is:",["5.5 L/min","5.1 L/min","10.1 L/min","Not interpretable"],1,"Area = 0.785 × D² = 3.14 cm². SV = 3.14 × 17 = 53 mL. CO = 53 × 95 = 5.07 L/min.");
q('Practice',45,'hemo',0,"To calculate stroke volume, which TTE view is best for LVOT diameter?",["PSAX aortic valve level","A4C","Subcostal 4C","PLAX","A2C"],3,"Diameter from zoomed PLAX (inner edge to inner edge, mid-systole, at the annulus); VTI from A5C/A3C with PW aligned to flow. SV = π(D/2)² × VTI; CO = SV × HR.");
q('Practice',64,'hemo',1,"A 38-year-old with ARDS and septic shock, HR 120. Based on the echo measurements shown, approximate cardiac output?",["2.4 L","3.1 L","4.3 L","5 L","6 L"],4,"r = 1.18 → area 4.37 cm². SV = 4.37 × 11.6 = 50.7 mL. CO = 50.7 × 120 = 6.1 L/min. Note: a low VTI can still give normal CO at high HR.");
q('Practice',76,'hemo',0,"After LAD STEMI and PCI, SBP 85, new pansystolic murmur; A4C shows a VSD. CW peak left-to-right shunt velocity 3 m/s. RVSP?",["32 mm Hg","49 mm Hg","65 mm Hg","82 mm Hg"],1,"VSD gradient = 4(3)² = 36. RVSP = LVSP (≈SBP) − 36 = 85 − 36 = 49 mm Hg. Without pulmonic stenosis, RVSP = PASP.");
q('Practice',119,'hemo',1,"A patient with dilated cardiomyopathy has the LVOT Doppler pattern shown. This finding is most consistent with:",["Pulsus paradoxus","Pulsus alternans","Dynamic LVOTO","Arrhythmia"],1,"Beat-to-beat alternation in regular rhythm = pulsus alternans (severe LV dysfunction, poor prognosis). Paradoxus varies with respiration (tamponade); LVOTO gives a late-peaking dagger; arrhythmia varies with cycle length.");
q('Practice',156,'hemo',1,"Baseline and current LVOT VTI of a 73-year-old after ascending aortic replacement are shown. Best interpretation?",["Baseline normal, current low","Baseline high, current low","Both normal","Baseline high, current normal"],1,"Normal LVOT VTI ≈ 18–22 cm. High VTI: AR (large forward SV), sepsis/high output. VTI <10–12 cm → low SV/cardiogenic shock. VTI is used for PLR and VA-ECMO weaning.");
q('Post-test',13,'hemo',0,"Septic shock, HR 105: LVOT diameter 2.6 cm, mean LVOT VTI 14.4 cm (A5C). Cardiac output?",["8.0 L/min","7.6 L/min","6.8 L/min","3.2 L/min","Cannot be calculated"],0,"r = 1.3 → area = π × 1.69 = 5.31 cm². SV = 5.31 × 14.4 = 76.5 mL. CO = 76.5 × 105 = 8.0 L/min.");

// 3.2 Preload & fluid responsiveness
q('Practice',15,'fluid',0,"Which echo parameter best predicts fluid responsiveness with passive leg raise in shock?",["Indexed LVEDA","E/e'","Indexed LVESA","Aortic (LVOT) VTI","MAPSE"],3,"PLR-induced VTI rise ≥12.5% predicts ≥15% SV rise after volume (sens 77%, spec 100%, Lamia 2007). Works with spontaneous breathing and arrhythmia. End-expiratory + end-inspiratory occlusion: summed VTI change >13% → responsive. Static measures (EDA, E/e') don't predict.");
q('Practice',24,'fluid',1,"A 64-year-old woman with sepsis: T 38.3, MAP 66, HR 120, RR 35, SpO2 94% on 2 L, urine 80 mL in 4 h. PSAX views are shown. Next most appropriate step?",["Furosemide","Fluid bolus alone","Fluid + low-dose beta-blocker","Norepinephrine","Pericardiocentesis"],1,"End-systolic cavity obliteration ('kissing papillary muscles') = severe hypovolemia; with hypoperfusion give fluid. EDA itself doesn't predict response. Beta-blocker only for dynamic LVOTO; pressors after adequate filling.");
q('Practice',39,'fluid',0,"A ventilated trauma patient with bilateral chest tubes and extensive subcutaneous emphysema is still hypotensive after splenectomy. TEE is used. Best TEE measure of volume responsiveness?",["LVEDD","IVC variation","TR Vmax","SVC respiratory collapsibility"],3,"ME bicaval view with M-mode: SVC collapsibility >36% (controlled ventilation, Vt ≥8 mL/kg, no effort) → sens 90%, spec 100%. TEE shows the SVC reliably; the IVC distensibility belongs to TTE.");
q('Practice',46,'fluid',0,"A 44-year-old with severe LV systolic dysfunction awaiting transplant has a UTI; BP 87/56 on norepinephrine 0.03 mcg/kg/min, lactate 1.5, UO 60 mL/h. Echo: dilated IVC, restrictive E/A, E/e' near 15, no B-lines. Best next step?",["Fluids until off pressor","Fluids until B-lines appear","Fluids while VTI rises >10%","Continue vasopressors"],3,"Perfusion is adequate on a low pressor dose and the heart has little filling reserve (high LAP). Fluid responsiveness ≠ fluid need. If testing is needed, use reversible PLR rather than boluses; FALLS-guided loading is risky here.");
q('Practice',67,'fluid',0,"In which patient (controlled ventilation, sinus rhythm) is LVOT velocity variation an appropriate measure of fluid responsiveness?",["Hemorrhagic shock","Severe ARDS","Tamponade","Abdominal compartment syndrome"],0,"SVV/VTI variation requires Vt ≥8 mL/kg, no spontaneous effort, sinus rhythm, closed chest, normal abdominal pressure, normal lung compliance. ARDS (low Vt), tamponade and intra-abdominal hypertension invalidate it.");
q('Practice',97,'fluid',1,"This image is from an ARDS patient on controlled low-Vt ventilation: HR 105, BP 122/74, RR 26. Appropriate management?",["1 L crystalloid","No fluid","PLR then 1 L if positive","Raise Vt to 10 mL/kg and reassess"],1,"Fluid responsive does not mean fluid is needed: he is normotensive. A PLR wouldn't change management. Note he may drop pressure with diuresis/dialysis. Never raise Vt in ARDS.");
q('Practice',136,'fluid',1,"A 56-year-old with alcoholism, jaundice, pancytopenia, fever and B-cell lymphoma has worsening hypotension on 2 L O2. Which is an accurate assessment?",["He is fluid responsive","IVC collapsibility is the test of choice","PLR is the least sensitive test","The LV is hyperdynamic"],3,"Small collapsing IVC estimates low RAP but does not predict response. In spontaneous breathing use PLR (most sensitive; SVC collapsibility is most specific; IVC distensibility is for ventilated patients). Hyperdynamic LV in the ED strongly predicts sepsis (or bleeding/low afterload).");
q('Practice',150,'fluid',0,"Which could DECREASE the accuracy of a passive leg raise test?",["Same probe position and angle for VTI each time","Re-measuring LVOT diameter at each assessment","Measuring SV before, 1 min into PLR and after return to baseline","Starting semi-recumbent at 45°, then lowering head to 0°"],1,"LVOT diameter doesn't change during PLR; re-measuring it adds the largest error. Use % change in VTI. Accuracy improves with consistent probe position, confirming reversal, and starting semi-recumbent (bigger preload shift).");
q('Practice',166,'fluid',1,"A 38-year-old in shock and respiratory distress after mediastinal biopsy has Kussmaul breathing. Based on the vena cava pictured, what can be inferred about response to a 1-L crystalloid challenge?",["Responsive because of Kussmaul breathing","IVC collapsibility not applicable in spontaneous breathing","Response is uncertain","Not responsive because IVC doesn't collapse"],2,"Tamponade causes IVC plethora even when the patient may respond to fluid, so IVC is unreliable. Kussmaul/forceful breathing increases false positives. IVC collapsibility has some utility in spontaneous breathing otherwise.");

// 3.3 Shock & cardiac arrest
q('Practice',18,'shock',1,"A 68-year-old active smoker becomes dyspneic while cycling (BP 78/48, HR 110, SpO2 88%), turns pale and loses all pulses. Initial imaging and a follow-up video are shown. Besides continuing ACLS, the next best step is:",["Thrombolytic","IABP","STEMI alert","Stop resuscitation"],0,"Arrest with a dilated RV plus DVT = presumed massive PE → systemic thrombolysis during CPR.");
q('Practice',29,'shock',0,"After myectomy/maze, a man on VV-ECMO with leukocytosis and AKI is hyperdynamic on TEE (no LVOTO), fluid-unresponsive, norepinephrine 0.5. Stroke volume index and VTI are inappropriately low; EF normal with contrast; high E/e'. Type of shock?",["Cardiogenic","Distributive","Hypovolemic","Distributive plus diastolic dysfunction"],3,"Not hypovolemic (fluid-unresponsive). Low SV with normal EF and high E/e' = diastolic dysfunction, which alone doesn't explain instability → mixed distributive + diastolic.");
q('Practice',51,'shock',1,"A 71-year-old found unconscious, intubated in the field, had ROSC on arrival. In the ICU he now has no palpable pulse; the image shows no cardiac activity for 10 minutes. Most appropriate next step?",["Defibrillate","Pericardiocentesis","Thrombolytic","Stop resuscitation","Continue resuscitation"],3,"Sonographic standstill carries an extremely poor prognosis (no ROSC after 10 min of standstill in a study). Integrate with the full clinical picture; no VF, tamponade or RV failure here.");
q('Practice',53,'shock',1,"The 68-year-old smoker who collapsed after cycling has had 25 minutes of ACLS. The video shown is obtained. Which is an accurate assessment?",["Poor likelihood of ROSC","This is true PEA","Reasonable to cease resuscitation","All of the above"],3,"No organized contractility after ≥25 min = true PEA (vs pseudo-PEA with organized motion); very poor prognosis.");
q('Practice',72,'shock',1,"The 68-year-old smoker (BP 78/48, HR 110, SpO2 88%) goes pale and loses all pulses. Based on this information and the video, the next step should include:",["Bilateral needle decompression","Pericardial drainage","3 L fluid bolus","Vasopressor infusion and more data","Stop resuscitation"],3,"Acute RV failure (PE or RV infarct): support with vasopressors and gather more data. Large boluses worsen RV dilation.");
q('Practice',80,'shock',1,"The same 19-year-old (sore throat, fever, BP 87/42, bilirubin 5.2): integrated cardiac, lung and venous ultrasound images are shown. Which type of shock is this?",["Hypovolemic","Cardiogenic","Obstructive","Distributive"],3,"Pump hyperdynamic, tank not empty, non-homogeneous B-lines (capillary leak), pipes show IJ DVT but normal RV → distributive (septic; Lemierre).");
q('Practice',120,'shock',1,"A 30-year-old transferred as 'septic shock' has 4 weeks of dyspnea, dry cough and chills despite azithromycin, and 3 days of orthopnea and leg edema. She is on epinephrine and vasopressin. Based on the echo, next best step?",["Diuresis and consider mechanical support","Fluids and antibiotics","tPA","Pericardiocentesis","Revascularization"],0,"Cardiogenic shock from myocarditis. Degree of dysfunction and history are atypical for sepsis cardiomyopathy; no RWMA, tamponade or RV clot.");
q('Practice',124,'shock',1,"A 72-year-old a month after hip fracture surgery suddenly has chest pain and dyspnea: MAP 68, HR 128, SpO2 92% on HFNC, clear CXR. The apical 4-chamber view is shown. Next most appropriate measure?",["Heparin","IABP","Antibiotics","IV tPA","Valve surgery"],3,"Right-heart thrombus in transit = high risk of further massive embolism → urgent fibrinolysis (or embolectomy). Heparin alone is inadequate.");
q('Practice',135,'shock',0,"Recently discharged after AAA surgery, a man has dyspnea, chest pain, hypotension, sinus tachycardia and lateral ST depression. Next diagnostic test?",["Spiral CT","TEE","Portable perfusion scan","TTE"],3,"Unstable: bedside TTE can show RWMA (ischemia) or RV dilation (PE). CT is unsafe to travel for; TEE is stressful in a non-intubated possible MI.");
q('Practice',142,'shock',1,"A 68-year-old with 3 days of dyspnea and low-grade fever is tachycardic and hypotensive, is intubated, and then has a PEA arrest. Images shown. Best next step:",["Chemistry panel","CTA","Heparin infusion","Alteplase bolus then remainder over 2 h","V/Q scan"],3,"Arrest/hemodynamic instability with RV dilation/dysfunction → thrombolysis once absolute contraindications excluded; too unstable for CT.");
q('Post-test',9,'shock',1,"A 65-year-old with urosepsis given 5.6 L crystalloid develops respiratory failure (BP 85/42, PEEP 5, norepinephrine). She has a brief PEA arrest during tachycardia, with BP improving after rate control with amiodarone. A4C and subcostal clips are shown. Most likely reason for instability?",["Hypovolemia","LV systolic dysfunction","PE","Septic shock","Dynamic obstruction"],4,"Dynamic LVOT obstruction worsened by tachycardia (improved with rate control). Not PE (normal RV, no clot), not LV failure, not pure hypovolemia (dilated IVC).");
q('Post-test',12,'shock',0,"A 35-year-old woman, back from South America (drug use), has two arrests with ROSC; BP 88/52, HR 115. Echo: moderate RV hypokinesis and dilation (basal diameter 48 mm, RV/LV ratio > 1). Next step?",["Chemistry panel","CTA","Heparin","Alteplase 10 mg bolus then 90 mg over 2 h","V/Q scan"],3,"Massive PE with recurrent arrest and RV dysfunction → systemic thrombolysis; too unstable for confirmatory CT.");
q('Post-test',14,'shock',1,"A 65-year-old in shock (BP 80/50, HR 142, low-dose norepinephrine) is emergently intubated; breath sounds bilateral. A subcostal cardiac clip is shown. Next most appropriate step?",["Inotropes","Treatment-dose thrombolysis","Lactated Ringer's bolus","Empiric antibiotics","Pericardiocentesis"],1,"Clot in transit with massive PE physiology → thrombolysis or surgical embolectomy. Distinguish from vegetation (attached to a thickened leaflet). Fix the cause before inotropes; fluids harm the RV.");
q('Post-test',19,'shock',1,"A 66-year-old in the cardiac ICU for chest pain suddenly loses pulses. POCUS between compressions shows the image. Next best step?",["Defibrillation","Stop the code","Amiodarone 300 mg","Pericardiocentesis"],0,"Ultrasound can reveal VF/VT (fine VF can mimic asystole on the monitor) → defibrillate. Amiodarone does not replace shocks.");
q('Post-test',24,'shock',0,"Per the FEEL algorithm, cardiac image acquisition during ALS should take how long?",["< 1 min","< 30 s","< 10 s","As long as needed"],2,"FEEL: scan only during the pulse check, ≤10 s, to keep hands-off time minimal; record a clip and review during compressions.");

// 3.4 Lung & pleural ultrasound
q('Practice',13,'lung',1,"A 62-year-old woman in hypoxemic respiratory failure (WBC 15,800, CRP 80) is intubated. Lung ultrasound images are shown. Which is true?",["Diffuse interstitial syndrome includes pneumonia","Consistent with cardiogenic edema","LUS cannot narrow the differential","Irregular pleura and subpleural sparing are not characteristic of cardiogenic edema"],3,"Cardiogenic edema: diffuse, homogeneous B-lines from a smooth, regular pleura. Inflammatory/fibrotic (ARDS, ILD): irregular pleura, spared areas, subpleural consolidations. Pneumonia is usually focal. This patient had IPF.");
q('Practice',40,'lung',1,"A 35-year-old intubated, unstable trauma patient has worsening hypoxemia after an attempted right subclavian line, with decreased breath sounds on the right. Based on the images, most likely diagnosis?",["Right pneumothorax","Right contusion","Right airway occlusion","Normal","Right hemothorax"],2,"Lung pulse means visceral pleura is apposed → no pneumothorax. Absent sliding with lung pulse = no ventilation (mainstem/airway occlusion, atelectasis, apnea). Pneumothorax has neither sliding nor pulse.");
q('Practice',58,'lung',1,"A 35-year-old asthmatic has dyspnea (HR 104, BP 110/64, SpO2 92% RA). Lung ultrasound from multiple windows is shown. According to the BLUE protocol, which profile fits?",["A","A'","B","B'","A/B"],4,"A = bilateral A-lines with sliding; A' = A without sliding (± lung point → PTX); B = bilateral B-lines with sliding (cardiogenic edema); B' = B without sliding (pneumonia); A/B = asymmetric (pneumonia). Normal = A profile without PLAPS.");
q('Practice',66,'lung',1,"A 19-year-old in an airbag-deploying MVC has chest pain. FAST is negative; the exam is extended to both flanks, mid-axillary line and diaphragm with similar findings (image shown). Which is true?",["Bilateral sliding excludes pneumothorax","Absent sliding suggests PTX","Additional imaging is needed to diagnose or exclude PTX","Pulmonary contusion is present"],2,"Sliding or B-lines exclude PTX only at the point examined. Scan multiple anterior/lateral points bilaterally (air rises anteriorly in supine). Loculated PTX can be missed.");
q('Practice',91,'lung',1,"The images below represent:",["Lung point","Lung sliding","Seashore sign","Barcode sign"],0,"Lung point = 100% specific for pneumothorax. Caveat: a patient breathing then pausing can mimic it.");
q('Practice',94,'lung',1,"Which patient most likely has a pneumothorax (A or B)?",["Patient A","Patient B","Both","Neither"],0,"Hand or probe motion can create a false lung point; check that the probe is still and that both patterns follow respiration.");
q('Practice',98,'lung',1,"A 23-year-old with severe TBI from a gunshot is ventilated with severe hypoxemia (PEEP 26, FiO2 1.0, SpO2 79%) despite mode changes and bronchoscopy. Ultrasound and echo are shown; CXR pending. Most appropriate next step?",["Chest tube","tPA","Prone","Diuretic"],2,"Dependent consolidation/atelectasis, not PTX (sliding), not diffuse edema (no anterior B-lines), PE unlikely. Little recruitable lung anteriorly; proning redistributes ventilation.");
q('Practice',102,'lung',1,"A patient with acute-on-chronic subdural hematoma is difficult to liberate from the ventilator. Based on the images, the diagnosis is:",["Empyema","Lung abscess","Consolidation","Hiatal hernia"],1,"Abscess: hypoechoic cavity with irregular wall within lung parenchyma (moves with lung). Empyema is pleural, lens-shaped, with split pleura.");
q('Practice',105,'lung',0,"Regarding B-lines, pulmonary edema and PAOP, which is true?",["More sensitive than CXR; number correlates well with PAOP","More sensitive than CXR; correlates poorly with PAOP","Less sensitive; correlates well","Less sensitive; correlates poorly"],1,"B-lines track extravascular lung water better than CXR but do not predict wedge pressure (permeability edema). Accuracy for EVLW improves at higher PEEP.");
q('Practice',121,'lung',1,"An 82-year-old with 3 days of dyspnea has SpO2 82% on room air. Lung ultrasound results are shown. Most likely diagnosis?",["Left PTX","Left pneumonia","Normal","COPD exacerbation"],1,"Asymmetric A/B profile = pneumonia (BLUE). Sliding excludes PTX; COPD shows an A-profile.");
q('Practice',133,'lung',0,"Which finding helps identify a pleural effusion?",["Bat sign and sliding","Lung point and lung pulse","Spine sign","A-lines and B-lines"],2,"Spine visible above the diaphragm (fluid transmits sound) and loss of the curtain sign = effusion. Mirror image above the diaphragm is normal. Bat sign = rib shadows; lung point rules in PTX.");
q('Post-test',16,'lung',1,"The image shown demonstrates:",["Pneumothorax","Seashore sign","Pleural effusion","Barcode sign"],3,"Barcode (stratosphere) = absent sliding. Not lung point: the disturbance extends above the pleural line (probe movement).");

// 3.5 Vascular, DVT & procedures
q('Practice',7,'vasc',1,"Before paracentesis for large-volume ascites in a man with alcoholic cirrhosis, a POCUS image is obtained. Which structure is seen?",["Iliac artery","Common femoral artery","Descending aorta","Inferior epigastric artery"],3,"The inferior epigastric artery runs in the rectus sheath next to the parietal peritoneum lateral to the umbilicus — map it with color before paracentesis.");
q('Practice',23,'vasc',0,"Regarding US-guided subclavian venous catheterization, which is true?",["Delto-pectoral insertion improves proficiency","The vein is usually cephalad to the artery","US reduces subclavian stenosis risk for dialysis catheters","Ideal trajectory aims at the rib to protect the pleura"],3,"Aim at the 1st/2nd rib (backstop, compressible). The artery is usually cephalad and deeper. Deltopectoral is the landmark site; the axillary vein there is deeper and smaller.");
q('Practice',35,'vasc',1,"A 26-year-old with chest and left calf pain after an 8-hour drive has a positive D-dimer. What do the left-leg ultrasound images demonstrate?",["Popliteal thrombus","SFV thrombus","CFV thrombus","No evidence of thrombus"],3,"Full compression = no clot at that site. Limits: two-point misses the femoral (superficial femoral) vein — a deep vein despite its name. Adequate compression should deform the artery. Embolization risk from compression is low.");
q('Practice',41,'vasc',1,"Which structure is visualized in the groin video shown?",["CFV","Superficial femoral artery","Deep femoral artery","Great saphenous vein"],3,"At the groin the GSV enters the CFV (saphenofemoral junction); just distal, the CFA divides into superficial and deep femoral arteries.");
q('Practice',43,'vasc',1,"A 19-year-old with sore throat, sweats, dyspnea, diarrhea and fever 40 \u00b0C: BP 87/42, HR 97, warm skin, lactate 2.7, WBC 13,000, creatinine 1.5, bilirubin 5.2. CT: small basal ground-glass nodules and periportal/mesenteric edema. Most probable source of infection?",["Intraabdominal","Intravascular","Pulmonary","Pleural"],1,"Lemierre syndrome: septic IJ thrombophlebitis after pharyngitis (Fusobacterium necrophorum) with septic emboli.");
q('Practice',49,'vasc',1,"What does the popliteal fossa video shown identify?",["Normal compression","Abnormal compression","Inadequate compression","Unclear"],1,"Adequate pressure (artery deforms) with a non-compressible vein = DVT.");
q('Practice',70,'vasc',1,"After percutaneous right common femoral arterial access, a trauma patient has a palpable groin mass, a diminished distal pulse and leg numbness. The ultrasound is shown. Which is true?",["Can be treated non-surgically","Shows an AV communication","Frequently causes arterial thrombosis","Will not resolve without treatment"],0,"Pseudoaneurysm: yin-yang color, to-and-fro neck flow. Treat with US-guided compression or thrombin injection; observation if <3 cm. AV fistula = turbulent flow between artery and vein.");
q('Practice',125,'vasc',0,"Why is visualizing the great saphenous vein important?",["It marks where to start scanning","Proximal GSV clot is treated like a DVT","It identifies the CFA and CFV","All of the above"],1,"Clot near the saphenofemoral junction readily propagates into the CFV, so it's managed as DVT.");
q('Practice',127,'vasc',1,"A 64-year-old with acute dyspnea: per the clip shown, how is her compression test best characterized?",["Adequate, identifies DVT","Adequate, rules out DVT","Inadequate study","Cannot evaluate"],2,"Without enough pressure to deform the artery, non-compression cannot be called DVT.");

// 3.6 FAST, abdominal & airway
q('Practice',6,'abd',1,"A 65-year-old in an MVC is hypotensive despite fluids; chest and pelvis films are normal. A FAST image is shown. Which statement is true?",["Rules out splenic injury","Repeating FAST improves detection","Rules out retroperitoneal injury","Fluid is most likely seen in the LUQ"],1,"FAST is specific (>90%) but variably sensitive; repeating it in hypotensive patients raised sensitivity from 31% to 72%. RUQ (Morison's pouch) is the most common site of fluid. FAST cannot assess the retroperitoneum.");
q('Practice',21,'abd',1,"A 23-year-old ICU patient is evaluated for AKI and this ultrasound is obtained. Which statement is true?",["No hydronephrosis","Hydronephrosis is uncommon in ICU patients","No more imaging needed","Surgery is required"],1,"Post-renal causes are <5% of hospital AKI. CT is more sensitive for stones/obstruction; most ureteral stones pass spontaneously.");
q('Practice',32,'abd',1,"An abdominal ultrasound in suspected small bowel obstruction is shown. Which is true?",["Peristalsis is reassuring","Free air is concerning","Free fluid is concerning","Normal diameter rules out obstruction"],2,"Free fluid between loops in SBO suggests strangulation/ischemia. Loss of peristalsis is late; distal decompressed bowel can look normal.");
q('Practice',33,'abd',1,"A 55-year-old in coma from ICH (history of neck radiation) is undergoing difficult intubation. Based on the airway ultrasound video, best next step?",["Ventilate","Chest tube","Reposition the ETT","Move the cric needle medially"],2,"'Double tract sign' = esophageal intubation (esophagus usually left of trachea). Real-time tracheal US detected 100% tracheal and 83% esophageal intubations (Arya).");
q('Practice',59,'abd',1,"After an MVC, FAST is performed. Pulse 80, BP 100/66. Based on the image, next best step?",["Surgery","DPL","CT abdomen/pelvis","Discharge"],2,"Hemodynamically normal with positive FAST → CT to grade solid-organ injury and find others. Unstable + positive FAST → OR.");
q('Practice',75,'abd',1,"A 70-year-old admitted after syncope becomes hypotensive in the ICU. The abdominal ultrasound is shown. Which is correct?",["A negative FAST does not rule out rupture","Internal diameter is most important","This doesn't explain hypotension","External diameter is unnecessary"],0,"~95% of ruptures are retroperitoneal, invisible to FAST. Measure outer wall to outer wall (≥3 cm aneurysm).");
q('Practice',140,'abd',1,"A 23-year-old with multiple gunshot wounds to abdomen and chest: HR 110, BP 80/30, RR 32, SpO2 97%. FAST images are shown. Next best step?",["CT","Emergent laparotomy","Serial FAST","Wait for labs"],1,"Unstable penetrating trauma → OR. FAST is specific but not sensitive; don't delay.");
q('Practice',141,'abd',0,"A hemodynamically normal woman stabbed in the lower left chest has a negative FAST (no fluid, no effusion). True?",["FAST has a high false-negative rate in penetrating trauma","A negative FAST rules out bowel injury","FAST shouldn't be used for cardiac injury","FAST reliably identifies diaphragm injury"],0,"Penetrating: sensitivity 28–100%, specificity 94–100% → can't rule out. Cardiac views are excellent (90–100%) and speed time to OR. US can't see diaphragm or hollow-viscus injury reliably.");
q('Practice',143,'abd',1,"A 63-year-old with scleroderma, a week of vomiting, severe dyspnea (RR 36, SpO2 93% on FiO2 1.0, BP 90/55) and right pneumonia needs intubation. A PLAX clip is shown. Best next step before intubation?",["Fluid bolus","Pericardiocentesis","NG tube","Norepinephrine","Inotrope"],2,"Gastric ultrasound showing a full stomach → decompress to reduce aspiration risk.");

const LN={};function L(lec,t,d,stem,opts,ans,exp){const n=LN[lec]=(LN[lec]||0)+1;let s=lec*1009+n*7919;const r=()=>(s=(s*16807)%2147483647)/2147483647;const idx=opts.map((_,i)=>i);for(let i=idx.length-1;i>0;i--){const j=Math.floor(r()*(i+1));[idx[i],idx[j]]=[idx[j],idx[i]]}Q.push({src:'Lecture',lec,n,t,d,stem,opts:idx.map(i=>opts[i]),ans:idx.indexOf(ans),exp});}
// Lecture 2 — Fundamentals of Physics & Knobology
L(2,'phys',1,"A 4 MHz phased-array probe images soft tissue (c = 1540 m/s). What is the wavelength?",["0.039 mm","0.385 mm","3.85 mm","6.16 mm"],1,"λ = c/f = 1540 / 4,000,000 = 0.000385 m = 0.385 mm. Image resolution is no better than 1–2 wavelengths; penetration depth is directly related to wavelength.");
L(2,'phys',1,"Which property of an ultrasound wave is determined only by the sound source and is NOT changed by the tissue it travels through?",["Propagation velocity","Frequency","Wavelength","Attenuation"],1,"Frequency is set by the transducer; to change it substantially you change probes. Propagation speed depends on the medium (bone 2000–4000, lung 300–1200, soft tissue 1540 m/s), and wavelength = c/f changes with it.");
L(2,"phys",2,"You want to improve AXIAL resolution of a structure lying along the beam. Most effective change?",["Narrow the sector to raise the frame rate","Decrease the depth so the target sits higher","Switch to a higher-frequency transducer","Increase overall gain to brighten the structure"],2,"Axial resolution (two structures parallel to the beam) improves with higher frequency/shorter pulse. Lateral resolution: higher frequency, optimal focal zone, minimal gain. Temporal resolution: narrower sector and less depth (higher frame rate).");
L(2,'phys',2,"Imaging depth is increased from 12 cm to 20 cm. What happens to the pulse repetition period (PRP) and PRF?",["PRP ↓, PRF ↑","PRP ↑, PRF ↓","Both unchanged","PRP ↑, PRF ↑"],1,"Deeper imaging = longer listening time → longer PRP → lower PRF. PRF is determined by imaging depth only, not by transducer frequency. Lower PRF → lower Nyquist limit and lower frame rate.");
L(2,'phys',2,"In tissue harmonic imaging with a 2 MHz transmit frequency, the displayed image is formed from echoes at:",["1 MHz","2 MHz","4 MHz","8 MHz"],2,"Second harmonic = twice the transmitted frequency. Harmonics are generated in the tissue (not the transducer); improves endocardial border definition.");
L(2,"phys",2,"Which statement about ultrasound bioeffects is correct?",["Thermal effects are greatest with plain B-mode imaging at any depth","Mechanical index rises as the transmit frequency is increased","MI rises with peak rarefaction pressure and lower frequency","Cavitation cannot occur at any diagnostic power setting used"],2,"MI = peak rarefaction pressure / √frequency → higher with more negative rarefaction pressure and lower frequency. Thermal effects are most prevalent with spectral and color Doppler. The eye is the most susceptible organ.");
L(2,'dop',2,"Which Doppler mode measures velocity at a specific location but is limited by aliasing above about 2 m/s?",["Continuous-wave","Pulsed-wave","Color M-mode","Tissue Doppler only"],1,"PW is range-specific (sample gate) but limited by the Nyquist limit (PRF/2). CW samples every velocity along the beam (range ambiguous) with no velocity limit, giving a filled-in envelope; PW gives a 'hollow' crisp envelope.");
L(2,'dop',1,"Tissue Doppler differs from blood-flow PW Doppler because it is filtered to detect signals that are:",["High velocity, low amplitude","Low velocity, high amplitude","High velocity, high amplitude","Low velocity, low amplitude"],1,"Myocardium moves slowly and reflects strongly ('slow and loud'); blood is 'fast and quiet'. Uses: e' and a' for diastolic function, RV s' for RV systolic function.");
L(2,'dop',2,"To evaluate a suspected PFO with color Doppler, the color scale (Nyquist) should be:",["Raised to 80–90 cm/s","Kept at 55–65 cm/s","Lowered to about 20 cm/s","Set to zero baseline shift"],2,"Interatrial shunt flow is low velocity; reduce the scale (~20 cm/s) to display it. 50–70 cm/s (ASE 2017) is standard for valve regurgitation. Color also lowers frame rate—narrow the color box/sector.");
L(2,'hemo',2,"Qp:Qs is calculated as:",["(CSA_LVOT × VTI_LVOT) / (CSA_PA × VTI_PA)","(CSA_PA × VTI_PA) / (CSA_LVOT × VTI_LVOT)","VTI_PA / VTI_LVOT","(VTI_LVOT × HR) / (VTI_PA × HR)"],1,"Qp = pulmonary (RV) stroke volume = CSA_PA × VTI_PA; Qs = systemic (LV) stroke volume = CSA_LVOT × VTI_LVOT. Continuity principle: A1V1 = A2V2.");
L(2,"phys",3,"Which is a current (2018 ASE) contraindication to ultrasound-enhancing agents (microbubble contrast)?",["Acute coronary syndrome within the last week","Moderate pulmonary hypertension","Known hypersensitivity to the agent","Mechanical ventilation with high PEEP"],2,"Remaining contraindications: hypersensitivity (anaphylactoid reactions <1/10,000); older cautions about ACS, MI, PH and critical illness were removed. For contrast imaging lower the MI and power, adjust focus, increase gain/dynamic range.");

// Lecture 3 — Concepts of Imaging, Artifacts & Knobology
L(3,'art',2,"Artifacts arise when a basic ultrasound assumption is violated. Which artifact violates the assumption that echoes originate only from objects on the transducer axis?",["Reverberation","Side lobe","Acoustic enhancement","Range ambiguity"],1,"Off-axis echoes: side lobe, beam width, slice thickness. Sound not travelling in straight lines: refraction/reflection. Travel time not just distance: reverberation, mirror image. Brightness not just scatter: near-field clutter, shadowing, enhancement. Echo from previous pulse: range ambiguity.");
L(3,"art",2,"On M-mode, a suspected linear echo inside the LA appears as lines at equal spacing, fading with depth and moving exactly with the structure in front of it. This is:",["Layered thrombus","Reverberation","Side-lobe artifact","Beam-width artifact"],1,"Reverberation: copies at equal intervals (multiples of the reflector depth), decreasing intensity, no independent motion. Classic examples: LAA 'ridge' copies on TEE, comet tails.");
L(3,"art",2,"A TEE in a patient with a St Jude MVR shows an apparent jet in the mid-LV that has the same timing and Doppler profile as a paravalvular MR jet. Most likely explanation?",["Gerbode (LV-to-RA) shunt through the septum","Ruptured sinus of Valsalva aneurysm","Muscular ventricular septal defect","Mirror artifact of the paravalvular MR"],3,"Strong reflectors (mechanical valves, pericardium/pleura) produce mirror images in 2D, color, PW and CW. Confirm with off-axis or other planes.");
L(3,'art',2,"Which technique most reduces side-lobe artifact and near-field clutter?",["Fundamental imaging at higher gain","Tissue harmonic imaging","Increasing sector width","Raising the mechanical index"],1,"Second-harmonic echoes have much lower side lobes and suppress near-field reverberation. Also: optimize TGC, focus, frequency, depth; use contrast for apical clutter.");
L(3,'art',1,"Increased echo brightness distal to a fluid-filled structure such as the descending aorta on TEE is called:",["Acoustic shadowing","Acoustic enhancement","Reverberation","Refraction"],1,"Enhancement occurs behind low-attenuation media (fluid). Shadowing (dropout) occurs behind strongly attenuating/reflecting structures such as calcified plaque or prosthetic valves.");
L(3,"art",2,"An apparent apical LV 'thrombus' is hazy, does not move with the wall and sits in the near field. Best next step?",["Start full-dose anticoagulation now and repeat in a week","Use contrast, harmonics and focus/TGC to exclude clutter","Repeat a limited TTE in about 6 months to reassess","Proceed to TEE immediately before any other step"],1,"Near-field clutter mimics apical thrombus. Move the focus up, use harmonics, adjust TGC/depth, and give an ultrasound-enhancing agent; a real thrombus shows a filling defect with contrast.");
L(3,"views",1,"Which structures are better imaged by TEE than TTE?",["LV apex, RV free wall and the anterior pericardium","Tricuspid and pulmonic valves in long and short axis","LAA, mitral valve, atrial septum and aorta","Pericardium lying anterior to the RV free wall"],2,"TEE images from posterior: LA/LAA, MV, IAS, thoracic aorta. TTE images from anterior: LV, RV, TV, AV, PV.");
L(3,"art",2,"CW Doppler of the tricuspid regurgitant jet in a patient with mitral stenosis shows an unusually high-velocity diastolic signal. Most likely cause?",["Severe torrential tricuspid regurgitation","Severe pulmonary hypertension raising TR velocity","The CW beam also crosses the mitral stenosis jet","Aliasing of the TR signal at high velocity"],2,"CW is range-ambiguous: it records every velocity along the beam, so an adjacent jet (MS) can be superimposed. Confirm with timing and alternative windows.");
L(3,"phys",1,"Which knob change compensates for attenuation with depth while leaving the near field unchanged?",["Overall (master) gain","Time gain compensation","Dynamic range / compression","Sector width"],1,"TGC sliders amplify signal at selected depths. Overall gain affects every depth equally.");
L(3,"art",1,"Bright, irregular streaks that suddenly fill the image during surgery or appear with an LVAD are due to:",["Side-lobe artifact from a strong nearby reflector","Electrical interference (electrocautery/device)","Refraction of the beam through the sternum","Mirror image created behind the pleural line"],1,"Electrocautery (Bovie) and devices such as an HVAD cause electrical interference artifact—not anatomy.");

// Lecture 4 — Normal Transthoracic Exam
L(4,'views',1,"In the ASE nomenclature, changing the angle of the probe in the SAME imaging plane (moving the beam toward the index mark side) without moving the probe position is called:",["Tilting","Rocking","Rotating","Sliding"],1,"Rocking = angling within the plane toward/away from the indicator. Tilting (fanning) = angling across the plane (out of plane). Rotating = turning about the probe axis. Sliding = moving the probe to a new skin location.");
L(4,'views',1,"From the parasternal long-axis view, which manoeuvre gives the parasternal short-axis view?",["Rotate 90° clockwise","Rotate 90° counter-clockwise","Slide one space down","Tilt the tail down"],0,"PLAX indicator toward the right shoulder; rotate ~90° clockwise (indicator to left shoulder) for PSAX. Then tilt from base (AV) to MV, papillary and apical levels.");
L(4,"views",2,"Where should the PW sample volume be placed to measure LVOT VTI?",["At the aortic valve leaflet tips, inside the jet core","3–5 mm gate just on the LV side of the aortic valve","In the mid-LV cavity below the mitral leaflet tips","In the proximal ascending aorta above the sinuses"],1,"Apical 5- or 3-chamber view, 3–5 mm gate in the LVOT just proximal to the flow-acceleration zone; good signal shows a narrow, smooth envelope; trace the modal (densest) velocity.");
L(4,'views',1,"Which TTE view is used to image the aortic arch and its branches?",["Subcostal long axis","Suprasternal notch","Right parasternal","Apical 3-chamber"],1,"Suprasternal notch: arch, brachiocephalic, left carotid and left subclavian take-offs, descending aorta (coarctation, dissection, holodiastolic reversal in AR).");
L(4,"views",2,"Which view best shows the RV outflow tract and pulmonic valve in long axis?",["PLAX tilted toward the left shoulder (RVOT view)","Apical 2-chamber with a slight anterior tilt","Subcostal long-axis view of the IVC and hepatic veins","Apical 3-chamber (apical long-axis) view"],0,"From PLAX tilt anteriorly/superiorly toward the left shoulder for the RV outflow view (RVOT, PV, main PA). Also seen in basal PSAX.");
L(4,"views",2,"Which structures are seen in the apical 3-chamber (apical long-axis) view?",["RA, RV, LA and LV with both atrioventricular valves","LA, LV, LVOT/aortic valve; anteroseptum, inferolateral","LA, LV and the LA appendage; anterior and inferior walls","RV, RA, IVC and coronary sinus; RV free wall only"],1,"A3C ≈ apical PLAX: anteroseptal and inferolateral walls, LVOT, AV. A2C: anterior and inferior walls. A4C: inferoseptum and anterolateral wall.");
L(4,"views",1,"In the apical 4-chamber view, PW Doppler of the pulmonary veins is usually recorded from:",["Coronary sinus, ~1 cm from its RA ostium","Right upper pulmonary vein, ~1 cm into the vein","Left lower pulmonary vein at its ostium into the LA","IVC at the RA junction"],1,"The right upper pulmonary vein is most aligned with the beam in A4C; sample 1–2 cm into the vein for S, D and Ar waves.");
L(4,'views',2,"Doppler principle: when a reflector moves TOWARD the transducer, the received frequency is:",["Lower, wavelength longer","Higher, wavelength shorter","Unchanged","Lower, wavelength shorter"],1,"Motion toward the transducer compresses the wave → higher frequency, shorter wavelength (positive shift, displayed above baseline). Away → lower frequency (below baseline).");

// Lecture 5 — Transesophageal Echocardiography Views
L(5,'views',1,"TTE is estimated to be inadequate in roughly what proportion of mechanically ventilated ICU patients?",["10%","25%","50%","90%"],2,"~50% of ventilated patients have inadequate TTE windows (obesity, anasarca, post-sternotomy, open chest, subcutaneous emphysema, hyperinflation, chest trauma). TEE adds unexpected diagnoses in up to 40%.");
L(5,"views",2,"For which assessment is TTE generally SUPERIOR to TEE?",["Left atrial appendage thrombus","Thoracic aortic dissection flap","TR velocity and the LV apex","Localized post-cardiotomy tamponade"],2,"TEE is inferior for chamber quantification, LV apex, IVC, pulmonic valve, TR velocity (alignment) and global pericardial effusion. TEE wins for aorta, MV, pulmonary veins, LAA, SVC, IAS, central PE and localized tamponade.");
L(5,'views',2,"Best estimate of upper GI perforation risk from TEE?",["1 in 50","1 in 500","1 in 5,000","1 in 500,000"],2,"Overall complication ~1/500 (ambulatory); perforation ~1/5,000; major GI bleeding ~1%. Most injuries occur at the hypopharynx/upper esophagus.");
L(5,'views',1,"Which TEE control flexes the probe tip anteriorly/posteriorly (anteflexion/retroflexion)?",["Advancing/withdrawing the probe","Large wheel","Small wheel","Rotating the whole probe"],1,"Large wheel = anteflexion/retroflexion (direction of turn varies by probe model and viewpoint — check your probe). Small wheel = left/right lateral flexion. Keep wheels unlocked during insertion; use a bite guard, jaw thrust, slight anteflexion around the tongue base.");
L(5,'views',2,"In mid-esophageal TEE views, which chamber lies closest to the probe (top of the sector)?",["Right atrium","Left atrium","Left ventricle","Right ventricle"],1,"The LA sits directly anterior to the esophagus. Other rules: ascending aorta and PA are perpendicular; ascending aorta and SVC are parallel; anterior is opposite inferior; septal is opposite lateral.");
L(5,"views",2,"The mid-esophageal 4-chamber view corresponds to which TTE view, and which LV walls does it show?",["PLAX; anteroseptal and inferolateral walls","Apical 4-chamber; inferoseptal and anterolateral","Apical 2-chamber; anterior and inferior LV walls","PSAX; all six mid-ventricular LV segments"],1,"ME 4C ≈ A4C: inferoseptum and anterolateral wall. ME 2C ≈ A2C: anterior and inferior (coronary sinus seen). ME LAX ≈ PLAX/A3C: anteroseptal and inferolateral.");
L(5,'views',2,"Which TEE view shows the SVC, IVC, interatrial septum (fossa ovalis), Eustachian valve and RA appendage?",["ME aortic valve short axis","ME bicaval","Transgastric mid SAX","UE aortic arch"],1,"ME bicaval (~90–110°): SVC on the right of screen, IVC on the left, IAS — used for PFO/bubble studies, ECMO cannula positioning, SVC collapsibility.");
L(5,"views",2,"The transgastric mid-papillary short-axis TEE view is most useful for:",["Aortic valve gradients and continuity valve area","Rapid global/regional LV function and filling","PFO and interatrial septum bubble assessment","Descending thoracic aorta and dissection flaps"],1,"TG mid SAX ≈ PSAX papillary level: all three coronary territories, LV size/filling and global function — the core monitoring view in shock.");
L(5,"views",1,"During cardiac arrest, TEE compared with TTE is associated with:",["Longer compression pauses during each pulse check","Shorter pauses and continuous imaging during CPR","Higher rates of airway and esophageal trauma overall","Inability to assess compression quality or depth"],1,"TEE images continuously during compressions, shortens pauses (Fair 2019), and can guide hand position (area of maximal compression).");

// Lecture 6 — LV Systolic Function
L(6,"lv",1,"Which method does the ASE recommend for calculating LVEF on 2D echo?",["Teichholz formula from M-mode LV dimensions","Fractional shortening from PLAX diameters","Biplane method of disks (modified Simpson's)","E-point septal separation (EPSS) from M-mode"],2,"Trace end-diastolic and end-systolic endocardium in A4C and A2C; disks are summed. ASE does not recommend EF from linear measurements (Teichholz assumes a symmetric ellipsoid LV without RWMA).");
L(6,'lv',1,"LVEDD 55 mm, LVESD 41 mm. Fractional shortening?",["14%","25%","34%","41%"],1,"FS = (LVEDD − LVESD)/LVEDD = (55 − 41)/55 = 25%. Normal ≈ 25–45%. Measure in PLAX at the mitral leaflet tips, perpendicular to the LV long axis.");
L(6,'lv',2,"According to ASE 2015, an LVEF of 38% is classified as:",["Normal","Mildly reduced","Moderately reduced","Severely reduced"],2,"ASE 2015: normal 52–72% (men) / 54–74% (women); mildly abnormal 41–51% (men) / 41–53% (women); moderately abnormal 30–40%; severely abnormal < 30%.");
L(6,'lv',2,"Which EPSS value is associated with severe LV dysfunction (EF < 30%) in the ED/ICU literature?",["> 2 mm","> 4 mm","> 7 mm","> 15 mm"],2,"EPSS >7 mm → EF <30% (McKaigney 2014). Measure on M-mode in PLAX at the anterior leaflet tip. Invalid with MS, AR jets, or regional WMA.");
L(6,'lv',2,"MAPSE greater than which value in a woman correlates with EF > 55%?",["> 7 mm","> 9 mm","> 11 mm","> 15 mm"],2,"MAPSE ≥11 mm (women) and ≥13 mm (men) indicate normal EF (>55%); <6 mm (either sex) indicates severely reduced EF (Matos, JASE 2012). M-mode through the lateral mitral annulus in A4C.");
L(6,'lv',1,"Normal LV fractional area change (FAC) in parasternal short axis is approximately:",["10–20%","20–30%","35–65%","70–90%"],2,"FAC = (EDA − ESA)/EDA × 100; normal ≈ 35–65%.");
L(6,'lv',2,"Foreshortening of the LV apex in apical views causes:",["Overestimation of LV volumes","Underestimation of LV volumes","No change in volumes","Overestimation of EF only"],1,"Foreshortening → underestimates volumes. Endocardial dropout → overestimates volumes. Tachycardia can make qualitative function look better; bradycardia worse.");
L(6,"lv",2,"Septal and inferolateral wall thickness are measured:",["At end-systole at the papillary muscle level","At end-diastole at the mitral leaflet tips in PLAX","At end-systole just below the aortic valve annulus","At any cardiac phase in the apical 4-chamber view"],1,"PLAX, perpendicular to the LV long axis at the mitral leaflet tips, at end-diastole, by 2D or M-mode.");
L(6,"hemo",2,"When calculating stroke volume from LVOT diameter, the largest source of error is:",["Tracing the LVOT VTI envelope at the modal velocity","Beat-to-beat variation in heart rate","LVOT diameter, as the radius is squared","A Doppler intercept angle of 10° to flow"],2,"CSA = π r² so any diameter error is squared. Zoom, reduce depth, measure inner edge to inner edge at the annulus in mid-systole.");
L(6,"lv",3,"An ICU patient with a known home EF of 35% now has an EF of 40–45% while hypovolemic and on norepinephrine. The key question for the intensivist is:",["Whether Simpson's EF should be repeated every day","Whether reduced function drives current instability","Whether the EF has now returned to its normal range","Whether any further echo adds information at all"],1,"Critical care echo describes the current loading state (SVR, catecholamines, PEEP, volume, acidemia, arrhythmia), not chronic function. EF and SV are only part of the story.");

// Lecture 7 — LV Diastolic Function
L(7,'dia',1,"Diastole is defined physiologically as the interval from:",["Mitral valve closure to aortic valve opening","Aortic valve closure to mitral valve closure","Mitral valve opening to the P wave","QRS onset to T-wave end"],1,"Diastole runs from AV closure to MV closure: isovolumic relaxation, rapid filling (E), diastasis, atrial contraction (A). Determined by active relaxation and chamber stiffness plus loading conditions.");
L(7,"dia",2,"Before applying Doppler criteria, which 2D finding alone implies impaired LV relaxation is present?",["Normal EF with no LVH and a normal LA volume index","EF <50%, regional WMA, or pathologic concentric LVH","A dilated, non-collapsing IVC on the subcostal view","A small LA volume index below 34 mL/m² in sinus rhythm"],1,"If EF <50%, RWMA or pathologic LVH is present, relaxation is impaired (~100%) — go straight to the filling-pressure algorithm (E/A, E, E/e', TR, LAVI).");
L(7,"dia",2,"LA volume index > 34 mL/m² is found in > 90% of patients with diastolic dysfunction but is NOT specific because it also occurs with:",["Hypovolemia with low LV filling pressures","AF, high output, athletes, mitral disease","Acute myocardial infarction only","Pericardial effusion without tamponade physiology"],1,"LA size reflects chronic exposure to high LAP; enlargement also from AF, high CO (liver failure), athletic heart, MR/MS.");
L(7,"dia",2,"Impaired relaxation (abnormal LV): mitral E/A 1.2, E 85 cm/s. Average E/e' 16, TR 3.0 m/s, LAVI 40 mL/m². Classification?",["Normal LAP, grade I dysfunction","Elevated LAP, grade II dysfunction","Grade III (restrictive) dysfunction","Indeterminate LAP and grade"],1,"E/A 0.9–1.9 (or ≤0.8 with E >50) → apply 3 criteria (E/e' >14, TR >2.8, LAVI >34). ≥2 positive = elevated LAP, grade II. E/A ≥2 = grade III. E/A ≤0.8 with E ≤50 = grade I, normal LAP.");
L(7,"dia",2,"Impaired relaxation; mitral E/A 0.7 with E 45 cm/s. Interpretation?",["Grade I DD with normal LAP","Grade II DD (pseudonormal)","Grade III DD (restrictive)","Indeterminate; need more data"],0,"E/A ≤0.8 and E ≤50 cm/s = grade I (impaired relaxation) with normal mean LAP; no further criteria needed.");
L(7,"dia",2,"Mitral E/A 2.3 in a patient with EF 25%. Classification?",["Normal diastolic function","Grade I (impaired relaxation)","Grade II (pseudonormal)","Grade III (restrictive)"],3,"E/A ≥2 with reduced EF = grade III, elevated LAP (short DT, high E). Mean LAP ≥15 mm Hg.");
L(7,"dia",1,"Average E/e' < 8 and > 15 predict which mean PCWP values, respectively?",["Elevated; normal","Normal; elevated","Normal; normal","Elevated; elevated"],1,"E/e' <8 → normal PCWP; >15 → elevated PCWP (Nagueh). ASE 2016 uses average E/e' >14 as abnormal.");
L(7,"dia",3,"A 78-year-old on BiPAP with diffuse infiltrates: LVEF 47%, E 55 cm/s, e' 8 cm/s, TR Vmax 2.6 m/s, BNP 180. Is IV diuresis supported by echo?",["Yes: E/e' indicates high LAP and cardiogenic edema","No: E/e' ≈6.9 and TR 2.6 m/s mean normal LAP","Yes: an EF below 50% implies LV volume overload","Cannot be judged at all while the patient is on BiPAP"],1,"E/e' 55/8 ≈ 7 and TR <2.8 → normal filling pressures; diagnosis was COPD/cancer/pneumonia, not pulmonary edema.");
L(7,'dia',3,"A 59-year-old with class IV HFrEF in the CCU: E 30 cm/s with E/A < 1, average E/e' 5, normal LAVI, SV 19.7 mL, CO 1.6 L/min. Worst treatment choice?",["Milrinone","IABP","Fluids","Diuretics"],3,"Filling pressures are low (grade I pattern, E/e' 5) with very low output → diuresis would worsen output. Needs inotrope/mechanical support; cautious fluid may help.");
L(7,"dia",2,"Which conditions limit the accuracy of the ASE diastolic algorithm?",["Sinus tachycardia only, above 100 beats per minute at rest","AF, significant MAC, regional e' variation, constriction","A normal ejection fraction above 55% with no LVH","Young age with brisk e' velocities and a small LA"],1,"AF (no A wave), MAC/MV disease, regional WMA affecting septal vs lateral e', pericardial constriction (annulus reversus) all confound the algorithm.");

// Lecture 8 — Evaluation of the Right Ventricle
L(8,'rv',1,"Qualitatively, an RV that is larger than 2/3 of the LV but still smaller than the LV in A4C is:",["Normal","Mildly enlarged","Moderately enlarged","Severely enlarged"],1,"Normal RV <2/3 LV; mild >2/3 but <LV; moderate RV = LV; severe RV >LV.");
L(8,'rv',2,"Which RV inflow dimension in an RV-focused A4C indicates RV dilation?",["Basal diameter > 41 mm","Basal diameter > 28 mm","Longitudinal diameter > 60 mm","Mid diameter > 20 mm"],0,"Dilation: basal >41 mm, mid >35 mm, longitudinal >83 mm (ASE/EACVI 2015). RVOT: PLAX > 30 mm, proximal (PSAX) > 35 mm, distal > 27 mm also abnormal.");
L(8,"rv",2,"RV free-wall thickness of 7 mm (subcostal, end-diastole) indicates:",["Normal RV free-wall thickness for an adult","RV hypertrophy (chronic pressure overload or infiltration)","Acute cor pulmonale from a large pulmonary embolus","A small pericardial effusion mimicking a thickened RV free wall"],1,">5 mm = RVH (>10 mm severe) → suggests chronic process (chronic PH, infiltrative/restrictive CM). Acute PE gives a dilated thin-walled RV.");
L(8,'rv',2,"Which combination best indicates ACUTE rather than chronic RV failure?",["RVH > 5 mm, RA dilated, preserved function","Dilated thin-walled RV, RVSP < 60 mm Hg, no RVH","RVSP 85 mm Hg with RVH","Dilated RA only"],1,"A normal RV cannot acutely generate >~60 mm Hg; chronic disease shows RVH, RA dilation and often RVSP >60.");
L(8,"rv",1,"TAPSE threshold suggesting RV systolic dysfunction (M-mode, lateral tricuspid annulus, A4C):",["< 25 mm","< 20 mm","< 16–17 mm","< 10 mm (only)"],2,"TAPSE <17 mm (lecture uses <16) = dysfunction. Other cutoffs: RV FAC <35%, tissue Doppler s' <9.5 cm/s.");
L(8,'rv',2,"In a spontaneously breathing patient the IVC is 1.8 cm and collapses < 50% with sniff. Estimated RAP?",["3 mm Hg (0–5)","8 mm Hg (5–10)","15 mm Hg (10–20)","Cannot estimate"],1,"Small IVC + good collapse → 3; large + poor collapse → 15; mixed (either abnormal) → 8 mm Hg.");
L(8,'rv',3,"In a mechanically ventilated patient, which IVC finding reliably predicts RAP < 10 mm Hg?",["IVC collapse > 50%","IVC diameter < 12 mm","IVC > 2.1 cm","IVC distensibility > 18%"],1,"With positive pressure the IVC is largest at end-inspiration and collapsibility doesn't track RAP; IVC <12 mm is ~100% specific for RAP <10 (Jue 1992). A large IVC is NOT predictive.");
L(8,'rv',3,"Tricuspid E/e' (lateral tricuspid annulus) of ≥ 4.7 in septic patients predicts:",["RAP < 5 mm Hg","RAP ≥ 10 mm Hg","PCWP > 18","Fluid responsiveness"],1,"Tricuspid E/e' ≥4.7 predicted CVP ≥10 mm Hg with sensitivity 85% and specificity 90% — better than IVC size/collapse (Arbo 2013).");
L(8,'rv',2,"Peak TR velocity 4.04 m/s with RAP 15 mm Hg. RVSP?",["31 mm Hg","50 mm Hg","80 mm Hg","95 mm Hg"],2,"4 × 4.04² ≈ 65 + 15 = 80 mm Hg. Normal PASP ≤35 mm Hg and TR Vmax <2.8–2.9 m/s.");
L(8,"rv",2,"Which surgical factor is most associated with RV dysfunction after cardiac surgery?",["Off-pump CABG with brief cardiac manipulation","Bypass >150 min, poor protection, RCA air embolism","Mitral valve repair with a short bypass time","Late deep sternal wound infection after the operation"],1,"Risk factors: pre-existing RV dysfunction, prolonged CPB, air to the anteriorly placed RCA, inadequate cardioplegia, LVAD insertion (~11%), transplant (graft dysfunction).");
L(8,"rv",2,"After cardiac arrest, which finding independently predicts poor outcome regardless of LV function?",["A hyperdynamic LV after ROSC","RV dysfunction after resuscitation","A small, collapsing IVC after ROSC","A normal RV systolic pressure"],1,"Post-ROSC RV dysfunction predicts poor outcome independent of LV function (Ramjee 2015).");

// Lecture 9 — Preload & Fluid Responsiveness
L(9,"fluid",1,"Which statement is correct?",["Fluid responsiveness means fluid should always be given","Preload values (LVEDA, CVP) predict fluid responsiveness","Ask: is the patient responsive, is fluid indicated, tolerated?","An IVC diameter above 10 mm reliably excludes responsiveness"],2,"Preload ≠ preload responsiveness; fluid responsiveness ≠ give fluid; fluid responsive ≠ fluid tolerant. Static measures help only at extremes or serially.");
L(9,"fluid",2,"Which patient is best suited for stroke-volume (LVOT velocity) variation?",["ARDS on 6 mL/kg, paralysed with cisatracurium infusion","COPD on BiPAP with active expiration and air trapping","Overdose on 8 mL/kg, sedated but pulling against restraints","Post-arrest, passive 10 mL/kg, sinus bradycardia","Mobitz II on high-flow oxygen with cardiac tamponade"],3,"SVV needs passive ventilation, Vt 8–10 mL/kg, normal compliance, regular rhythm, closed chest, normal abdominal pressure, HR/RR >3.6. Spontaneous effort/arrhythmia → false positives; low Vt/low compliance/open chest → false negatives.");
L(9,"fluid",2,"Which condition causes a FALSE NEGATIVE stroke-volume variation test?",["Spontaneous breathing efforts","Atrial fibrillation with irregular RR","Low tidal volume / low compliance","Raised intra-abdominal pressure"],2,"False negatives: low Vt, low compliance, open chest, very high RR (HR/RR <3.6). False positives: spontaneous breaths, arrhythmias, intra-abdominal hypertension, RV failure.");
L(9,'fluid',2,"In a passively ventilated septic patient, which threshold of IVC distensibility (ΔIVC/IVCmin) predicted fluid response (Barbier 2004)?",["> 5%","> 18%","> 50%","> 80%"],1,"Barbier: ΔIVC/IVCmin >18%. Feissel: ΔIVC/IVCmean >12%. SVC collapsibility (TEE) >36% (Vieillard-Baron).");
L(9,'fluid',2,"With positive-pressure inspiration, the IVC and SVC behave how?",["IVC collapses, SVC distends","IVC distends, SVC collapses","Both collapse","Both distend"],1,"Positive pressure raises pleural/RA pressure: IVC (extrathoracic) distends, SVC (intrathoracic) collapses. Spontaneous inspiration: IVC collapses, SVC distends.");
L(9,'fluid',2,"Which condition makes IVC collapsibility FALSELY NEGATIVE (plethoric IVC despite fluid responsiveness)?",["Extreme inspiratory effort in asthma","Tamponade, RV infarction or severe TR","Lateral displacement of the IVC","Spontaneous breathing"],1,"False negatives: tamponade, RV dysfunction/infarct, severe TR, hyperinflation. False positives: extreme effort (COPD/asthma), lateral displacement of the IVC (cylinder effect). Abdominal hypertension and ECMO cannulas confound.");
L(9,"fluid",1,"Passive leg raise transfers roughly how much blood toward the heart?",["About 50 mL","About 300 mL","About 1000 mL","About 2000 mL"],1,"PLR autotransfuses ~300 mL (reversible). Positive response = ≥10–15% rise in CO/SV/VTI within 1 min. Works with spontaneous breathing, arrhythmia, low Vt and low compliance.");
L(9,'fluid',3,"A 45-year-old with bilateral below-knee amputations, DKA and urosepsis on 2 L nasal cannula. Which test is appropriate?",["PLR with ΔLVOT VTI","IVC collapsibility","LVOT velocity variation","SVC distension","No test is valid"],1,"PLR is unreliable after bilateral leg amputation. He is spontaneously breathing, so SVV and SVC (TEE, ventilated) are invalid; IVC collapsibility remains (limited accuracy, ~40–48% thresholds in spontaneous breathers).");
L(9,"fluid",2,"The 'mini-fluid challenge' described by Wu (2014) uses:",["500 mL over 15 min, cardiac output change >15%","50 mL over 10 s, LVOT VTI change ≥10%","100 mL colloid over 1 min, PPV >13%","10 mL/kg bolus, IVC diameter change"],1,"Rapid 50 mL bolus over 10 s with VTI change ~9–10% predicted responsiveness; usable with spontaneous breathing and arrhythmia.");
L(9,"fluid",2,"When using TTE for a PLR test, which practice improves accuracy?",["Re-measure the LVOT diameter at every single step","Keep the probe still and confirm return to baseline","Start the manoeuvre from a flat supine position","Use IVC diameter change instead of the VTI"],1,"Consistency beats accuracy: same window and angle, compare % change in VTI, add a third measurement after returning to baseline. PLR is not feasible in ~42% (raised ICP, open abdomen, hip fracture, pregnancy, amputation, abdominal hypertension).");

// Lecture 10 — ARDS & Acute Cor Pulmonale
L(10,"rv",2,"Which four factors make up the ACP risk score in ARDS (Mekontso Dessap 2016)?",["Age >65, shock, acute kidney injury and lactate >4","Pneumonia, driving pressure >18, P/F <150, PaCO2 >48","PEEP >15, Vt >8 mL/kg, sepsis and obesity","Prone position, inhaled NO, ECMO and vasopressin"],1,"One point each; risk of ACP rises with score (score 4 ≈ two-thirds). ACP incidence ~20–25% in the lung-protective era; severe ACP increases mortality.");
L(10,"rv",2,"Acute cor pulmonale is defined echocardiographically as:",["RV systolic pressure >60 mm Hg on TR Doppler alone","RVEDA/LVEDA 0.6–1.0 + septal dyskinesia; >1 severe","TAPSE <16 mm alone with a normal-sized RV","RV free wall >5 mm with a dilated right atrium"],1,"ACP = RV dilation + systolic septal dyskinesia (paradoxical motion at end-systole/early diastole) from acute afterload rise.");
L(10,"lung",2,"Which lung ultrasound pattern favours ARDS over cardiogenic pulmonary edema?",["Homogeneous B-lines, smooth pleura, bilateral effusions","Patchy B-lines, irregular pleura, subpleural consolidation","Bilateral A-lines with preserved lung sliding everywhere","An isolated lung point on one side only"],1,"Cardiogenic: homogeneous, diffuse B-lines, regular pleura, sliding present, effusions common. ARDS: patchy B-lines, spared areas, irregular/thickened pleura, subpleural consolidation, ± reduced sliding.");
L(10,"rv",2,"In ARDS with ACP on norepinephrine, which vasopressor property is helpful?",["Phenylephrine lowers pulmonary vascular resistance","Vasopressin 0.03 U/min can cause pulmonary vasodilation","Epinephrine reduces RV afterload more than any other agent","Dopamine is the first-line agent in acute cor pulmonale"],1,"Low-dose vasopressin raises SVR with neutral/lowered PVR. Norepinephrine preferred over phenylephrine. Inhaled NO/prostanoids preferred over enteral pulmonary vasodilators; PDE5 inhibitors may cause systemic hypotension.");
L(10,"rv",2,"Which ventilator strategy is 'RV protective' in ARDS?",["Plateau <35 with permissive PaCO2 >60 mm Hg tolerated","Plateau <30, ΔP <18, PaCO2 control, oxygenation, prone","High PEEP regardless of lung overdistension","Raise tidal volume to 10 mL/kg to lower PaCO2"],1,"Limit plateau and driving pressure, avoid hypercapnia and hypoxemia (pulmonary vasoconstriction), titrate PEEP to recruit without overdistension, and prone (unloads RV).");
L(10,"rv",3,"Flu ARDS: VAC Vt 420, PEEP 20, Pplat 35, CVP 10, mPAP 30, PCWP 8, CO 2.9, BP 88/40; echo shows a dilated RV with septal dyskinesia. Best immediate strategy?",["Add milrinone to lower PVR and support the RV","Start a PDE5 inhibitor to unload the RV","Small 100 mL bolus and assess the SV response","Increase PEEP to 24 to improve oxygenation"],2,"Optimize RV preload cautiously with mini-challenges (100–250 mL) measuring SV; diurese if right pressures are high. Then reduce afterload (lower driving pressure, prone, inhaled vasodilators) and support contractility; milrinone may worsen hypotension.");
L(10,"rv",2,"In ARDS, which supportive measure for ACP is recommended regarding rhythm?",["Accept AF and focus on ventricular rate control only","Restore sinus rhythm (chemical/electrical cardioversion)","Pace at 50 bpm to lengthen RV filling time","Beta-block to a heart rate of about 50 bpm to aid filling"],1,"Atrial contraction matters for the failing RV; restore sinus rhythm.");
L(10,'lung',1,"Lung 'hepatization' with air bronchograms on ultrasound indicates:",["Pneumothorax","Consolidation","Pleural effusion","Normal aerated lung"],1,"Tissue-like (liver-like) lung with dynamic air bronchograms = consolidation (pneumonia); static bronchograms suggest atelectasis.");
L(10,"mass",2,"In a severely hypoxemic ARDS patient with ACP, hypoxemia worsening with higher PEEP should prompt a search for:",["Unrecognized rheumatic mitral stenosis","Right-to-left shunt across a PFO (bubble study)","Severe aortic stenosis limiting cardiac output","An LV apical thrombus with systemic emboli"],1,"Raised RA pressure from ACP/high PEEP opens a PFO (~15–20% of ARDS) causing refractory hypoxemia; detect with agitated saline (TEE bicaval most sensitive).");
L(10,'rv',1,"ARDS mortality by Berlin severity (mild, moderate, severe) is approximately:",["10%, 20%, 30%","27%, 32%, 45%","40%, 50%, 70%","5%, 15%, 25%"],1,"Berlin (JAMA 2012): mild 27%, moderate 32%, severe 45%. P/F categories 200–300, 100–200, <100 with PEEP ≥5.");

// Lecture 11 — Lung & Pleura
L(11,"lung",1,"Which three findings are all absent at a site of pneumothorax?",["A-lines, lung sliding and the seashore sign","Lung sliding, lung pulse and B-lines","Curtain sign, spine sign and mirror image","Pleural line, rib shadows and A-lines"],1,"Any of sliding, pulse or B-lines proves the visceral pleura is apposed at that spot. PTX: no sliding, no pulse, no vertical artifacts; A-lines persist. Lung point rules it in.");
L(11,'lung',2,"Compared with supine CXR in trauma, lung ultrasound for pneumothorax has a sensitivity of about:",["47% vs 91%","91% vs 47%","60% vs 60%","99% vs 99%"],1,"Cochrane 2020: US sensitivity 91%, specificity 99%; CXR sensitivity 47%, specificity 100%.");
L(11,"lung",2,"Absent lung sliding is NOT specific for pneumothorax. Which other condition abolishes sliding?",["Simple pleural effusion with a freely floating lung","Bullae, adhesions, mainstem block, ARDS, overdistension","Cardiogenic pulmonary edema with diffuse bilateral B-lines","Normal tidal ventilation in a supine patient"],1,"Lack of sliding also occurs with bullae (can mimic PTX), adhesions/pleurodesis, apnea or one-lung ventilation, ARDS, hyperinflation. Look for lung pulse and lung point.");
L(11,"lung",1,"Which description defines a B-line?",["Horizontal lines repeating at multiples of the pleural depth below it","Short vertical comet tail fading within 1–2 cm, not reaching the bottom","Laser-like vertical line from pleura to screen bottom, moving with sliding","Acoustic shadow cast behind each rib along the chest wall"],2,"B-lines = vertical reverberations from increased lung density (water, cells, fibrosis). ≥3 B-lines in one intercostal space defines a positive (interstitial) region (Volpicelli 2012). They erase A-lines.");
L(11,"lung",2,"Which statement about B-lines is correct?",["They correlate closely with PAOP in most ventilated ICU patients","They track lung water early, before P/F falls, but are non-specific","They occur only in cardiogenic, never in permeability, edema","They are reliably reduced by applying high PEEP in every patient"],1,"B-lines are sensitive, dynamic and correlate with EVLW/severity but not with wedge pressure; diffuse causes include edema, ARDS, pneumonitis, ILD, hemorrhage.");
L(11,"lung",2,"A dynamic air bronchogram within a consolidation suggests:",["Obstructive (resorptive) atelectasis","Pneumonia with patent airways","Pulmonary infarction after PE","Compressive atelectasis from effusion"],1,"Dynamic (moving with respiration) air bronchograms indicate patent airways → infectious consolidation; essentially rules out resorptive atelectasis. Static bronchograms suggest atelectasis/obstruction.");
L(11,"lung",3,"A small subpleural consolidation that is hypoechoic, homogeneous, wedge-shaped with sharp margins and no air bronchograms most suggests:",["Lobar pneumonia","Pulmonary infarct (PE)","Pleural metastasis","Compressive atelectasis"],1,"Type 1 (wedge, sharp, homogeneous, no air) = infarct; type 2 (polygonal, blurred, air inclusions) = pneumonia; type 3 (round/oval, sharp) = metastasis (Volpicelli 2008).");
L(11,"lung",2,"Which effusion appearance always indicates an exudate (or hemothorax)?",["Anechoic, free-flowing","Complex septated","Small volume only","Bilateral and equal"],1,"Transudates are always anechoic, but anechoic effusions can also be exudates or acute hemothorax. Septations and echogenic (particulate/homogeneous) fluid indicate exudate or subacute hemothorax.");
L(11,'lung',2,"In a supine ventilated patient, the maximal parietal–visceral pleural separation at end-expiration (posterior axillary line) is 30 mm. Estimated effusion volume (Balik)?",["~200 mL","~600 mL","~1,500 mL","~3,000 mL"],1,"Balik: V (mL) ≈ 20 × separation (mm) = 600 mL. Usta: V ≈ 16 × D at mid-diaphragm.");
L(11,"lung",2,"The 'sinusoid sign' on M-mode over a pleural effusion indicates:",["Trapped lung that cannot re-expand during inspiration","Free-flowing fluid; lung moves to pleura on inspiration","Pneumothorax with an air-fluid interface","Consolidated lung floating passively within the effusion"],1,"Respiratory variation of the visceral pleura toward the parietal line = free effusion; absence suggests trapped lung or viscous fluid.");
L(11,"abd",2,"On transverse airway ultrasound, which structure marks the site for emergency front-of-neck access?",["Thyrohyoid membrane above the thyroid cartilage","Cricothyroid membrane (thyroid–cricoid gap)","Fourth tracheal ring below the thyroid isthmus","Epiglottis seen through the thyrohyoid window"],1,"Identify thyroid cartilage, cricoid ring and tracheal rings; the cricothyroid membrane lies between thyroid and cricoid cartilage. US also confirms tracheal vs esophageal intubation.");

// Lecture 12 — Respiratory Failure
L(12,'lung',1,"The BLUE protocol (Lichtenstein 2008) combines lung ultrasound with which other examination?",["Echocardiography","Venous (DVT) ultrasound","IVC assessment","Diaphragm ultrasound"],1,"BLUE = lung profiles (A/B lines, sliding, consolidation, effusion/PLAPS) + venous compression for DVT; correct diagnosis in 90.5%. A-profile with DVT → PE; A-profile without DVT and with PLAPS → pneumonia; without PLAPS → COPD/asthma.");
L(12,'lung',2,"In the BLUE protocol, a patient with bilateral anterior A-lines and lung sliding, no PLAPS, and a positive lower-limb DVT most likely has:",["Pneumonia","Pulmonary embolism","Cardiogenic edema","COPD exacerbation"],1,"A-profile (no interstitial syndrome) + DVT → PE. A-profile, no DVT, PLAPS → pneumonia; A-profile, no DVT, no PLAPS → COPD/asthma.");
L(12,'lung',2,"Compared with CXR for acute heart failure, lung ultrasound (pooled) has sensitivity and specificity of roughly:",["77% / 87%","92% / 92%","60% / 99%","99% / 60%"],1,"Meta-analysis (Chiu 2022): LUS Se 91.8%, Sp 92.3%; CXR Se 76.5%, Sp 87%. Adding LUS to clinical assessment reduces diagnostic error.");
L(12,"lung",2,"In the LUS-ARDS score (Smit 2023), a cut-off > 8 gives:",["High specificity but low sensitivity for ARDS","High sensitivity (~94%) to rule out ARDS","A confirmed diagnosis of bacterial pneumonia","A prediction of recruitability with higher PEEP"],1,">8: sensitivity 0.94 (useful to exclude ARDS); >27: specificity ~0.94 (rule in). LUS is now accepted for bilateral opacities in the Global ARDS definition.");
L(12,"lung",3,"Which statement about LUS score changes with PEEP is correct?",["LUS score accurately quantifies PEEP-induced recruitment","LUS shows aeration but misses recruitment and overdistension","LUS predicts the oxygenation response to proning in all studies","The LUS score rises as the lung is progressively recruited"],1,"Global/regional LUS scores correlate with CT density, but ΔLUS was unrelated to PEEP-induced recruitment (Stevic 2021); hyperinflation isn't seen. Prone-response prediction is inconsistent.");
L(12,"lung",2,"During an SBT, which lung ultrasound change identifies weaning-induced pulmonary edema (Ferré 2019)?",["Loss of lung sliding over the anterior chest","≥6 new B-lines over 4 anterior points","A new pleural effusion at the posterior bases","Appearance of a lung point on one side"],1,"ΔB-lines ≥6 (4 anterior points): Se 88%, Sp 88%, AUC 0.91. LUS aeration score >17 at end-SBT predicts post-extubation distress (LR 11.8); <13 low risk (Soummer 2012).");
L(12,'dia',2,"In mechanically ventilated patients (TEE), lateral mitral E/e' ≤ 8 predicts PAOP:",["≥ 25 mm Hg","≤ 18 mm Hg","Exactly 12 mm Hg","Cannot be predicted"],1,"Lateral E/e' ≤8 → PAOP ≤18 (Se 83%, Sp 88%; Vignon, Crit Care 2008, ventilated ICU patients, TEE). Rise of E/A and E/e' during an SBT signals weaning-induced cardiac dysfunction.");
L(12,"lung",2,"Which echo findings before SBT identify patients at high risk of weaning failure from cardiac dysfunction?",["LVEF >60% with E/A <1 and a normal LA volume index","LVEF <40% with E/A >2, or E/e' >12; no PLR CO rise","Small, collapsing IVC before the trial begins","TAPSE >20 mm with a normal RV size on the A4C view"],1,"Mayo/Dres: LVEF <40%, restrictive E/A >2 or E/e' >12 with normal EF, and failure of CO to rise with PLR. After SBT, rising E/A and E/e' suggests weaning-induced edema.");
L(12,"lung",2,"Normal right hemidiaphragm excursion in quiet breathing (men) is about 1.8 cm. Which lower-limit value suggests dysfunction?",["< 3.5 cm in both men and women","< 1.0 cm (men) / 0.9 cm (women)","< 2.5 cm in men, < 2.0 cm in women","< 5 cm on deep inspiration only"],1,"Boussuges 2009 lower limits — quiet: 1.0 (men)/0.9 cm (women); sniff 1.8/1.6; deep 4.7/3.7. Diaphragm dysfunction is often unrecognized in weaning failure; thickening fraction is an alternative.");
L(12,"lung",1,"Integrated POCUS for acute dyspnea, compared with standard care, has been shown to:",["Reduce 30-day all-cause mortality","Shorten time to diagnosis and correct treatment","Increase hospital length of stay overall","Remove the need for CT in nearly all patients"],1,"Meta-analyses: shorter time to diagnosis/treatment, more appropriate treatment, possibly shorter ventilation; no proven mortality effect (low certainty).");

// Lecture 13 — Pericardial Disease & Tamponade
L(13,"peri",1,"On PLAX, how is a pericardial effusion distinguished from a left pleural effusion?",["Pericardial fluid tracks posterior to the descending aorta","Pericardial fluid stays anterior to the descending aorta","Both pericardial and pleural fluid lie anterior to it","Pleural fluid is always echogenic while pericardial fluid is not"],1,"The descending aorta is the landmark: pericardial effusion anterior (between aorta and LA/LV), pleural effusion posterior. Small effusions collect posterior to the LV first.");
L(13,"peri",1,"An echo-free space measuring 15 mm at end-diastole is classified as:",["Trivial (seen only in systole)","Small (< 10 mm, under ~100 mL)","Moderate (10–20 mm)","Large (> 20 mm, over ~500 mL)"],2,"ASE: trivial = systole only; small <10 mm (50–100 mL); moderate 10–20 mm (100–500 mL); large >20 mm (>500 mL). Measure at end-diastole.");
L(13,"peri",2,"Which echo sign is MOST SPECIFIC for raised intrapericardial pressure?",["Late-diastolic right atrial collapse","Early-diastolic RV free-wall inversion","Mitral inflow variation above 25%","Presence of a circumferential effusion"],1,"RV diastolic collapse: Se 92%, Sp 100%. RA inversion (late diastole/early systole): Se 100%, Sp 82%, PPV 50% — specificity rises if collapse >1/3 of the cycle. Doppler variation is nonspecific.");
L(13,'peri',2,"Which respirophasic Doppler thresholds support tamponade physiology?",["Mitral E ≥ 10%, tricuspid ≥ 15%","Mitral E ≥ 30%, tricuspid E ≥ 60%","Mitral E ≥ 60%, tricuspid ≥ 30%","Any variation"],1,"Normal mitral variation <15%. Tamponade: mitral ≥30%, tricuspid ≥60%. Constriction: mitral >25%, tricuspid >40%. Not specific (COPD, acute RV failure); blunted by mechanical ventilation and AF.");
L(13,"peri",2,"A plethoric IVC in tamponade has which test characteristics?",["Low sensitivity but high specificity for cardiac tamponade","High sensitivity, low specificity; normal IVC helps exclude","Both low sensitivity and low specificity in most published series","Both high sensitivity and high specificity overall"],1,"IVC plethora occurs in >90%. Exception: low-pressure tamponade (hypovolemia) where the IVC may be small.");
L(13,"peri",2,"Which condition attenuates or abolishes RV diastolic collapse despite tamponade?",["Hypovolemia with low RV filling pressure","Severe pulmonary hypertension or RVH","A small, underfilled left ventricle","Sinus tachycardia above 120 bpm"],1,"High RV pressure/thick RV resists collapse (left heart may collapse instead). Pulsus paradoxus may be absent with extreme hypotension, localized hematoma, RVH, LV dysfunction/high LV filling pressure, severe AR, ASD, positive pressure ventilation.");
L(13,"peri",2,"Hepatic vein Doppler in tamponade typically shows:",["Systolic-dominant flow, expiratory diastolic reversal","Diastolic-dominant forward flow with inspiratory reversal","Continuous, non-phasic forward flow throughout the cycle","Prominent systolic flow reversal with each beat"],0,"Tamponade: systolic predominance, loss of diastolic (y) forward flow, expiratory diastolic reversal. Constriction: expiratory diastolic reversal too. Restriction: inspiratory diastolic reversal.");
L(13,"peri",2,"Constriction vs restrictive cardiomyopathy — which set favours CONSTRICTION?",["Low medial e', normal septal motion, inspiratory hepatic vein flow reversal","Annulus reversus, septal bounce, >25% mitral variation, expiratory HV reversal","E < A with a long deceleration time and no respiratory variation","Severe biventricular LVH with apical-sparing strain and biatrial enlargement"],1,"Constriction: pericardial process, myocardium relaxes normally → high medial e', annulus reversus, ventricular interdependence. Restriction: myocardial disease → low e', no respiratory variation, inspiratory hepatic reversal.");
L(13,"peri",3,"Which is a contraindication to percutaneous echo-guided pericardiocentesis, favouring surgery?",["Malignant effusion with recurrent reaccumulation","Type A dissection or post-MI free-wall rupture","Effusion after cardiac surgery without clot","Effusion reachable only by a para-apical approach"],1,"Also coagulopathy (INR >1.5), thrombocytopenia, severe PH. Echo-guided success ~97%, major complications ~1.2%; para-apical approach most common (63%), subcostal 15%. Agitated saline confirms needle position.");
L(13,"peri",2,"Congenital absence of the left pericardium typically shows:",["Small RV with a normal axis and normal cardiac position","Large-looking RV, central 'teardrop' heart, leftward shift","Large circumferential pericardial effusion","Thick, calcified pericardium with a septal bounce on M-mode"],1,"Mostly asymptomatic; abnormal CXR/ECG; leftward displacement makes the RV look dilated and the apex unusual.");

// Lecture 14 — Echocardiography in Shock
L(14,"shock",1,"The first goal of echocardiography in an undifferentiated shocked patient is to:",["Calculate the EF accurately with Simpson's biplane method","Find life threats: acute LV failure, tamponade, cor pulmonale","Measure LV mass and wall thickness to characterise chronic disease","Grade diastolic function using the full ASE algorithm"],1,"Then classify the shock (cardiogenic, distributive, obstructive, hypovolemic) and find contributors (severe valve disease, masses, LVOT obstruction).");
L(14,"shock",2,"Tamponade and acute cor pulmonale are both obstructive shock. How does echo separate them?",["Both show RV dilation, so echo cannot separate the two","Tamponade: effusion, small RV; ACP: big RV, no effusion","Both show a pericardial effusion of similar size and position","Only IVC size differentiates the two conditions"],1,"Same physiological category, opposite treatment (drainage vs RV afterload reduction/lysis). Both may show a plethoric IVC.");
L(14,"shock",2,"A hyperdynamic LV with a small IVC collapsing > 50% is expected in hypovolemia. Which other situation can show a small IVC despite high CVP?",["Cardiac tamponade with a plethoric IVC","Abdominal compartment syndrome","Severe tricuspid regurgitation","Right ventricular infarction"],1,"Raised intra-abdominal pressure compresses the IVC (small IVC, high CVP). Conversely, mechanical ventilation can produce a large IVC with low CVP.");
L(14,'shock',2,"In cardiogenic shock, which Doppler findings carry adverse prognostic value?",["High e' and low E/e'","Low e' and high E/e'","Normal LVOT VTI","Small LA"],1,"Low e' (impaired relaxation) and high E/e' (raised LAP) predict worse outcomes in cardiogenic shock.");
L(14,"shock",1,"Which valvular emergency causes shock and is visible on focused echo?",["Mild aortic regurgitation with a narrow jet","Flail leaflet or papillary rupture with severe MR","Trace tricuspid regurgitation at normal pressure","Mitral annular calcification without stenosis"],1,"Acute valve causes: severe regurgitation (flail leaflet, papillary rupture, vegetation), severe stenosis, valve masses, dynamic LVOT obstruction. Refer for comprehensive TTE/TEE.");
L(14,"shock",2,"Dynamic LVOT obstruction can occur in which settings?",["Only in hypertrophic obstructive cardiomyopathy","HCM, Takotsubo, or any hyperdynamic underfilled LV","Dilated cardiomyopathy with a low EF and big LV","Severe aortic regurgitation with LV volume overload"],1,"Recognize SAM and late-peaking dagger CW signal; treat with fluid, stop inotropes, add vasoconstrictor ± beta-blocker.");
L(14,"shock",2,"A prone, ARDS patient on PEEP 20 develops new shock with a dilated RV and septal flattening. Most likely mechanism?",["Hypovolemia from high intrathoracic pressure","Acute cor pulmonale from high RV afterload","Cardiac tamponade from a new effusion","Dynamic LVOT obstruction in the prone position"],1,"High PEEP/driving pressure and hypoxemia increase PVR → ACP; lower airway pressures, consider prone/inhaled vasodilators.");
L(14,"shock",1,"Which extra-cardiac ultrasound components belong in a shock protocol (e.g. RUSH/E-FAST)?",["Cardiac views only, with no other components","Lung, leg veins, FAST free fluid and the aorta","Thyroid, carotid arteries and jugular veins","Renal resistive index and bladder volume only"],1,"Pump (heart), tank (IVC, FAST, pleural/lungs), pipes (aorta, DVT).");
L(14,"shock",2,"Which LV regional pattern suggests Takotsubo rather than LAD infarction?",["Anterior and septal akinesis that spares the apex, in the LAD territory","Apical ballooning beyond one coronary territory, hyperkinetic base","Inferior and inferoseptal akinesis confined to the RCA territory","Isolated lateral wall akinesis in the circumflex territory"],1,"Takotsubo involves all apical segments (anterior, septal, lateral, inferior) — non-coronary distribution — with hyperkinetic base. A wrap-around LAD can mimic it; angiography decides.");
L(14,"shock",1,"Tamponade is ultimately diagnosed as:",["A purely echocardiographic diagnosis made on images alone","A clinical/hemodynamic diagnosis that echo supports","Any pericardial effusion measuring over 2 cm","Right atrial collapse alone on a single view"],1,"Echo is highly sensitive for raised pericardial pressure but the decision to drain integrates clinical findings.");

// Lecture 15 — Focused Ultrasound in Cardiac Arrest
L(15,"shock",1,"'Pseudo-PEA' is defined as:",["Electrical activity without any cardiac motion","Organized ECG with cardiac motion but no pulse","Asystole on the monitor with VF on the echo","A palpable pulse with new ST-segment elevation"],1,"True PEA = electrical activity, no spontaneous cardiac motion (very poor prognosis). Pseudo-PEA = organized motion without palpable pulse — look for treatable causes (tamponade, PE, hypovolemia, severe LV dysfunction).");
L(15,'shock',2,"Detection of cardiac activity on ultrasound during arrest is associated with survival to hospital discharge with an odds ratio of about:",["1.0","2","5.7","50"],2,"Gaspari 2016: OR 3.6 for admission and 5.7 for discharge. Standstill carries near-100% mortality but must be integrated with the full clinical picture.");
L(15,'shock',1,"During CPR, what is the maximum pause for pulse check plus echo?",["5 s","10 s","20 s","30 s"],1,"≤10 s. The leader counts down aloud; record a clip during the check and review it during compressions. In practice POCUS lengthened pauses (median 17 vs 11 s) — training mitigates this.");
L(15,"shock",2,"During a PEA arrest, the subcostal view is non-diagnostic at the 10-second mark. Best next step?",["Keep scanning until an adequate view is obtained","Resume CPR now; try parasternal at the next check","Give a fluid bolus while continuing to scan","Give thrombolytics for presumed massive PE"],1,"Never prolong the pause for imaging; change window at the next check.");
L(15,'shock',2,"In a TEE series of out-of-hospital arrests (n = 33), what proportion of apparent asystole was actually fine VF?",["0%","12%","50%","80%"],1,"4/33 (12%) had fine VF → defibrillated. RV dilation in 57%; area of maximal compression was over the aortic root/LVOT in 53%; TEE impacted management in 97%.");
L(15,"shock",2,"During CPR, TEE shows the area of maximal compression over the aortic root/LVOT. Significance?",["Optimal compression of the left ventricular cavity","Hands may be obstructing LV outflow; move them","Evidence of a developing cardiac tamponade","No clinical significance during CPR"],1,"Compressions over the LVOT/aortic root impede forward flow; TEE can guide repositioning toward the LV.");
L(15,'shock',2,"Which pseudo-PEA finding points to massive PE?",["Small hyperdynamic LV and RV with collapsing IVC","Dilated hypokinetic RV with underfilled LV","Effusion with RV diastolic collapse","Globally hypokinetic LV with normal RV"],1,"PE: RV dilation/dysfunction, small LV. Tamponade: effusion with right-chamber collapse. Hypovolemia: small hyperdynamic ventricles, flat IVC. Severe LV dysfunction: dilated hypokinetic LV.");
L(15,"shock",2,"After ROSC from VF arrest, echo shows a new regional wall motion abnormality. This should prompt:",["Discharge planning once hemodynamically stable","Consideration of coronary angiography","Immediate systemic thrombolysis for presumed PE","Urgent pericardiocentesis"],1,"SCCM: post-ROSC RWMA after VT/VF is a surrogate for coronary disease → cardiac catheterization (though global stunning is common post-arrest).");
L(15,'shock',1,"In-hospital cardiac arrest survival to discharge is approximately:",["2%","18%","50%","75%"],1,"~18% with ~73% of survivors having good neurologic function (Morrison 2013).");

// Lecture 16 — Heart Failure Syndromes
L(16,'lv',1,"Which LVEF cut-off separates HFpEF from HFrEF in the lecture algorithm?",["35%","40%","50%","60%"],2,"LVEF ≥50% = preserved. Then assess volumes, diastolic function and key etiologic features (RWMA, wall thickness, trabeculation, aneurysm, valves, PA pressure).");
L(16,"dia",2,"Which set indicates INCREASED LV filling pressure?",["E/A <0.8 with DT >240 ms and a normal-sized LA","E/A >1.5, E/e' >15, DT <160 ms, big LA, high PASP","Average E/e' below 8 with normal septal and lateral e'","Normal LA volume and a TR jet below 2.5 m/s"],1,"Restrictive-type indices: high E/A, short DT, high E/e', LA enlargement, high PASP.");
L(16,'hemo',2,"A 24-year-old after anthracycline has LVOT diameter 2.2 cm, SV 26 mL, HR 101, BSA 1.51 m². Cardiac index?",["1.2 L/min/m²","1.7 L/min/m²","2.6 L/min/m²","3.5 L/min/m²"],1,"CO = 26 × 101 = 2.63 L/min; CI = 2.63/1.51 ≈ 1.74 L/min/m² (low; lecture slide quoted ~2.0). SV = π(1.1)² × VTI.");
L(16,"lv",2,"Which are Mayo criteria for stress (Takotsubo) cardiomyopathy?",["Fixed regional WMA confined to a single coronary artery territory","Transient WMA beyond one territory, no culprit CAD, new ECG/troponin","Pheochromocytoma must be present, with EF below 20% at onset","A pericardial effusion with diffuse concave ST elevation on the ECG"],1,"Also exclude pheochromocytoma and myocarditis. Variants: apical (typical), midventricular, basal (inverted). Can cause LVOT obstruction.");
L(16,"lv",2,"Which echo feature favours HCM over hypertensive LVH?",["Concentric, mild and symmetric wall thickening","Septum ~19 vs posterior ~12 mm, low e', high E/e'","Normal e' velocities with a normal average E/e' ratio","A dilated LV with thin walls and low EF"],1,"Sun 2019: HCM septum 18.9 mm, medial e' 4.7, E/e' 18.2; HTN septum 12.5 mm, e' 6.4, E/e' 11.8. Asymmetric septal hypertrophy, SAM and LVOT obstruction typify HCM.");
L(16,"lv",2,"Which features suggest cardiac amyloidosis?",["Thin walls with a dilated, globally hypokinetic left ventricle","Thick sparkling walls, biatrial dilation, apical-sparing strain","Isolated basal septal bulge in an older hypertensive patient","Normal diastolic function with a normal LA size"],1,"Also small/normal cavity, low voltage ECG discordant with wall thickness. Types: AL, ATTRm, ATTRwt. Atrial thrombi in ~35%.");
L(16,'lv',3,"A 67-year-old with renal failure has thick LV walls, a 'two-layered' endocardium and very low α-galactosidase A. Diagnosis?",["Amyloidosis","Fabry disease","Danon disease","Friedreich ataxia"],1,"X-linked α-galactosidase A deficiency; cardiac involvement ~80% (40s), renal failure, neuropathy. CMR: inferolateral midwall LGE sparing subendocardium.");
L(16,"lv",2,"Which acute complications of MI can be diagnosed on bedside echo?",["Free-wall rupture, VSD, papillary rupture, ischemic MR","Only LV thrombus; the other complications need CT angiography","Dressler syndrome, diagnosed reliably on echo alone","Spontaneous coronary artery dissection of the LAD"],0,"Mechanical complications are echo diagnoses. Ischemic MR arises from annular dilation and posterior leaflet tethering.");
L(16,'lv',1,"The preferred method for LV volume and EF assessment in heart failure is:",["Linear M-mode (Teichholz)","Volumetric (biplane or 3D)","Visual estimate only","EPSS"],1,"Volumetric assessment is preferred; strain adds sensitivity for subclinical dysfunction.");
L(16,"lv",2,"Eosinophilic myocarditis progresses through which stages?",["Hypertrophy, then progressive dilation and systolic failure","Inflammation → necrosis → thrombus → fibrosis","Valvular calcification, then progressive stenosis","Fatty infiltration of the RV, then ventricular arrhythmia"],1,"Thrombotic stage shows apical thrombus overlying abnormal myocardium; fibrotic stage → restrictive physiology with posterior mitral leaflet tethering.");

// Lecture 17 — Pulmonary Embolism & Pulmonary Hypertension
L(17,"rv",2,"Which conditions can all produce an echo picture identical to acute PE (acute cor pulmonale)?",["Only massive PE; every other cause looks clearly different on echo","Fat/gas/amniotic emboli, ARDS, contusion, RV infarct, cor pulmonale","Only RV infarction, which is identical in every respect to acute PE","Cardiac tamponade with diastolic collapse of the right-sided chambers"],1,"Echo shows the RV response, not the cause. RV infarct is usually accompanied by inferior LV WMA.");
L(17,'rv',2,"McConnell's sign (mid-RV free-wall akinesis with apical sparing) has approximately:",["Sensitivity 95%, specificity 50%","Sensitivity 77%, specificity 94%","Sensitivity 25%, specificity 25%","Sensitivity 100%, specificity 100%"],1,"Suggests acute RV dysfunction (classically PE) but also seen in RV infarction.");
L(17,"rv",2,"Mid-systolic deceleration ('notching') of the RVOT PW Doppler envelope indicates:",["Valvular pulmonic stenosis with a fixed gradient","Raised RV afterload / pulmonary vascular resistance","A normal RVOT flow profile in most adults","Severe pulmonic regurgitation with RV volume load"],1,"Notching and a short PA acceleration time (<60–100 ms) mark raised PVR; 60/60 sign (AT <60 ms with TR gradient 30–60 mm Hg) suggests acute PE (sens ~25%, spec ~94%).");
L(17,'rv',2,"Mean PAP from the pulmonary acceleration time (simplified Mahan formula): RVOT AT = 90 ms. Estimated mPAP?",["5 mm Hg","35 mm Hg","45 mm Hg","80 mm Hg"],1,"mPAP ≈ 80 − (AT/2) = 80 − 45 = 35 mm Hg (simplified Mahan formula; Dabestani uses 90 − 0.62 × AT). PH = mPAP >20 mm Hg (2022 ESC/ERS; previously >25).");
L(17,'rv',2,"Peak PR velocity 2.7 m/s, RAP 11 mm Hg. Estimated mPAP?",["22 mm Hg","29 mm Hg","40 mm Hg","51 mm Hg"],2,"mPAP ≈ 4(PR peak)² + RAP = 4 × 7.29 + 11 ≈ 40 mm Hg. PA diastolic = 4(PR end-diastolic)² + RAP.");
L(17,"rv",2,"Why is RVSP generally UNDERESTIMATED in severe (wide-open) TR?",["The Doppler angle is always poor in wide-open TR","RA and RV pressures equalize, so Bernoulli fails","TR velocity always exceeds 5 m/s, beyond CW range","Aliasing of the CW signal at very high velocities"],1,"Laminar low-velocity TR with large v waves; use other signs (septal shape, PA AT, PR).");
L(17,"rv",2,"In a patient with suspected PE, a lower-extremity DVT on ultrasound:",["Requires CT pulmonary angiography before any treatment","Is enough to justify anticoagulation without more tests","Is irrelevant to the management of suspected PE","Effectively excludes PE as the cause of symptoms"],1,"DVT present in 30–50% of PE; compression US has >90% sensitivity/95% specificity for symptomatic DVT.");
L(17,"rv",2,"A hemodynamically unstable patient has a mobile thrombus in transit in the RA. Recommended management?",["Unfractionated heparin alone and close observation","Systemic thrombolysis (or embolectomy)","IVC filter placement alone without anticoagulation","Observation with a repeat echo in 24 hours"],1,"Unstable + clot in transit → systemic tPA. Unstable with thrombus in situ → catheter-directed or systemic. Stable with RV strain (RV:LV >0.9 + troponin) = submassive → anticoagulate, consider lysis/CDT case by case.");
L(17,"rv",2,"Ultrasonographic pulmonary infarcts are typically:",["Large central masses next to the hilum with air bronchograms","Small pleural-based hypoechoic wedges, often posterobasal","Diffuse bilateral B-lines with a smooth, thin pleural line","A-lines only, with normal lung sliding"],1,"70–80% are peripheral pleural-based; normal pleura elsewhere.");
L(17,"rv",3,"A 72-year-old on heparin for NSTEMI becomes profoundly hypotensive after a long flight. The 60/60 sign is negative and norepinephrine has no effect. Next step?",["Give tPA now for presumed massive PE without more imaging","A negative 60/60 sign effectively excludes PE","Complete the scan: RV, LV, effusion, IVC, valves, DVT","Call for an intra-aortic balloon pump for cardiogenic shock"],2,"The 60/60 sign has low sensitivity; it cannot exclude PE, and alternative diagnoses (mechanical MI complication, tamponade) must be sought before acting.");

// Lecture 18 — Aorta & Great Vessels
L(18,'mass',1,"The three layers of the aortic wall from inside out are:",["Adventitia, media, intima","Intima, media, adventitia","Media, intima, adventitia","Endocardium, myocardium, epicardium"],1,"Dissection = intimal tear with blood tracking within the media, creating true and false lumens separated by an intimal flap.");
L(18,'mass',2,"Which imaging modality is uniquely strong for assessing aortic regurgitation mechanism and is available intraoperatively in dissection?",["CT","MRI","TTE/TEE","Chest radiograph"],2,"TEE ≈ CT ≈ MRI for sensitivity/specificity/classification; echo excels for AR, effusion and intraoperative availability. CT is best for side branches, follow-up and comfort.");
L(18,"mass",2,"How is the TRUE lumen typically distinguished from the false lumen on TEE?",["True lumen is larger and filled with spontaneous contrast","True lumen expands in systole with forward flow; false is larger, slow","False lumen expands in systole and has brisk forward systolic flow too","They cannot be told apart on TEE without contrast CT angiography first"],1,"True lumen: systolic expansion, early systolic flow. False lumen: diastolic expansion, slow or reversed flow, spontaneous echo contrast, thrombus, 'cobwebs'.");
L(18,'mass',2,"The cumulative (lifetime) risk of rupture or dissection of an ascending aortic aneurysm > 6.0 cm is approximately:",["0%","5%","16%","31%"],3,"Ascending aneurysms > 6 cm carry a ~31–34% cumulative risk of rupture/dissection (Coady/Elefteriades 'hinge point'). Yearly rates for aneurysms > 6 cm: rupture 3.7%, rupture or dissection 6.9%, death/rupture/dissection 15.6% (Davies 2002). Risk factors: smoking, hypertension, bicuspid valve, connective tissue disease, giant cell arteritis.");
L(18,"mass",2,"At what ascending aortic diameter is surgery recommended in Marfan syndrome?",["4.0 cm in all patients","4.5–5.0 cm","5.5 cm, as in the general population","6.5 cm or above only"],1,"General population ≥5.5 cm; Marfan 4.5–5.0 cm; bicuspid 5.5 cm (lower with family history of dissection or rapid growth). Also: symptoms, growth ≥5 mm/year, traumatic, pseudo- or mycotic aneurysm.");
L(18,"mass",2,"A linear echo in the ascending aorta on TTE moves parallel to the aortic wall at twice its distance from the transducer. Most likely?",["Intimal dissection flap","Reverberation artifact","Intra-aortic balloon pump","Mural thrombus"],1,"The aorta is a strong reflector: reverberations appear at multiples of the wall depth and move with it; a true flap has independent motion and disturbs color flow. Confirm in another plane.");
L(18,"mass",1,"Which complications of type A dissection are best detected by bedside echo?",["Renal artery malperfusion and rising creatinine","AR, pericardial effusion/tamponade, coronary RWMA","Spinal cord ischemia with lower-limb weakness","Mesenteric ischemia with rising lactate"],1,"Echo shows AR, hemopericardium and regional WMA from coronary ostial involvement; CT is better for side branches.");
L(18,"mass",2,"Which TTE window can show a proximal main pulmonary artery thrombus?",["Apical 2-chamber view with posterior tilt","PSAX at aortic valve level / RV outflow view","Subcostal IVC view with hepatic veins","Suprasternal notch view of the aortic arch only"],1,"Basal PSAX/RV outflow view displays RVOT, PV, main PA and bifurcation; distal thrombus usually needs TEE or CT.");

// Lecture 19 — Hemodynamics (static intracardiac pressures)
L(19,'hemo',1,"Which measurement is NOT used to estimate pulmonary artery pressure?",["IVC diameter","TR velocity","TAPSE","RV outflow acceleration time"],2,"TAPSE measures RV longitudinal systolic function. IVC → RAP (added to TR gradient), TR → systolic, RVOT AT → mean, PR → mean/diastolic.");
L(19,'hemo',1,"TR Vmax 3.78 m/s, RAP 10 mm Hg. PA systolic pressure?",["10 mm Hg","57 mm Hg","67 mm Hg","77 mm Hg"],2,"4(3.78)² = 57.2 + 10 = 67 mm Hg (assuming no PS/RVOT obstruction).");
L(19,'hemo',2,"End-diastolic PR velocity 1.77 m/s, RAP 15 mm Hg. PA diastolic pressure?",["12.6 mm Hg","15 mm Hg","27.6 mm Hg","42 mm Hg"],2,"PADP = 4(1.77)² + RAP = 12.5 + 15 ≈ 27.6 mm Hg (assumes RVEDP = RAP).");
L(19,'hemo',2,"sPAP 60 and dPAP 24 mm Hg. Calculated mean PAP?",["36 mm Hg","42 mm Hg","48 mm Hg","30 mm Hg"],0,"mPAP = 1/3 sPAP + 2/3 dPAP = 20 + 16 = 36 mm Hg. Alternatives: 4(PR peak)² + RAP; 79 − 0.45 × AT (or 90 − 0.62 × AT if AT <120 ms); TR mean gradient + RAP.");
L(19,'hemo',2,"RVOT acceleration time 100 ms. Estimated mPAP using 90 − 0.62 × AT (AT < 120 ms)?",["28 mm Hg","38 mm Hg","48 mm Hg","58 mm Hg"],0,"90 − 62 = 28 mm Hg. Shorter AT = higher PA pressure (reduced compliance, early reflected waves).");
L(19,'hemo',2,"Average E/e' is 12. Estimated PCWP using PCWP ≈ 1.24 × E/e' + 1.9 (Nagueh) / or E/e' + 4 rule?",["~8 mm Hg","~16 mm Hg","~25 mm Hg","~35 mm Hg"],1,"Lecture shortcut: PAOP ≈ E/e' + 4 = 16 mm Hg (Nagueh regression gives ~17). <8 normal LAP; >14 high.");
L(19,"hemo",2,"E/e' is NOT accurate in which condition?",["Sinus rhythm with structurally normal mitral and aortic valves","MAC, MS, significant MR, prosthetic MV, pericardial disease","Systemic hypertension with mild concentric LVH and normal valves","Normal EF with preserved e' velocities"],1,"Septal e' is lower than lateral; average is optimal (septal alone acceptable with its own cut-off).");
L(19,'hemo',1,"RV diastolic pressure equals RAP provided there is no:",["Pulmonic stenosis","Tricuspid stenosis","Mitral stenosis","Aortic stenosis"],1,"RVSP = PASP requires no pulmonic stenosis/RVOT obstruction; RVEDP = RAP requires no tricuspid stenosis.");

// Lecture 20 — DVT & Vascular Access
L(20,"vasc",1,"SCCM 2015 recommends that intensivists screen for proximal lower-limb DVT at which sites?",["Iliac veins and the calf veins below the knee","Common femoral and popliteal veins (2-region)","Great saphenous vein only, along its full length","Common femoral artery and the popliteal artery"],1,"2-point compression ≈ whole-leg US in symptomatic outpatients (Bernardi 2008). Intensivist-performed: Se 88%, Sp 98% (Kory 2011). Do not interrogate iliac veins.");
L(20,"vasc",1,"Which is the single most important criterion of a NORMAL compression study?",["Color Doppler fills the vein completely","Vein walls fully coapt with gentle pressure","Distal augmentation produces forward flow","The vein is larger than the adjacent artery"],1,"Normal = complete collapse. Abnormal only if the artery deforms (adequate pressure) while the vein stays open. 'It's only a vein if an artery is next to it' — beware lymph nodes and Baker's cysts.");
L(20,'vasc',2,"Which pitfall can mimic a non-compressible thrombosed vein in the groin?",["Great saphenous vein","Lymph node","Femoral artery","Inguinal ligament"],1,"Lymph nodes are oval, with an echogenic hilum and no accompanying artery. Hamstring tendons can confuse the popliteal fossa.");
L(20,"vasc",2,"After a negative 2-point exam in a patient with ongoing suspicion, best practice is:",["Stop investigating; the result is definitive","Repeat 2-point compression in 5–7 days","Start empiric anticoagulation for 3 months","Scan the iliac veins with a phased array probe"],1,"Limited exams miss isolated calf DVT; serial exam captures propagation.");
L(20,'vasc',2,"In the multi-organ ultrasound approach to suspected PE (Nazerian 2014), which three components are combined?",["Heart, lung, veins","Heart, abdomen, aorta","Lung, IVC, kidney","Carotid, femoral, radial"],0,"Lung (subpleural infarcts), heart (RV dilation/strain), veins (DVT) increased sensitivity for PE.");
L(20,"vasc",1,"SCCM 2015: which approach for real-time US-guided venous cannulation is recommended (grade 1B)?",["Long-axis (in-plane) approach only","Short-axis (transverse) approach","Landmark technique with a pre-scan","Doppler-only guidance without imaging"],1,"Real-time US guidance with short axis; confirm placement and exclude PTX by US (detects ~4/5 malpositions). IJ (1A) and femoral (1A, novices) strongly recommended.");
L(20,"vasc",2,"Per SCCM 2015, ultrasound for subclavian vein catheterization is:",["Mandatory for every subclavian line in all operators (grade 1A)","Of limited value for experts; helps learners/axillary (2C)","Contraindicated because the clavicle blocks the beam","Equivalent to its proven value for internal jugular cannulation"],1,"Later meta-analyses (Lalu 2015) show real-time 2D US improves success and reduces adverse events; aim needle trajectory toward the rib.");
L(20,"vasc",1,"Which probe and frequency suit vascular access at 2–8 cm depth?",["Phased-array probe at 1–5 MHz","Linear array probe at 4–10 MHz","Curvilinear probe at 2–5 MHz","A TEE probe at 3–7 MHz"],1,"High-frequency linear probe for shallow vessels. Track the needle tip continuously ('trifurcation' of beam, needle and vessel).");
L(20,'fluid',3,"Carotid artery blood flow increase with passive leg raise of ≥ 20% (Marik 2013) predicted fluid responsiveness with:",["Sensitivity 50%, specificity 50%","Sensitivity 94%, specificity 86%","Sensitivity 100%, specificity 20%","No predictive value"],1,"Carotid Doppler is an alternative SV surrogate when cardiac windows are poor.");
L(20,"vasc",2,"Which central line complication carried the highest death rate in closed claims (Domino 2004)?",["Carotid artery puncture","Iatrogenic pneumothorax","Pulmonary artery rupture","Guidewire embolization"],2,"PA rupture ~100% death, hemothorax 93%, tamponade 81% — much of it from substandard care; real-time US reduces avoidable complications.");

// Lecture 21 — Trauma including FAST
L(21,"abd",1,"Which FAST view is most likely to show free fluid, regardless of which organ is injured?",["Splenorenal (left upper quadrant)","Hepatorenal (Morison's pouch)","Suprapubic (pelvic) view","Subxiphoid pericardial view"],1,"RUQ/Morison's pouch is the most dependent upper abdominal space in supine patients. In LUQ, fluid often collects above the spleen (subphrenic).");
L(21,"abd",2,"How much intraperitoneal fluid is typically needed before most sonographers detect it on FAST?",["About 20–50 mL","About 100 mL","About 400–600 mL","About 2000–3000 mL"],2,"Around 400–600 mL for most operators; ~100 mL in right decubitus with skilled operators. Repeat FAST raises sensitivity (31% → 72% in hypotensive patients).");
L(21,'abd',2,"FAST test characteristics in blunt trauma are best described as:",["High sensitivity, low specificity","Specificity > 95%; sensitivity 22–89%","Both > 99%","Both < 50%"],1,"Positive FAST = injury (rule in); negative FAST doesn't exclude injury. Cannot assess retroperitoneum or most solid-organ injuries.");
L(21,"abd",2,"Which can produce a FALSE NEGATIVE subxiphoid cardiac FAST for hemopericardium?",["A full bladder compressing the pelvic window","Left hemothorax decompressing it, or pneumopericardium","Large-volume ascites surrounding the liver edge","Advanced pregnancy displacing the heart upward and leftward"],1,"A pericardial laceration can drain into the left chest. Fat pad and pneumopericardium are other pitfalls; cardiac sensitivity normally 85–100%.");
L(21,"abd",1,"In E-FAST, where is the anterior chest scanned for pneumothorax in a supine patient?",["Mid-axillary line, 8th–9th intercostal space","Medial to mid-clavicular line, 3rd–5th spaces","Supraclavicular fossa above the first rib","Posterior axillary line, lower intercostal spaces"],1,"Air rises anteriorly. Mid/posterior axillary line at 5th–6th space screens for hemothorax.");
L(21,'vasc',2,"After femoral access, a pulsatile groin mass shows swirling 'yin-yang' color flow in a sac connected to the artery. Diagnosis?",["Hematoma","Pseudoaneurysm","AV fistula","Arterial thrombosis"],1,"Hematoma: anechoic collection without flow. AV fistula: high-velocity turbulent communication. Thrombosis: echogenic lumen, no flow (1:1000 femoral access). Dissection: intimal flap.");
L(21,"mass",2,"Blunt traumatic aortic injury most often occurs at:",["Ascending aorta (~5%)","Aortic isthmus (~90%)","Abdominal aorta (~2%)","Aortic root (~3%)"],1,"Isthmus (just distal to the left subclavian, ligamentum arteriosum). TTE cannot exclude it; TEE Se 91%/Sp 98% for flap, mural hematoma, pseudoaneurysm.");
L(21,'abd',2,"Which valve is most commonly injured in blunt cardiac trauma when a valve is involved?",["Tricuspid","Mitral","Aortic","Pulmonic"],2,"Aortic > mitral > tricuspid; papillary muscle rupture is the most common valvular apparatus lesion; always regurgitant. Myocardial rupture usually involves RA/RV (>80% mortality).");
L(21,'abd',2,"Lung ultrasound vs CXR for rib fractures — sensitivity?",["80% vs 24%","24% vs 80%","50% vs 50%","99% vs 90%"],0,"CXR misses 33–50% of rib fractures. LUS with a linear probe along the rib shows cortical disruption (Se 80%, Sp 83%).");
L(21,"abd",2,"A stable patient with an abdominal stab wound has a POSITIVE FAST. Next step?",["CT abdomen with contrast","Operating room","Repeat FAST in 30 minutes","Observation and discharge"],1,"Penetrating trauma: positive FAST → OR; negative FAST is not helpful (low sensitivity). FAST helps plan chest vs abdomen first in thoraco-abdominal wounds.");

// Lecture 22 — Abdominal Ultrasound in the ICU
L(22,"abd",2,"Which ultrasound finding is a criterion for cholecystitis?",["Posterior wall thickness >1 mm with a few small stones","Anterior wall >3 mm, pericholecystic fluid, Murphy sign","A non-mobile shadowing polyp attached in the fundus","Common bile duct of 4 mm in an adult"],1,"Always measure the ANTERIOR wall. Stones + positive Murphy sign → PPV 92%. Meta-analysis Se 81%, Sp 83%.");
L(22,"abd",2,"A cirrhotic ICU patient has a thick-walled gallbladder with pericholecystic fluid. Interpretation?",["Diagnostic of acute calculous cholecystitis in this setting","Non-specific: cirrhosis, CHF, low albumin also thicken it","Stones in the lumen alone confirm the diagnosis","Indicates choledocholithiasis with common duct obstruction"],1,"Many ICU patients have thick walls and fluid without cholecystitis; SCCM does not recommend intensivist-only diagnosis of cholecystitis.");
L(22,"abd",1,"Gallstones are distinguished from polyps because stones are:",["Immobile and non-shadowing on repositioning","Mobile, echogenic and cast acoustic shadows","Attached to the wall with a vascular stalk","Anechoic with posterior acoustic enhancement"],1,"Polyps don't shadow and don't move with position change.");
L(22,'abd',2,"The common bile duct is considered dilated when it exceeds:",["2 mm","4 mm","6 mm","12 mm"],2,">6 mm. Find the portal vein first ('exclamation point'); use color to separate CBD from hepatic artery/portal vein.");
L(22,'abd',2,"Moderate hydronephrosis is defined by:",["Dilated renal pelvis only","Dilation extending into the calyces","Calyceal dilation with cortical thinning","Perinephric fluid"],1,"Mild = pelvis only; moderate = into calyces; severe = calyceal dilation with cortical thinning. Obstructed infected kidney can cause sepsis.");
L(22,"abd",1,"Bladder volume formula on ultrasound:",["Length × width × height × 0.1","Depth × width × length × 0.75","Diameter squared × 3.14","Length × 2 in the sagittal plane"],1,"Volume ≈ L × W × H × correction factor (0.52 for an ellipsoid; 0.7–0.75 in many ICU/ED references). Depth and width transverse, length longitudinal; >250 mL post-void residual is abnormal. Also check Foley position/obstruction.");
L(22,"abd",2,"Which ultrasound features favour small bowel obstruction over ileus?",["Air-filled loops under 25 mm without any visible peristalsis at all","Fluid-filled loops >25 mm, to-and-fro peristalsis, transition point","Normal-calibre bowel with normal peristalsis throughout the abdomen","Free intraperitoneal air only, with no bowel dilation"],1,"Ileus: air-filled, <25 mm, no wall edema, absent peristalsis. High-grade SBO: free fluid between loops, wall edema >3 mm, absent peristalsis, pneumatosis. US Se 92%, Sp 97% (≈ CT).");
L(22,"abd",2,"Ultrasound guidance for paracentesis improves success and reduces bleeding by about:",["Success 65% → 95%; bleeding down ~68%","No measurable change in success or bleeding","Success rises only from 20% to 30%","Success unchanged but bleeding doubles"],0,"Locate the deepest pocket away from bowel; identify inferior epigastric and abdominal wall vessels with color Doppler.");
L(22,"abd",2,"Abdominal aortic diameter should be measured:",["Inner lumen diameter at a single level near the renal arteries","Outer-to-outer wall, AP at 90°, three levels; AAA ≥3 cm","Only in the longitudinal plane at one level, inner to inner","Using color Doppler width only"],1,"Normal aorta <3 cm (iliacs <1.5 cm). If AAA and hypotensive → surgeon; 95% rupture into the retroperitoneum (FAST may be negative). Peri-aortic fluid suggests rupture.");
L(22,"abd",2,"Intraperitoneal free air on ultrasound appears as:",["Anechoic free fluid in Morison's pouch","Lost 'gut slide' with A-lines over the liver","Multiple B-lines arising from the peritoneum","A shadowing echogenic focus like a stone"],1,"Mimics pneumothorax pattern; normal bowel gas can confuse — tilt right side up so air collects anterior to the liver.");

// Lecture 23 — Devices & Foreign Bodies (ECMO, LVAD, Impella, IABP)
L(23,'mass',2,"Which is NOT a contraindication to Impella placement?",["LV thrombus","Ventricular septal defect","Severe mitral regurgitation","Moderate–severe aortic regurgitation"],2,"Contraindications: LV thrombus, mechanical AV, critical AS (≤0.6 cm²), mod–severe AR, significant RV failure, ASD/VSD, free wall rupture/pseudoaneurysm, tamponade.");
L(23,"mass",2,"Correct Impella CP position on echo:",["Inlet at the mitral valve level, outlet in the LV cavity","Inlet ~3.5 cm below the aortic annulus; outlet in aorta","Inlet in the left atrium across the septum, outlet in aorta","Outlet in the LV with the inlet in the aorta"],1,"Impella 5.5 inlet ~5.0 cm from annulus. Confirm inflow/outflow with color; the inlet appears as a 'teardrop' reverberation — inflow ≠ pigtail.");
L(23,"mass",2,"Which echo finding does NOT suggest worsening RV function in an LVAD patient?",["Rightward shift of the interventricular septum","Worsening functional tricuspid regurgitation","A dilated, non-collapsing IVC","Falling RVOT velocity-time integral on serial study"],0,"RV failure → leftward septal shift, RV dilation, more TR, plethoric IVC, low RVOT VTI. Rightward shift means high LV pressure (low speed, AR, high afterload, pump thrombosis/kink).");
L(23,'mass',2,"For a dual-lumen bicaval VV-ECMO cannula, the return (outflow) jet should be directed:",["Into the SVC","Across the interatrial septum","Toward the tricuspid valve","Into the IVC"],2,"Drainage ports in SVC and IVC; return port in the RA aimed at the TV (bicaval view 100–120°). Jet toward the septum or across a PFO causes recirculation/shunting; distal tip must not cross the TV.");
L(23,'mass',2,"With two-cannula VV-ECMO (femoral drainage, RA return), ideal separation between cannula tips to limit recirculation is about:",["1 cm","~10 cm","30 cm","No separation needed"],1,"Return tip in the RA/cavo-atrial junction, access cannula in the intrahepatic IVC ~10 cm apart.");
L(23,"mass",2,"On peripheral VA-ECMO, which echo signs indicate inadequate LV unloading?",["Small LV with frequent aortic valve opening each beat","Distended LV, closed AV, SEC, worse MR/AR, edema","Normal arterial pulsatility on the arterial line trace","A hyperdynamic, small LV cavity"],1,"Retrograde flow raises LV afterload; consider inotrope, IABP, Impella or LA/LV vent.");
L(23,"mass",2,"Echo predictors of successful VA-ECMO weaning at flow ≤ 1.5 L/min (Aissaoui 2011):",["LVOT VTI ≥10 cm, LVEF >20–25%, lateral s' ≥6 cm/s","TAPSE >25 mm alone, regardless of LV function on echo","Average E/e' above 15 at a flow of 1.5 L/min or less","IVC below 1 cm with >50% collapse"],0,"No single parameter suffices; combine echo, hemodynamics and clinical factors; assess RV too.");
L(23,'mass',2,"LVAD low-flow alarm with small LV, small RV, collapsing IVC most likely reflects:",["RV failure","Hypovolemia","Pump thrombosis","Severe AR"],1,"Hypovolemia: small LV/RV, low RAP. RV failure: small LV, large RV, high RAP. Tamponade: small chambers, high RAP, effusion/compression. Inflow/outflow obstruction: large LV, high cannula velocity (>1.5–2 m/s).");
L(23,"mass",2,"LVAD high-flow/high-power with dilated LV, rightward septum, frequent AV opening and raised LDH suggests:",["Hypovolemia with suction of the septum onto the inflow","Pump thrombosis (or severe aortic regurgitation)","Cardiac tamponade compressing the right ventricle","A suction event from an underfilled LV"],1,"Thrombosis/severe AR: LV not unloaded despite power; vasodilation gives high flow with small LV. AR often worsens after LVAD and causes recirculation.");
L(23,"mass",2,"Why may hypoxemia develop after LVAD implantation in a patient with a PFO?",["Rising LA pressure from an inflow cannula malposition","LV/LA decompression lowers left pressures → R-to-L shunt","New aortic regurgitation driving cardiogenic pulmonary edema","Chronic RV hypertrophy from long-standing PH"],1,"Screen and close PFO at implant; bubble study if unexplained desaturation.");
L(23,"mass",1,"Correct IABP tip position on TEE is:",["At the aortic valve level","1–2 cm distal to the left subclavian artery","At the renal arteries in the abdominal aorta","In the proximal ascending aorta"],1,"Contraindications: moderate–severe AR, aortic dissection, severe aortic atheroma.");

// Lecture 24 — Ischemic Heart Disease & LV Wall Motion
L(24,'lv',1,"In the 17-segment model, the basal inferior and mid inferior walls are classically supplied by:",["LAD","RCA (PDA)","Left circumflex alone","Diagonal branch"],1,"Inferior = RCA; anterior/anteroseptal/apex = LAD; lateral/inferolateral = LCx (overlapping). No region is supplied by the LCx alone. Apical cap = segment 17.");
L(24,'lv',1,"Best single view to diagnose an acute RCA infarct:",["PLAX","A4C","A3C","A2C"],3,"A2C shows the inferior and anterior walls; the inferior wall is RCA territory.");
L(24,"lv",2,"Which statement about systolic myocardial motion is most accurate?",["Abnormal wall motion is always ischemic in origin, never otherwise","Abnormal septal motion with normal thickening (surgery, LBBB)","Motion and thickening are both independent of loading conditions","Abnormal septal motion never occurs with RBBB"],1,"Use THICKENING, not motion: LBBB, post-op septal translation, WPW, pacing, RV volume/pressure overload alter motion but preserve thickening.");
L(24,'lv',2,"Wall motion score for a segment with < 10% wall thickening and no outward systolic motion:",["1","2","3","4"],2,"1 normal (≥40% WT), 2 hypokinetic (<40%), 3 akinetic (<10%), 4 dyskinetic (systolic outward expansion). WMSI = sum / segments visualized; > 1.5 = poor outcome.");
L(24,"lv",2,"Echo features that favour an OLD infarct over acute ischemia:",["Normal-thickness akinetic segment that improves with nitrates","Thin (<5 mm), bright akinetic/dyskinetic wall, aneurysmal","A hyperdynamic segment adjacent to the infarct zone","Normal regional wall motion with a normal thickening"],1,"Acute ischemia: normal-thickness NK/HK/AK wall, may resolve with nitrates. Absent RWMA does not exclude CAD (small/branch vessel, collaterals).");
L(24,"lv",2,"Post-menopausal woman with chest pain after emotional stress, apical ballooning beyond a single coronary territory, modest troponin. Most likely?",["Anterior STEMI from LAD occlusion","Takotsubo (stress) cardiomyopathy","Acute viral myocarditis","Acute type A aortic dissection"],1,"Transient LV dysfunction, non-coronary distribution, normalizes in weeks. Variants: midventricular, reverse (basal), may involve RV apex. Can cause LVOT obstruction / SAM.");
L(24,"lv",2,"Echo features that distinguish LV pseudoaneurysm (contained free-wall rupture) from a true aneurysm:",["Wide neck and obtuse angle with myocardium lining the whole sac wall","Abrupt wall break, narrow neck (<0.5), clot and to-and-fro flow","Akinetic, thinned wall that still contains myocardium on every view","Located only at the LV apex, never involving the inferior or lateral wall"],1,"True aneurysm: wide neck, contains myocardium, mostly apical, rupture very rare. Pseudoaneurysm: pericardium-contained, often inferolateral, effusion common, high rupture risk.");
L(24,"lv",2,"Post-infarct ventricular septal rupture after an INFERIOR MI is typically:",["Simple, direct defect in the apical septum","Complex serpiginous tract in the basal inferoseptum","A defect through the membranous septum near the AV","Never visible on TTE; only diagnosed at surgery"],1,"Anterior MI: simple tear in distal/apical septum. Inferior MI: complex, basal inferoseptum. Occurs 1–7 days; harsh holosystolic murmur ± thrill; RVSP = SBP − 4V².");
L(24,"valve",2,"Three days after MI: acute pulmonary edema, hypotension, soft murmur, small hyperdynamic LV, normal LA size. Most likely?",["Ventricular septal rupture with a left-to-right shunt","Papillary muscle rupture (usually posteromedial)","A large mobile LV apical thrombus","Dressler syndrome with a pericardial rub"],1,"PMPM has single (PDA) supply → 6–10× more often. MR may look trivial (eccentric, low gradient 'flash'); V-wave cutoff on CW; mobile mass on leaflet; absence of a loud murmur or flail does not exclude it.");
L(24,"rv",2,"Echo features of acute RV infarction:",["Small RV with a normal TAPSE and a normal IVC size","Dilated, hypokinetic RV, low TAPSE/S', plethoric IVC","LV apical ballooning with basal hyperkinesis","An isolated pericardial effusion without RV changes"],1,"Complicates ~50% of inferior MIs; hypotension, high JVP, clear lungs. Shock from RV infarct carries mortality similar to LV shock (SHOCK trial).");
L(24,"mass",1,"An acute LV thrombus after anterior MI typically appears:",["Laminated, bright and flat along the wall","Mobile, protruding, echolucent centre, akinetic apex","Attached to the anterior mitral leaflet tip","Moving independently of the wall like a reverberation"],1,"Chronic clots: brighter, laminated. Improve detection with UEA contrast, high frequency, apical focus. Mimics: trabeculations, false chords, near-field clutter.");

// Lecture 25 — Aortic Valve Disease
L(25,'valve',1,"Which finding is NOT consistent with severe aortic stenosis?",["Vmax 4.5 m/s","Calculated AVA 0.9 cm²","Dimensionless index 0.27","Mean gradient 55 mm Hg"],2,"Severe AS: Vmax ≥ 4 m/s, MG ≥ 40 mm Hg, AVA ≤ 1.0 cm², AVAi < 0.6 cm²/m², DI ≤ 0.25. DI 0.27 is above the severe threshold.");
L(25,'valve',2,"LVOT diameter 2.2 cm, LVOT VTI 25 cm, AV VTI 114 cm. AVA by continuity?",["0.53 cm²","0.83 cm²","1.2 cm²","3.8 cm²"],1,"LVOT CSA = 0.785 × 2.2² = 3.8 cm². AVA = 3.8 × 25 / 114 = 0.83 cm². LVOT diameter is squared — the largest source of error.");
L(25,"valve",2,"ICU patient, EF 30%: Vmax 3.0 m/s, MG 20 mm Hg, AVA 0.66 cm², LVOT VTI 9 cm, DI 0.16. Interpretation?",["Moderate AS with a well-preserved forward stroke volume","Possible low-flow, low-gradient severe AS (discordant)","Normal aortic valve with a hyperdynamic LVOT","Measurement error only; repeat with a smaller sample box"],1,"Low flow (SVi < 35 mL/m²) reduces gradient. DI ≤ 0.25 is flow-independent; dobutamine stress distinguishes true severe from pseudo-severe AS.");
L(25,"valve",2,"Simplified Bernoulli for AS should use 4(V2² − V1²) when:",["Always, for every aortic stenosis gradient","LVOT velocity >1.5 m/s or AV velocity <3 m/s","Only when atrial fibrillation is present","Only when aortic regurgitation coexists"],1,"Otherwise proximal velocity is negligible. Peak instantaneous (echo) gradient > peak-to-peak (cath) gradient.");
L(25,"valve",2,"A late-peaking 'dagger-shaped' CW signal in the LVOT that increases with inotropes and hypovolemia indicates:",["Fixed valvular AS with a calcified valve","Dynamic LVOT obstruction","Mitral regurgitation picked up by the beam","A fixed subaortic membrane below the valve"],1,"AS: rounded, symmetric, starts after IVCT. MR: starts in IVCT, longer duration, higher velocity (≥5 m/s). Dynamic LVOTO: late peaking. Causes: HOCM, basal septal hypertrophy + hyperdynamic LV, hypovolemia, sigmoid septum, apical MI/Takotsubo, post-MV repair.");
L(25,'valve',1,"On TEE mid-esophageal AV short-axis, the cusp adjacent to the interatrial septum is the:",["Right coronary cusp","Left coronary cusp","Non-coronary cusp","Pulmonic cusp"],2,"NCC sits next to the IAS/atria; RCC is anterior (toward RVOT); LCC toward the left/PA.");
L(25,'valve',2,"Which AR parameter is relatively load-independent and works in eccentric jets?",["Jet width/LVOT ratio","Vena contracta width","Pressure half-time","Jet length"],1,"Severe AR VC > 0.6 cm. Jet/LVOT ratio (≥65%) and jet CSA/LVOT CSA (≥60%) apply to central jets only.");
L(25,'valve',1,"Which pressure half-time indicates severe AR?",["> 500 ms","350 ms","< 200 ms","PHT does not grade AR"],2,"Mild > 500 ms; severe < 200 ms. PHT shortens with high LVEDP, vasodilators; lengthens with high SVR. More accurate in acute AR.");
L(25,'valve',2,"Holodiastolic flow reversal in the ABDOMINAL aorta indicates:",["Mild AR","At least moderate AR","Severe AR","Normal finding"],2,"Descending thoracic reversal → at least moderate; abdominal holodiastolic reversal → severe. Also seen with aortopulmonary shunts / PDA.");
L(25,"valve",2,"Acute severe AR (e.g., endocarditis, type A dissection) differs from chronic AR in that:",["LV is dilated with a large, impressive color jet","Non-dilated LV, modest jet, short PHT, early MV closure","Pulse pressure is wide with bounding peripheral pulses","It is usually well tolerated for months or years"],1,"Abrupt volume load into a non-compliant LV: LVEDP rises rapidly → early MV closure, diastolic MR, shock and pulmonary edema.");
L(25,"valve",2,"Quantitative criteria of severe AR:",["EROA ≥0.2 cm², RVol ≥30 mL, RF ≥30%","EROA ≥0.3 cm², RVol ≥60 mL, RF ≥50%","EROA ≥0.4 cm², RVol ≥45 mL, RF ≥30%","Vena contracta >0.3 cm with a central jet"],1,"Note severe MR EROA ≥ 0.4 cm² vs severe AR ≥ 0.3 cm².");

// Lecture 26 — Tricuspid & Pulmonic Valve
L(26,"valve",2,"Which finding indicates severe tricuspid regurgitation?",["Soft, parabolic, late-peaking CW signal of low density","Systolic hepatic vein reversal; dense triangular CW","Vena contracta of 0.3 cm on zoomed color Doppler","Tricuspid E-wave velocity of 0.6 m/s"],1,"Severe TR: VC > 0.7 cm, jet area > 10 cm², PISA radius > 0.9 cm, EROA ≥ 0.4 cm², RVol ≥ 45 mL, tricuspid E > 1.0 m/s, dilated RA/RV/IVC.");
L(26,"valve",2,"In massive TR, why may RVSP be underestimated from TR velocity?",["Simplified Bernoulli fails at very high TR jet velocities","RA pressure is 'ventricularized' and hard to estimate","The Doppler angle is always perfect in severe TR","Coexisting pulmonic valve stenosis is very common in TR"],1,"TR velocity ≠ TR severity; a falling TR velocity may signal RV failure, not improvement.");
L(26,"valve",1,"The most common cause of tricuspid regurgitation is:",["Carcinoid heart disease with plaque deposits","Secondary/functional (left heart disease, PH, AF)","Ebstein anomaly with apical leaflet displacement","Infective endocarditis in people who inject drugs"],1,"~80% secondary; primary causes include rheumatic, IE, carcinoid, prolapse, trauma, pacing/ICD leads, biopsy, radiation.");
L(26,"valve",2,"Thickened, retracted, immobile tricuspid leaflets fixed in a semi-open position with free TR in a patient with flushing and diarrhea suggest:",["Rheumatic disease","Carcinoid heart disease","Infective endocarditis","Ebstein anomaly"],1,"Serotonin-mediated right-sided plaques; also affects the pulmonic valve (PS/PR). Left-sided involvement suggests PFO or lung metastases.");
L(26,"valve",2,"Ebstein anomaly is characterized by:",["Basal displacement of the anterior mitral leaflet with a cleft","Apical septal-leaflet displacement, atrialized RV, ASD/PFO, WPW","Absent pulmonic valve with aneurysmal pulmonary arteries","Cleft anterior mitral leaflet with a primum atrial defect"],1,"Associated with maternal lithium. Septal leaflet displacement ≥ 8 mm/m² vs mitral insertion.");
L(26,"valve",2,"Criteria for severe tricuspid stenosis:",["MG >5 mm Hg, PHT ≥190 ms, TVA ≤1.0 cm²","MG >10 mm Hg, TVA <2.0 cm², PHT ≥100 ms","MG >2 mm Hg on any inflow Doppler trace","Peak tricuspid inflow velocity above 4 m/s"],0,"Causes: rheumatic, carcinoid, congenital, prosthetic. Gradients rise with TR/high flow. RA and IVC dilated; RV usually normal size.");
L(26,'valve',2,"Pulmonic stenosis: RVSP 80 mm Hg, transpulmonic peak velocity 3.5 m/s. PA systolic pressure?",["31 mm Hg","49 mm Hg","80 mm Hg","129 mm Hg"],0,"Gradient = 4 × 3.5² = 49. PASP = RVSP − PV gradient = 80 − 49 = 31 mm Hg. RVSP ≠ PASP when RVOT/PV obstruction is present.");
L(26,"valve",2,"Severe pulmonic regurgitation (e.g., after TOF repair with transannular patch) shows:",["Long, slowly decelerating PR signal with a narrow central jet","Dense, steep PR signal ending early; wide jet; RV dilation","Small central jet confined to the valve level","Normal RV size with a faint, soft PR signal throughout diastole"],1,"Laminar low-velocity free PR is easily missed on color. Volume overload → diastolic septal flattening.");
L(26,'valve',1,"Most common valve involved in right-sided infective endocarditis:",["Pulmonic","Tricuspid (> 90%)","Eustachian valve","Mitral"],1,"RSIE is 5–10% of IE; risk factors: IVDU, CIEDs, dialysis access, congenital disease. Most are treated medically.");
L(26,'valve',2,"Gradient across a normally functioning bioprosthetic tricuspid valve is typically:",["< 3–5 mm Hg mean","10–15 mm Hg","> 20 mm Hg","Same as aortic prosthesis"],0,"Flow-dependent; rises with pregnancy, anemia, hyperthyroidism, TR. Reverberation artifact limits assessment.");

// Lecture 27 — Mitral Valve Disease
L(27,'valve',2,"Which parameter is NOT used in guideline grading of mitral stenosis severity?",["Pressure half-time","Mean transmitral gradient","Peak transmitral gradient","Mitral valve area"],2,"Severe MS: MVA ≤ 1.5 cm² (very severe < 1.0), MG 5–10 (> 10 very severe), PHT ≥ 150 (> 220 very severe), PASP > 30 mm Hg. Peak gradient is not a grading criterion. Always report MG with heart rate.");
L(27,'valve',1,"Mitral PHT is 220 ms. MVA by the PHT method?",["0.8 cm²","1.0 cm²","1.2 cm²","2.2 cm²"],1,"MVA = 220 / PHT = 1.0 cm². PHT = DT × 0.29.");
L(27,"valve",2,"Rheumatic MS patient in septic shock, HR 110: MVA by PHT 2.5 cm², mean gradient 20 mm Hg. Her MS is:",["Mild (progressive)","Moderate (progressive)","Severe (stage D)","Very severe (MVA ≤1.0)"],0,"Gradient is flow- and HR-dependent (tachycardia shortens diastole, high CO raises flow). Valve area defines severity.");
L(27,'valve',2,"Which condition makes the PHT method OVERESTIMATE mitral valve area?",["Impaired LV relaxation (grade 1)","Severe AR or reduced LV compliance","Sinus bradycardia","Mild MR only"],1,"AR and stiff LV raise LVEDP rapidly → shorter PHT → larger calculated MVA. Impaired relaxation prolongs PHT → underestimates MVA. Also inaccurate immediately after balloon valvotomy.");
L(27,'valve',3,"MS PISA: radius 0.89 cm, aliasing velocity 59 cm/s, peak MV velocity 180 cm/s, funnel angle 60°. MVA?",["0.36 cm²","0.54 cm²","1.1 cm²","1.6 cm²"],1,"MVA = 2πr² × Va / Vmax × (α/180) = 1.63 × 0.33 ≈ 0.54 cm².");
L(27,"valve",2,"MR PISA: radius 1.0 cm, aliasing velocity 40 cm/s, MR Vmax 5 m/s. EROA?",["< 0.2 cm² (mild)","0.2–0.3 cm² (moderate)","0.3–0.4 cm² (moderate–severe)","> 0.4 cm² (0.5)"],3,"EROA = 2πr² × Va / Vmax = 6.28 × 40 / 500 = 0.50 cm². Shortcut with Va 40, Vmax 5 m/s: EROA ≈ r²/2. RVol = EROA × VTI_MR (0.4 × 150 = 60 mL).");
L(27,'valve',2,"MV annulus 3.2 cm, MV VTI 14.6 cm; LVOT 1.8 cm, LVOT VTI 26 cm. Mitral regurgitant volume?",["21 mL","51 mL","66 mL","117 mL"],1,"SV_MV = 0.785 × 3.2² × 14.6 ≈ 117 mL; SV_LVOT = 0.785 × 1.8² × 26 ≈ 66 mL; RVol = 51 mL (moderate; severe ≥ 60). Invalid with significant AR.");
L(27,'valve',1,"Which finding is most specific for severe MR?",["Blunted systolic pulmonary venous flow","Systolic flow reversal in pulmonary veins","A-wave dominant mitral inflow","Jet area 20% of LA"],1,"Blunting is non-specific (high LAP, AF). Severe MR: VC ≥ 0.7 cm, EROA ≥ 0.4 cm², RVol ≥ 60 mL, RF ≥ 50%, E > 1.2 m/s, dense triangular CW. A-dominant inflow essentially excludes severe MR.");
L(27,"valve",2,"Acute severe MR from papillary muscle rupture may be UNDERESTIMATED on color because:",["The LA is already dilated and very compliant in acute MR","Stiff small LA → fast equalization, brief eccentric jet","High systolic blood pressure increasing the apparent jet size","The LV is dilated, spreading the regurgitant flow"],1,"Look for flail leaflet/ruptured head, hyperdynamic LV, normal LA size, V-wave cutoff on CW. Hypertension makes MR jet area look larger for the same EROA.");
L(27,"valve",2,"Carpentier type IIIb mitral regurgitation is caused by:",["Leaflet prolapse or flail from chordal rupture","Annular dilation with normal leaflet motion","Systolic restriction from LV dilation/tethering","Leaflet perforation after endocarditis"],2,"I: normal motion (annular dilation, perforation). II: excessive motion (prolapse ≥ 2 mm above annulus in PLAX, flail). IIIa: restricted in systole+diastole (rheumatic). IIIb: restricted in systole (functional/ischemic).");
L(27,"valve",2,"Contraindications to percutaneous mitral balloon valvotomy include:",["Wilkins score under 8 with mobile leaflets","Moderate or worse MR, or LA/LAA thrombus","Sinus rhythm with a normal-sized left atrium","Pliable, non-calcified leaflets and commissures"],1,"Favorable: Wilkins ≤ 8, MVA ≤ 1.5 cm² with symptoms.");

// Lecture 28 — Intracardiac Masses
L(28,'mass',1,"The most common primary cardiac tumor is:",["Papillary fibroelastoma","Myxoma","Lipoma","Angiosarcoma"],1,"Myxoma (20–30%): LA attached to the interatrial septum (fossa ovalis) by a stalk, gelatinous/friable — embolism and AV-valve obstruction. Carney complex (AD, ~7%). Can recur.");
L(28,"mass",1,"The most common benign tumor of cardiac valves is:",["Myxoma","Papillary fibroelastoma","Rhabdomyoma","Fibroma (fibrous tumor)"],1,"Small, mobile, frond-like ('sea anemone'), on the downstream side; can embolize or occlude a coronary ostium — benign tumor, malignant course.");
L(28,"mass",2,"Which features favour LV thrombus over tumor?",["Stalk attachment to a normally contracting, thick-walled segment","On an akinetic segment, avascular, shrinks on anticoagulants","Hypervascular enhancement after contrast with a feeding vessel","Invading the myocardium beyond the endocardium"],1,"Assess location, attachment, shape/texture, vascularity (contrast perfusion), wall motion. Echo cannot give a pathological diagnosis.");
L(28,"mass",2,"Features that favour a malignant cardiac mass:",["Pedunculated LA mass attached to the atrial septum by a stalk","Broad-based, invasive, rapidly growing, vascular, with effusion","Small calcified nodule on a valve leaflet tip in an older patient","Thin-walled echolucent cyst with no blood flow"],1,"Metastases are far more common than primary tumors. Angiosarcoma: RA free wall. Lymphoma: infiltrative, chemo-responsive.");
L(28,"mass",1,"A ridge between the LAA and left upper pulmonary vein on TEE is:",["Organised thrombus within the LA appendage","Coumadin (warfarin) ridge, a normal variant","Left atrial myxoma on a short stalk","Vegetation attached to the tip of the ridge"],1,"Normal variants mimicking masses: moderator band (RV), Eustachian valve/Chiari network (RA), crista terminalis, lipomatous hypertrophy of IAS, LAA pectinate muscles, false tendons.");
L(28,"mass",2,"Lipomatous hypertrophy of the interatrial septum characteristically:",["Involves and thickens the fossa ovalis","Dumbbell shape that spares the fossa ovalis","Is highly mobile, swinging with each beat","Is always a malignant infiltrating tumor"],1,"Fat deposition in the septum (> 1.5 cm), common in elderly/obese — benign; do not confuse with myxoma (which attaches at the fossa ovalis).");
L(28,"mass",2,"A serpiginous, highly mobile right atrial mass prolapsing through the tricuspid valve in a dyspneic patient with DVT is most consistent with:",["Right atrial myxoma","Thrombus in transit","Chiari network","Septal lipoma"],1,"Emergency: high early mortality; consider thrombolysis vs surgical embolectomy; look for PFO and paradoxical embolism risk.");
L(28,"mass",2,"Persistent bacteremia after removal of a hemodialysis catheter with an RA mass where the catheter tip was. Most likely?",["Right atrial myxoma on a stalk","Infected fibrin sheath ('ghost')","Lipomatous septal hypertrophy","Prominent Eustachian valve remnant"],1,"Catheter-related thrombus/fibrin sheath may persist after line removal and act as a nidus of infection.");
L(28,"art",2,"A tapered, bright linear echo extending distally from a prosthetic valve or pacemaker lead is most likely:",["Small vegetation","Comet-tail artifact","Mobile thrombus","Papillary fibroelastoma"],1,"Reverberations appear at multiples of the true depth (d, 2d). Artifacts cross anatomic borders and move with the reflector.");
L(28,"valve",2,"Diastolic flow in the LVOT with a perforated, aneurysmal non-coronary cusp after endocarditis indicates:",["Dynamic LVOT obstruction","AR through the cusp perforation","Normal diastolic LVOT flow","Mitral stenosis inflow jet seen"],1,"Endocarditis complications: perforation, abscess, pseudoaneurysm, fistula; TEE for prosthetic valves, CIEDs and suspected perivalvular extension.");

// Lecture 29 — Congenital Heart Disease in Adults
L(29,'valve',1,"Most common bicuspid aortic valve morphology:",["R–L cusp fusion (~86%)","R–NC fusion","L–NC fusion","True bicuspid without raphe"],0,"BAV ~2% prevalence, M:F 2–3:1. Best view PSAX in systole (fish-mouth). Systolic doming and eccentric closure in PLAX.");
L(29,"valve",2,"Associations of bicuspid aortic valve:",["Ebstein anomaly of the tricuspid valve","Aortopathy and coarctation (~7% of BAV)","Cleft mitral valve with a primum ASD","Sinus venosus ASD with anomalous veins"],1,"Most BAV become stenotic by age 75; aneurysm risk ~20% at 25 years; dissection risk increased.");
L(29,"vasc",2,"Abdominal aortic PW Doppler showing blunted, delayed systolic upstroke with continuous antegrade diastolic flow suggests:",["Severe aortic regurgitation","Aortic coarctation","Arteriovenous fistula","Normal abdominal flow"],1,"Coarctation: high-velocity CW across isthmus with diastolic 'tail' (suprasternal). Holodiastolic REVERSAL suggests AR instead. Coarctation increases intracranial aneurysm risk ~5-fold.");
L(29,"mass",1,"A patent foramen ovale:",["Causes right heart volume overload in most adults","Found in ~25–35% of adults; no RV dilation","Is a form of ostium primum atrial septal defect","Always shunts left to right in every patient"],1,"Agitated saline with Valsalva; bubbles in the LA within 3 cardiac cycles of RA opacification = intracardiac shunt; after 3–5 cycles = intrapulmonary shunt. TEE is the preferred direct diagnosis.");
L(29,'rv',2,"Which defect does NOT typically cause right heart dilation?",["Secundum ASD","Sinus venosus ASD","Partial anomalous pulmonary venous return","Ventricular septal defect"],3,"VSD shunt volume passes RV → PA in systole and loads the LV/LA (LV dilation). Atrial-level shunts (pre-tricuspid) dilate the RA/RV.");
L(29,'mass',2,"Most common type of atrial septal defect:",["Primum","Secundum (~80%)","Sinus venosus","Coronary sinus"],1,"Primum ~15%, sinus venosus 5–10%, coronary sinus < 1%. Primum ASD (partial AVSD): inferior septum, cleft MV, LAD on ECG, Down syndrome.");
L(29,"mass",2,"Sinus venosus ASD is commonly associated with:",["Cleft anterior mitral valve leaflet","Anomalous right upper pulmonary vein","Coarctation of the thoracic aorta","Ebstein anomaly of the tricuspid"],1,"Superior/posterior septum at the SVC–RA junction; often missed on TTE — use TEE/CT/MRI. Suspect when RV is dilated and no defect is seen.");
L(29,"hemo",2,"A Qp/Qs ratio considered significant for a left-to-right shunt is:",["> 0.8 (closure if any shunt at all)","> 1.5 (closure if RV overload)","Exactly 1.0 (balanced flow)","< 0.5 (reversed shunt flow)"],1,"Qp = RVOT CSA × RVOT VTI; Qs = LVOT CSA × LVOT VTI. Closure is indicated with RA/RV enlargement and Qp:Qs ≥1.5, provided PASP < ½ systemic and PVR < ⅓ systemic (AHA/ACC 2018). Eisenmenger may return the ratio to ~1.0.");
L(29,"valve",2,"The most common long-term problem after tetralogy of Fallot repair (transannular patch) is:",["Residual VSD with left-to-right shunt","Severe PR with RV dilation","Acquired mitral stenosis","Recurrent aortic coarctation"],1,"Others: residual PS, VSD, AR, RV dysfunction, arrhythmias (VT). TOF: VSD, overriding aorta, RVOT obstruction, RVH.");
L(29,'rv',3,"After an atrial switch (Mustard/Senning) for d-TGA, the systemic ventricle is the:",["Morphologic LV","Morphologic RV","Single ventricle","LV via Rastelli conduit"],1,"Late problems: systemic RV failure, TR, baffle leak/obstruction, arrhythmia. Arterial switch restores LV as systemic ventricle (watch coronary reimplantation and neo-aortic root).");

const BN={};function B(bk,t,d,stem,opts,ans,exp){const n=BN[bk]=(BN[bk]||0)+1;Q.push({src:'Book',bk,n,t,d,stem,opts,ans,exp});}
// Chapter 01 — Basics: Physics, Modalities, and Image Acquisition
B(1,'phys',1,"You are preparing for ultrasound-guided right internal jugular cannulation in a ventilated ICU patient. The vein lies about 1.5 cm below the skin. Which transducer choice best fits this task?",["Linear transducer around 10 MHz for high axial resolution at shallow depth","Phased-array transducer around 2 MHz for deep penetration through rib spaces","Curvilinear transducer around 3 MHz for a wide abdominal field of view","Endocavitary transducer around 6 MHz for a small microconvex footprint"],0,"Superficial needle guidance needs high axial resolution with only a few centimetres of penetration, so a high-frequency linear probe (5–13 MHz range, ~10 MHz) is ideal. Low-frequency phased-array or curvilinear probes (1–5 MHz) trade resolution for depth and are suited to the heart, abdomen or a 200-kg patient's aorta.");
B(1,'dop',3,"During pulsed-wave Doppler interrogation, the machine is operating at a pulse repetition frequency (PRF) of 8 kHz. What is the maximum Doppler frequency shift that can be displayed without aliasing?",["2 kHz","4 kHz","8 kHz","16 kHz"],1,"The Nyquist limit equals PRF/2, so 8 kHz/2 = 4 kHz. Shifts above this wrap around to the other side of the baseline (aliasing); increasing PRF, minimizing depth or moving the baseline reduces it.");
B(1,'dop',2,"Pulsed-wave Doppler of the carotid artery shows the peak of the systolic envelope truncated and displayed below the baseline. Which adjustment will help eliminate this finding?",["Increase the imaging depth","Decrease the velocity scale (PRF)","Shift the baseline","Increase the 2D gain"],2,"This is aliasing from exceeding the Nyquist limit (PRF/2). Moving the baseline, increasing PRF (velocity scale) and minimizing depth reduce aliasing; increasing depth lowers PRF and worsens it, and 2D gain has no effect on the Doppler scale.");
B(1,'dop',2,"A hypotensive patient with suspected pulmonary embolism has a tricuspid regurgitant jet on color Doppler. You want the peak jet velocity to estimate pulmonary artery pressure. Which modality is most appropriate and why?",["Pulsed-wave Doppler, because its range specificity localizes the peak velocity","Color power Doppler, because it is direction independent in low-flow states","Tissue Doppler, because it is filtered to display low-velocity signals","Continuous-wave Doppler, because it is not limited by the Nyquist limit"],3,"Continuous-wave Doppler uses 2 crystals transmitting and receiving continuously, so it is not subject to the Nyquist limit and can record very high velocities such as TR jets and stenotic valves. Its trade-off is range ambiguity; pulsed-wave Doppler has range specificity but aliases at high velocities.");
B(1,'phys',2,"While imaging a target at a fixed depth of 12 cm, the operator switches the transducer from 2 MHz to 4 MHz. What happens to attenuation?",["It decreases, because higher frequency penetrates deeper","It increases, because the attenuation coefficient rises with frequency","It is unchanged, because attenuation depends only on depth","It is unchanged, because attenuation depends only on tissue type"],1,"Total attenuation = attenuation coefficient × depth, and the attenuation coefficient is proportional to frequency. Doubling frequency at the same depth increases signal loss, which is why high frequency gives better resolution but shallower penetration.");
B(1,"phys",2,"Why do air and bone make poor acoustic windows compared with water and soft tissue?",["Their impedance differs greatly from soft tissue, so most energy reflects","Air and bone convert all incident energy into heat by absorption, leaving none","Air and bone are anechoic because they send no echoes back to the transducer","Air and bone lower the effective frequency, which degrades axial resolution"],0,"Reflection depends on the acoustic impedance mismatch (Z = density × propagation speed). Water (~1,480 m/s) and soft tissue (1,540 m/s) have similar impedance, so little energy is reflected, whereas air and bone differ greatly from soft tissue. Frequency is set by the transducer, not the medium.");
B(1,'phys',2,"Tissue harmonic imaging is turned on with a fundamental transmit frequency centred at 2 MHz. Which frequency is predominantly used for image formation?",["1 MHz subharmonic","6 MHz third harmonic","8 MHz fourth harmonic","4 MHz second harmonic"],3,"The second harmonic (2 × 2 = 4 MHz) is generated within tissue and is used for imaging, while the fundamental is filtered or cancelled (e.g., pulse inversion). Harmonics are weak in near-field reverberations and side lobes, so artifacts fall and signal-to-noise improves in difficult patients.");
B(1,"phys",2,"In a technically difficult apical view, the left ventricular apex at 6 cm appears sharp, but the mitral annulus at 14 cm is laterally blurred. Which adjustment most directly improves lateral resolution at the annulus?",["Increase the overall gain to brighten the far field","Increase the transducer frequency for finer detail","Move the focal zone to the depth of the mitral annulus","Increase the sector width to include the whole annulus"],2,"Lateral resolution is maximal at the focal zone, where beam width is narrowest, and falls dramatically deep to it. Place the focal zone at, or slightly deeper than, the area of interest. Raising frequency mainly targets axial resolution and costs penetration at depth.");
B(1,"phys",2,"You want to evaluate a rapidly moving mitral valve leaflet in 2D. The current image has excessive depth with unused screen space below the heart. What is the main benefit of reducing depth?",["It raises transducer frequency and therefore axial resolution","It improves lateral resolution by narrowing the beam at all depths","Larger image and higher frame rate, as less listening time is needed","It reduces attenuation by lowering the tissue attenuation coefficient"],2,"Depth is the first control adjusted. Decreasing depth enlarges the displayed field and, by shortening wait time between pulses (higher PRF), increases frame rate for moving structures such as valves. Frequency is fixed by the transducer, and the attenuation coefficient depends on frequency, not depth.");
B(1,'art',2,"While imaging the femoral artery in transverse section, a dark vertical band is seen deep to the lateral border of the round vessel, with no bright reflector above it. What is the most likely explanation?",["Acoustic shadowing from a calcified plaque","Side lobe artifact from an off-axis reflector","Reverberation between the skin and the vessel wall","Edge artifact from refraction at the curved vessel border"],3,"Edge artifact occurs at the lateral border of a circular structure when the beam strikes nearly tangentially; increased refraction produces a dark band deep to the edge. Unlike true acoustic shadowing, it arises without a strongly reflecting structure (such as bone or a stone).");
B(1,'art',2,"During bladder imaging, a faint echogenic signal appears inside the anechoic lumen at the same depth as a bright echogenic structure lying just outside the main beam. What is this artifact?",["Side lobe artifact","Posterior acoustic enhancement","Mirror-image reverberation","Edge artifact"],0,"Side lobe artifact comes from beams sent outside the central slice that reflect off strong off-axis reflectors and are displayed over the main image, typically within anechoic or hypoechoic structures such as the bladder or a vessel, at the depth of the responsible reflector.");
B(1,'art',1,"During an ultrasound-guided procedure, multiple evenly spaced bright lines appear parallel to and deep to the metallic needle. What is this artifact?",["Acoustic shadowing","Reverberation","Side lobe artifact","Posterior acoustic enhancement"],1,"Reverberation is generated between 2 parallel, highly reflective surfaces, such as the skin and a needle, wire, pleural line or soft-tissue air. It appears as hyperechoic lines parallel to and deep to the reflecting structure.");
B(1,'dop',1,"Which Doppler mode is essentially pulsed-wave Doppler filtered to display the low velocities of myocardial motion, and is commonly used when assessing diastolic function?",["Continuous-wave Doppler","Color power Doppler","Color flow Doppler","Tissue Doppler"],3,"Tissue Doppler is pulsed-wave Doppler filtered for the slower velocities of tissue rather than intracardiac blood, for example at the lateral mitral annulus. Color power Doppler ignores direction and is used for low-flow states such as testicular or ovarian imaging.");
B(1,"phys",2,"In a parasternal long-axis view, the near field (right ventricle) appears appropriately bright, but the posterior left ventricular wall and pericardium in the far field appear too dark. Which control best corrects this?",["Increase the overall gain until the far field is bright","Adjust the TGC sliders for the deeper field","Increase the transducer frequency for better penetration","Add more focal zones to the far field of the image"],1,"TGC sliders each control brightness at a separate depth and are set so similar tissues appear equally bright regardless of depth. Overall gain amplifies all echoes equally and would overbrighten the near field; extra focal zones improve lateral resolution at the cost of frame rate.");

// Chapter 02 — Transthoracic Echocardiography Examination
B(2,'views',1,"You have a good parasternal long-axis view with the indicator pointing at the patient's right shoulder. How do you obtain the parasternal short-axis view?",["Rotate the transducer 90° counterclockwise so the indicator points to the left hip","Tilt the tail toward the right shoulder without rotating","Rotate the transducer 90° clockwise so the indicator points to the left shoulder","Slide the transducer down 2 intercostal spaces and rock the tail left"],2,"PSAX is obtained by rotating 90° clockwise from PLAX, ending with the indicator toward the left shoulder, while keeping the transducer axis fixed. If the image is lost, return to a standard PLAX and rotate again.");
B(2,'views',2,"While attempting a parasternal long-axis view, you instead see the right atrium, tricuspid valve and right ventricle, with no left ventricle or aortic root. What is the correct adjustment?",["Tilt the tail of the transducer down slightly","Tilt the tail of the transducer up further","Rotate the transducer 90° clockwise","Slide the transducer one intercostal space up"],0,"This is the RV inflow view, produced by tilting the tail up from a standard PLAX; correct it by tilting the tail down. Tilting the tail down too far from PLAX produces the RV outflow view (RVOT, pulmonic valve, PA).");
B(2,"rv",2,"A ventilated patient with suspected pulmonary hypertension has a parasternal short-axis view in which the left ventricle appears teardrop-shaped. What is the most appropriate interpretation?",["The teardrop shape confirms RV pressure overload in this patient","A teardrop LV indicates RV volume rather than pressure overload","Septal flattening can be judged only from the subcostal window","Likely off-axis; judge septal flattening on an on-axis mid PSAX"],3,"An on-axis PSAX shows a circular LV normally or a D-shaped LV with RV pressure or volume overload. An off-axis view can make the LV look like a teardrop, oval or pear and mimic septal flattening; correct it by sliding an intercostal space or by tilting, rocking or rotating.");
B(2,"views",2,"In an apical 4-chamber view, the heart appears to lean to the side and the right ventricle sits near the top of the screen. The RV looks dilated. What is the best next step?",["Accept it as true RV dilatation and evaluate for pulmonary embolism","Slide laterally and rock the tail left until the apex is at the top","Tilt the tail cephalad to bring the coronary sinus into the plane","Rotate the transducer 60° counterclockwise to open the RV fully"],1,"A leaning heart with the RV near the top means the transducer is too medial. Slide laterally and rock the tail left until the apex is on top and the septum is vertical. A medially displaced A4C can create the illusion of RV enlargement when the RV is normal.");
B(2,'views',2,"An apical 4-chamber view shows the ventricles and right atrium, but the left atrium is foreshortened and the coronary sinus is seen between the ventricles and atria. How should the image be corrected?",["Tilt the tail caudad to angle the beam more anteriorly","Tilt the tail cephalad to angle the beam more posteriorly","Rotate the transducer clockwise by 60°","Slide the transducer medially one intercostal space"],0,"A visible coronary sinus with a foreshortened LA means the beam is aimed at the caudal/inferior heart. Tilting the tail caudad angles the beam anteriorly. If lung then blocks the image, sliding down an intercostal space may give a better window.");
B(2,'lv',2,"From a standard apical 4-chamber view, the transducer is rotated 60° to 90° counterclockwise. Which left ventricular walls are now displayed, and which chamber disappears?",["Anteroseptal and inferolateral walls; the left atrium disappears","Anterolateral and inferoseptal walls; the right atrium disappears","Anterior and inferior walls; the right ventricle disappears","Anteroseptal and inferior walls; the aortic root disappears"],2,"The A2C shows the LV anterior and inferior walls and the LA, with no RV. A4C shows anterolateral and inferoseptal walls; rotating a further 60° gives the apical long-axis view, showing anteroseptal and inferolateral walls.");
B(2,'phys',3,"An ultrasound beam takes 0.1 ms to travel through 7.7 cm of tissue and return. If imaging depth is set to 15.4 cm and the sector contains 100 scan lines, what is the approximate maximum 2D frame rate (ignoring processing time)?",["25 frames/s","50 frames/s","100 frames/s","200 frames/s"],1,"At 15.4 cm each scan line takes 0.2 ms, so 100 lines take 20 ms per frame, or about 50 frames/s. Frame rate depends more on sector width, depth and scan line density than on transducer frequency, so narrowing the sector or reducing depth increases temporal resolution.");
B(2,'views',1,"Tilting through the parasternal short-axis view, which finding identifies the midventricular (midpapillary) level?",["Absence of papillary muscles and mitral leaflets","Anterior and posterior mitral leaflets in a fish-mouth appearance","All 3 aortic valve cusps with both atria","Anterolateral and posteromedial papillary muscles"],3,"The midventricular PSAX is defined by the anterolateral (about 3 o'clock) and posteromedial (about 7 o'clock) papillary muscles. The apex has no papillary muscles, the base shows the mitral leaflets (fish mouth), and further tilting shows the aortic valve (RV inflow-outflow view).");
B(2,"fluid",2,"You are measuring the IVC from the subcostal window to assess fluid responsiveness in a hypotensive patient. A tubular vessel is seen in long axis. What must be shown to ensure accurate measurement?",["Pulsatile flow on color Doppler along the whole length of the vessel","Complete collapse of the vessel during inspiration","A diameter clearly smaller than the adjacent aorta","Its entry into the RA, measured near the cavoatrial junction"],3,"Recording the IVC entering the RA confirms the vessel is not the aorta, and IVC measurements are standardized near the cavoatrial junction. The hepatic vein is often seen joining it. IVC size and collapsibility are measured from the subcostal window.");
B(2,"views",2,"A mechanically ventilated patient after sternotomy has chest dressings and hyperinflated lungs, so parasternal and apical windows cannot be obtained. Which view is the most useful substitute for the apical 4-chamber view?",["Subcostal 4-chamber view, overhand grip, ~2 cm below the xiphoid","Suprasternal view with the indicator toward the left shoulder","Apical long-axis view with the indicator toward the right shoulder","RV inflow view from the parasternal window with a medial tilt"],0,"When body habitus, ventilation or dressings prevent an A4C, the subcostal 4-chamber view is a useful substitute. Place the probe about 2 cm below the xiphoid, nearly flat, with an overhand grip and the indicator at 3 o'clock. It also suits RV wall thickness and inferior pericardial effusion.");
B(2,"peri",2,"A hypotensive patient with chest pain has a large pericardial effusion with tamponade physiology on the first subcostal view. Why must the examination continue to the parasternal long-axis view before concluding?",["PLAX is required to measure the IVC diameter and collapse","PLAX is the only view able to quantify the effusion volume","PLAX may show an aortic root dissection feeding the effusion","PLAX is needed to confirm right atrial collapse on M-mode"],2,"Examinations must be complete; never stop at the first abnormal finding. Stopping after a subcostal view showing effusion and tamponade could miss an aortic root dissection, visible on PLAX, that communicates with the pericardial space. IVC size and collapsibility are measured from the subcostal window.");
B(2,'views',1,"During critical care echocardiography, an intensivist sees a possible but uncertain regional wall motion abnormality. Under the principle of favoring specificity over sensitivity, what is the appropriate action?",["Treat as acute coronary syndrome because missing it is dangerous","Seek consultation or additional evidence before changing management","Disregard the finding because focused studies are qualitative","Repeat the study only after the patient is extubated"],1,"Critical care echo favors specificity: a definite finding should change management, while an uncertain finding requires consultation or more evidence. Misdiagnosis is the main risk, especially for novices, and any uncertainty should prompt consultation with a local expert.");
B(2,"shock",2,"A patient with massive hemorrhage has received multiple transfusions and is now hypoxemic. Echocardiography shows an enlarged right ventricle and an underfilled left ventricle. What is the most appropriate interpretation?",["Not necessarily PE; consider alternatives such as TRALI","Diagnostic of pulmonary embolism and warrant thrombolysis now","An underfilled LV effectively excludes RV pressure overload","They indicate pericardial tamponade until proven otherwise"],0,"Correlate findings with clinical context and avoid anchoring. In a transfused hemorrhage patient, RV enlargement with an underfilled LV may reflect TRALI rather than PE. Ask whether the echocardiographic diagnosis makes sense clinically.");
B(2,'views',2,"In a patient with a systolic murmur, you need to calculate cardiac output and evaluate for left ventricular outflow obstruction. Starting from an apical 4-chamber view, which maneuver gives the most appropriate view?",["Rotate counterclockwise 60° to 90° to obtain the apical 2-chamber view","Slide medially to obtain the subcostal 4-chamber view","Rotate 90° clockwise to obtain the parasternal short-axis view","Tilt the tail slightly caudad to obtain the apical 5-chamber view"],3,"The A5C, obtained by tilting the tail caudad from A4C, brings the LVOT, aortic valve and proximal aorta into view between the atria. This aligns flow for cardiac output, aortic stenosis and LVOT obstruction assessment. Its basal walls are more anterior than those in A4C.");

// Chapter 03 — Transesophageal Echocardiography Examination in the ICU
B(3,'peri',2,"A 65-year-old man is 6 hours after mitral valve repair. He develops hypotension, rising filling pressures, and falling chest-tube output. TTE windows are limited by drains and dressings and show no obvious pericardial fluid. What is the most appropriate next step?",["Perform TEE to look for a localized pericardial collection or clot","Accept the TTE as excluding tamponade and start an inotrope","Repeat TTE from the apical window after the drains are removed","Use the subcostal IVC diameter to exclude tamponade"],0,"In the first 72 h after cardiac surgery, TTE fails to show the fluid in almost 60% of cases. These effusions are often small and localized and do not cause classic tamponade signs. TEE is preferred for postoperative effusion or tamponade.");
B(3,'views',1,"Which of the following is an ABSOLUTE contraindication to TEE probe insertion?",["Hiatal hernia","Previous esophagectomy","Barrett's esophagus","Esophageal varices with recent bleeding"],1,"ASE absolute contraindications: perforated viscus, esophageal stricture/tumor, perforation or laceration, esophageal diverticulum, active upper GI bleed, and recent esophageal/gastric surgery (an esophagectomized patient has no native esophagus to intubate). Relative: hiatal hernia, varices, recent (not active) upper GI bleed, Barrett's esophagus, prior neck/mediastinal radiation, coagulopathy, dysphagia, restricted neck mobility.");
B(3,'fluid',2,"A septic patient on volume-controlled ventilation (tidal volume 8 mL/kg) is fully sedated with no spontaneous breathing effort. In the TEE bicaval view, M-mode shows 45% respirophasic variation in SVC diameter. How should this be interpreted?",["Not interpretable, because SVC variation applies only to spontaneously breathing patients","Suggests fluid intolerance and supports starting diuresis","Suggests volume responsiveness, because it exceeds the 36% threshold","Indeterminate, because the threshold is 50% at this tidal volume"],2,"In passively ventilated patients with tidal volume ≥8 mL/kg, SVC variation >36% predicts volume responsiveness with 90% sensitivity and 100% specificity. This performs better than TTE-based IVC variation. The measurement requires no spontaneous effort.");
B(3,"mass",1,"TEE can image almost the entire thoracic aorta. Which segment usually stays hidden?",["The descending thoracic aorta lying behind the esophagus","The transverse aortic arch and the arch vessel origins","The origin of the left subclavian artery from the arch","A short distal ascending segment hidden by the airway"],3,"Air in the left mainstem bronchus hides a small segment of the ascending aorta (often called the blind spot). The descending aorta lies directly behind the esophagus and is easy to see. The arch and the left subclavian origin are seen from the upper esophagus.");
B(3,'views',1,"Starting from the midesophageal 4-chamber view, you withdraw the probe slightly to obtain the midesophageal aortic valve short-axis view and see all three cusps. Which omniplane angle is typically needed?",["0°","30–45°","90°","120–135°"],1,"The ME AV SAX view uses about 30–45°. It shows all three aortic cusps with the right heart wrapping around them, similar to the basal parasternal short-axis view on TTE. An angle of 120–135° gives the ME long-axis view, and about 90° gives the 2-chamber and bicaval views.");
B(3,'views',2,"You need stroke volume and cardiac output in a ventilated patient. You plan pulsed-wave Doppler in the LVOT and continuous-wave Doppler across the aortic valve, both well aligned with flow. Which TEE view should you use?",["Midesophageal 4-chamber view","Transgastric midpapillary short-axis view","Midesophageal bicaval view","Deep transgastric long-axis view"],3,"The deep transgastric long-axis view looks up from the LV apex at 0° with full anteflexion, often with left lateral tilt. It aligns the beam with LVOT and aortic valve flow, which allows cardiac output and stroke volume variation measurements. The ME long-axis view places the LVOT nearly perpendicular to the beam.");
B(3,'lv',2,"After coronary bypass surgery, a patient develops new hypotension. Which single TEE view lets you assess LV wall motion in all three coronary artery territories, plus LV size, RV size, and septal motion?",["Transgastric midpapillary short-axis view","Midesophageal 2-chamber view","Midesophageal aortic valve short-axis view","Upper esophageal aortic arch view"],0,"The transgastric midpapillary SAX view shows segments supplied by all three coronary arteries. It is equivalent to the parasternal SAX midpapillary view on TTE. The ME 2-chamber view shows only the anterior and inferior walls.");
B(3,'views',1,"What happens when you rotate the large control wheel of a modern TEE probe clockwise?",["The probe tip retroflexes","The tip flexes laterally to the right","The probe tip anteflexes","The omniplane angle rotates forward"],2,"The large wheel controls tip flexion: clockwise anteflexes and counterclockwise retroflexes. The small wheel controls lateral flexion, and separate buttons rotate the omniplane angle through 180°. Use the locking lever with caution because of the risk of esophageal trauma.");
B(3,"views",2,"Which of these patients has the highest risk of esophageal perforation during TEE?",["A 30-year-old man after a single, uneventful insertion","A 45-year-old man on a proton pump inhibitor for reflux","A 50-year-old woman who was recently intubated orally for surgery","A 78-year-old on chronic steroids with prior chest radiation"],3,"Most perforations occur in elderly women, usually intraoperatively, and the thoracic esophagus is the most common site. Risk factors are chronic steroids, prior chest radiation, severe cervical osteoarthritis with spurs, a large left atrium distorting the esophagus, and multiple insertion attempts. About 40% of patients with perforation present in shock, with 28% mortality.");
B(3,'lung',2,"During transesophageal lung ultrasound (TELU) in a ventilated patient, which statement about detecting pleural effusion is correct?",["Left effusions are easier to detect because the descending aorta acts as an acoustic window","Right effusions are easier to detect because the liver acts as an acoustic window","Both sides are detected equally, at about 50 mL","Left effusions are harder to detect because of the vertebral bodies"],0,"The median volume needed for detection is 125 mL on the left versus 225 mL on the right. On the left, the aorta serves as an acoustic window. On the right, the vertebral bodies block the beam from the posterior lung.");
B(3,'views',1,"For which of these assessments is TTE preferred over TEE?",["Excluding left atrial appendage thrombus","Evaluating a prosthetic mitral valve","Measuring tricuspid regurgitation velocity","Assessing the interatrial septum for a shunt"],2,"TTE is the standard for chamber quantification, mitral stenosis, diastolic function, TR velocity, the LV apex, the IVC, and the hepatic veins. It is also more reliable for the RV and for circumferential effusions. TEE is better for the LAA, the interatrial septum, prosthetic valves, and the thoracic aorta.");
B(3,'views',1,"Which statement about miniaturized TEE probes in the ICU is correct?",["They provide full multiplane imaging with complete Doppler capability","They can be left in place for up to 72 hours for serial monitoring","They have higher image resolution than standard probes","They can be used only in spontaneously breathing patients"],1,"Miniaturized probes can stay in place for up to 72 h, and transnasal insertion has been described. This reduces the injury risk from repeated insertions. Their drawbacks are lower resolution, monoplane imaging, and no M-mode or full Doppler.");

// Chapter 04 — Lung Ultrasonography Fundamentals
B(4,'lung',2,"A ventilated patient becomes hypoxic right after a subclavian line is placed. You want to rule out pneumothorax with lung ultrasound. What is the best initial approach?",["Scan zones 1 and 5 (anterior chest) with a high-frequency linear probe","Scan zones 4 and 8 (dependent) with a low-frequency curvilinear probe","Scan the posterior lung fields bilaterally with a low-frequency phased array probe","Scan zones 4 and 8 with a high-frequency linear probe"],0,"Air rises and fluid falls. For pneumothorax, scan nondependent zones 1 and 5 with a high-frequency probe. For effusion or edema, scan dependent zones 4 and 8 with a low-frequency probe.");
B(4,"art",1,"Which description fits a sonographic B line rather than a Z line?",["Arises from the pleura, fades after 2–4 cm and does not move","Vertical, laser-like, moves with pleura, erases A lines, full depth","Horizontal and repeating at regular intervals below the pleura","Hyperechoic focus inside consolidated lung that shimmers with breath"],1,"B lines are vertical reverberation artifacts. They move with the pleura, block A lines, and extend to the bottom of the screen. Z lines extend only 2–4 cm, do not move, and have no known significance. Scanning depths of 10–16 cm help tell them apart.");
B(4,'lung',2,"In a trauma patient, one anterior rib space shows no clear lung sliding, but two B lines are seen arising from the pleura in the same space. What can you conclude?",["A pneumothorax is confirmed at that rib space","A lung point is present","A pneumothorax is ruled out at that rib space","A tension pneumothorax is likely"],2,"B lines arise from the visceral pleura and lung, so their presence rules out pneumothorax at that rib space. Absent sliding is sensitive but not specific for pneumothorax.");
B(4,'lung',2,"After emergency intubation, the left hemithorax shows no lung sliding, but M-mode shows rhythmic pleural oscillations in time with the heartbeat. Lung sliding is normal on the right. What is the most likely explanation?",["Left tension pneumothorax","Left pneumothorax with a lung point","Massive left pleural effusion","Right mainstem intubation"],3,"A lung pulse is cardiac motion transmitted through lung that touches the parietal pleura, so it excludes pneumothorax. Sliding can be absent with a lung pulse in atelectasis, pneumonia, or the left lung during right mainstem intubation.");
B(4,'lung',1,"Which statement about the lung point is correct?",["It is pathognomonic for pneumothorax in all settings","It was once thought pathognomonic, but pulmonary blebs can mimic it","It is best seen with the probe moving quickly across rib spaces","It marks where B lines change to A lines"],1,"The lung point is the transition between present and absent sliding with the probe held still. It strongly supports pneumothorax in the right clinical context, but blebs can mimic it. If sliding is absent in one zone, move the probe inferiorly or laterally to look for it.");
B(4,'lung',3,"In a ventilated patient, the maximal separation between the parietal and visceral pleura at the base measures 40 mm. Using the formula V (mL) = 20 × Sep (mm), what is the estimated effusion volume?",["400 mL","600 mL","1,200 mL","800 mL"],3,"V = 20 × 40 = 800 mL. The chapter gives this as a simple bedside estimate of effusion size. A qualitative grade of small, intermediate, or large is also used.");
B(4,'lung',1,"What are the approximate minimum pleural fluid volumes reliably detected by lung ultrasound and by chest radiograph?",["20 mL by ultrasound vs 200 mL by radiograph","50 mL by ultrasound vs 500 mL by radiograph","100 mL by ultrasound vs 175 mL by radiograph","5 mL by ultrasound vs 50 mL by radiograph"],0,"Ultrasound can detect about 20 mL because anechoic fluid contrasts with the hyperechoic diaphragm. A chest radiograph needs at least 200 mL. With CT as the reference, ultrasound beats auscultation and radiography.");
B(4,'lung',2,"An anechoic right pleural effusion shows a thoracic spine sign and spans about two probe lengths along the chest wall. Using the semiquantitative approach, what is the estimated volume?",["<100 mL","100–500 mL","500–1,500 mL","More than 1,500 mL"],2,"Fluid at the costophrenic angle only is under 100 mL. One probe length is 100–500 mL, two probe lengths is 500–1,500 mL, and three or more is over 1,500 mL. The spine sign means nonaerated tissue or fluid between the probe and the vertebrae, but it is nonspecific.");
B(4,'lung',2,"A hypoxemic ventilated patient has ≥3 B lines per rib space in many zones, an irregular fragmented pleural line, scattered subpleural consolidations, and some anterior areas with a normal A-line profile. Which diagnosis fits best?",["Cardiogenic pulmonary edema","Bilateral pneumothorax","Simple bilateral transudative effusions","Acute respiratory distress syndrome"],3,"Three or more B lines per rib space indicates alveolar-interstitial syndrome. ARDS causes a fragmented pleura, subpleural consolidations, and spared A-line areas. Cardiogenic edema typically gives a smooth, continuous pleural line with B lines in adjacent zones.");
B(4,'lung',2,"A febrile patient has a right lower lobe hepatized consolidation. Inside it are hyperechoic branching foci that move and sparkle with each breath. What do these findings indicate?",["Dynamic air bronchograms, highly specific for pneumonia","Static air bronchograms, diagnostic of atelectasis","A lines, indicating normal aeration","Z lines, without pathologic significance"],0,"Dynamic air bronchograms (the starry sky sign) come from aerated bronchi trapped inside consolidation and are highly specific for pneumonia. Static air bronchograms do not change with breathing and occur in both atelectasis and pneumonia.");
B(4,'rv',2,"A postoperative patient develops sudden hypoxemia. Lung ultrasound shows bilateral lung sliding, an A-line profile, and no significant effusion. Bedside echo shows a dilated RV and a plethoric IVC. What is the most appropriate interpretation?",["Cardiogenic pulmonary edema is most likely","Pneumonia is most likely","Supports pulmonary embolism","A normal lung examination excludes a pulmonary cause"],2,"Hypoxemia without a lung explanation, with RV enlargement and a dilated IVC, supports PE. Finding a DVT adds further support, and this combined approach may reduce the need for CT pulmonary angiography.");
B(4,'fluid',2,"In the FALLS protocol for a patient in circulatory failure, which lung ultrasound change during fluid resuscitation should prompt you to reassess further fluid?",["Loss of the thoracic spine sign at the bases","New B lines in previously A-line zones","Appearance of a lung pulse","Return of lung sliding"],1,"FALLS combines echocardiography with the BLUE protocol. New B lines during fluid loading mark iatrogenic pulmonary edema and are the signal to stop and reassess fluids.");

// Chapter 05 — Abdominal Ultrasound Fundamentals
B(5,"abd",2,"During the right upper quadrant FAST view in a hypotensive patient, Morison's pouch looks dry. Which additional area must you see to complete this view?",["The caudal liver tip at the right paracolic gutter","The gallbladder fossa only, under the liver edge","The upper pole of the right kidney only, near the adrenal","The splenorenal recess through the same right window"],0,"Free fluid can collect along the paracolic gutter at the inferior tip of the liver. Scan from the diaphragm to the lower pole of the kidney and the liver tip. The splenorenal recess is imaged from the left posterior axillary line.");
B(5,'abd',2,"In a trauma patient, the transverse pelvic view behind the bladder shows no fluid. Why should you also obtain a sagittal view of the bladder?",["To measure bladder wall thickness accurately","To detect fluid above the bladder dome","To see the Foley balloon","To assess the ureteric jets"],1,"In the transverse view the beam angles into the pelvis (rectovesical or rectouterine pouch). The sagittal view shows peritoneal fluid sitting above the bladder dome, so both planes are needed.");
B(5,'abd',3,"Urine output falls in a patient with a renal transplant. Pulsed-wave Doppler of the central allograft artery shows a peak systolic velocity of 60 cm/s and an end-diastolic velocity of 9 cm/s. What is the resistive index, and what does it suggest?",["0.15; reassuring","0.73; within normal limits","0.85; suggests allograft dysfunction","0.85; diagnostic of renal vein thrombosis"],2,"RI = (PSV − EDV)/PSV = (60 − 9)/60 = 0.85. An RI over 0.80 suggests allograft dysfunction. Venous thrombosis is suggested instead by absent or reduced venous flow at the hilum.");
B(5,'abd',3,"A patient with ascites has a suspected blocked Foley catheter. Bladder dimensions are 10 cm length × 8 cm width × 6 cm height. What is the estimated bladder volume?",["480 mL","240 mL","300 mL","370 mL"],3,"Volume = L × W × H × 0.77 = 480 × 0.77 ≈ 370 mL. Automated bladder scanners can be inaccurate with ascites, so measure directly in both transverse and sagittal planes. A distended bladder with a visible Foley balloon means the catheter is not draining.");
B(5,'mass',2,"A transverse view of the infrarenal aorta shows a lumen of 2.6 cm (inner wall to inner wall) surrounded by mural thrombus. The outer wall to outer wall diameter is 3.8 cm. What is the correct interpretation?",["Normal aorta, because the lumen is under 3 cm","Abdominal aortic aneurysm (outer-to-outer diameter >3 cm)","Ectatic aorta that needs measurement only in long axis","Aortic dissection, because mural thrombus is present in the lumen"],1,"Measure the aorta outer wall to outer wall in transverse; AAA is defined as more than 3 cm. Measuring inner to inner excludes mural thrombus and underestimates size. Common iliac arteries over 1.5 cm suggest aneurysm.");
B(5,'mass',2,"A 74-year-old man has abdominal pain and a blood pressure of 78/40 mm Hg. Bedside ultrasound shows a 6-cm infrarenal AAA, and the FAST exam is negative. What is the best interpretation?",["Rupture is excluded because there is no free peritoneal fluid","Get an elective CT before involving surgery","The negative FAST suggests a nonvascular cause of shock","Strongly suspect retroperitoneal rupture despite the negative FAST"],3,"AAA rupture is often retroperitoneal, so free peritoneal fluid may be absent. In an unstable patient with pain and an AAA, treat this as a ruptured AAA. CT is for stable patients.");
B(5,'mass',2,"You see a thin intraluminal flap in the abdominal aorta of a hypotensive patient. What is the most appropriate next step?",["Scan the thoracic aorta from parasternal and suprasternal windows","Measure the inner luminal diameter to confirm a false lumen and stop imaging","Repeat the abdominal views in 6 hours to see if the flap persists","Proceed straight to MRI angiography regardless of hemodynamic stability"],0,"You need to know whether the ascending aorta is involved (Stanford A vs B), so scan the parasternal long-axis and suprasternal views. CT or MR angiography confirms the diagnosis in stable patients. TEE is often the modality of choice in unstable ones.");
B(5,'abd',2,"A septic ICU patient has right upper quadrant tenderness. Which gallbladder finding supports acute cholecystitis, and how should it be measured?",["Posterior wall thickness over 3 mm on the long-axis view","Common bile duct of 3 mm measured outer to outer","Anterior wall >3 mm with pericholecystic fluid","Gallbladder wall under 2 mm with posterior shadowing"],2,"Anterior wall over 3 mm, pericholecystic fluid, and a sonographic Murphy sign support cholecystitis. Measure the anterior wall, because posterior acoustic enhancement makes the posterior wall look falsely thick. Acalculous cholecystitis shows the same features without stones or sludge.");
B(5,'abd',3,"A 70-year-old woman with jaundice has never had a cholecystectomy. Using the age-based rule, what is the approximate upper limit of a normal common bile duct, measured inner wall to inner wall?",["4 mm","5 mm","10 mm","7 mm"],3,"The normal CBD is about 4 mm up to age 40 and increases by 1 mm per decade after that, so at age 70 the limit is about 7 mm. After cholecystectomy the CBD can be up to 10 mm. A dilated CBD suggests choledocholithiasis or another extrahepatic obstruction.");
B(5,"abd",3,"Before urgent intubation, gastric ultrasound in an 80-kg patient estimates an antral volume of 150 mL of clear fluid. How should this be interpreted?",["Increased risk, because the volume exceeds 1.5 mL/kg","Low risk, because only particulate matter matters for aspiration","Low risk, because the volume is still under 3 mL/kg","Not interpretable without first aspirating a nasogastric tube"],0,"150/80 ≈ 1.9 mL/kg, which is above 1.5 mL/kg. Volume over 1.5 mL/kg or any particulate matter increases aspiration risk. Scan the antrum supine or in right lateral decubitus.");
B(5,'abd',2,"Lawn-mower scanning in a distended ICU patient shows small bowel loops of 32 mm with 4-mm wall edema, free fluid between the loops, and intramural gas foci. What is the most likely diagnosis?",["Paralytic ileus with absent peristalsis","Low-grade mechanical obstruction","High-grade obstruction with infarction","Normal postoperative bowel"],2,"Dilated loops over 25 mm mean mechanical obstruction. Wall edema over 3 mm, fluid between loops, and intramural gas (pneumatosis intestinalis) indicate high-grade obstruction with infarction. Ileus shows loops under 25 mm without peristalsis, and ultrasound cannot locate the transition point.");
B(5,'art',1,"A dependent hypoechoic layer is seen in the gallbladder in one plane. Which finding supports side lobe artifact rather than biliary sludge?",["It casts a strong posterior acoustic shadow","It disappears as you fan through the gallbladder","It layers along the dependent wall in every imaging plane","It shows color flow on Doppler"],1,"Side lobe artifact comes from the curved gallbladder wall and appears or disappears as you fan. Sludge is hypoechoic, does not shadow, and layers dependently in every view. Stones are hyperechoic and cast shadows.");

// Chapter 06 — Left Ventricular Systolic Function and Cardiac Output
B(6,'lv',2,"A septic ICU patient has a parasternal long-axis M-mode at the mitral leaflet tips showing LVIDd 5.0 cm and LVIDs 4.0 cm. What is the fractional shortening?",["20%","25%","40%","80%"],0,"FS = (LVIDd − LVIDs)/LVIDd × 100 = (5.0 − 4.0)/5.0 × 100 = 20%. Dividing by LVIDs instead (25%) is the classic error; FS is a single basal cut and misleads with regional wall motion abnormalities.");
B(6,'lv',2,"A 68-year-old in undifferentiated shock has a parasternal long-axis view showing the anterior mitral leaflet in early diastole separated from the septum by 21 mm. No valvular disease is known. What does this finding most suggest?",["Hyperdynamic LV with high output","Severely reduced EF around 30% or less","Normal EF with impaired relaxation","Isolated RV systolic dysfunction"],1,"EPSS >7 mm classically indicates abnormal EF, and EPSS >18 mm suggests severely abnormal EF (about 30%). EPSS rises as the LV fails and dilates.");
B(6,'lv',1,"Which MAPSE value is described as highly sensitive and specific for an LV ejection fraction greater than 50%?",["Greater than 5 mm","Greater than 7 mm","Greater than 10 mm","Greater than 18 mm"],2,"MAPSE >10 mm is highly sensitive and specific for EF >50%, while MAPSE <8 mm is associated with EF <50%. Measured by M-mode on the lateral (± septal) mitral annulus in an apical view.");
B(6,'lv',2,"In which patient is MAPSE least reliable as a surrogate of global LV systolic function?",["Obese patient with poor parasternal windows but a good apical view","Patient with poorly defined endocardial borders on apical imaging","Novice operator scanning a patient with a clear apical 4-chamber view","Patient with a prior surgical mitral valve repair"],3,"Basal regional wall motion abnormalities, mitral annular stenosis, mitral valve disease, or prior mitral surgery reduce MAPSE validity. MAPSE does not need clear endocardial borders and is feasible for novices; its main practical drawback is needing a good apical view.");
B(6,"lv",1,"Regarding the Simpson biplane method of disks for LV ejection fraction, which statement is correct?",["It uses parasternal long-axis and short-axis tracings together","Traces apical 4- and 2-chamber views, including papillary muscles","It extrapolates volume from a single linear LV diameter","It closes the endocardial tracing at the level of the aortic annulus"],1,"The modified Simpson method traces endocardial borders (papillary muscles included) in apical 4- and 2-chamber views at end-diastole and end-systole, closing at the mitral annulus, and sums 20 disks. It is the recommended EF method; single-diameter extrapolation is the Teichholz method.");
B(6,'lv',2,"An intensivist wants to follow LV function in a patient with limited acoustic windows using fractional area change (FAC). Where is FAC best measured?",["Parasternal short-axis at the papillary muscle level","Parasternal long-axis at the mitral leaflet tips","Apical 4-chamber view at the mitral annulus","Subcostal 4-chamber view at the LV apex"],0,"FAC = (LVEDA − LVESA)/LVEDA × 100, traced (including papillary muscles) in a true midpapillary short-axis view. Normal values range widely (35%–65%) and it ignores basal and apical heterogeneity.");
B(6,'hemo',3,"A ventilated patient has an LVOT diameter of 2.0 cm, LVOT VTI of 20 cm, and heart rate of 100/min. What is the estimated cardiac output?",["About 4.0 L/min","About 25.1 L/min","About 3.1 L/min","About 6.3 L/min"],3,"LVOT area = π(d/2)² = 3.14 × 1² = 3.14 cm²; SV = 3.14 × 20 ≈ 63 mL; CO = 63 × 100 ≈ 6.3 L/min. Using the diameter rather than the radius in the area formula would quadruple the result (about 25 L/min).");
B(6,'hemo',3,"An LVOT diameter is undermeasured by 10% (1.8 cm instead of a true 2.0 cm). All other measurements are accurate. By roughly how much is stroke volume underestimated?",["About 5%","About 10%","About 19%","About 40%"],2,"Area depends on the radius squared, so diameter error is squared: (0.9)² = 0.81, about 19% underestimation. LVOT diameter is the largest source of error in Doppler cardiac output.");
B(6,'dop',2,"While measuring LVOT VTI in an apical 5-chamber view, the pulsed-wave sample is aligned at a large angle to LVOT flow. What is the expected effect?",["Overestimation of stroke volume","Aliasing with spurious high velocities","Underestimation of stroke volume","No effect because VTI is angle-independent"],2,"Doppler velocity is maximal when the beam is parallel to flow; off-axis interrogation underestimates velocity, VTI, and stroke volume. Place the PW sample just proximal to the aortic annulus with flow as parallel as possible.");
B(6,'hemo',2,"A patient in atrial fibrillation with variable R-R intervals needs an echocardiographic cardiac output. What is the best approach?",["Measure the single beat with the longest R-R interval","Measure the single beat with the highest VTI","Use M-mode fractional shortening instead","Average stroke volume over as many beats as feasible"],3,"Doppler cardiac output assumes similar stroke volume beat to beat; in arrhythmias such as AF, averaging over as many beats as feasible reduces error. Selecting one beat biases the estimate.");
B(6,'lv',2,"EPSS would be least reliable for estimating EF in which ICU patient?",["Patient with severe aortic insufficiency","Patient with ischemic cardiomyopathy and normal valves","Patient with dilated LV and no valve disease","Patient with sepsis and structurally normal valves"],0,"EPSS is validated in ischemic disease without valve abnormality but is inaccurate with mitral stenosis, mitral insufficiency, aortic insufficiency (regurgitant jet restricts leaflet opening), annular disease, or prior valve surgery.");
B(6,"hemo",1,"For Doppler stroke volume, where and when is the LVOT diameter ideally measured?",["Apical 5-chamber view at end-diastole at the annular hinge points","PLAX at midsystole, just proximal to aortic leaflet insertion","PSAX at the aortic valve level during mid-diastole","PLAX at end-diastole, about 2 cm below the aortic valve"],1,"LVOT diameter is measured in the parasternal long-axis view, inner edge to inner edge at midsystole, just proximal to the aortic leaflet insertion; the PW VTI is then obtained in the apical 5-chamber view just proximal to the annulus.");

// Chapter 07 — Right Ventricular Function
B(7,'rv',3,"A hypoxemic ICU patient has a peak TR velocity of 3.5 m/s by continuous-wave Doppler. Invasive CVP is 10 mm Hg and there is no pulmonic stenosis. What is the estimated PA systolic pressure?",["39 mm Hg","49 mm Hg","59 mm Hg","73 mm Hg"],2,"RVSP = 4V² + RAP = 4 × 3.5² + 10 = 49 + 10 = 59 mm Hg; without RVOT or pulmonic gradient RVSP equals PASP. Forgetting RAP gives 49; normal peak TR velocity is ≤2.8 m/s and PASP should not exceed 35–40 mm Hg.");
B(7,'hemo',3,"A patient with PH has peak TR velocity 3.0 m/s and RVOT VTI 12 cm. Using the TR velocity/RVOT VTI method, what is the estimated PVR?",["About 2.5 Wood units","About 1.25 Wood units","About 0.25 Wood units","About 5.0 Wood units"],0,"Ratio = 3.0/12 = 0.25. A ratio >0.175 suggests PVR >2 WU; for 0.175–0.275 multiply by 10 (2.5 WU). Above 0.275 the multiplier is 5.");
B(7,'rv',2,"In the parasternal short-axis view at the papillary level, the septum flattens into a D shape only in diastole, with a normal circular LV contour in systole. What does this pattern indicate?",["Pure RV pressure overload","Constrictive pericarditis","Acute LV volume overload","RV volume overload"],3,"Diastolic-only D shape indicates RV volume overload (eg, large ASD). Pressure overload flattens the septum first in systole and, as it worsens, throughout the cycle, impairing LV filling.");
B(7,'rv',2,"In a standard apical 4-chamber view of a hypotensive patient, the RV end-diastolic area equals the LV end-diastolic area and the RV forms the apex. How should this be interpreted?",["Mild RV dilation, normal variant","Severe RV dilatation","Normal RV size if LV is small","Artifact of an RV-focused view"],1,"Normally RVEDA is no more than two-thirds of LVEDA and the LV forms the apex. An RV:LV ratio ≥1.0 and an RV-predominant apex indicate severe RV dilatation and failure.");
B(7,"rv",1,"Which statement about TAPSE is correct?",["A value above 17 mm reliably excludes any RV dysfunction","Below 17 mm is highly specific but not sensitive for RV dysfunction","It is measured with tissue Doppler at the septal tricuspid annulus","It remains valid in the presence of RV regional wall motion defects"],1,"TAPSE (M-mode, lateral tricuspid annulus, A4C) <17 mm is highly specific but not sensitive. It assumes longitudinal motion reflects global function, so it is invalid with regional RV wall motion abnormalities such as RV infarction.");
B(7,'rv',2,"A patient with an inferior STEMI from a proximal RCA lesion has an RV free wall that is dyskinetic while the apex contracts. Which index is preferred to quantify RV systolic function?",["TAPSE","RV myocardial performance index","Tricuspid annular Sʹ","RV fractional area change"],3,"With regional wall motion abnormalities, RV FAC is preferred because TAPSE may underestimate (or misrepresent) RV compromise, especially in proximal RCA lesions. Normal RV FAC is >35%.");
B(7,'rv',2,"A patient with dyspnea has an RVOT pulsed-wave acceleration time of 65 ms. How should this be interpreted?",["Highly suggestive of severe PH","Normal, does not support PH","Borderline, consistent with high cardiac output only","Indicates isolated LV diastolic dysfunction"],0,"AT >100 ms does not support PH, while AT <70 ms is highly suggestive of severe PH. AT is especially useful in borderline cases.");
B(7,'rv',3,"A patient with known PAH has an RVOT pulsed-wave Doppler envelope with two distinct peaks (midsystolic notching). What does this pattern most suggest?",["PH from left-sided heart disease with normal PVR","Normal RV-PA coupling with high flow","Severely increased PVR with advanced RV dysfunction","Early-stage PAH with only mild PVR elevation"],2,"Midsystolic notching reflects wave reflection with markedly increased PVR and advanced RV dysfunction in PAH. Late-systolic notching is associated with left-sided heart disease and early PAH; a normal envelope suggests normal PVR.");
B(7,'rv',2,"A patient with acute dyspnea has a dilated RV with free wall thickness of 8 mm in the subcostal view at end-diastole. What does the wall thickness imply?",["Typical of de novo acute RV failure","Measurement artifact requiring parasternal confirmation","Normal RV wall thickness","Chronic RV overload with RV hypertrophy"],3,"RV wall thickness >5 mm (subcostal, end-diastole, excluding epicardial fat and trabeculations) indicates RVH and chronicity. Acute RV failure characteristically lacks hypertrophy.");
B(7,"rv",2,"When acquiring an RV-focused apical 4-chamber view for RV linear dimensions, which technique is correct?",["Include the LVOT in the plane to confirm the correct rotation","Center LV apex, exclude LVOT, rotate to maximize RV base","Center the RV apex and minimize the RV basal diameter","Use a 5-chamber view to standardize the imaging plane"],1,"Rotate gently (counterclockwise) to the plane with the largest RV basal diameter, keeping the LV apex centered to avoid RV foreshortening and excluding the LVOT (4- not 5-chamber). Basal diameter >41 mm (ASE 2015) is abnormal.");
B(7,'rv',2,"In a patient with poor apical windows, the subcostal 4-chamber view shows an RV:LV ratio greater than 1. How should this be interpreted?",["Likely overestimation; repeat in apical view","Normal finding in the subcostal plane","Strongly suggests RV enlargement, likely severe","Indicates pressure rather than volume overload"],2,"The subcostal view tends to underestimate RV size, so an RV:LV ratio >1 in a true subcostal 4-chamber view strongly suggests (severe) RV enlargement.");
B(7,"rv",1,"Which subcostal technique has strong correlation with TAPSE and can replace it when apical windows are suboptimal?",["SEATAK (subcostal tricuspid annular kick)","Subcostal IVC collapsibility index (cIVC)","Subcostal RV fractional area change (FAC)","Subcostal LVOT VTI by pulsed Doppler"],0,"SEATAK correlates strongly with TAPSE and is useful in patients with suboptimal apical windows; the subcostal view is often easier when the heart is displaced caudally by RV enlargement.");
B(7,'rv',3,"A patient with acute inferior wall MI is evaluated for RV involvement with continuous-wave Doppler of pulmonary regurgitation. Which finding is the strongest predictor of RV involvement?",["PR pressure half-time 150 ms or less","Gradual mid-diastolic PR deceleration","PR end-diastolic gradient below 5 mm Hg","PR peak velocity above 2.8 m/s"],0,"With RV infarction, PR shows rapid rise then abrupt mid-diastolic deceleration; PR pressure half-time ≤150 ms predicts RV involvement (sensitivity 100%, NPV 100%). Gradual deceleration is seen without RV involvement.");
B(7,'peri',2,"A patient with long-standing PAH is admitted with decompensated right heart failure, severe TR, and a large pericardial effusion without other cause. What is the appropriate approach to the effusion?",["Urgent pericardiocentesis to improve RV filling","Pericardial window before vasodilator therapy","Avoid drainage; it marks decompensated ACRVF","Drain only if collapse of the RV free wall is seen"],2,"In PAH, pericardial effusion predicts worse outcome and larger effusions accompany RV failure, severe TR, and ventricular interdependence. It is a marker of decompensated ACRVF and should not be tapped.");
B(7,'rv',3,"An ICU patient with PH has LA enlargement, mitral annular calcification, preserved TAPSE, and RVOT acceleration time >100 ms. Which etiology is most likely?",["Pulmonary arterial hypertension","PH due to left-sided heart disease","Acute massive pulmonary embolism","Portopulmonary hypertension"],1,"Left-heart (venous) PH features LA enlargement, mitral annular calcification, grade 2–3 diastolic dysfunction, preserved RV function, AT >100 ms, and no effusion. PAH shows no LA enlargement, RV dysfunction, short AT, leftward septal motion, and effusion.");
B(7,'fluid',2,"A ventilated patient with a dilated, hypokinetic RV has pulse pressure variation of 18% and marked LVOT VTI variation. What is the most appropriate interpretation?",["Reliable sign of fluid responsiveness; give a bolus","Indicates tamponade physiology needing drainage","Confirms hypovolemia regardless of RV function","Likely reflects RV failure worsened by positive pressure"],3,"Confirm normal RV function before using PPV or LVOT variability. In RV failure, high variation likely reflects RV afterload from positive pressure ventilation (false positive), supported by reduced IVC variation and absent SVC variation on TEE.");

// Chapter 08 — Fluid Management by Critical Care Echocardiography
B(8,"views",1,"Which approach gives the best longitudinal view of the superior vena cava for measuring its respiratory collapsibility index (∆SVC)?",["TTE suprasternal notch view of the aortic arch","TEE upper esophageal view at an omniplane of ~90°","TEE transgastric short-axis view at 0° omniplane","TTE subcostal long-axis view of the vena cava"],1,"The SVC is best seen in its long axis via the TEE upper esophageal view at about 90°. A transthoracic SVC window has been described only in a pilot study; the subcostal view images the IVC, not the SVC.");
B(8,'fluid',2,"A mechanically ventilated patient in septic shock, fully adapted to the ventilator, has TEE showing a superior vena cava collapsibility index of 38%. What is the most appropriate interpretation?",["Hypovolemia is likely and the patient should benefit from more fluid","The finding is in the gray zone and fluids should be withheld","Collapse reflects high intrathoracic pressure and indicates RV failure","∆SVC is unreliable in ventilated patients and should be ignored"],0,"∆SVC had the highest specificity (~84%) among echo indices, and a value >31% predicted fluid responsiveness with 90% specificity. SVC collapse during tidal ventilation reflects a fall in transmural pressure from inadequate thoracic blood volume, so a patient still in shock likely needs fluid.");
B(8,'fluid',2,"A ventilated patient in shock with normal intra-abdominal pressure has an end-expiratory IVC diameter of 9 mm on subcostal imaging. Based on the large-series data, how specific is this finding for fluid responsiveness?",["About 64%, because IVC diameter mirrors LV stroke volume variation","About 80%, because 9 mm lies in the 13–25 mm gray zone","About 90%, as it is below the 10 mm cutoff","It cannot be interpreted because IVC diameter predicts only non-response"],2,"An IVC end-expiratory diameter ≤13 mm predicted fluid response with 80% specificity, rising to 90% with a ≤10 mm cutoff. A diameter ≥25 mm predicted absence of response with 80% specificity (90% if ≥27 mm).");
B(8,'fluid',1,"Why does critical care echocardiography have an inherent limitation when assessing total volume status?",["Most blood resides in the pulmonary circulation, which cannot be imaged","The heart in diastole contains most of the circulating volume","Systemic arteries hold the largest share of blood and are not visualized","About 63% of blood lies in the venous reservoir, which CCE cannot image directly"],3,"Roughly 63% of blood volume is in the venous reservoir, 15% in systemic arteries, 9% in pulmonary circulation, 5% in small vessels and 8% in the heart. CCE detects thoracic hypovolemia (~17% of volume) but not venous reservoir status, so specificity should be favored over sensitivity.");
B(8,'fluid',2,"In the large study evaluating end-expiratory IVC diameter to predict fluid responsiveness, which factor most limited its utility?",["IVC respiratory variation was more accurate than diameter","Elevated intra-abdominal pressure (≥12 mm Hg) altered the results","Spontaneous breathing efforts were present in most patients","The 25 mm cutoff had poor specificity for non-response"],1,"Intra-abdominal pressure ≥12 mm Hg (30% of patients) altered results, IVC feasibility was only 78%, and only 29% of patients fell between the cutoffs. IVC respiratory variation itself has limited accuracy in ventilated patients.");
B(8,'fluid',2,"A ventilated patient in shock has a hyperkinetic LV with end-systolic cavity obliteration and an end-diastolic area of 4 cm²/m² in short axis. Systolic anterior motion of the mitral valve is seen. What profile is most likely?",["Hypovolemia with dynamic LVOT obstruction","Pure vasoplegia with preserved preload","Acute cor pulmonale with septal shift","Hypertrophic cardiomyopathy unrelated to volume"],0,"A small LV end-diastolic area (<5.5 cm²/m²) with systolic exclusion is highly suggestive of hypovolemia, and dynamic LVOT obstruction from SAM is not rare. Vasoplegia also causes a hyperkinetic LV, but the end-diastolic area is not decreased.");
B(8,"rv",2,"A ventilated patient in shock has a pulse pressure variation of 18%. TEE shows a markedly dilated RV with a small LV. What is the best next step regarding fluids?",["Give a bolus, since PPV above 13% confirms fluid responsiveness","Do a passive leg raise and treat PPV as proof of hypovolemia","Repeat PPV after increasing tidal volume to confirm the result","Withhold fluid: PPV here reflects RV failure, not low preload"],3,"PPV only signals a defect in LV preload and cannot distinguish primary hypovolemia from RV failure with secondary low LV filling, which often does not need fluid. PPV is a warning signal; CCE is the diagnostic tool.");
B(8,'dop',2,"Respiratory variation of LVOT velocity-time integral in ventilated patients with circulatory failure is best characterized by which accuracy profile?",["High specificity (~90%) but low sensitivity","Specificity of about 84% with sensitivity of about 50%","Best sensitivity (~80%) but low specificity (~64%)","Both sensitivity and specificity above 90%"],2,"In a large ventilated population, respiratory variation of LV stroke volume had the best sensitivity (~80%) but only 64% specificity, giving many false positives. ∆SVC had the highest specificity (~84%).");
B(8,'hemo',3,"In a septic shock patient within 12 hours of ICU admission, which combination was highly specific (99.3%) for a hypovolemic hemodynamic profile?",["Aortic VTI <16 cm, mitral E <67 cm/s, and ∆SVC >39%","Aortic VTI <12 cm, mitral E/A >1, and IVC <13 mm","LV end-diastolic area <5 cm²/m², E/e' >14, and ∆SVC >31%","Aortic VTI <20 cm, IVC <10 mm, and PPV >13%"],0,"In 360 septic shock patients, hypovolemia (19%) was identified with 99.3% specificity by aortic VTI <16 cm (low stroke volume), mitral E <67 cm/s (low LV filling pressure), and ∆SVC >39%.");
B(8,'fluid',3,"During staged fluid expansion in a ventilated patient, LVOT VTI continues to rise after the second bolus, but the mitral inflow pattern changes from inverted E/A to E/A >1. What should be done?",["Continue boluses because stroke volume is still increasing","Stop fluids because LV filling pressure has become elevated","Start an inotrope because E/A >1 indicates systolic failure","Repeat the bolus and reassess after a passive leg raise"],1,"CCE evaluates both efficacy (VTI/stroke volume) and tolerance (LV filling pressure). A shift to E/A >1 indicates elevated LV filling pressure; even with some VTI gain, fluids should be discontinued.");

// Chapter 09 — Pulmonary Embolism and Deep Vein Thrombosis
B(9,"rv",2,"A previously healthy patient with acute dyspnea has a severely dilated, hypokinetic RV, but the TR-derived PA systolic pressure is only 45 mm Hg. What best explains this combination?",["Severe TR causes underestimation through laminar regurgitant flow","An unconditioned RV cannot acutely generate PASP much above ~60","Chronic thromboembolic disease has already caused RV hypertrophy","Left ventricular failure is lowering the pulmonary artery pressure"],1,"A previously normal RV fails before it can generate PASP >~60 mm Hg (mean ~40), so severe RV dysfunction with only modestly raised PASP suggests an acute insult such as PE. PASP >60 mm Hg or RV hypertrophy suggests a chronic or acute-on-chronic process.");
B(9,'rv',3,"A patient with suspected PE has a pulmonary acceleration time of 55 ms measured by pulsed-wave Doppler in the RVOT and a TR-derived PA systolic pressure of 50 mm Hg. What does this represent?",["A normal pulmonary flow profile","Findings typical of chronic pulmonary hypertension","A McConnell sign with high sensitivity for PE","A positive 60/60 sign, about 94% specific for PE"],3,"The 60/60 sign is PA acceleration time ≤60 ms (normal >120 ms) with TR peak systolic gradient (4V²) ≤60 mm Hg, reported as 94% specific for PE. Accurate measurement requires correct RVOT identification and cursor alignment.");
B(9,"rv",1,"What defines the McConnell sign?",["Basal/mid RV free-wall hypokinesis with a spared apex","Global RV hypokinesis together with apical akinesis","Diastolic flattening of the interventricular septum","RV apex extending down to the level of the LV apex"],0,"McConnell sign is basal and mid-RV hypokinesis with preserved apical contraction. Originally reported as 94% specific and 77% sensitive for PE, it is now considered overestimated but still suggests acute RV dysfunction. Shared apex is a separate sign of RV dilation.");
B(9,'rv',2,"In an RV-focused apical 4-chamber view, which measurement meets the ASE definition of RV dilation?",["Mid-RV diameter of 32 mm","Longitudinal RV dimension of 78 mm","Basal RV diameter of 44 mm","Distal RVOT diameter of 24 mm in short axis"],2,"ASE defines RV dilation as basal diameter >41 mm, mid >35 mm, longitudinal >83 mm in RV-focused A4C; PLAX RVOT >30 mm; PSAX proximal RVOT >35 mm and distal RVOT >27 mm. These values are not indexed to body size.");
B(9,'rv',2,"A patient with suspected PE has an RV free wall thickness of 7 mm in the subcostal view at end-diastole. What does this suggest?",["An acute insult within the last 72 hours","Measurement error, as free wall thickness is unreliable in PE","A chronic or acute-on-chronic process with RV hypertrophy","Pericardial effusion mimicking wall thickening"],2,"RV wall thickness >5 mm in subcostal end-diastole suggests RV hypertrophy, a time-dependent process that raises the possibility of chronic pulmonary thromboembolic disease rather than a purely acute insult.");
B(9,'rv',2,"In the parasternal short-axis view, septal flattening throughout both systole and diastole indicates which RV condition?",["Pressure overload","Volume overload alone","Normal ventricular interdependence","Isolated LV hypertrophy"],0,"The septum flattens only in diastole with RV volume overload but throughout the cardiac cycle with pressure overload, producing a D-shaped LV. Either should prompt further assessment of PA pressures.");
B(9,'rv',1,"What is the negative predictive value of echocardiography for pulmonary embolism?",["Above 90%, making it a good rule-out test","About 70%, similar to D-dimer","About 80%, equivalent to lung ultrasound","Poor, about 40% to 50%"],3,"Echocardiography has a poor NPV for PE (40%–50%), so a normal study does not exclude PE. Its value lies in showing RV pressure or volume overload in unstable patients for diagnosis and prognosis.");
B(9,'lung',2,"A pregnant patient with suspected PE declines CT. Lung ultrasound shows a wedge-shaped, homogeneous, hypoechoic pleural-based lesion in the dorsal right lower lobe and a small pleural effusion. How should this be interpreted?",["Typical of bacterial pneumonia with air bronchograms","Consistent with pulmonary infarction from PE","Diagnostic of atelectasis unrelated to embolism","A finding that excludes PE"],1,"In 70%–80% of PE cases, vascular occlusion produces wedge- or round-shaped, homogeneous, hypoechoic pleural-based lesions, mainly in the dorsal lower lobes. Pleural effusion is seen in >50% of PEs. Lung US has about 87% sensitivity and 82% specificity.");
B(9,"vasc",1,"During 2-point compression ultrasonography, which finding defines a positive study for DVT?",["Vein not fully collapsing despite pressure deforming the artery","Visible echogenic thrombus, which is required for the diagnosis","Absence of color flow at rest, before any compression is applied","Venous diameter clearly larger than the adjacent artery at rest"],0,"A positive exam is a noncompressible vein despite enough pressure to deform the artery. Echogenic material may be absent depending on technique and thrombus composition, so its absence does not exclude DVT.");
B(9,"vasc",1,"In the inguinal region, what is the arrangement of the neurovascular bundle from lateral to medial?",["Femoral vein, femoral artery, femoral nerve","Femoral artery, femoral nerve, femoral vein","Femoral nerve, femoral vein, femoral artery","Femoral nerve, femoral artery, femoral vein"],3,"Lateral to medial: femoral nerve, common femoral artery, common femoral vein. In the popliteal fossa, the popliteal artery lies deep to the popliteal vein. Confusing arteries and veins is a common pitfall.");
B(9,"vasc",2,"Which technique is appropriate for point-of-care 2-point DVT ultrasonography in a supine ICU patient?",["Low-frequency phased-array probe with the bed tilted into Trendelenburg","5–10 MHz linear probe, compress every ~1 cm, reverse Trendelenburg","One compression at the common femoral vein and one at mid-calf","Color Doppler augmentation at each level as the main criterion"],1,"Use a 5–10 MHz linear probe (curvilinear in extreme obesity), compress about every 1 cm over ~10 cm from the common femoral vein through the femoral/deep femoral bifurcation, and in the popliteal fossa to ~7 cm past the crease. Reverse Trendelenburg increases leg venous filling.");
B(9,"vasc",2,"Which statement about the role of Doppler and the limits of the focused 2-point DVT exam is correct?",["ACEP strongly endorses routine pulsed-wave augmentation at every site","Proximal pelvic DVT is reliably detected by the focused 2-point exam","Color Doppler mainly helps identify vessels versus nodes or nerves","An occlusive DVT increases venous flow during a calf squeeze"],2,"ACEP does not strongly endorse routine Doppler. Color Doppler helps identify vessels and distinguish nodes and nerves; augmentation is controversial at the bedside. Proximal pelvic DVT may be missed by both the 2-point and formal exams.");

// Chapter 10 — Cardiac Tamponade
B(10,'peri',1,"On end-diastolic echocardiography, a circumferential pericardial effusion measures 22 mm. How is it classified?",["Small","Moderate","Large","Very large"],2,"Semiquantitative size by end-diastolic echo-free space: trivial (<10 mm, systole only), small (<10 mm), moderate (10–20 mm), large (>20 mm), very large (>25 mm). Size may not correlate with hemodynamic effect.");
B(10,'peri',1,"On the parasternal long-axis view, which feature best identifies fluid as pericardial rather than left pleural?",["Fluid tracks anterior to the descending thoracic aorta","Fluid collects posterior to the descending thoracic aorta","Fluid is seen only anterior to the RV","Fluid moves with the heart and appears brighter than myocardium"],0,"Pericardial effusion tracks anterior to the descending thoracic aorta; pleural fluid collects behind it. Fluid anterior only and moving with the heart, brighter than myocardium, suggests epicardial fat.");
B(10,"peri",2,"A patient develops shock minutes after a pacemaker lead procedure. A small to moderate pericardial effusion is seen. Why can an effusion this size cause tamponade?",["Small effusions cause tamponade only if they are exudative","Rapid accumulation gives no time for stretch; ~250 mL may suffice","Iatrogenic effusions always cause right-sided collapse before pressure rises","Acute effusions collect first anterior to the RV and compress it"],1,"The pericardial pressure-volume curve is nonlinear and stiffness has not adjusted in rapid accumulation, so acute effusions (trauma, perforation, rupture, dissection) can cause tamponade at about 250 mL. Chronic effusions may become large before symptoms appear.");
B(10,"peri",2,"Which statement about right atrial collapse in tamponade is correct?",["It occurs in early diastole and is more specific than RV collapse","It is best seen in the parasternal long-axis view on M-mode","It is rarely the first cardiac chamber to collapse in tamponade","Late diastole/early systole; more specific if >30% of the cycle"],3,"The thin-walled, low-pressure RA is usually the first chamber to collapse, during its relaxation phase in late ventricular diastole or early systole. It is sensitive but less specific, and specificity rises when collapse lasts >30% of the cycle. It is best seen in apical 4-chamber and subcostal views.");
B(10,"peri",2,"In a tachycardic patient with a large effusion, M-mode through the RV at the mitral leaflet tips shows the RV free wall indenting just after the T wave. What does this indicate?",["Early diastolic RV collapse: less sensitive, more specific than RA","Late systolic RA collapse, a sensitive but nonspecific tamponade sign","A normal finding during inspiration in a tachycardic patient","Left ventricular diastolic collapse from a posterior hematoma"],0,"RV collapse occurs in early diastole (after the T wave), first only during inspiration and then throughout respiration as severity rises. M-mode is very useful for timing in tachycardia. RV collapse is less sensitive but more specific than RA collapse.");
B(10,'peri',2,"In a spontaneously breathing patient with a large effusion, the IVC measures 2.5 cm with <50% inspiratory change. Which hepatic vein pulsed-wave Doppler finding would also support tamponade?",["Prominent systolic forward flow increasing with inspiration","Monophasic continuous flow without respiratory variation","Blunted or reversed diastolic flow during expiration","Systolic flow reversal only during inspiration"],2,"IVC plethora (>2.1 cm with <50% collapse) was present in 92% of patients with pulsus paradoxus who required drainage but is nonspecific. Hepatic vein dilation confirms high venous pressure; expiratory blunting or reversal of diastolic flow is typical of tamponade.");
B(10,'dop',3,"A spontaneously breathing patient with a pericardial effusion has mitral E velocity 100 cm/s during expiration and 62 cm/s during inspiration. What is the respiratory variation and its significance?",["24%, not significant","38%, significant (above 30%)","38%, not significant (threshold is 60% for mitral)","62%, significant only for tricuspid inflow"],1,"Variation = (Expiration − Inspiration) ÷ Expiration = (100 − 62)/100 = 38%. Mitral inspiratory decrease >30% and tricuspid expiratory decrease >60% are significant. Do not use inflow variation alone without chamber collapse, IVC plethora, or abnormal hepatic vein flow.");
B(10,"peri",3,"A patient on positive pressure ventilation after major surgery has a pericardial effusion and hypotension. Mitral and tricuspid inflows show no respiratory variation, and there is no clear chamber collapse. Which finding has been suggested as more useful?",["Septal shift into the RV during each inspiration","Hepatic vein systolic predominance on Doppler","Normal IVC size together with a small RV cavity","A dilated IVC (high RAP) with a small RV cavity"],3,"PPV can abolish respirophasic inflow variation and chamber collapse despite tamponade. A dilated IVC with high RA pressure combined with a small RV cavity is a more useful clue, and hemodynamic improvement after drainage confirms the diagnosis.");
B(10,'peri',2,"A trauma patient with hemorrhage has a pericardial effusion with RA and RV diastolic collapse, but the IVC is small and collapsible. What is the most likely diagnosis?",["Low-pressure tamponade","Pericardial effusion without hemodynamic significance","Constrictive pericarditis","Tamponade excluded by the IVC finding"],0,"In hypovolemia, chambers collapse at lower intrapericardial pressures with equalized pressures <10 mm Hg, so IVC plethora is absent despite tamponade. These patients may still benefit from pericardiocentesis, though tamponade is often less severe.");
B(10,'peri',2,"A patient with severe chronic pulmonary hypertension and RV hypertrophy develops a large effusion and hypotension. Which chamber is most likely to collapse?",["Right ventricle in early diastole","Left ventricle","Right atrium throughout systole","None, because pulmonary hypertension prevents tamponade"],1,"When RV pressure exceeds intrapericardial pressure, the RV stays expanded despite the effusion. The LV may instead become the chamber that collapses, and tricuspid inflow variation may be absent.");
B(10,"peri",2,"Twelve hours after valve surgery, a patient has rising vasopressor needs and high right-sided pressures. TTE shows no effusion. What is the next step?",["Reassure; a negative TTE effectively excludes tamponade here","Start volume loading and repeat the TTE in 24 hours","Urgent TEE to look for a localized, often posterior, hematoma","Rely on the presence of pulsus paradoxus to decide on re-exploration"],2,"Postoperative tamponade is often from a localized, posteriorly located hematoma that TTE misses; a negative TTE should prompt urgent TEE. Early tamponade (<24 h) usually reflects surgical bleeding or coagulopathy, and pulsus paradoxus or pressure equalization may be absent.");
B(10,"peri",2,"While awaiting pericardiocentesis, which interim management statement is correct?",["Volume expansion helps all patients and should be given routinely","Inotropes are the preferred bridge to drainage in most patients","Patients with a low RA pressure benefit least from fluid loading","Fluid helps some but lowers CI in ~1/3; norepinephrine raises MAP"],3,"Volume expansion increases cardiac index in some patients, especially those with low baseline BP and cardiac index, but lowers it in one-third. Patients with low RA pressure do not seem to benefit, so routine fluid is not recommended. Norepinephrine raises MAP; inotropes are controversial.");
B(10,"mass",2,"A patient on venoarterial ECMO with a new pericardial effusion fails repeated weaning attempts. Chamber collapse is equivocal. What should be suspected?",["Tamponade, warranting pericardiocentesis or clot evacuation","Primary RV failure that is unrelated to the pericardial effusion","Hypovolemia, warranting fluid and a repeat weaning trial","A left pleural effusion mimicking pericardial fluid"],0,"VA ECMO can modify chamber collapse and right-sided pressures, making classic signs unreliable. Loss of pulsatility with a new effusion suggests tamponade, and inability to wean with an effusion should prompt pericardiocentesis or clot evacuation.");
B(10,'peri',2,"Six hours after surgical drainage of a large effusion, a patient with previously normal ventricular function develops acute RV dilatation and shock. Which statement about this syndrome is correct?",["It occurs only within minutes of drainage","It has substantial mortality (about 29%) after surgical evacuation","It mainly affects patients with preexisting severe LV dysfunction","It is caused by reaccumulation of pericardial fluid"],1,"Pericardial decompression syndrome causes paradoxical worsening from LV, RV, or biventricular failure, from immediately up to 48 hours after drainage, usually with normal preexisting function. Mortality is about 29% after surgical evacuation, which has not been seen after pericardiocentesis.");

// Chapter 11 — Assessment and Implications of Diastolic Dysfunction in Critical Illness
B(11,'dia',2,"A ventilated patient with septic shock has a mitral inflow peak E velocity of 110 cm/s and a septal eʹ of 7 cm/s on tissue Doppler. What is the best interpretation of left atrial pressure (LAP)?",["Normal LAP, because E/eʹ is below 8","Indeterminate LAP, because E/eʹ falls between 8 and 14","Elevated LAP, because septal E/eʹ exceeds 15","Cannot be estimated without a tricuspid regurgitant jet"],2,"E/eʹ = 110/7 ≈ 16. ASE 2016 cut-offs: average E/eʹ >14, septal >15, lateral >13. E/eʹ <8 is usually normal. E/eʹ does not require a TR jet to be interpreted.");
B(11,'dia',1,"Which pair of tissue Doppler mitral annular eʹ velocities represents the lower limits of normal at the septal and lateral annulus, respectively?",["≥7 cm/s septal and ≥10 cm/s lateral","≥10 cm/s septal and ≥7 cm/s lateral","≥5 cm/s septal and ≥8 cm/s lateral","≥8 cm/s septal and ≥14 cm/s lateral"],0,"Normal eʹ is ≥7 cm/s at the septal annulus and ≥10 cm/s at the lateral annulus. eʹ reflects intrinsic myocardial relaxation (lusitropy and elastic recoil) and is relatively load-independent.");
B(11,'dia',2,"A 76-year-old woman with septic shock has a normal ejection fraction, mitral E/A of 0.6, septal eʹ of 6 cm/s and average E/eʹ of 12, with a normal-sized left atrium. Which physiological state do these findings best describe?",["Restrictive filling with markedly elevated LAP","Pseudonormal filling with elevated LAP","Normal relaxation with a preload deficit","Impaired ventricular relaxation without elevated LAP"],3,"Reversed E/A (≤0.8) plus low eʹ indicates impaired intrinsic relaxation, while a non-elevated E/eʹ indicates LAP has not yet risen (grade I pattern). In the case, subsequent fluid loading raised E/A to 1.5 and E/eʹ to 16, reflecting rising LAP.");
B(11,"dia",2,"An ICU patient has mitral E/A of 1.2 and it is unclear whether filling is normal or pseudonormal. Which bedside maneuver can help distinguish the two?",["Passive leg raise, looking for a rise in eʹ velocity","Valsalva strain phase, looking for a ≥50% fall in E/A","Raising PEEP, looking for a longer deceleration time","Fluid bolus, looking for the E/A ratio to rise above 2"],1,"Reducing preload with the strain phase of a Valsalva maneuver lowers LAP; in pseudonormal filling E/A falls by ≥50%, unmasking underlying impaired relaxation. Normal filling does not reverse in this way.");
B(11,'dia',2,"A patient with ischemic cardiomyopathy has mitral E/A of 2.4, reduced eʹ, E/eʹ of 18 and a markedly short E-wave deceleration time. Which grade of diastolic function is present?",["Grade I (impaired relaxation)","Grade III (restrictive filling)","Grade II (pseudonormal filling)","Normal diastolic function"],1,"Restrictive filling (grade III) shows E/A >2 with low eʹ and high E/eʹ; the poorly compliant ventricle rapidly obliterates the gradient, shortening deceleration time (normal >160 ms). Pseudonormal filling has E/A between 0.8 and 2.");
B(11,'dia',2,"A patient with ARDS has a peak tricuspid regurgitant velocity of 3.3 m/s. Why is this parameter of limited value for grading diastolic function in this patient?",["TR velocity is valid only when measured from the subcostal view","TR velocity is load-independent and therefore cannot reflect LAP","The guideline cutoff of 2.8 m/s applies only to atrial fibrillation","TR velocity reflects LAP only when the pulmonary vasculature is normal"],3,"The 2016 guidelines use a TR cutoff of 2.8 m/s because LAP is transmitted back to the right heart. Preexisting pulmonary hypertension or acute respiratory failure breaks this assumption, making TR velocity relatively unhelpful in the ICU.");
B(11,"dia",1,"What left atrial volume index cutoff is used in diastolic function assessment, and how useful is it in critically ill patients?",["34 mL/m²; less useful in ICU as the LA may not have remodeled","34 mL/m²; more useful in ICU because PPV enlarges the atrium","22 mL/m²; equally useful in outpatients and ICU patients alike","48 mL/m²; useful only when it is measured by TEE in the ICU"],0,"LAVI >34 mL/m² (biplane method of discs, excluding pulmonary veins and appendage) suggests chronically elevated LAP. It is less useful in the ICU because acute changes may not have caused remodeling and interventions such as positive pressure ventilation alter atrial size.");
B(11,'dia',2,"A patient in atrial fibrillation with variable RR intervals needs estimation of LAP. Which approach is most appropriate?",["Avoid E/eʹ and rely on left atrial volume index","Use the A-wave velocity from the longest RR interval","Use E/eʹ from beats with similar preceding interbeat intervals","Average E/A ratio over the five shortest cardiac cycles"],2,"In atrial fibrillation there is no A wave, but E/eʹ remains valid if E and eʹ are taken from beats with similar preceding interbeat intervals so the measurements are comparable.");
B(11,'dia',3,"A patient with suspected constrictive pericarditis has a septal eʹ of 12 cm/s and E/eʹ of 7. Why should these values be interpreted with caution?",["Constriction lowers mitral E, falsely reducing E/eʹ","Constriction abolishes the A wave, invalidating E/A","Constriction slows the lateral annulus, which must be used instead","Constriction increases septal eʹ, invalidating E/eʹ assumptions"],3,"Constrictive pericarditis increases septal eʹ velocity, which falsely lowers E/eʹ and invalidates its use as an LAP surrogate. Other caveats include mitral stenosis, prosthetic mitral valves, significant MR and regional wall motion abnormalities.");
B(11,'dia',1,"Where should the pulsed-wave sample volume be placed to record mitral E and A velocities in the apical 4-chamber view?",["At the mitral annulus, with tissue Doppler filters applied","At the mitral leaflet tips within the left ventricle","Near the LV apex to minimize Doppler angle error","In the left atrium just proximal to the mitral valve"],1,"E and A are recorded with the PW gate at the mitral leaflet tips within the LV, angle <20°, averaging 3 beats at end-expiration. Placing the sample too apically yields slower, more dispersed velocities.");
B(11,'fluid',2,"A hypotensive septic patient has an E/eʹ of 17. The resident proposes withholding fluid because LAP is high and the patient therefore cannot be preload responsive. What is the best response?",["Correct, because high E/eʹ reliably predicts fluid unresponsiveness","Correct, because E/eʹ >14 indicates restrictive physiology","Incorrect, because preload (LAP) is distinct from preload responsiveness","Incorrect, because E/eʹ underestimates LAP in sepsis"],2,"E/eʹ estimates LAP, analogous to PCWP, and PCWP does not correlate with fluid responsiveness. E/eʹ may relate to fluid tolerance, but data are lacking; it is unlikely to predict fluid responsiveness.");
B(11,'dia',2,"A tachycardic patient (HR 135/min) shows fused mitral E and A waves. How should LAP be estimated?",["Treat the fused wave as the E velocity and calculate E/eʹ","Report diastolic function as indeterminate without calculation","Use deceleration time of the fused wave as the LAP surrogate","Use the A-wave component alone divided by aʹ velocity"],0,"Tachycardia often fuses E and A waves, making E/A unusable, but E/eʹ remains generally accurate if the fused wave peak is taken as E velocity.");

// Chapter 12 — Ultrasound-Driven Approach to Patients in Shock
B(12,'fluid',2,"A hypotensive postoperative patient has a small, hyperdynamic LV with near cavity obliteration and a left ventricular end-diastolic area (LVEDA) of 4.8 cm²/m². What does this suggest?",["Vasodilatory shock, which is excluded by an LVEDA below 12 cm²","Hypovolemia, since LVEDA below 5.5 cm²/m² is suggestive","Normal filling, since LVEDA must exceed 12 cm² for hypovolemia","Dynamic LVOT obstruction, which requires LVEDA above 5.5 cm²"],1,"In FUSA, LVEDA <5.5 cm²/m² suggests hypovolemia, whereas LVEDA >12 cm² is not consistent with hypovolemia. A small hyperdynamic LV with cavity obliteration supports volume depletion.");
B(12,'fluid',2,"In the FUSA approach, which IVC finding indicates hypovolemia in a passively mechanically ventilated patient?",["Collapsibility index greater than 50%","Distensibility index less than 12%","Collapsibility index greater than 75%","Distensibility index greater than 18%"],3,"FUSA uses an IVC distensibility index >18% in mechanically ventilated patients and a collapsibility index >75% in spontaneously breathing patients to identify hypovolemia.");
B(12,"views",1,"What is the first unique step of the FUSA algorithm that distinguishes it from other shock protocols?",["Determining whether signs of chronic cardiac disease are present","Screening for tamponade first with subcostal imaging","Measuring the LVOT velocity-time integral at baseline","Performing compression ultrasound of both femoral veins first"],0,"FUSA begins by looking for chronic cardiac disease (dilation, hypertrophy), because chronic disease confounds focused volume assessment and may warrant a comprehensive study. Its 5 steps are chronic disease, pump function, hypovolemia/vasodilation, tamponade, and lung ultrasound.");
B(12,'rv',2,"A patient in shock has a dilated RV that forms the apex, RV/LV ratio greater than 1, septal flattening, and an RV free wall thickness of 3 mm. Which process is most likely?",["Chronic pulmonary hypertension from lung disease","Hypertrophic cardiomyopathy with RV involvement","An acute process such as massive pulmonary embolism","Chronic LV failure with RVOT obstruction"],2,"RV dilation without hypertrophy (RV wall ≤5 mm) suggests an acute process such as massive PE. RV hypertrophy (wall >5 mm) implies chronic or acute-on-chronic disease such as pulmonary hypertension or COPD.");
B(12,"mass",2,"In the RUSH protocol, which component is evaluated under the question 'Are the pipes ruptured or obstructed?'",["IVC size and internal jugular venous distension","Aortic dissection or aneurysm and leg DVT","Pericardial effusion and the RV:LV size ratio","Pneumothorax, pleural effusion and FAST views"],1,"The 'pipes' step examines the thoracic and abdominal aorta (suprasternal, PLAX, epigastric, abdominal views) for dissection or aneurysm, then femoral and popliteal veins for thrombosis. IVC, lung and FAST belong to the 'tank'; pericardium and RV:LV belong to the 'pump'.");
B(12,'peri',2,"An unstable patient has a moderate circumferential pericardial effusion. Which chamber collapse is typically seen earliest as tamponade develops?",["Right atrial systolic collapse","Right ventricular diastolic collapse","Left atrial systolic collapse","Left ventricular diastolic collapse"],0,"Once intrapericardial pressure exceeds intracavitary pressure, RA systolic collapse appears early, and RV diastolic collapse follows with worsening compression. The LV becomes small and hyperdynamic as it is underfilled.");
B(12,'peri',1,"In the parasternal long-axis view, how is a posterior pericardial effusion distinguished from a left pleural effusion?",["Pericardial fluid tracks behind the left atrium to the right pulmonary vein","Pleural fluid lies anterior to the right ventricle","Pericardial fluid is posterior and below the descending aorta","Pericardial fluid lies anterior to the descending aorta"],3,"With enough depth to see the descending aorta, a pericardial effusion lies proximal to (above) the descending aorta, whereas a left pleural effusion lies distal to (below) it.");
B(12,'peri',3,"Six hours after cardiac surgery, a patient develops shock. TTE shows no visible pericardial effusion, but the LV appears compressed. What is the most appropriate next step?",["Perform TEE to visualize a loculated posterior collection","Exclude tamponade because no effusion is seen on TTE","Assume RV failure because the right heart was not compressed","Repeat TTE after a fluid challenge to unmask the effusion"],0,"Post-cardiotomy tamponade is often loculated and posterior, may compress the left heart before the right, and can be missed on TTE. TEE better visualizes the posterior heart and is used as backup when TTE is insufficient.");
B(12,'fluid',3,"A patient in shock has a stroke volume of 50 mL before and 59 mL after a fluid challenge. How should this response be interpreted?",["Not fluid responsive, as the increase is below 20%","Contractile reserve is present, as SV rose more than 15%","Fluid responsive, as SV increased by more than 15%","Indeterminate, as SV changes require inotrope testing"],2,"SV rose by 9/50 = 18%, exceeding the 15% threshold that defines fluid responsiveness. A 20% rise in SV with inotrope administration defines contractile reserve.");
B(12,"hemo",2,"In which scenario can LVOT VTI not be used as a surrogate for stroke volume?",["Heart rate between 55 and 95 beats per minute","Moderate mitral regurgitation with a central jet","Mechanical ventilation with PEEP of 10 cm H2O","Dynamic LVOT obstruction or severe AR"],3,"LVOT VTI cannot proxy SV with dynamic LVOT obstruction or severe AR. Normal VTI at heart rate 55–95 bpm is 18–22 cm; at heart rate <55, VTI should be at least 18 cm to maintain SV.");
B(12,'shock',2,"A febrile patient in shock has a small hyperdynamic LV with an increased stroke volume, normal LVEDA and normal IVC indices. What is the most likely mechanism?",["Underfilled LV from tamponade or tension pneumothorax","Decreased afterload, as in sepsis or anaphylaxis","Dynamic LVOT obstruction from systolic anterior motion","Severe hypovolemia from hemorrhage"],1,"With a small hyperdynamic LV, increased SV suggests decreased afterload (sepsis, vasodilators, anaphylaxis, liver disease, adrenal insufficiency). Low SV would instead suggest an underfilled LV or LV outflow obstruction; vasodilatory shock is a diagnosis of exclusion.");
B(12,'shock',2,"A hypertensive patient with LV wall thickness of 15 mm becomes hypotensive after starting dobutamine. Spectral Doppler in the LVOT shows a late-peaking, dagger-shaped high-velocity signal. What is the diagnosis?",["Severe aortic regurgitation","Acute mitral papillary muscle rupture","Dynamic LVOT obstruction","Restrictive LV filling physiology"],2,"In shock with LV hypertrophy (wall >12 mm), dynamic LVOT obstruction should be considered, provoked by hypovolemia or inotropes; the LVOT progressively closes in systole, producing the classic dagger-shaped Doppler profile.");

// Chapter 13 — Ultrasound-Driven Approach to Patients With Acute Respiratory Failure
B(13,'lung',3,"A 42-year-old woman with lupus is intubated for refractory hypoxemia and becomes hypotensive. LUS shows diffuse nonhomogeneous B lines and dependent consolidations with dynamic air bronchograms. Echo shows reduced LVEF, RV pressure overload, a moderate pericardial effusion and an IVC collapsed throughout the respiratory cycle. What is the most appropriate next step before a recruitment maneuver?",["Urgent pericardiocentesis for tamponade","Start an inotrope for RV failure","Diurese because of diffuse B lines","Give a fluid bolus for the collapsed IVC"],3,"Despite RV findings and effusion, a fully collapsed IVC without inspiratory distensibility indicates low preload, so a fluid bolus precedes recruitment. Recruitment then reaerated consolidations, PEEP was raised to 20 cm H2O, and oxygenation and hemodynamics improved.");
B(13,"lung",1,"Why is the 12-zone lung ultrasound protocol generally favored in critically ill patients?",["It is the only protocol validated against chest CT","It covers dependent consolidation and tracks aeration","It is the fastest protocol for excluding pneumothorax","It avoids the need to scan any posterior lung zones"],1,"The 12-zone protocol adds posterior zones (between posterior axillary line and spine), allowing assessment of dependent consolidations and monitoring of aeration changes. No study has compared performance of the different protocols.");
B(13,'lung',1,"For which purpose has a 28-zone lung ultrasound protocol been proposed?",["Rapid exclusion of pneumothorax in trauma","Diagnosis of pulmonary embolism with venous ultrasound","Monitoring interstitial syndrome in chronic heart failure","Guiding PEEP titration during ECMO"],2,"A 28-zone protocol was proposed for monitoring interstitial syndrome in chronic heart failure. The abbreviated 6-zone protocol is used in emergencies to identify pneumothorax, hemothorax and bilateral severe interstitial syndrome.");
B(13,'lung',2,"In the original BLUE protocol study, what were the sensitivity and specificity for pulmonary embolism?",["81% sensitivity and 99% specificity","99% sensitivity and 81% specificity","90.5% sensitivity and 88% specificity","88% sensitivity and 90.5% specificity"],0,"The BLUE protocol (12-zone LUS plus venous ultrasound in 260 patients) was correct in 90.5% of cases, with sensitivity and specificity >88% for pulmonary edema, asthma, COPD, pneumothorax and pneumonia; for PE, sensitivity was 81% and specificity 99%.");
B(13,'lung',2,"After emergency intubation, LUS shows absent lung sliding over the entire left hemithorax with an A-line pattern, but no lung point. Which condition can produce this as a false-positive pneumothorax finding?",["Endobronchial (right mainstem) intubation","Small loculated anterior pneumothorax","Subcutaneous emphysema producing E lines","Severe bradycardia abolishing lung pulse"],0,"Absent lung sliding occurs whenever visceral pleura does not slide on parietal pleura: apnea, adhesions, overinflation, bullous disease, low compliance, pleural symphysis or endobronchial intubation. These cause false-positive pneumothorax findings.");
B(13,'lung',2,"Which finding is a recognized cause of a false-positive lung point?",["A-line pattern with absent lung pulse","Coalescent B lines in a dependent zone","Pericardial movement in the paracardiac area","An anechoic collection above the diaphragm"],2,"Pericardial movement (paracardiac area), diaphragm motion, adhesions or the transition between normal lung and a bulla can be mistaken for a lung point. Note that a complete pneumothorax has no lung point at all.");
B(13,'lung',2,"A trauma patient has a pleural effusion containing a dependent echogenic layer in the costophrenic recess and a superficial anechoic layer. What does this suggest?",["An acute transudate","An older hemothorax with a hematocrit sign","An acute hemothorax with homogeneous clot","A simple exudate from pneumonia"],1,"Acute hemothorax is usually homogeneously echogenic, whereas older hemothoraces layer (hematocrit sign) with echogenic cells dependently and an anechoic acellular layer above. LUS sensitivity and specificity for hemothorax in trauma are 92% and 100%.");
B(13,"lung",1,"A pleural effusion is completely anechoic on ultrasound. What can be concluded about its nature?",["It is a transudate, since it is anechoic","It is an exudate with a low protein content","It is an acute hemothorax that has not yet clotted","It cannot be classed as transudate or exudate"],3,"Complex effusions suggest exudate, but a simple anechoic effusion does not distinguish exudate from transudate; transudates are mostly anechoic, yet there is significant overlap.");
B(13,'lung',1,"Which lung ultrasound pattern indicates severe loss of aeration?",["Three or more well-spaced B lines per intercostal space","A lines with preserved lung sliding","Multiple coalescent B lines per intercostal space","One or two B lines in a dependent zone"],2,"The B2 pattern (multiple coalescent B lines) reflects severe loss of aeration, whereas B1 (≥3 well-defined spaced B lines per intercostal space) reflects moderate loss. Isolated B lines in dependent areas or in the elderly may be nonpathological.");
B(13,'lung',2,"After chest tube insertion, a patient with subcutaneous emphysema shows vertical hyperechoic artifacts in the anterior chest. What is the key pitfall?",["E lines from subcutaneous tissue can mimic B lines","Lung pulse can be mimicked by intercostal muscle motion","A lines may represent pleural fluid in this setting","The liver mirror artifact can mimic consolidation"],0,"E lines are vertical artifacts originating in subcutaneous tissue with subcutaneous emphysema; misreading them as pleural-origin vertical artifacts causes false-positive interstitial syndrome and false-negative pneumothorax assessment. True B lines arise from the pleural line.");
B(13,'lung',3,"A patient with Pneumocystis jiroveci pneumonia develops sudden dyspnea. Lung ultrasound, performed semi-recumbent, shows lung sliding in all anterior zones. What is the best interpretation?",["Pneumothorax is excluded and no further imaging is required","Lung sliding confirms a lung point is present","Pneumothorax is excluded only if B lines are absent","High pretest probability warrants CXR or CT despite negative LUS"],3,"With high pretest probability, a negative LUS should not immediately rule out pneumothorax, especially if the patient could not lie completely supine (least dependent zones may be missed); confirm with CXR or CT.");
B(13,'lung',2,"A patient presents with acute respiratory failure, pleuritic chest pain and a normal bilateral lung ultrasound (A lines with sliding). Which additional POCUS application is most appropriate next?",["Diaphragm ultrasound to assess for paralysis","Venous compression ultrasound and RV assessment","LV assessment for systolic dysfunction","Abdominal FAST to look for free fluid"],1,"Respiratory failure with chest pain and normal LUS should trigger venous ultrasound and RV assessment for pulmonary embolism. Diffuse B lines, in contrast, should prompt LV assessment for dysfunction.");

// Chapter 14 — Failure to Wean From Mechanical Ventilatory Support
B(14,'lung',2,"A ventilated patient passes a 1-hour T-piece SBT. Lung ultrasound at the end of the trial, using the 12-region aeration score, totals 19. What is the most appropriate interpretation?",["High risk of postextubation distress; optimize aeration before extubation","Low risk of postextubation distress; proceed directly to extubation now","Indeterminate score; repeat the SBT tomorrow on higher pressure support","Score reflects pleural effusion only and should be ignored"],0,"An end-SBT LUS score >17 is highly predictive of extubation failure, while <13 is highly predictive of success. Loss of aeration is the common final pathway of weaning failure whatever its cause, so aeration should be optimized before extubation.");
B(14,'lung',1,"In the lung ultrasound aeration score used in the ICU, coalescent B lines occupying more than 50% of the pleural line in a region are scored as:",["1 (moderate loss of aeration)","2 (severe loss of aeration)","3 (complete loss of aeration)","0 (normal aeration)"],1,"Score 0 = A lines or ≤2 B lines; 1 = ≥3 well-spaced B lines; 2 = coalescent B lines; 3 = tissue-like pattern. Six regions per hemithorax give a global score of 0–36.");
B(14,'lung',1,"How many regions are scored in the global lung ultrasound aeration score, and what is its maximum value?",["8 regions, maximum score 24","6 regions, maximum 18","12 regions, maximum 36","16 regions, maximum 48"],2,"Sternum, anterior and posterior axillary lines define anterior, lateral and posterior areas, each split superior/inferior: 6 regions per hemithorax, 12 total, each scored 0–3, so 0–36.");
B(14,'lung',2,"Diaphragm ultrasound in the zone of apposition shows an end-expiratory thickness of 2.0 mm and an end-inspiratory thickness of 2.3 mm during an SBT. What is the thickening fraction and its interpretation?",["30%; normal diaphragm contractility","15%; abnormal (normal is greater than 20%)","13%; normal because thickness exceeds 1.7 mm","87%; consistent with diaphragm edema"],1,"Thickening fraction = (Tmax − Tmin)/Tmin = (2.3 − 2.0)/2.0 = 15%. A thickening fraction >20% is normal; a reduced value has been shown to predict weaning failure, though data are discordant.");
B(14,'lung',2,"A patient after cardiac surgery is evaluated with a low-frequency probe and anatomic M-mode along the axis of right hemidiaphragm excursion. Maximal excursion is 0.8 cm. What does this indicate?",["Normal excursion for a ventilated patient","Mild dysfunction not affecting weaning","Excursion cannot be measured with M-mode","Severe diaphragmatic dysfunction"],3,"Normal diaphragmatic excursion is 1.5–2.5 cm; excursion <1.0 cm identifies severe dysfunction. Impaired excursion is associated with longer weaning and more weaning failure.");
B(14,'lung',2,"Why has diaphragmatic excursion been questioned as a weaning predictor when measured during an SBT on low pressure support?",["It reflects both patient and ventilator activity","Excursion cannot be imaged reliably with a phased-array probe in ventilated patients","Excursion is invariably normal in ICU patients receiving any pressure support","Excursion correlates poorly with fluoroscopy"],0,"During pressure support, diaphragm displacement is driven by both patient and ventilator, so it does not purely reflect muscle function. Excursion actually correlates well with Gilbert index, fluoroscopy and EMG.");
B(14,'dia',2,"A patient with COPD fails an SBT with tachypnea. During the trial, mitral inflow E rises and lateral E/Eʹ increases from 7 to 14 with preserved LVEF. Which mechanism and intervention are best supported?",["Diaphragm paralysis from critical illness; noninvasive ventilation after extubation","Primary lung derecruitment; recruitment maneuvers","Raised LV filling pressure; diuretics","Dynamic LVOT obstruction; inotropes"],2,"Increasing E/Eʹ during SBT predicts weaning failure (threshold values 8–15 across studies) and reflects increased LV filling pressure; with overload, diuretics are the tailored intervention. Inotropes would worsen LVOT obstruction.");
B(14,'dia',1,"Weaning failure occurs in up to what proportion of patients with a pseudonormal or restrictive mitral inflow pattern?",["20%","50%","35%","80%"],3,"Weaning failure occurs in up to 80% of patients with moderate (pseudonormal) or severe (restrictive) diastolic dysfunction, so CCE should always follow weaning or extubation failure. Reduced LVEF, in contrast, is present in fewer than 20% of weaning patients.");
B(14,'dia',2,"In which patient should the E/Eʹ ratio NOT be relied upon to estimate LV filling pressure during an SBT?",["Patient with sinus tachycardia of 105/min","Patient with a mitral prosthesis","Patient with mild tricuspid regurgitation","Patient receiving low-dose norepinephrine"],1,"E velocity and E/Eʹ have not been validated in mitral regurgitation, mitral stenosis, mitral annular calcification or mitral prosthetic valves.");
B(14,'lv',2,"During an SBT, a patient with an asymmetric septal hypertrophy develops hypotension, a new systolic murmur and worsening mitral regurgitation from dynamic LVOT obstruction. Which management is suggested?",["Beta-blockers and an alpha-1 agonist","Dobutamine infusion titrated to cardiac output","Nitrates and loop diuretics with afterload reduction","Milrinone and fluid restriction"],0,"Dynamic LVOT obstruction during SBT increases MR and filling pressure; β-blockers plus an α1 agonist if hypotensive are recommended. Inodilators and vasodilators worsen the obstruction.");
B(14,'lung',3,"At the end of an SBT, LUS shows a global score of 20 with B lines and consolidations mainly in posterolateral regions and well-aerated anterior fields. CCE shows E/A <1, lateral Eʹ 0.11 m/s and E/Eʹ 6.8. What is the most likely mechanism of predicted weaning failure?",["Cardiogenic weaning-induced pulmonary edema from diastolic dysfunction","Severe diaphragmatic paralysis","Lung derecruitment","Large pleural effusion compressing the lung"],2,"Normal Eʹ and E/Eʹ with impaired-relaxation inflow indicate no rise in filling pressure; loss of aeration with spared anterior fields points to derecruitment, so aeration should be optimized before extubation. Diffuse B lines with high E/Eʹ would instead suggest cardiogenic edema.");
B(14,'lung',2,"Regarding regional aeration changes during a spontaneous breathing trial, which statement is correct?",["Anterior and lateral regions gain aeration from diaphragm contraction","Pleural effusion size is a validated predictor of weaning failure","Assessing only anterior fields for B-line predominance is sufficient","Rising antero-lateral B lines suggest weaning-induced edema"],3,"Dependent posterior regions may gain aeration with active diaphragm contraction while nondependent antero-lateral regions may lose it; rising antero-lateral B lines suggest weaning-induced pulmonary edema. A simplified anterior-only approach is not accurate enough, and the impact of pleural effusion is controversial.");

// Chapter 15 — Extracorporeal Membrane Oxygenation Support
B(15,'mass',2,"A patient with severe ARDS is being considered for ECMO. Pre-cannulation echocardiography shows severely depressed LV systolic function. What is the most appropriate implication?",["VA ECMO may be a better modality than VV ECMO","VV ECMO is preferred because it unloads the LV","ECMO is contraindicated in LV dysfunction","Proceed with VV ECMO and add inotropes only if lactate rises"],0,"VV ECMO provides little hemodynamic augmentation, so adequate cardiac (especially LV) function must be confirmed before VV cannulation; significant LV depression favors VA ECMO.");
B(15,'rv',2,"Why should the tricuspid regurgitation jet be measured before rather than after initiating VV ECMO?",["TR always disappears once oxygenation and pH normalize on the circuit","The circuit decompresses the RV, making TR inaccurate","The return cannula prevents any apical imaging","TR velocity cannot be measured with TEE"],1,"After VV ECMO starts, RV decompression by the circuit makes TR-derived estimates inaccurate, so baseline RVSP should be obtained beforehand and used to follow RV recovery.");
B(15,'rv',3,"Before VV ECMO, a patient has a peak TR velocity of 3.5 m/s and an estimated right atrial pressure of 15 mm Hg, with no pulmonic stenosis. What is the estimated PA systolic pressure?",["49 mm Hg","64 mm Hg","29 mm Hg","79 mm Hg"],1,"RVSP = RAP + 4v² = 15 + 4(3.5)² = 15 + 49 = 64 mm Hg; without pulmonic stenosis PA systolic pressure equals RVSP.");
B(15,'mass',2,"During 2-site femoral–jugular VV ECMO cannulation, where should the cannula tips ideally be positioned?",["Both tips together at the cavo-atrial junction to maximize mixing","Drainage tip in the RV; return tip in the SVC","Drainage ~10 cm below the RA in the IVC; return just inside the RA","Drainage tip in the RA; return tip in the hepatic IVC"],2,"The drainage cannula tip sits in the IVC ~10 cm below the RA, and the return tip slightly within the RA, free of the interatrial septum and tricuspid valve. Closely approximated cannulas cause recirculation.");
B(15,'mass',2,"A bicaval dual-lumen cannula is inserted via the right internal jugular vein for VV ECMO. Which position is optimal?",["Tip in the hepatic IVC with the return port directed toward the SVC","Tip in the RV with return jet directed at the pulmonic valve","Drainage port in the RA and return port in the hepatic vein","Drainage ports in SVC and IVC; return jet aimed at the tricuspid valve"],3,"The dual-lumen cannula has 2 drainage ports (SVC and IVC) and 1 return port in the RA aimed directly across the tricuspid valve; TEE is preferred to confirm drainage ports and return flow direction.");
B(15,'mass',1,"Which TEE view is best for monitoring guidewire and cannula position in the SVC and IVC during VV ECMO cannulation?",["Midesophageal bicaval view","Transgastric short-axis view","Midesophageal aortic valve short-axis view","Deep transgastric long-axis view"],0,"The midesophageal bicaval view best visualizes guidewires and cannulas in the SVC and IVC; with TTE, subcostal and parasternal RV inflow-outflow views are used.");
B(15,'mass',2,"A patient on VV ECMO with a dual-lumen cannula has persistent hypoxemia despite high circuit flow and a functioning oxygenator. TTE shows the cannula tip in the RV. What is the most likely mechanism?",["Cardiac tamponade limiting drainage","Hypovolemic suck-down event with IVC collapse","High cardiac output exceeding ECMO flow","Recirculation"],3,"A dual-lumen cannula too deep (tip in the RV), too shallow or malrotated allows the distal drainage port to take up returned oxygenated blood, causing recirculation. Agitated saline microbubbles moving from return into drainage cannula can confirm it.");
B(15,'mass',2,"On VV ECMO, the drainage line is noted to bounce rhythmically ('chugging') with falling flows. Subcostal imaging shows the IVC collapsing around the drainage cannula. What is the best next step?",["Increase pump speed to overcome the obstruction","Convert immediately to VA ECMO for hemodynamic support","Give fluid with real-time ultrasound monitoring","Start esmolol to slow the heart rate"],2,"A suck-down event occurs when the drainage cannula draws the IVC walls against itself (eg, hypovolemia or oversized cannula); echocardiography confirms it and can monitor fluid resuscitation in real time.");
B(15,'hemo',3,"A septic patient on VV ECMO with near-100% shunt remains hypoxemic. LVOT diameter is 2.0 cm, LVOT VTI 25 cm and heart rate 120/min; ECMO flow is 4 L/min. What is the cardiac output and a reasonable intervention?",["About 9.4 L/min; esmolol","About 7.9 L/min; increase sweep gas flow on the oxygenator","About 3.1 L/min; start dobutamine to raise oxygen delivery","About 12.0 L/min; reposition the drainage cannula"],0,"SV = π(1.0)² × 25 ≈ 78.5 mL; CO = 78.5 × 120 ≈ 9.4 L/min, far above ECMO flow, so desaturated venous return dilutes circuit blood. Reducing cardiac output with esmolol can improve hypoxemia; CO should be reassessed after intervention.");
B(15,'mass',1,"Which finding on pre-VA ECMO echocardiography is a relative contraindication to VA ECMO?",["Massive PE with RV failure","Severe aortic insufficiency","Severe LV systolic dysfunction after MI","Moderate pericardial effusion without tamponade"],1,"Severe aortic insufficiency, aortic dissection and papillary muscle rupture with severe MR are relative contraindications to VA ECMO. PE with RV failure and post-MI cardiogenic shock are indications.");
B(15,'mass',2,"On peripheral VA ECMO, daily TEE shows the aortic valve no longer opens, dense spontaneous echo contrast in the LA and a dilating LV. Which action is most appropriate first?",["Increase ECMO flow to improve systemic perfusion and coronary flow","Begin weaning by clamping the circuit","Lower flow under echo guidance; vent the LV if needed","Ignore; this is expected with full support"],2,"Retrograde arterial return raises LV afterload; failure of AV opening causes stasis and risk of intracardiac/aortic valve thrombus. Lower flows under echo to restore opening; if impossible, vent the LV (IABP, Impella or surgical vent).");
B(15,'mass',2,"During a VA ECMO turn-down study, which set of echocardiographic findings is associated with successful weaning?",["LVOT VTI 7 cm with LVEF 20%","LVEF 35% with progressive LV dilation and mitral Sʹ 4 cm/s","Rising LV end-diastolic dimension and new pericardial effusion","LVEF 30%, LVOT VTI 12 cm, mitral Sʹ 7 cm/s"],3,"Predictors of VA ECMO weaning success include LVEF >25% (reported 25–40%), LVOT VTI >10 cm, absence of LV dilation, mitral annular peak systolic velocity >6 cm/s and no tamponade.");
B(15,'rv',2,"During weaning from VA ECMO, why must the RV be specifically interrogated before decannulation?",["Low-flow VA ECMO can mask RV dysfunction","RV function is the main determinant of oxygenator performance","RV size cannot change once the circuit is clamped","TR velocity is accurate only at full ECMO flow and must be measured then"],0,"Even low-flow VA ECMO can mask RV dysfunction, which may lead to cardiac failure after decannulation if unrecognized; RV size, function, PASP and valves should be assessed at each step.");
B(15,'mass',2,"For femoral VA ECMO cannulation, what are the optimal positions of the drainage and return cannula tips?",["Drainage in the SVC; return in the ascending aorta","Drainage at IVC–RA junction; return in iliac artery or distal aorta","Drainage 10 cm below the RA; return in the descending thoracic aorta at the arch","Drainage in the RV; return tip kept within the common femoral artery only"],1,"In VA ECMO the drainage tip is optimally at the IVC–RA junction (TEE bicaval or TTE subcostal/RV inflow views); the femoral return cannula typically terminates in the iliac artery or distal abdominal aorta. Visualizing the guidewire in the aorta reduces extra-arterial placement.");

// Chapter 16 — Neurocritical Care
B(16,'lv',2,"A 32-year-old woman with aneurysmal subarachnoid hemorrhage, coiled and with a new subclavian line, develops rising oxygen needs and falling blood pressure. Lung ultrasound shows diffuse bilateral B lines with lung sliding present; echocardiography shows reduced LV function with a normal-sized RV. What is the most likely diagnosis?",["Iatrogenic pneumothorax from subclavian cannulation","Aspiration pneumonia with septic shock","Neurogenic stress cardiomyopathy","Acute massive pulmonary embolism from a prothrombotic state"],2,"Diffuse B lines with preserved sliding plus new LV systolic dysfunction and normal RV size point to stress cardiomyopathy after SAH; lung sliding excludes pneumothorax and a normal RV argues against massive PE. Treatment was diuresis and inotropes.");
B(16,'vasc',1,"For B-mode cranial ultrasound through the temporal window, which probe and orientation are used?",["Phased-array 1–3 MHz above the zygoma, marker to the eyes","Linear 10 MHz probe over the closed eyelid, marker cephalad","Curvilinear probe in the suboccipital region, marker toward the ear","Phased-array probe over the mastoid, marker toward the occiput"],0,"The thin temporal bone just above the zygomatic arch (anterior and superior to the tragus) is the temporal window; a phased-array probe is placed with the marker toward the eyes, aligned with the basal cistern.");
B(16,'vasc',1,"On transtemporal B-mode imaging aligned with the basal cisterns, which structure appears as a hypoechoic 'butterfly'?",["Third ventricle","Calcified pineal gland","Circle of Willis","Midbrain"],3,"The midbrain appears as a hypoechoic butterfly formed by the cerebral peduncles; the third ventricle appears as 2 hyperechoic lines anterior to it, and a calcified pineal may be seen posteriorly.");
B(16,'vasc',3,"Transtemporal ultrasound measures the distance from the temporal bone to the third ventricle as 76 mm from the right and 64 mm from the left. What is the midline shift?",["12 mm","6 mm","3 mm","70 mm"],1,"Midline shift = (difference between the 2 distances)/2 = (76 − 64)/2 = 6 mm. Absence of shift does not rule out raised ICP, as lesions above or below the midbrain plane or global injury may be missed.");
B(16,'vasc',2,"Pulsed-wave TCD of the middle cerebral artery shows a narrow vertical systolic upstroke and diastolic flow less than one-fourth of peak systolic flow, with no flow reversal. What does this indicate?",["Rising intracranial pressure","Normal low-resistance cerebral circulation in a sedated patient","Cerebral circulatory arrest","Cerebral hyperemia from impaired autoregulation"],0,"Normal MCA waveforms have rapid upstroke, stepwise deceleration and diastolic flow one-third to one-half of systolic. Diastolic flow <1/4 of systolic with a sharp upstroke reflects a resistive bed from increased ICP; reversed diastolic flow indicates ICP above diastolic BP.");
B(16,'vasc',2,"In a patient with global brain injury, TCD shows reversed (below-baseline) diastolic flow that is persistent and reproducible in all major intracranial arteries. What does this signify?",["Treatable vasospasm amenable to hypertensive therapy","Normal finding in sedated patients","Irreversible impending circulatory arrest","Artifact from an excessively high wall filter"],2,"When ICP exceeds diastolic blood pressure, flow reverses in diastole; if persistent and reproducible in all arteries, this stage is considered irreversible. Progression continues to systolic spikes and finally absent flow.");
B(16,'vasc',2,"A patient on VA ECMO post cardiac arrest is paralyzed with fixed dilated pupils. MCA pulsed Doppler shows nonpulsatile forward flow with indistinct systole and diastole and a mean velocity of about 60 cm/s. How should this be interpreted?",["Cerebral circulatory arrest confirmed by loss of pulsatility","Intact cerebral blood flow","Severe vasospasm requiring angiography","Technically inadequate study; the window is absent"],1,"With ECMO or LVADs, nonpulsatile forward flow is expected and reflects intact cerebral blood flow, ruling out cerebral circulatory arrest. Post-arrest paralysis can produce false absence of brainstem reflexes.");
B(16,'vasc',2,"TCD of the MCA shows absent flow in a patient being evaluated for brain death; no prior study is available. Why can this not be taken as evidence of cerebral circulatory arrest?",["TCD cannot insonate the anterior circulation","Absent MCA flow is a normal finding in deeply sedated patients","Absent flow only indicates vasospasm","Temporal windows were never documented"],3,"Absence of Doppler flow is only meaningful if prior insonation demonstrated transcranial windows; ~10% of the population has none. Ancillary TCD also requires protocolized insonation of all anterior and posterior circulation vessels.");
B(16,'vasc',2,"A patient with aneurysmal SAH on day 7 has a left MCA mean flow velocity of 201 cm/s with aliasing on color Doppler. Which statement is correct?",["This is within the normal MCA range for a young adult","This proves vasospasm without need for clinical correlation","Low velocities like this indicate shock","Elevated; cause needs clinical correlation"],3,"Normal MCA mean flow velocity is 40–80 cm/s. Elevated velocities may reflect vasospasm, hyperemia or stenosis, which require clinical correlation; low velocities are seen in shock.");
B(16,'vasc',1,"When a low-flow state is suspected during color or spectral TCD, which adjustment is recommended?",["Lower the velocity scale and wall filter and increase the gain","Increase the wall filter to reduce noise","Increase the sample gate to 20 mm to capture more signal","Switch to a linear high-frequency probe"],0,"In low-flow states, lower the color/spectral scale (PRF) and wall filter and increase gain so low velocities are not filtered out or missed. The pulsed-wave sample gate is typically set at 5 mm on the proximal MCA.");
B(16,'vasc',2,"A patient with cerebral venous sinus thrombosis on therapeutic anticoagulation becomes obtunded; invasive ICP monitoring is contraindicated. TCD shows normal MCA waveforms with normal velocities and pulsatility index. What can be concluded?",["Raised ICP is confirmed and osmotherapy is required","Impaired cerebral perfusion pressure can be reliably ruled out","Brainstem function is intact and brain death excluded definitively","Midline shift is excluded"],1,"Normal physiological waveforms with normal velocities and pulsatility indices are a reliable, sensitive way to rule out impaired CPP when CT or invasive monitoring is impractical. TCD does not assess brainstem function or midline shift.");
B(16,'vasc',2,"Which statement about TCD in the determination of brain death is correct?",["TCD alone can replace the clinical examination and apnea test","Absent color Doppler flow at first insonation confirms brain death","TCD does not assess brainstem function","Insonation of both middle cerebral arteries alone is sufficient for confirmation"],2,"TCD can show cerebral circulatory arrest but not brainstem function, so clinical evaluation and apnea testing must precede and be consistent with it. Protocolized insonation of all anterior and posterior circulation vessels is required.");

// Chapter 17 — The Extended Focused Assessment With Sonography in Trauma (E-FAST)
B(17,'abd',2,"A 30-year-old man with blunt abdominal trauma undergoes FAST. In the right upper quadrant view, which specific area has been shown to be the most sensitive location for detecting free fluid?",["Caudal tip of the liver","Hepatorenal recess (Morison's pouch)","Subdiaphragmatic space above the liver","Space posterior to the right kidney"],0,"In the Lobo series, the caudal tip of the liver was positive in 93.8% of positive RUQ scans versus 84.4% for the hepatorenal recess and 15.6% subdiaphragmatic. Contrary to popular belief, Morison's pouch is not the most sensitive spot, so all 3 RUQ areas must be imaged.");
B(17,"abd",2,"A hypotensive patient after a motorcycle crash has a negative initial FAST and is too unstable for CT. No other bleeding source is found. What is the most appropriate next step according to the chapter?",["Accept the negative FAST and attribute shock to a non-abdominal cause","Repeat FAST; DPL or laparotomy if two are negative and doubt persists","Proceed directly to CT once a single unit of blood has been given","Get a chest radiograph to exclude hemothorax before any repeat scan"],1,"FAST has poor sensitivity (pooled 68%), so hypotensive patients with a negative FAST should be rescanned; a second FAST raised sensitivity from 31.1% to 72.1% in one study. After 2 negative FASTs with ongoing concern, DPL or exploratory laparotomy is indicated because both are more sensitive for bleeding.");
B(17,'abd',1,"According to the most recent Cochrane review cited, what were the pooled sensitivity and specificity of FAST for abdominal injury?",["Sensitivity 95%, specificity 68%","Sensitivity 81%, specificity 98%","Sensitivity 68%, specificity 95%","Sensitivity 78.6%, specificity 100%"],2,"Pooled FAST sensitivity was 68% and specificity 95%: a positive scan reliably indicates significant injury, but a negative scan cannot exclude it. 81%/98% are the lung US figures for pneumothorax (Staub meta-analysis), and 78.6%/100% come from Rozycki's 1995 study.");
B(17,'abd',2,"When counseling trainees about the volume of intraperitoneal blood needed for a positive FAST, which statement best reflects the data presented?",["Most operators reliably detect volumes as small as 50 mL in the RUQ","Trendelenburg positioning increases the volume needed for RUQ detection","The pelvic view requires more fluid than the RUQ view for detection","Fewer than 10% of operators detect volumes below 400 mL"],3,"Branney found that fewer than 10% of sonographers detected less than 400 mL (average RUQ threshold about 619 mL). Trendelenburg lowered the RUQ threshold (443 vs 668 mL supine), and the pelvic view detected about 157 mL, less than the RUQ.");
B(17,'lung',1,"Compared with a chest radiograph, approximately how much pleural fluid can thoracic ultrasound detect in trauma?",["As little as 20 mL, versus a minimum of about 175 mL on radiograph","As little as 100 mL, versus a minimum of about 400 mL on radiograph","As little as 175 mL, versus a minimum of about 500 mL on radiograph","As little as 5 mL, versus a minimum of about 50 mL on radiograph"],0,"US detects as little as 20 mL of pleural fluid compared with ~175–200 mL on an upright chest radiograph (more on a supine film), and consistently outperforms radiography for both hemothorax and pneumothorax in trauma.");
B(17,'lung',2,"During the RUQ view of an E-FAST, the probe is slid 1 to 2 rib spaces cranially. The thoracic spine is now visible as a continuation of the abdominal spine above the diaphragm. What does this finding indicate?",["Normal aerated lung with mirror image artifact","Pleural fluid, consistent with hemothorax","Pneumothorax with loss of lung sliding","Diaphragmatic rupture with liver herniation"],1,"Aerated lung normally blocks the beam above the diaphragm, so the spine is not seen. When fluid (hemothorax) is present the beam transmits to the thoracic spine, producing the spine sign.");
B(17,'lung',2,"In a ventilated trauma patient, the anterior chest view shows absent lung sliding at one interspace, but several B lines arising from the pleural line are clearly visible. What is the correct interpretation?",["Pneumothorax is confirmed at that location","Lung point is present and pneumothorax is likely","Pneumothorax is ruled out at that location","The finding is nondiagnostic and requires CT"],2,"B lines arise from the visceral pleura and interlobular septa; air between the pleural layers prevents them from forming. Any B line therefore rules out pneumothorax at that spot even if sliding is absent.");
B(17,'lung',2,"A blunt trauma patient is intubated in the field. E-FAST shows absent lung sliding over the entire left hemithorax, no B lines, and normal sliding on the right. Breath sounds are absent on the left. Which non-pneumothorax cause of this finding must be considered before placing a chest tube?",["Small left hemothorax","Rib fractures with chest wall hematoma","Low positive end-expiratory pressure","Right mainstem intubation"],3,"Loss of lung sliding is not diagnostic of pneumothorax; mainstem intubation, high PEEP, adhesions, bullous emphysema, massive atelectasis, pulmonary fibrosis, an existing chest tube, HFOV and severe ARDS inflammation can all abolish sliding.");
B(17,"peri",3,"A man with a stab wound to the left chest is hypotensive. E-FAST shows a large left hemothorax and a subxiphoid view with no pericardial fluid. What is the most important pitfall to recognize?",["A pericardial tear may decompress into the pleura; test further","The negative cardiac view excludes cardiac injury (sensitivity >90%)","Pericardial fat is likely being mistaken for a normal pericardial space","Tamponade cannot occur in penetrating trauma with a hemothorax present"],0,"The most common cardiac US pitfall is accepting a negative pericardial view in the setting of a left hemothorax: a pericardial laceration may allow blood to drain into the pleural space. Additional testing is needed despite the generally high (90%-100%) sensitivity of cardiac US for penetrating injury.");
B(17,'lung',2,"For a supine trauma patient, which probe position is most likely to detect a small anterior pneumothorax?",["Midaxillary line at the sixth to eighth intercostal spaces","Parasternal position at the third to fifth intercostal spaces","Midclavicular line at the first to second intercostal spaces","Posterior axillary line at the costophrenic angle"],1,"CT mapping showed the parasternal position (medial to the midclavicular line) is the best place to screen, and the third to fifth interspaces are more likely to contain air than the first and second, since the highest point in the supine chest is around the fifth or sixth rib. Scanning all 3 interspaces raised sensitivity to 88%.");
B(17,'abd',1,"When performing the LUQ (splenorenal) view of the FAST, where does free fluid most commonly collect?",["Splenorenal recess","Around the inferior pole of the kidney","Between the diaphragm and spleen","Anterior to the stomach"],2,"In the LUQ the subdiaphragmatic space between the diaphragm and spleen is the most common site of fluid (64.7% of positive LUQ scans). The view is harder to obtain because the spleen is posterior; start at the posterior axillary line and angle obliquely to avoid rib shadows.");
B(17,'shock',2,"A trauma patient in arrest is being considered for an emergency department resuscitative thoracotomy. Subxiphoid ultrasound shows no cardiac motion. Based on the data presented, what is the expected outcome?",["About 50% survival if thoracotomy is performed within 10 minutes","Survival similar to patients with cardiac motion if tamponade is drained","Outcome cannot be predicted by ultrasound in penetrating trauma","100% mortality, so thoracotomy is likely futile"],3,"Inaba showed 100% mortality after resuscitative thoracotomy in patients without cardiac motion on US; had US been used first, almost 60% of ED thoracotomies could have been avoided.");

// Chapter 18 — Acute Coronary Syndrome
B(18,"lv",3,"After an anterior STEMI, 16 LV segments are adequately visualized: 8 are normal, 4 hypokinetic and 4 akinetic. What is the Wall Motion Score Index and its significance?",["1.75; above ~1.7, suggesting a large infarct and higher risk","2.00; exactly at the threshold that identifies higher complication risk","1.50; consistent with mild dysfunction and a low complication risk","2.25; indicating severe dysfunction, cardiogenic shock and high risk"],0,"WMSI = sum of segment scores divided by the number of segments visualized: (8×1 + 4×2 + 4×3)/16 = 28/16 = 1.75. Normal is 1.0; WMSI ≥1.7 suggests a perfusion defect >20% and worse prognosis.");
B(18,'lv',2,"A patient with chest pain has hypokinesis of the basal inferoseptal, mid inferior and apical inferior segments with normal anterior and lateral walls. Which coronary artery is most likely involved?",["Left anterior descending artery","Right coronary artery","Left circumflex artery","Left main coronary artery"],1,"In the 17-segment model, the RCA supplies segments 3, 4, 9, 10 and 15 (basal/mid inferoseptal, basal/mid inferior, apical inferior). The LAD supplies 1, 2, 7, 8, 13, 14, 17 and the LCx supplies 5, 6, 11, 12, 16.");
B(18,"valve",2,"Four days after a small inferior MI, a patient develops sudden pulmonary edema and hypotension. TTE shows a flail mitral leaflet with a freely mobile mass moving between the LV and left atrium. Which structure is most likely ruptured and why?",["Anterolateral papillary muscle, as it is supplied only by the LCx artery","Anterior mitral chordae, because of necrosis in the LAD territory","Posteromedial papillary muscle: single PDA blood supply","Basal inferior free wall, because inferior infarcts are always transmural"],2,"Papillary muscle rupture typically occurs 1 to 7 days post-MI, often with relatively small infarcts. The posteromedial muscle depends on the posterior descending artery alone, whereas the anterolateral muscle has dual LAD and LCx supply.");
B(18,'shock',2,"On day 2 after PCI, a patient becomes acutely dyspneic and hypotensive. Echo shows a hypercontractile noninfarcted LV and color Doppler demonstrates a high-velocity jet from LV to RV in the apical septum. What is the diagnosis?",["Papillary muscle rupture with eccentric MR","Dynamic LVOT obstruction","Ventricular free wall rupture","Post-infarction ventricular septal rupture"],3,"Post-MI VSD presents 24 hours to 5 days after MI with shock and a high-velocity left-to-right shunt plus hypercontractile noninfarcted LV. Screen the entire septum base to apex; defects may be simple or complex serpiginous channels. Incidence fell from 3%-5% to 0.2%-1% with early revascularization.");
B(18,'peri',2,"Three days after an anterior STEMI, a patient develops recurrent chest pain, hypotension and bradycardia. Echo shows a pericardial effusion with intrapericardial echogenic material and tamponade physiology, but no defect is seen in the myocardium. What is the most likely diagnosis?",["Subacute LV free wall rupture","Post-infarction pericarditis with small effusion","RV infarction with pericardial reaction","Rupture of a true LV aneurysm into the pleura"],0,"Free wall rupture affects 1%-4.5% of MI patients, half within the first 5 days, usually in the LAD anterior/lateral territory. Echo shows tamponade, hemopericardium and intrapericardial thrombus; the rupture site itself may be only a slit and hard to see. Post-MI pericarditic effusions are usually small and rarely cause tamponade.");
B(18,'shock',3,"After an apical MI with sparing of the base, a patient is hypotensive with a new systolic murmur. Echo shows basal hyperkinesis and systolic anterior motion of the mitral valve. Dobutamine is being started. What is the best response?",["Continue dobutamine because pump failure is the leading cause of shock","Stop dobutamine, as β1 agents worsen dynamic LVOT obstruction and hypotension","Add milrinone to further unload the left ventricle","Urgently consult surgery for papillary muscle rupture"],1,"Apical infarcts with basal sparing cause basal hyperkinesis, SAM and dynamic LVOT obstruction. Inotropes and vasopressors with β1 action exacerbate the obstruction and hypotension.");
B(18,"rv",2,"A patient with inferior STEMI is hypotensive and bradycardic, with clear lung fields and raised JVP. He is also severely hypoxemic despite clear lungs. Echo shows a dilated, hypokinetic RV and the interatrial septum bowing toward the LA. What explains the hypoxemia?",["Pulmonary edema from LV pump failure despite clear X-ray","Acute ischemic mitral regurgitation from papillary dysfunction","Right-to-left shunting across a PFO","Pulmonary embolism complicating the inferior infarct"],2,"RV infarction complicates up to 30% of inferior MIs. Raised right atrial pressure bulges the septum into the LA and can drive right-to-left shunting across a PFO, causing severe hypoxemia. Other findings include reduced TAPSE, severe TR and a dilated, non-collapsing IVC.");
B(18,"mass",2,"After an MI, echo shows an outpouching of the LV wall with a narrow neck containing thrombus. Which feature distinguishes this lesion from a true aneurysm?",["A wide neck composed of thinned necrotic myocardium","Systolic dyskinesia with a diastolic deformity of the wall","Location confined to the apical LAD territory only","Wall of pericardium and clot after contained rupture"],3,"Pseudoaneurysms result from incomplete rupture; the wall is pericardium and hematoma, the neck is narrow and thrombus is common. True aneurysms follow transmural MI, are made of necrotic myocardium and have a wide neck.");
B(18,"lv",1,"Regarding Takotsubo (stress) cardiomyopathy, which statement is correct?",["Angiography is needed to exclude a culprit lesion","It accounts for about 10–15% of all suspected STEMI presentations","Basal ballooning with apical hyperkinesis is the commonest pattern","Wall motion abnormalities follow a single coronary territory"],0,"Takotsubo affects about 1%-3% of suspected STEMI presentations, is caused by catecholamine release, and most commonly shows apical ballooning. Echo alone cannot reliably separate it from ACS; angiography is needed to exclude an acute culprit lesion. Coexisting CAD does not exclude Takotsubo (InterTAK; ~15% have CAD).");
B(18,"lv",1,"In the ischemic cascade after acute coronary occlusion, which event occurs earliest of the following?",["ST-segment changes on the surface ECG","Systolic regional wall motion abnormality","Onset of chest pain","Irreversible myocardial necrosis on biomarkers"],1,"The cascade runs perfusion abnormality, metabolic change, diastolic dysfunction, systolic dysfunction, ECG changes, angina, then necrosis. RWMAs therefore appear before ECG changes and symptoms, which is why echo can help in early diagnosis.");
B(18,"rv",2,"A patient with chest pain, elevated troponin and BNP undergoes bedside echo. Which pattern favors pulmonary embolism over ACS?",["Inferior hypokinesis with a dilated RV and reduced TAPSE","Anterior akinesis with an apical LV thrombus","Dilated RV, spared RV apex, hyperdynamic LV","Global LV hypokinesis with a small pericardial effusion"],2,"PE produces RV dilatation and dysfunction with preserved motion of the RV free wall apex, a dilated IVC without respiratory variation, and normal or hyperdynamic LV. RVSP is only mildly elevated (under 60 mm Hg) even in massive PE.");
B(18,'lv',1,"On Wall Motion Score Index grading, a segment that moves outward in systole and is thinned receives which score?",["2 (hypokinesis)","3 (akinesis)","1 (normal)","4 (dyskinesis)"],3,"ASE 2015 uses a 4-point scale: 1 normal/hyperkinetic, 2 hypokinetic, 3 akinetic, 4 dyskinetic (including aneurysm). Older schemes scored aneurysm as 5.");

// Chapter 19 — Assessment of Valvular Heart Disease in Critical Illness
B(19,"dop",2,"While screening a native mitral valve with color flow Doppler, the color scale is set at 15 cm/s and a mosaic turbulent pattern is seen across leaflets that open normally. What is the most appropriate interpretation?",["Significant MS is likely; measure the pressure half-time next","The aliasing confirms a high-velocity regurgitant orifice","Nyquist too low; reset to 50–70 cm/s before judging","Color gain is too low, causing loss of the laminar signal"],2,"Valve color assessment requires a Nyquist limit of at least 50 cm/s (50-70 cm/s); a low scale produces false turbulence/acceleration and overestimates regurgitation. Normal leaflet excursion with laminar flow through the valve excludes obstruction.");
B(19,'valve',2,"In grading mitral regurgitation with pulsed-wave Doppler of the pulmonary veins, which finding is specific for severe MR?",["Systolic flow reversal in more than one pulmonary vein","Systolic blunting of pulmonary vein flow","Systolic reversal in a single vein toward which an eccentric jet is directed","Diastolic-predominant pulmonary vein flow in a patient with LA enlargement"],0,"Reversal in more than one pulmonary vein is specific for severe MR. Systolic blunting corresponds to moderate MR and also occurs with reduced LV/LA compliance; single-vein reversal can occur with less than severe MR when the jet is aimed at that vein.");
B(19,'valve',1,"Continuous-wave Doppler through a calcified aortic valve shows a peak velocity of 4.5 m/s. What is the peak transvalvular gradient by the simplified Bernoulli equation?",["18 mm Hg","45 mm Hg","64 mm Hg","81 mm Hg"],3,"ΔP = 4V² = 4 × 4.5² = 81 mm Hg. A peak velocity ≥4.0 m/s is in the severe AS range; accurate velocity requires coaxial beam alignment, otherwise the gradient is underestimated.");
B(19,'valve',3,"A hypotensive ICU patient has calcific aortic stenosis. LVOT diameter is 2.0 cm, LVOT TVI (PWD) is 20 cm, and aortic valve TVI (CWD) is 80 cm. What is the aortic valve area by the continuity equation?",["0.5 cm²","0.8 cm²","1.2 cm²","1.6 cm²"],1,"CSA LVOT = 0.785 × 2.0² = 3.14 cm²; AVA = (3.14 × 20)/80 ≈ 0.8 cm², which is severe (<1.0 cm²). The LVOT TVI sample volume must be placed at the level where the diameter was measured.");
B(19,'valve',2,"For calculation of aortic valve area by the continuity equation, how should the LVOT diameter be measured?",["In mid-systole, inner edge to inner edge, within 2-5 mm of the aortic cusp hinge points","In end-diastole, leading edge to leading edge, exactly at the aortic annulus","In mid-systole at the sinotubular junction","In early diastole, 1 cm below the annulus at the mitral-aortic continuity"],0,"The LVOT is measured in the parasternal long-axis (or ME long-axis on TEE) in mid-systole, inner edge to inner edge, within 2-5 mm of the hinge points. Because CSA = 0.785 × D², any diameter error is squared.");
B(19,"valve",3,"A septic patient with a hyperdynamic LV has a calcified aortic valve with peak velocity 4.2 m/s and mean gradient 42 mm Hg. LVOT TVI is 30 cm and aortic valve TVI is 100 cm. What is the best interpretation?",["Severe AS is confirmed by a peak velocity of 4 m/s or more","Severe AS is confirmed by the dimensionless index of 0.30","DI 0.30 argues against severe AS; high flow inflates gradient","The DI cannot be used because the LVOT diameter was not measured"],2,"DI = LVOT TVI/AV TVI = 30/100 = 0.30; severe AS is suggested by DI ≤0.25. The DI incorporates LVOT flow, making it useful in high-flow states such as sepsis, and it does not require the LVOT diameter.");
B(19,"valve",2,"A tachycardic, hypovolemic patient on inotropes after mitral valve repair becomes hypotensive. TEE shows the anterior mitral leaflet contacting the septum in systole, a posteriorly directed MR jet, and a high-velocity late-peaking dagger-shaped LVOT CWD profile. What is the diagnosis?",["Severe calcific aortic stenosis with a fixed orifice","Fixed obstruction from a discrete subaortic membrane","Acute papillary muscle rupture with a flail leaflet","Dynamic LVOT obstruction from mitral SAM"],3,"A late-peaking dagger-shaped CWD profile with SAM-septal contact and posterior MR is typical of dynamic LVOT obstruction, promoted by tachycardia and an underfilled hyperdynamic LV. Aortic stenosis gives a more parabolic profile; a subaortic membrane is a fixed obstruction.");
B(19,"valve",3,"A patient in cardiogenic shock (LVEF 20%) has a heavily calcified aortic valve with restricted opening. Peak velocity is 3.2 m/s, mean gradient 24 mm Hg, and continuity-equation AVA 0.8 cm². How should this be interpreted?",["Moderate AS, because the mean gradient is below 40 mm Hg","Low flow lowers the gradient; severe AS remains possible","The continuity equation is invalid in low flow and should be ignored","Mild AS, because velocity and gradient are below severe thresholds"],1,"Jet velocity and mean gradient are flow-dependent and underestimate severity in low-flow states. The continuity-derived area is relatively flow independent, and the DI is helpful when low or high flow distorts gradients.");
B(19,'valve',3,"A patient with rheumatic mitral stenosis has a mitral inflow pressure half-time of 275 ms. What is the estimated mitral valve area?",["0.6 cm²","0.8 cm²","1.2 cm²","1.5 cm²"],1,"MVA = 220/PHT = 220/275 = 0.8 cm², which is severe by ASE criteria (<1.0 cm²). The PHT slope should follow the mid-portion of the early (E) wave.");
B(19,'valve',2,"An elderly dialysis patient has heavy mitral annular calcification extending into the leaflets with a mean transmitral gradient of 11 mm Hg. Which method of valve area estimation is not valid in this type of stenosis?",["Continuity equation using LVOT stroke volume","Mean transmitral gradient","PISA flow convergence method","Pressure half-time (MVA = 220/PHT)"],3,"PHT correlates with valve area in rheumatic MS but is not validated in degenerative calcific stenosis and is affected by LA and LV pressures (eg, diastolic dysfunction). Calcific MS begins in the annulus and extends into the leaflets.");
B(19,'valve',2,"A patient with rheumatic mitral stenosis develops atrial fibrillation with a ventricular rate of 130/min and a mean transmitral gradient of 14 mm Hg. Which statement is correct?",["The gradient should be averaged over 5 beats, and tachycardia/high flow may overestimate severity","Atrioventricular valve gradients are heart rate independent, so severe MS is confirmed","Only the single beat with the longest RR interval should be measured","The peak rather than the mean gradient should be used to grade severity"],0,"Transmitral gradient depends on flow and heart rate, so severity may be overestimated in tachycardic, high-flow patients. In AF or irregular rhythms, average over 5 beats.");
B(19,'valve',2,"A patient with carcinoid heart disease has thickened, restricted tricuspid leaflets, a dilated IVC, and an enlarged right atrium. Which Doppler finding is specific for severe tricuspid stenosis?",["Mean gradient ≥3 mm Hg","Inflow TVI >40 cm","Mean gradient ≥5 mm Hg","Valve area by continuity ≤1.5 cm²"],2,"Severe TS: mean gradient ≥5 mm Hg, inflow TVI >60 cm, T1/2 ≥190 ms, area by continuity ≤1 cm². Concomitant TR increases the transvalvular gradient.");
B(19,'valve',2,"A patient has an estimated RV systolic pressure of 90 mm Hg from the TR jet. Continuous-wave interrogation of the RVOT and pulmonary valve shows a peak velocity of 4.3 m/s. What is the best interpretation?",["Mild pulmonary stenosis; the elevated RVSP reflects pulmonary hypertension","Moderate pulmonary stenosis with a peak gradient of 36-64 mm Hg","Normal pulmonic flow; velocities up to 4.5 m/s are physiologic","Severe pulmonary stenosis; RVSP does not equal pulmonary artery systolic pressure"],3,"PS is severe with peak velocity >4 m/s or peak gradient >64 mm Hg (4 × 4.3² ≈ 74 mm Hg). When RVSP is elevated, pulmonary flow velocity should be interrogated to exclude PS before attributing it to pulmonary hypertension.");
B(19,"valve",2,"TEE in a patient with acute pulmonary edema shows a flail mitral leaflet with an eccentric, wall-hugging MR jet occupying only about 20% of the left atrium. What is the best approach to grading?",["Use vena contracta and PISA; Coanda shrinks eccentric jets","Grade as mild because the jet fills less than half of the left atrium","Lower the Nyquist limit to about 20 cm/s to reveal the full jet","Increase color gain until the regurgitant jet fills the atrium"],0,"Wall-hugging (Coanda) jets appear smaller than central jets of the same regurgitant volume, so jet area underestimates severity. A flail leaflet is itself a specific sign of severe MR; flow convergence and vena contracta are more reliable in eccentric jets.");
B(19,'valve',3,"PISA assessment of MR: aliasing velocity shifted to 40 cm/s, PISA radius 1.0 cm, peak MR velocity 500 cm/s, MR TVI 150 cm. What are the EROA, regurgitant volume, and severity?",["0.25 cm², 38 mL, moderate","0.32 cm², 48 mL, moderate","0.50 cm², 75 mL, severe","0.80 cm², 120 mL, severe"],2,"Flow = 2πr² × Va = 2π × 1² × 40 ≈ 251 mL/s; EROA = 251/500 ≈ 0.50 cm²; RVol = 0.50 × 150 = 75 mL. Severe MR: EROA >0.4 cm² and RVol >60 mL.");
B(19,'valve',2,"In which situation is a short aortic regurgitation pressure half-time most likely to overestimate AR severity?",["Chronic AR with a dilated, compensated LV","Septic shock with low systemic vascular resistance","Hypertension with high aortic diastolic pressure","Bradycardia with prolonged diastole"],1,"AR PHT <200 ms suggests severe AR, but PHT shortens with high LV filling pressure or low SVR independent of valve severity. Conversely PHT may underestimate chronic severe AR with a compensated ventricle.");
B(19,'valve',1,"Which pulsed-wave Doppler finding is most specific for severe aortic regurgitation?",["Holodiastolic flow reversal in the abdominal aorta","Brief early-diastolic flow reversal in the descending thoracic aorta","A faint, incomplete CWD regurgitant signal","An AR pressure half-time of 550 ms"],0,"Holodiastolic reversal in the abdominal aorta is more specific for severe AR than reversal in the descending thoracic aorta. Brief early-diastolic reversal is normal, and reversals occur in elderly patients with stiff aortas.");
B(19,'valve',3,"Stroke volume method for AR: LVOT diameter 2.2 cm, LVOT TVI 30 cm, mitral annular diameter 3.0 cm, mitral annular TVI 7 cm. No significant MR is present. What are the AR regurgitant volume, regurgitant fraction, and severity?",["About 25 mL, RF 22%, mild","About 50 mL, RF 44%, moderate","About 65 mL, RF 36%, moderate","About 65 mL, RF 57%, severe"],3,"SV LVOT = 0.785 × 2.2² × 30 ≈ 114 mL; SV mitral = π(1.5)² × 7 ≈ 50 mL; RVol ≈ 65 mL; RF ≈ 57%. Severe AR: RVol >60 mL, RF >50%. The method is invalid with concomitant MR and AR.");
B(19,"valve",2,"A patient with sudden pulmonary edema after an inferior MI has a flail P2 segment of the posterior mitral leaflet on TEE. In which direction is the MR jet expected to be directed?",["Posteriorly, along the posterior LA wall","Anteriorly, away from the flail leaflet","Centrally into the mid left atrium","Toward the side of the tethered leaflet"],1,"With prolapse or flail, the jet is directed away from the involved leaflet, so a flail posterior leaflet produces an anteriorly directed jet. In ischemic or rheumatic MR the jet moves toward the tethered leaflet.");
B(19,'valve',2,"A patient with a flail tricuspid leaflet has severe TR, a dilated IVC, a tricuspid annulus of 42 mm, and interventricular septal flattening present only in diastole. What do these findings indicate?",["RV pressure overload with a D-shaped LV throughout the cardiac cycle","A normal finding in mechanically ventilated patients","RV volume overload from severe TR with severe annular dilatation","Constrictive physiology with ventricular interdependence"],2,"Severe TR causes RV volume overload with septal flattening in diastole; pressure overload flattens the septum throughout the cycle. Severe tricuspid annular dilatation is a diameter ≥40 mm; severe TR also gives hepatic vein systolic flow reversal.");

// Chapter 20 — Infective Endocarditis
B(20,'valve',2,"A 65-year-old man on hemodialysis via a tunneled catheter, with a bioprosthetic aortic valve, has persistent Staphylococcus aureus bacteremia and septic shock. TTE shows no vegetation. What is the next imaging step?",["Endocarditis is excluded; treat as catheter-related bacteremia","Perform TEE","Repeat TTE after 2 weeks of antibiotics","No imaging is needed until 5 minor Duke criteria are met"],1,"TTE sensitivity for prosthetic valve or device IE is only 40-70%, and a negative TTE does not exclude IE with high suspicion or S aureus bacteremia. TEE is recommended for prosthetic valves, intracardiac devices, and S aureus bacteremia, and detects complications such as abscess.");
B(20,'valve',2,"A febrile (38.9°C) patient who injects drugs has Janeway lesions and a mobile vegetation on the tricuspid valve on TEE. Blood cultures are pending. How is this classified by modified Duke criteria?",["Rejected, because blood cultures are not yet positive","Possible IE (one major and one minor criterion)","Possible IE pending a second major criterion","Definite IE (one major and three minor criteria)"],3,"Vegetation on echo is a major criterion; fever >38°C, predisposition (IV drug use), and vascular phenomena (Janeway lesions) are three minor criteria. One major plus three minor = definite IE.");
B(20,'valve',1,"Which statement about echocardiographic sensitivity in infective endocarditis is correct?",["TTE sensitivity for prosthetic valve or device-related IE is only about 40-70%","TTE specificity for native valve IE is about 50%","TEE is more sensitive for prosthetic than for native valve IE","A negative high-quality TTE excludes IE even with S aureus bacteremia"],0,"TTE: sensitivity 50-90% and specificity 90% for native valve IE, but only 40-70% for prosthetic/device IE. TEE sensitivity is 90-100% for native valves and about 86% for prosthetic valves; TEE detects small 2-5 mm lesions.");
B(20,'valve',1,"An initial TEE in a patient with high clinical suspicion for endocarditis is negative. When should repeat TEE be performed if suspicion persists?",["Within 24 hours","After completing 6 weeks of antibiotics","3 to 7 days after the initial study","Repeat TEE is not needed because TEE is 100% sensitive"],2,"TEE is not 100% sensitive; repeat imaging 3-7 days later is indicated when suspicion remains high. In confirmed IE with clinical deterioration, TEE should be repeated immediately to look for complications.");
B(20,"valve",2,"TEE in a patient with Viridans streptococcal bacteremia shows a 12-mm mobile vegetation on the anterior mitral leaflet with mild MR and preserved hemodynamics. What is the significance of this finding?",["Vegetations only predict embolism once they exceed 20 mm in length","Surgery is indicated only after a documented embolic event occurs","Mobile ≥10 mm vegetation = high embolic risk; consider early surgery","Size should be reassessed after 6 weeks of antibiotics before surgery"],2,"Embolic risk rises with vegetations >10 mm, multivalve involvement, abscess, and anterior mitral leaflet location; >15 mm is an independent risk factor for death. ESC 2023: a vegetation ≥10 mm with an embolic event (or with another indication such as HF or uncontrolled infection) is an indication for early surgery; without these, early surgery may be considered (IIb).");
B(20,'mass',2,"An afebrile patient with a cryptogenic stroke has a mobile, homogeneous mass with frond-like edges attached by a stalk to the aortic side of the aortic valve. Valve function is normal and blood cultures are negative. What is the most likely diagnosis?",["Papillary fibroelastoma","Infective vegetation","Lambl's excrescence","Left atrial myxoma"],0,"Papillary fibroelastomas are frond-like stalked masses, typically <20 mm, 80% on valves, on the downstream side (aortic side of AV, ventricular side of MV). Vegetations sit on the upstream side and usually damage the valve; Lambl's excrescences are thin filiform strands 3-10 mm long.");
B(20,"mass",2,"A woman with systemic lupus erythematosus and antiphospholipid syndrome has layered, rounded verrucous lesions and thickening at the mitral leaflet tips without regurgitation. Blood cultures are negative. What is the most likely diagnosis?",["Marantic endocarditis of malignancy","Lambl's excrescences on the leaflets","Infective (culture-negative) vegetation","Libman-Sacks endocarditis"],3,"Nonbacterial thrombotic endocarditis produces verrucous lesions with echodensity similar to vegetations, often at the leaflet tips, usually without valve damage. In SLE/antiphospholipid syndrome it is Libman-Sacks; marantic endocarditis is associated with malignancy.");
B(20,"valve",2,"A patient with aortic valve endocarditis and significant aortic regurgitation is being evaluated. Where are vegetations most typically located on the aortic valve?",["On the aortic (downstream) surface of the cusps","On the ventricular surface, in the AR jet path","At the sinotubular junction above the valve","On the aortic wall of the non-coronary sinus"],1,"Vegetations form on the upstream side of regurgitant valves (atrial side of AV valves, ventricular side of semilunar valves), low-pressure zones adjacent to high-velocity jets. Papillary fibroelastomas, by contrast, are on the downstream side.");
B(20,"valve",2,"A patient with a bicuspid aortic valve and Viridans streptococcal endocarditis develops new heart block. TTE showed only a thickened valve. TEE shows heterogeneous thickening of the aortic annulus and mitral-aortic intervalvular fibrosa. What is the interpretation?",["Periannular abscess: a major Duke criterion; early surgery","Post-inflammatory thickening that needs antibiotics alone","A Lambl's excrescence at the line of cusp coaptation","Pannus formation around the annulus from an old injury"],0,"Native valve abscess favors the aortic valve and the intervalvular fibrosa; bicuspid and prosthetic valve IE carry higher abscess risk. TTE sensitivity for abscess can be as low as 29%, so TEE is indicated with risk factors such as new heart block.");
B(20,"valve",2,"TEE in prosthetic aortic valve endocarditis shows an echolucent cavity in the mitral-aortic intervalvular fibrosa that expands in systole, with color Doppler flow into and out of the cavity. What is this finding?",["An abscess cavity without any communication to the lumen","A loculated posterior pericardial effusion near the annulus","A pseudoaneurysm communicating with the lumen","A dilated coronary sinus from a persistent left SVC"],2,"Pseudoaneurysms are echolucent perivalvular chambers with systolic expansion and color flow communication with the lumen; the most common site is the intervalvular fibrosa in prosthetic aortic valve IE. They can progress to fistulae into any cardiac chamber.");
B(20,'valve',2,"A patient with a mechanical mitral valve and bacteremia has visible rocking of the prosthesis and severe periprosthetic regurgitation on TEE. Which statement is correct?",["Leaflet destruction is more typical of mechanical than bioprosthetic valve infection","Periprosthetic regurgitation is expected after valve surgery and is not a Duke criterion","Pannus is the most likely explanation because it is highly mobile","The findings indicate sewing-ring dehiscence, and new partial dehiscence is a major Duke criterion"],3,"Mechanical valve IE involves the sewing ring-myocardium junction, causing abscess, pseudoaneurysm, and dehiscence with periprosthetic regurgitation and rocking in advanced cases. Bioprostheses more often show leaflet destruction; pannus is relatively immobile.");
B(20,"valve",2,"A patient with a dual-chamber pacemaker has coagulase-negative staphylococcal bacteremia. TTE shows no valvular vegetation. Which approach is correct?",["TTE adequately excludes lead infection if visible leads look clean","TEE of leads in RA, RV, SVC; negative TEE doesn't exclude","An oscillating lead mass reliably distinguishes vegetation from thrombus","A mobile echodensity at the IVC-RA junction is a lead vegetation"],1,"TEE should be performed in all suspected CIED infections because TTE is limited by windows and reverberation. Lead thrombus and vegetation look nearly identical, so clinical context guides diagnosis; the Eustachian valve is a common mimic, and repeat TEE or adjunct imaging is advised if TEE is negative.");

// Chapter 21 — Acute Respiratory Distress Syndrome: Role and Interest of Critical Care Echocardiography
B(21,'rv',2,"A ventilated ARDS patient becomes hypotensive. TEE shows an enlarged RV and rising CVP with hepatic congestion. Which echocardiographic criterion defines 'significant' RV dilatation consistent with RV failure in this setting?",["End-diastolic RV:LV area ratio >0.6 with systemic congestion","End-systolic RV:LV area ratio >1.0 without congestion","TAPSE <16 mm with any degree of RV enlargement","RV basal diameter greater than the LV basal diameter in systole"],0,"Experts define RV failure in ARDS as significant RV dilatation (end-diastolic RV:LV area >0.6) leading to systemic congestion. TAPSE <16 mm was used to label RV dysfunction in a pre-ECMO cohort but is not the dilatation criterion.");
B(21,'shock',1,"In patients with ARDS who develop shock, which mechanism accounts for the largest share of cases?",["ARDS-related acute cor pulmonale from high pulmonary vascular resistance","Sepsis-related circulatory failure, about half of the cases","Decompensation of preexisting chronic cardiac disease","Dynamic LV outflow tract obstruction from hypovolemia"],1,"Sepsis is the leading cause of shock in ARDS (about half of cases). ARDS-related RV failure (acute cor pulmonale) is the main mechanism in the remaining unstable patients without septic shock; the two often coexist because pneumonia is both the main cause of ARDS and a risk factor for ACP.");
B(21,"fluid",2,"A patient with pneumonia-related ARDS on norepinephrine has a pulse pressure variation of 16%. TEE shows a dilated RV with cyclic enlargement during inspiration, a dilated IVC, high CVP and no respiratory variation of the SVC. What is the most appropriate next step?",["Give a 500 mL crystalloid bolus and reassess the PPV","Perform a passive leg raise to confirm fluid responsiveness first","Optimize norepinephrine and ventilation, control CO2, consider prone","Start dobutamine and increase PEEP to recruit more lung"],2,"Here PPV reflects increased RV afterload from transpulmonary pressure, so it is a false positive for fluid responsiveness. Management is norepinephrine, ventilator adjustment, hypercapnia control and prone positioning with no further fluid, because fluid can aggravate RV failure.");
B(21,'fluid',1,"Regarding respiratory variation of the superior vena cava (ΔSVC) measured by TEE in ventilated patients, which statement is correct?",["It is more sensitive than specific for fluid responsiveness","It cannot be assessed in patients ventilated with tidal volume below 8 mL/kg","It is best measured from a subcostal transthoracic window","It is much more specific than sensitive for fluid responsiveness"],3,"When accurately used, ΔSVC is much more specific than sensitive. It requires TEE (upper esophageal view of the SVC), and in a large study most patients, including ARDS patients, were ventilated with tidal volumes below 8 mL/kg.");
B(21,'rv',2,"In a patient with ARDS and a dilated RV, a short-axis view shows paradoxical septal motion at end-systole with a D-shaped LV. What does the end-systolic septal paradox specifically indicate?",["That the RV failure is driven by diastolic volume overload","That the RV failure is mediated by systolic pressure overload","That the patient has a hemodynamically significant patent foramen ovale","That LV systolic function is severely depressed"],1,"Acute cor pulmonale is RV dilatation plus paradoxical septal motion at end-systole. The end-systolic septal paradox reflects that the RV failure is mediated by systolic (pressure) overload; volume overload causes a diastolic septal shift instead.");
B(21,"rv",2,"Which of the following is one of the four recently reported risk factors promoting RV failure (acute cor pulmonale) in ARDS?",["Driving pressure ≥18 cm H2O","PEEP of 15 cm H2O or higher","PaO2:FIO2 below 250 mm Hg","Tidal volume above 8 mL/kg"],0,"The four risk factors are pneumonia as the cause of ARDS, PaO2:FIO2 <150 mm Hg, driving pressure ≥18 cm H2O and PaCO2 ≥48 mm Hg. VV ECMO can treat three of them (all except pneumonia).");
B(21,'mass',2,"A patient with refractory ARDS has just been placed on VV ECMO, and the team wants to follow cardiac output. Why is echocardiographic measurement (e.g., LVOT VTI by pulsed-wave Doppler) preferred?",["Pulse contour devices are contraindicated with any extracorporeal circuit","LVOT VTI cannot be obtained by transthoracic echo during ECMO","Pulmonary artery catheters cannot be placed with a femoral venous cannula","Most thermodilution-based monitoring devices are not accurate during ECMO"],3,"One CCE role on ECMO is monitoring cardiac output, because most thermodilution-based devices cannot be used accurately during ECMO. Other roles: assessing the RV before and during ECMO, confirming cannula position and evaluating worsening hypoxemia.");
B(21,'mass',2,"A patient with severe refractory ARDS needs extracorporeal support. He requires moderate-dose norepinephrine; echo shows pulmonary hypertension with a dilated RV and a normal LVEF. Which configuration is most appropriate?",["VA ECMO, because pulmonary hypertension contraindicates VV ECMO","VA ECMO, because any vasopressor requirement mandates arterial support","VV ECMO, because it can unload the RV by improving oxygenation and CO2 removal","Extracorporeal CO2 removal alone, because it corrects both oxygenation and hypercapnia"],2,"VV ECMO reduces pulmonary artery pressures and unloads the RV, so pulmonary hypertension and shock are not contraindications. Conversion from VV to VA was only 4.1% in the ELSO registry and 6% in EOLIA. ECCO2R does not correct oxygenation.");
B(21,"mass",2,"In which ARDS patient should VA rather than VV ECMO be considered?",["Severe cardiogenic shock, very low output and LVEF on high-dose support","PH with RV dilation and paradoxical septal motion on low-dose norepinephrine","PaCO2 of 60 mm Hg, driving pressure of 20 cm H2O, preserved LV function","Hyperlactatemia before cannulation with an entirely normal echocardiogram"],0,"VA ECMO should be considered for ARDS with severe cardiogenic shock: very low cardiac output, severely reduced LVEF on CCE and need for significant inotropes and/or norepinephrine. RV failure from pulmonary hypertension is usually relieved by VV ECMO.");
B(21,'lung',2,"In a shocked ARDS patient, which hemodynamic factor tends to make the PaO2:FIO2 ratio underestimate the severity of lung injury?",["Reopening of a patent foramen ovale with right-to-left shunting","A low cardiac index that decreases intrapulmonary shunt","A low mixed venous oxygen pressure","Acute cor pulmonale with a high RV:LV area ratio"],1,"A low cardiac index can decrease lung shunt, which makes the PaO2:FIO2 ratio underestimate severity. Low venous oxygen pressure and a reopened PFO do the opposite and overestimate severity; PFO is associated with a higher RV:LV end-diastolic ratio.");

// Chapter 22 — Severe Pneumonia, Cardiogenic Pulmonary Edema, and Acute Respiratory Distress Syndrome
B(22,'lung',1,"On lung ultrasound, a large area of lung has a tissue-like echotexture resembling the liver. What does this sonographic hepatization most specifically indicate?",["Nontranslobar subsegmental consolidation","Compressive atelectasis behind a pleural effusion","Lobar or translobar alveolar consolidation","Alveolar-interstitial syndrome from septal edema"],2,"Sonographic hepatization is specific for lobar or translobar consolidation, where exudate-filled lung changes acoustic impedance and looks like liver. Less extensive nontranslobar consolidation shows the shred sign, an irregular deep border against aerated lung.");
B(22,'lung',2,"A ventilated patient has a posterior consolidation. Which sonographic finding best favors pneumonia over atelectasis?",["Dynamic air bronchograms","Static air bronchograms alone","An A-line pattern with lung sliding","A small anechoic pleural effusion"],0,"Static and dynamic air bronchograms both indicate consolidation, but dynamic air bronchograms are more specific for pneumonia than for atelectasis (94%). A lung pulse also favors pneumonia when seen together with dynamic air bronchograms.");
B(22,'lung',2,"A hypoxemic patient has bilateral B lines in at least 3 zones. Which additional lung ultrasound feature favors ARDS over cardiogenic pulmonary edema?",["Thin, regular pleural line with preserved lung sliding","Distinct, homogeneously distributed laser-like B lines","Large bilateral pleural effusions","Spared areas of normal lung with subpleural consolidations"],3,"ARDS shows heterogeneous involvement: spared areas, subpleural consolidations, pleural thickening >2 mm, possible loss of sliding and a lung pulse. Homogeneous laser-like B lines, a thin regular pleura and bilateral effusions favor cardiogenic pulmonary edema.");
B(22,'dia',2,"A patient with acute hypoxemic respiratory failure has diffuse bilateral B lines and an LVEF of 60%. Tissue Doppler gives an average E/e' of 16. How should this be interpreted?",["Normal LV filling pressure, favoring ARDS","Elevated LV filling pressure, favoring cardiogenic pulmonary edema","Indeterminate, because E/e' is not valid with a normal LVEF","Elevated RV filling pressure, favoring acute cor pulmonale"],1,"With preserved LVEF, Doppler estimation of LV filling pressure is needed. ASE guidance: average E/e' >14 indicates elevated LVFP (CPE pattern) and E/e' <8 indicates normal LVFP (ARDS pattern ≤8 in the comparison table).");
B(22,'lung',3,"Using the cardiac and thoracic critical care ultrasound score to separate CPE from ARDS (B lines in ≥3 zones +3, left pleural effusion +4, moderate/severe LV dysfunction +3, IVC diameter ≤23 mm −2), calculate the score for a patient with B lines in 4 zones, a left pleural effusion, normal LV function and an IVC of 18 mm.",["Score 7, suggesting cardiogenic pulmonary edema","Score 3, suggesting ARDS","Score 5, which is in the indeterminate range","Score 9, strongly suggesting cardiogenic pulmonary edema"],2,"3 (B lines) + 4 (left effusion) + 0 (normal LV) − 2 (IVC ≤23 mm) = 5. A score ≥6 suggests CPE and ≤3 suggests ARDS, so 5 is between the cut-offs.");
B(22,'lung',2,"In the cardiac and thoracic ultrasound scoring study, a score of 6 or higher had a sensitivity of 0.30 and a specificity of 0.98 for cardiogenic pulmonary edema. What is the best clinical use of a score ≥6?",["Ruling out CPE when the score is below 6","Ruling in CPE when the score is 6 or higher","Diagnosing ARDS when the score is 6 or higher","Screening all patients for CPE because of high sensitivity"],1,"A high specificity (0.98) with low sensitivity (0.30) makes a score ≥6 a rule-in test for CPE; a lower score does not exclude it. A score ≤3 suggests ARDS (reported sensitivity 0.77 and specificity 0.69 at that cutoff).");
B(22,'lung',1,"Which proposed ARDS definition allows lung ultrasound to satisfy the imaging criterion, which is useful in resource-limited settings?",["The Kigali modification of the Berlin definition","The 2012 Berlin definition","The 2017 Montreux definition","The American-European Consensus definition"],0,"The Kigali modification proposes LUS as an alternative imaging modality where CXR or CT is not available. The Berlin definition relies on CXR and/or CT, and the neonatal Montreux definition does not yet include LUS.");
B(22,'lung',2,"A patient with progressive dyspnea has homogeneous bilateral B lines and an irregularly thickened pleural line, but no history consistent with ARDS. Which diagnosis must also be considered for this pattern?",["Bilateral pneumothorax","Lobar pneumonia with hepatization","Cardiogenic pulmonary edema with a thin regular pleura","Diffuse parenchymal lung disease such as fibrosis"],3,"Homogeneous B lines with irregularly thickened pleura are not specific to ARDS; this combination is also seen in diffuse parenchymal lung disease such as fibrosis. CPE typically has a thin, regular pleural line.");
B(22,"lung",2,"Which statement about diagnosing cardiogenic pulmonary edema in acute dyspnea is supported by the evidence?",["B-line predominance in several fields beats CXR, exam and NT-proBNP","A BNP below the laboratory cut-off reliably rules out acute CPE","Chest radiography has both sensitivity and specificity above 90% for CPE","Physical examination is more accurate than lung ultrasound for CPE"],0,"A B-line pattern (>2 B lines in multiple fields) outperforms CXR, clinical examination and NT-proBNP for CPE. BNP, NT-proBNP, CXR and examination have sensitivities and specificities of only about 50% to 60%, and BNP is inconclusive for ruling out CPE.");
B(22,'lung',2,"A patient with acute hypoxemia has interstitial syndrome on lung ultrasound. Which additional finding most supports cardiogenic pulmonary edema from left heart failure over ARDS?",["Subpleural consolidations with a lung pulse","Large bilateral pleural effusions","Absent lung sliding in non-dependent zones","Very small or absent pleural effusions"],1,"Bilateral (or left-sided) pleural effusions are almost always seen in CPE, and with interstitial syndrome they suggest left heart failure. In ARDS, effusions are very small or absent, and subpleural consolidations, lung pulse and loss of sliding are more typical.");

// Chapter 23 — Septic Shock and Its Echocardiographic Mimickers
B(23,"fluid",1,"How is the mini-fluid challenge performed, and what change predicts fluid responsiveness?",["250 mL over 5 minutes; cardiac output increase ≥15%","50 mL crystalloid over 10 s; VTI change of about 9%","100 mL colloid over 1 minute; VTI change of ≥18%","500 mL over 15 minutes; stroke volume change ≥10%"],1,"The mini-fluid challenge is 50 mL of crystalloid over 10 seconds, and a VTI variation of 9% predicts responsiveness. Like passive leg raising, it can be used with or without spontaneous respiratory effort.");
B(23,'fluid',3,"A septic patient is passively ventilated with no spontaneous effort. Subcostal M-mode of the IVC shows a maximal inspiratory diameter of 2.2 cm and a minimal expiratory diameter of 1.8 cm. Using the distensibility index referenced to the minimal diameter (threshold ≥18%), what is the result?",["11%, not fluid responsive","18%, at the threshold","20%, fluid responsive","22%, fluid responsive"],3,"Distensibility = (Dmax insp − Dmin exp)/Dmin exp × 100 = (2.2 − 1.8)/1.8 × 100 ≈ 22%, above the 18% threshold, so the patient is likely fluid responsive. If the mean diameter is used as the denominator, the threshold is ≥12%.");
B(23,'fluid',2,"A spontaneously breathing, non-intubated patient with sepsis has hypotension. Which IVC collapsibility value predicts fluid responsiveness?",[">48%",">18%","≥12%",">9%"],0,"In spontaneously breathing septic patients, IVC collapsibility [(Dmax exp − Dmin insp)/Dmax exp] above 48% predicts fluid responsiveness. The 12% and 18% thresholds apply to distensibility in passively ventilated patients.");
B(23,"fluid",2,"A patient with septic shock complicated by ARDS has persistent hypotension. ΔLVOT peak velocity is 14% and ΔIVC is 13%. What is the appropriate interpretation?",["Fluid responsive; give a bolus because both values exceed 10%","Fluid responsive; give a bolus because both values exceed 12%","Not clearly responsive; use a strict 18% cut-off at high risk","Not interpretable at all; dynamic indices are invalid in ARDS"],2,"In patients at high risk of volume overload, such as septic shock with ARDS, a strict 18% threshold for both ΔLVOT maximum velocity and ΔIVC should be used. Lower thresholds may be accepted only when the risk of lung water overload is low.");
B(23,'fluid',1,"In the 540-patient study of echocardiographic dynamic indices in ventilated patients, which parameters had the best sensitivity and the best specificity for fluid responsiveness?",["IVC distensibility best sensitivity; aortic peak velocity variability best specificity","Passive leg raise best sensitivity; IVC distensibility best specificity","Aortic peak velocity variability best sensitivity; SVC variability best specificity","SVC variability best sensitivity; aortic peak velocity variability best specificity"],2,"Aortic peak velocity variability had the best sensitivity and SVC variability had the best specificity. In that study, 42% of the 540 patients were fluid responsive.");
B(23,'shock',2,"A hypotensive septic patient receives 3 L of crystalloid. Repeat echo shows the LV end-diastolic area has increased to normal, but the end-systolic cavity remains nearly obliterated, and LVOT peak velocity shows minimal respiratory variation. What is the most likely cause of the persistent hypotension?",["Low systemic vascular resistance from vasodilatation","Persistent severe hypovolemia","Septic myocardial depression with low ejection fraction","Tension pneumothorax with obstructive shock"],0,"A persistently small LV end-systolic area despite a normalized end-diastolic area after fluid suggests vasodilatation. Severe hypovolemia is indicated by LVEDA <5.5 cm²/m², and minimal velocity variation argues against ongoing fluid responsiveness.");
B(23,'shock',2,"A hypovolemic, tachycardic elderly patient in septic shock has LV hypertrophy and systolic anterior motion of the mitral valve. Which Doppler finding defines severe LVOT obstruction?",["LVOT peak velocity above 1.5 m/sec on pulsed-wave Doppler","Early-peaking, rounded LVOT envelope","LVOT VTI variation above 12% with respiration","Peak instantaneous LVOT gradient ≥50 mm Hg on CW Doppler"],3,"Obstruction is defined by a peak instantaneous CW gradient ≥30 mm Hg (≈2.7 m/s); ≥50 mm Hg is hemodynamically significant. The profile is late-peaking and dagger-shaped. Dynamic LVOTO occurs in ~22% of septic shock patients and is associated with higher mortality.");
B(23,"shock",2,"A 78-year-old in septic shock is started on dobutamine for 'low output.' He becomes more hypotensive and tachycardic, and echo shows SAM with a late-peaking dagger-shaped LVOT Doppler profile. What is the best management?",["Increase dobutamine further to augment the stroke volume","Stop dobutamine, give fluid, slow the rate, use a pure vasopressor","Start milrinone to reduce afterload and improve forward flow quickly","Restrict fluids and start a diuretic to reduce LV filling"],1,"Dynamic LVOT obstruction is treated by increasing preload, avoiding tachycardia to lengthen diastolic filling and raising blood pressure without increasing contractility. Inotropes, especially those that increase heart rate and lower afterload, worsen the obstruction.");
B(23,"valve",2,"A patient with dynamic LVOT obstruction and SAM also has mitral regurgitation. What jet direction is typical, and why?",["Posterior, from an interleaflet gap as the anterior leaflet moves","Anteriorly directed, from prolapse of the posterior mitral leaflet","Central, from annular dilatation in a dilated, failing LV","Anteriorly directed, from chordal restriction of the anterior leaflet"],0,"In SAM, the anterior leaflet moves toward the LVOT more than the posterior leaflet can follow. This creates an interleaflet coaptation gap and a posteriorly directed MR jet.");
B(23,'lung',2,"Shortly after a difficult intubation, a patient with COPD develops profound hypotension. Lung ultrasound shows no lung sliding, no B lines and no lung pulse anteriorly on the right, with a barcode sign on M-mode. The IVC is plethoric and both ventricles look small and hyperdynamic from a subcostal view. What is the next step?",["Fluid bolus for hypovolemic shock","Start norepinephrine for vasodilatory septic shock","Immediate needle decompression","Pericardiocentesis for tamponade"],2,"Absent sliding, B lines and lung pulse with a barcode or stratosphere sign suggest pneumothorax, and a lung point is pathognomonic in anterior fields without blebs. A plethoric IVC with compressed, hyperdynamic ventricles indicates tension physiology and impending arrest, which requires immediate needle decompression.");
B(23,'shock',2,"When approaching shock with hypercontractile LV function, what is the first branch point in the practical algorithm?",["Whether lung sliding is present","Whether there is an LVOT gradient on continuous-wave Doppler","Whether the IVC is plethoric","Whether cardiac output is high or low"],3,"First decide whether cardiac output is high (non-volume-responsive septic shock) or low (hypovolemia, LVOT obstruction or tension pneumothorax). Low-output states receive volume and are reassessed; if output stays low, look for LVOT obstruction and pneumothorax.");
B(23,"views",1,"In septic shock, which situation most clearly favors TEE over TTE?",["First qualitative look at LV function in a spontaneously breathing patient","Intubated, poor windows, suspected endocarditis with root abscess","Measuring IVC collapsibility to guide fluids in a ventilated patient","Detecting a hyperdynamic LV with end-systolic cavity obliteration"],1,"TEE is preferred when transthoracic windows are poor, especially in intubated patients with suspected endocarditis and its complications, such as aortic root abscess. Qualitative TTE is sufficient for initial assessment. Comprehensive echo is indicated for chronic disease, suspected endocarditis, gross valve abnormalities or refractory shock.");

// Chapter 24 — Focused Point of Care Ultrasound in Cardiac Arrest
B(24,'shock',2,"A 64-year-old ICU patient becomes unresponsive with organized complexes on the monitor but no palpable carotid pulse. During the pulse check, a subcostal view shows coordinated ventricular contraction. Which term best describes this state?",["True PEA with cardiac standstill","Pseudo-PEA","Fine ventricular fibrillation","Asystole with artifactual electrical activity"],1,"Pseudo-PEA = no palpable pulse but coordinated myocardial activity on ultrasound. It carries better survival (ROSC, admission, discharge) than true PEA, where no cardiac motion is seen (cardiac standstill).");
B(24,'shock',2,"A meta-analysis evaluated detection of spontaneous cardiac motion on focused echo during cardiac arrest to predict ROSC. Which set of test characteristics was reported?",["Sensitivity 80%, specificity 95%, negative LR 0.20","Sensitivity 60%, specificity 99%, negative LR 0.40","Sensitivity 95%, specificity 80%, negative LR 0.06","Sensitivity 99%, specificity 60%, negative LR 0.02"],2,"Pooled sensitivity 95%, specificity 80%, negative LR 0.06 for predicting ROSC. Conversely, cardiac standstill carries a low likelihood of ROSC and is often used to guide cessation of resuscitation.");
B(24,'peri',2,"During a PEA arrest, a moderate pericardial effusion is seen after a brief ROSC. Which Doppler finding, in the presence of the effusion, supports tamponade physiology?",["Respiratory variation >30% transmitral and >60% transtricuspid","Respiratory variation >10% transmitral and >20% transtricuspid","Respiratory variation >60% transmitral and >30% transtricuspid","Fixed transmitral E/A ratio with no respiratory variation"],0,"Tamponade signs include RA systolic collapse, RV diastolic collapse, a plethoric IVC and respirophasic flow variation >30% across the mitral and >60% across the tricuspid valve. Note the tricuspid threshold is the higher one.");
B(24,'peri',3,"Two days after cardiac surgery a patient arrests with PEA. TTE shows only a small posterior pericardial collection with RV diastolic collapse, and lung ultrasound shows a large left pleural effusion. Which intervention is most likely to reverse the arrest physiology?",["Empiric systemic thrombolysis for presumed PE","Rapid 2 L crystalloid bolus for hypovolemia","Immediate defibrillation for presumed fine VF","Drainage of the large pleural effusion"],3,"Tamponade can occur with a small effusion if it is rapidly expanding, loculated, or combined with a large pleural effusion. Draining the pleural effusion (can be imaged during compressions) may reverse tamponade physiology, hence the need to combine cardiac and lung examination.");
B(24,'rv',2,"In a patient with suspected PE-related arrest, echocardiographic signs of acute RV strain typically become evident only after what degree of pulmonary arterial bed obstruction?",["More than 10%","More than 30%","More than 50%","More than 70%"],1,"Acute RV strain appears after obstruction of >30% of the pulmonary arterial bed and has a PPV for PE of 71% to 86%. Direct visualization of thrombus in the right heart or pulmonary arteries is definitive but rarely seen.");
B(24,'rv',2,"A patient in PEA arrest has a dilated RV with septal deviation on subcostal view. What additional bedside ultrasound finding most improves diagnostic accuracy for PE to nearly 90% sensitivity and specificity?",["A plethoric IVC without respiratory variation","Tricuspid regurgitation with a high peak velocity","DVT in the femoral or popliteal veins","Absence of lung sliding over the anterior chest"],2,"RV strain combined with a venous examination positive for femoral or popliteal DVT raises sensitivity and specificity for PE to nearly 90%. Hence EASY-ALS suggests a selected DVT screen in patients with RV dilation.");
B(24,'shock',2,"A trauma patient arrives in PEA. The FAST is negative, the LV is small and hyperdynamic with systolic cavity obliteration, and the IVC measures 0.8 cm and collapses. What does this pattern most strongly predict?",["Hemorrhagic shock responsive to volume loading","Obstructive shock from tension pneumothorax","Cardiogenic shock from blunt myocardial injury","Distributive shock from neurogenic causes"],0,"In trauma, a small (<1 cm) collapsible IVC, even with a negative FAST, strongly predicts hemorrhagic shock responsive to volume. Severe hypovolemia as the arrest cause should be considered only after other causes are excluded.");
B(24,'lung',2,"During an arrest after a subclavian line attempt, lung ultrasound is used to evaluate tension pneumothorax. Which statement is correct?",["Absent lung sliding alone confirms pneumothorax","B lines are typically present over a pneumothorax","Lung pulse indicates the lung is separated from the wall","Presence of lung sliding effectively rules out pneumothorax"],3,"Lung sliding effectively excludes pneumothorax. Absent sliding is not pathognomonic (eg, main-stem intubation, pleural fibrosis); absent sliding plus absent B lines strongly suggests it, and a lung point confirms it. Ultrasound sensitivity 92.3%, specificity 99.6%.");
B(24,'shock',1,"The monitor shows a near-flat line with low-amplitude undulations of uncertain origin. Which echocardiographic finding indicates shockable fine ventricular fibrillation rather than asystole?",["Complete absence of any cardiac motion","Diffuse, asynchronous myocardial contractile activity","Coordinated contraction with a pericardial effusion","Isolated valve leaflet motion with each ventilation"],1,"Fine VF appears as diffuse, asynchronous contractile myocardial activity, whereas true asystole shows no spontaneous cardiac motion. The distinction changes therapy (defibrillation) and prognosis.");
B(24,'shock',2,"Using the EASY-ALS protocol, the sonographer performs a subcostal 4-chamber view during a pulse check. At the latest, when should the command \"Resume chest compressions\" be given?",["After 4 seconds","After 15 seconds","After 8 seconds","After 12 seconds"],2,"EASY-ALS: probe placed subcostally during compressions, image acquired during the pulse check, and compressions resumed after 8 seconds at the latest; loops are reviewed during CPR. Each pulse check should not exceed 10 seconds. Depth is preset to 20 cm (female) or 24 cm (male).");
B(24,'views',1,"In cardiac arrest, a limited TEE examination is performed. Which set of views is described as of greatest utility?",["Midesophageal 4-chamber, midesophageal long-axis, transgastric short-axis","Upper esophageal aortic arch, midesophageal bicaval, deep transgastric","Midesophageal 2-chamber, midesophageal commissural, descending aorta","Transgastric long-axis, midesophageal RV inflow-outflow, LAA view"],0,"ME 4-chamber, ME long-axis and TG short-axis views identify organized activity vs standstill, LV/RV function, volume status and effusions. The probe can stay in place and real-time feedback can guide compression location to avoid LVOT and aortic obstruction.");
B(24,'rv',3,"A patient with confirmed massive PE has ROSC after a brief arrest but remains in shock that is likely to cause death within hours. Compared with systemic thrombolysis, what is the main advantage of catheter-directed thrombolysis described for this scenario?",["It avoids any need for subsequent ultrasound assessment","It eliminates the risk of intracranial hemorrhage entirely","It requires no anticoagulation after the procedure","It uses a much lower lytic dose with major bleeding about 2.5%"],3,"Systemic thrombolysis carries significant risk of life-threatening hemorrhage (about 20%) and intracranial hemorrhage (3-5%). Catheter-directed therapy uses a significantly reduced dose with about 2.5% major bleeding; ultrasound then documents resolution of RV strain.");

// Chapter 25 — Vascular Access
B(25,'vasc',1,"A systematic review of 35 trials compared ultrasound guidance with landmark technique for internal jugular cannulation. What effect of ultrasound was reported?",["Overall success up 12% and first-attempt success up 57%","Overall success up 57% and first-attempt success up 12%","Overall success unchanged but arterial puncture reduced","First-attempt success up 12% with longer cannulation time"],0,"Ultrasound increased successful placement by 12%, first-attempt success by 57%, shortened cannulation time, and reduced overall complications and inadvertent arterial puncture. Dynamic guidance is therefore recommended for IJV cannulation.");
B(25,'vasc',2,"A junior resident is placing a right IJV catheter using the short-axis (out-of-plane) approach. How should the needle tip be kept in view as it advances?",["Keep the probe fixed and advance until a flash appears","Tilt, fan or slide the beam ahead of the needle tip as it advances","Rotate the probe 90° to long axis once the skin is punctured","Increase gain until the whole shaft appears as a bright line"],1,"In short axis the beam must be kept just in front of the needle tip, tilting/fanning/sliding toward the clavicle in increments while aspirating. A fixed probe risks mistaking the shaft for the tip and advancing too deep.");
B(25,'vasc',2,"During short-axis IJV cannulation the anterior vein wall is tented by the needle. The tenting suddenly resolves, the vein reopens and resistance to aspiration eases. Which ultrasound appearance confirms correct needle position?",["Comet-tail artifact deep to the posterior wall","Complete collapse of the vein around the needle","A target sign with the needle in the center of the lumen","Hyperechoic needle shaft lying above the anterior wall"],2,"Correct position is a target (bull's-eye) sign with the needle seen centrally in the lumen. The guidewire is then passed and confirmed in transverse and longitudinal views before dilation.");
B(25,"vasc",2,"A guidewire has been passed into what appears to be the IJV in a hypotensive patient. What is the recommended step before dilation?",["Rely on dark, non-pulsatile blood return in the syringe","Obtain a chest radiograph to locate the wire before dilating","Measure the vein diameter in short axis only, then dilate","Image the wire in the vein in both planes"],3,"Key point: before dilating a central vessel, confirm the guidewire is within the vein in both transverse and longitudinal planes, proximal to the puncture site. Dilation only after confidence of no arterial cannulation; flash color is unreliable in hypotension.");
B(25,'vasc',2,"An experienced operator uses the oblique view for a right IJV catheter. Starting from the transverse view with the marker to the patient's left, how is the probe manipulated?",["Rotated 45° clockwise toward the sternal notch, needle in plane from the lateral end","Rotated 45° counterclockwise toward the shoulder, needle from the medial end","Rotated 90° to a longitudinal plane, needle entering just caudal to the marker","Kept transverse and angled 45° caudally, needle out of plane from the midline"],0,"Oblique view: rotate 45° so the probe's long axis points to the sternal notch (clockwise on the right, counterclockwise on the left) and insert in plane from the lateral end. It combines short- and long-axis benefits but is not for novices.");
B(25,'vasc',2,"A hemodynamically stable obese patient needs femoral venous access, and the femoral artery overlaps the vein. Which positioning maneuvers are recommended?",["Trendelenburg position and internal rotation of the hip","Reverse Trendelenburg and external rotation of the leg","Hip flexion to 90° and arm abduction","Valsalva maneuver with knee extension"],1,"External rotation of the leg decreases arteriovenous overlap and reverse Trendelenburg augments femoral vein size in stable patients. Trendelenburg engorges the IJV, not the femoral vein; Valsalva can augment femoral vein size but is impractical in sedated patients.");
B(25,"vasc",2,"A patient on therapeutic heparin needs central venous access. Why is the subclavian site of particular concern in this patient?",["The vein collapses with respiration in all patients at this site","Catheter malposition into the internal jugular vein is unavoidable","Arterial puncture here can't be compressed","Pneumothorax risk rises only in anticoagulated patients"],2,"Anticoagulation is a larger concern at the SCV because an inadvertent subclavian arterial puncture cannot be compressed. Femoral access is often preferred when anticoagulation precludes SCV access.");
B(25,'vasc',2,"For ultrasound-guided short-axis (out-of-plane) subclavian vein cannulation, which needle bevel orientation is recommended?",["Bevel-up, as for internal jugular access","Bevel-lateral, toward the shoulder","Bevel-medial, toward the sternum","Bevel-down (caudad)"],3,"For out-of-plane SCV access the needle is introduced bevel-down (caudad) to improve tip visualization and correct guidewire direction, whereas IJV and femoral access use bevel-up. Use very light probe pressure because the SCV collapses easily.");
B(25,'vasc',2,"After ultrasound-guided subclavian cannulation in a hypotensive, mechanically ventilated patient, it is unclear whether the vessel is venous or arterial. What confirmation is recommended?",["Central venous pressure check and blood gas analysis","Observation of blood color and pulsatility at the hub","Repeat compression of the vessel with the probe","Immediate dilation followed by chest radiograph"],0,"Venous vs arterial cannulation can be hard to distinguish in hypotension or mechanical ventilation, so confirm with a CVP check and blood gas analysis plus wire imaging in two planes before dilation and catheter insertion.");
B(25,'vasc',2,"After a right IJV catheter is placed, the distal port is flushed with agitated saline while imaging. Bubbles appear in the internal jugular vein but not in the right atrium on the subcostal view. What does this indicate?",["Correct tip position at the cavoatrial junction","Likely catheter malposition","An intracardiac right-to-left shunt","Normal finding requiring no action"],1,"Correct position produces echogenic bubbles in the RA on apical 4-chamber or subcostal views. Bubbles in the IJV or carotid artery indicate likely malposition. Lung sliding on the insertion side excludes pneumothorax.");
B(25,'vasc',1,"A meta-analysis of 20 studies compared ultrasound with chest radiography for detecting pneumothorax after procedures. Which reported values are correct?",["Ultrasound 52%/100%; radiography 88%/99%","Ultrasound 99%/88%; radiography 100%/52%","Ultrasound 88%/99%; radiography 52%/100%","Ultrasound 75%/95%; radiography 60%/98%"],2,"Ultrasound sensitivity 88% and specificity 99% versus 52% and 100% for chest radiography. Post-procedural ultrasound can confirm venous placement and exclude pneumothorax immediately.");
B(25,'vasc',2,"During ultrasound-guided radial arterial cannulation, the needle is inserted at 45° to 60° and a flash of bright red blood appears. What is the next step?",["Advance the needle 5 mm at the same steep angle","Withdraw the needle and insert the catheter blindly","Rotate the probe to long axis and inject saline","Lower the needle to 10° to 20° and advance 1 to 2 mm"],3,"After the flash, flatten the needle to about 10° to 20° from the skin and advance 1 to 2 mm, then pass a guidewire or catheter. A depth of about 2 cm is used to scan the radial artery in short axis.");
B(25,'vasc',2,"A patient undergoing active CPR needs arterial access, and two radial attempts have failed. Which feature makes the femoral artery advantageous?",["It is much larger, about 8.2 mm versus 2.3 mm","It has dual supply making thrombosis harmless","It has lower infection rates than the radial artery","It lies medial to the femoral vein, away from it"],0,"The femoral artery (about 8.2 mm) is much larger than the radial (about 2.3 mm) and is ideal during CPR, upper extremity trauma or burns, or after failed radial attempts. It is the main supply to the leg (thrombosis risks ischemia) and lies lateral to the femoral vein.");
B(25,"vasc",2,"During femoral arterial cannulation the needle passes through both the anterior and posterior arterial walls. How should this be managed?",["Remove the needle completely and puncture again at a new site","Withdraw slowly with gentle suction until blood flows freely","Advance the guidewire forcefully through the needle anyway","Apply firm probe pressure to compress and flatten the artery"],1,"For unintentional double-wall puncture, pull the needle back slowly while keeping gentle suction until blood flows freely, then pass the guidewire and confirm it in transverse and longitudinal views before Seldinger cannulation. Use only gentle probe pressure.");

// Chapter 26 — Thoracentesis and Thoracostomy Tube Placement
B(26,'lung',2,"A ventilated ICU patient has a right pleural effusion. Using Balik's method, the maximal interpleural separation (parietal to visceral pleura) is 25 mm. What is the estimated effusion volume?",["About 250 mL","About 500 mL","About 1000 mL","About 1250 mL"],1,"Balik's method: V (mL) = 20 × separation (mm), so 20 × 25 = 500 mL. It is described as the most feasible and reproducible US method and correlates significantly with drained volume.");
B(26,'lung',2,"A patient with pneumonia has a pleural effusion that, on ultrasound, contains multiple fibrin strands and septations. What can be concluded from this appearance alone?",["The effusion is an exudate","The effusion is most likely a transudate from heart failure","The effusion must be a hemothorax","The effusion cannot be drained by catheter"],0,"Transudates may be anechoic or complex nonseptated but are never complex septated or homogeneously echogenic; exudates can show any of the four patterns. Septations in a parapneumonic effusion may indicate the need for more invasive drainage or surgery, not that drainage is impossible.");
B(26,'lung',1,"Compared with a supine chest radiograph, what is the smallest pleural effusion volume that lung ultrasound can reliably identify?",["About 200 mL","About 500 mL","About 15 to 20 mL","About 100 to 150 mL"],2,"Ultrasound can detect effusions as small as 15 to 20 mL. On radiography at least 200 mL is needed to be seen, and about 500 mL to obscure the hemidiaphragm.");
B(26,'lung',2,"During ultrasound-guided therapeutic thoracentesis of a large malignant effusion, 1.5 L has been removed and the patient remains comfortable. More fluid remains. According to guidelines, how should further drainage proceed?",["Stop at 1.5 L and repeat the procedure in 24 hours regardless of symptoms","Continue freely until drainage stops spontaneously","Clamp for 1 hour, then drain the remainder in a single further aliquot","Measure pleural pressure by manometry and stop if it falls below –20 cm H2O"],3,"Guidelines advise removing no more than 1 to 1.5 L at a time; if more must be drained, use manometry and stop when pleural pressure drops below –20 cm H2O. Reexpansion pulmonary edema (hypoxemia and new infiltrates within 24 h) is now thought to relate to falling intrapleural pressure.");
B(26,'lung',2,"Before thoracentesis in an elderly patient with pulmonary hypertension, the operator places a linear probe perpendicular to the ribs at the planned site and applies color Doppler. The intercostal artery is seen running through the middle of the intercostal space. What is the best action?",["Proceed, inserting the needle just above the inferior rib","Proceed, since the artery always lies under the inferior border of the rib","Proceed with a smaller-gauge needle at the same site","Choose a different procedural site"],3,"The intercostal artery normally lies below the inferior rib border, but its course varies and may be tortuous in the elderly and in pulmonary hypertension or bronchiectasis. If it lies near the middle of the intercostal space it is at risk of laceration and the site should be moved.");
B(26,"lung",2,"A mechanically ventilated patient with an INR of 1.7 and platelets of 70,000 has a large effusion delaying liberation from the ventilator. A colleague hesitates to perform thoracentesis. Which statement best reflects current evidence?",["US-guided tap can proceed; ventilation and labs don't preclude it","Positive pressure ventilation is an absolute contraindication to tapping","Platelets and plasma must first be transfused to normal laboratory values","Drainage should be deferred until the patient has been extubated"],0,"Studies fail to show higher pneumothorax risk with mechanical ventilation, so it is not a contraindication. Newer data suggest patients outside traditional coagulation thresholds (INR >1.5, platelets <50,000) can safely undergo thoracentesis; bleeding risk is judged individually.");
B(26,"lung",2,"A trauma patient has a right pneumothorax. Ultrasound shows absent lung sliding anteriorly and a lung point in the midaxillary line. Where should the thoracostomy tube be placed under static ultrasound guidance?",["At the lung point itself, where lung sliding first reappears","Above the diaphragm, anterior to the lung point, no sliding","Below the level of the diaphragm in the posterior axillary line","Posterior to the lung point, where lung sliding is still present"],1,"The tube should be inserted above the diaphragm, anterior to the lung point, at an interspace where sliding is absent. Real-time needle visualization is difficult because pleural air blocks the image, so static guidance is acceptable; reappearance of sliding confirms reinflation.");
B(26,'lung',1,"Which statement about the static (ultrasound marking) technique for thoracentesis is correct?",["The linear probe is preferred for site selection because it penetrates deepest","It has a higher pneumothorax rate than the blind landmark technique","After the skin is marked, the patient should not be repositioned before puncture","Measurement of skin-to-effusion depth is unnecessary once the site is marked"],2,"Repositioning redistributes fluid and invalidates the mark, so the procedure should be done promptly in the same position. The phased array probe is used to find the largest pocket, and skin-to-effusion and skin-to-lung/organ depths should be measured; both US techniques outperform the blind approach.");
B(26,'lung',2,"Lung ultrasound in a dyspneic smoker shows a pleural effusion. Which accompanying finding raises suspicion that the effusion is malignant?",["Bilateral effusions with diffuse B-lines","Pleural thickening greater than 1 cm with pleural nodularity","An anechoic effusion with a mobile jellyfish sign","A hematocrit sign in the dependent costophrenic recess"],1,"Pleural thickening >1 cm and pleural nodularity suggest malignancy. Bilateral effusions with B-lines suggest heart failure (consider diuretics first), and a hematocrit sign suggests dense layering material, commonly blood.");
B(26,'lung',2,"After ultrasound-guided drainage of a chronic malignant effusion, an experienced operator finds a persistent pneumothorax adjacent to a lung that fails to reexpand. The patient is stable. What is the most likely explanation and management?",["Pneumothorax ex vacuo; it generally requires no treatment","Needle laceration of the visceral pleura; place a large-bore chest tube","Tension pneumothorax from positive pressure; perform needle decompression","Reexpansion pulmonary edema; start diuretics"],0,"Pneumothorax ex vacuo occurs when the lung cannot reexpand after drainage and is a common, unavoidable cause of post-thoracentesis pneumothorax even with expert US guidance; it generally needs no treatment. Only about one-third of iatrogenic pneumothoraces overall need a tube.");

// Chapter 27 — Airway Management
B(27,'abd',1,"Which transducer and initial depth are recommended for focused upper airway ultrasound?",["High-frequency linear probe (7.5-15 MHz), depth about 4 cm","Low-frequency phased array probe, depth about 12 cm","Curvilinear probe (2-5 MHz), depth about 8 cm","Endocavitary probe, depth about 6 cm"],0,"The upper airway is superficial, so a high-frequency linear probe is preferred, with depth set around 4 cm. The patient is scanned supine with the neck neutral or hyperextended.");
B(27,'abd',2,"Before a high-risk intubation in a patient with poorly defined neck landmarks, you want to mark the cricothyroid membrane. Scanning transversely, you move cephalad from the suprasternal notch through the tracheal rings. Which sonographic event marks the caudal edge of the cricothyroid membrane?",["Appearance of the hyperechoic vocal ligaments","Disappearance of the oval, thick cricoid cartilage","Appearance of the hyoid bone acoustic shadow","Loss of the air-mucosal interface"],1,"The cricoid appears as an oval heteroechoic structure thicker than tracheal rings; its disappearance as the probe moves cephalad indicates the caudal cricothyroid membrane. Ultrasound localization is far more accurate than palpation in abnormal necks (9-fold higher risk of inaccuracy with palpation).");
B(27,'abd',1,"In the longitudinal (sagittal) midline view of the anterior neck, what is the typical appearance of the tracheal cartilages?",["A single continuous hyperechoic band","An inverted U-shaped hyperechoic arch","A hypoechoic string of beads below a cricoid hump","An oval heteroechoic ring with posterior shadow"],2,"Longitudinally, tracheal rings appear as hypoechoic beads, with the cricoid forming a hump cephalad to them; the first tracheal cartilage is the longest. The inverted U shape is the transverse appearance of a tracheal ring.");
B(27,"abd",1,"Where is the esophagus typically visualized on transverse upper airway ultrasound?",["Anterior to the cricoid cartilage in the midline of the neck","Between the thyroid and cricoid cartilages in the midline","Lateral to the right carotid artery at the level of the hyoid","Behind the left thyroid lobe at tracheal rings 1–2"],3,"Sliding the transverse probe to the patient's left shows the esophagus posterior to the left thyroid lobe at the level of tracheal rings 1-2; peristalsis during swallowing helps confirm it and may be clearer in the longitudinal view.");
B(27,'abd',2,"Before elective intubation, ultrasound measures the distance from skin to epiglottis as 31 mm. How should this be interpreted?",["It is normal and excludes difficult laryngoscopy","It indicates the endotracheal tube should be one size smaller","It predicts postextubation stridor rather than difficult laryngoscopy","It exceeds 27.5 mm and is associated with difficult laryngoscopy"],3,"A skin-to-epiglottis distance >27.5 mm predicts difficult laryngoscopy (sensitivity 64.7%, specificity 77.1%). No single measurement excludes a difficult airway; bedside clinical tests are also poor discriminators.");
B(27,"abd",2,"On sublingual ultrasound during preintubation assessment, the hyoid bone cannot be visualized. What does this finding predict?",["Difficult intubation (Cormack-Lehane ≥3), high specificity","Esophageal intubation on the first attempt at laryngoscopy","Easy laryngoscopy because the tongue base is thin","Unilateral vocal cord paralysis on the left side"],0,"Inability to visualize the hyoid bone on sublingual US predicts difficult intubation (Cormack-Lehane ≥3) with sensitivity 70% and specificity 97%.");
B(27,'abd',2,"During cardiopulmonary resuscitation, an intubation is performed but the capnography waveform is flat and its reliability is uncertain. Which ultrasound approach best confirms tracheal tube placement?",["Phased array probe in the subcostal window looking for gastric distension","Linear probe placed transversely over the trachea at the suprasternal notch (TRUE)","Linear probe over the hyoid bone in the longitudinal plane","Curvilinear probe over the epigastrium to look for diaphragm motion"],1,"Capnography may be unreliable in cardiac arrest and low-flow states; the tracheal rapid ultrasound examination (transverse probe over the suprasternal notch) showed sensitivity 98.9% and specificity 95% versus capnography. Bilateral lung sliding further supports correct placement.");
B(27,'abd',3,"Before extubation, laryngeal ultrasound measures the air column width at the vocal cords with the cuff inflated and deflated. The difference between the two is 1.2 mm. What does this suggest?",["Excellent airway patency with low stridor risk","A falsely low value that should be ignored if the cuff leak test is positive","Increased risk of postextubation stridor from laryngeal edema","Vocal cord paralysis requiring tracheostomy"],2,"An air column width difference ≤1.6 mm predicted postextubation stridor (sensitivity and specificity 70%). Postextubation stridor from laryngeal edema occurs in 2% to 15% of extubations; in children the US measure outperformed the cuff leak test.");

// Chapter 28 — Paracentesis
B(28,"abd",2,"A cirrhotic patient with abdominal pain is evaluated for spontaneous bacterial peritonitis. Ultrasound shows the largest pocket of ascites is 3 cm deep. How does this finding affect the probability of SBP?",["Negligible SBP probability with a pocket under 5 cm","SBP probability is highest in small pockets under 5 cm","Pocket depth has no relationship at all to SBP risk","SBP is excluded only when no free fluid is visible at all"],0,"Abdominal pain and ascites depth on US are independent predictors of SBP, and SBP probability becomes negligible when the largest pocket is less than 5 cm deep.");
B(28,'abd',1,"Which is the only absolute contraindication to paracentesis?",["INR greater than 2.0","Acute abdomen","Pregnancy","Abdominal wall cellulitis"],1,"An acute abdomen is the only absolute contraindication. Severe thrombocytopenia, INR >2.0, pregnancy, abdominal wall cellulitis, bowel obstruction and surgical scar sites are relative contraindications.");
B(28,"abd",2,"A patient with decompensated cirrhosis needs a diagnostic paracentesis. INR is 2.4 and platelets are 45,000. What is the most appropriate approach?",["Transfuse fresh-frozen plasma until the INR is below 1.5 first","Transfuse platelets to above 100,000 before the procedure","Proceed with US guidance, no routine prophylactic transfusion","Defer paracentesis and treat empirically for peritonitis"],2,"Bleeding complications occur in about 1% and are not associated with the degree of thrombocytopenia or INR elevation; prophylactic FFP or platelets show no benefit. Early paracentesis in hospitalized patients is associated with lower mortality, so it should not be deferred.");
B(28,"abd",2,"Before a large-volume paracentesis in the left lower quadrant, what is the best way to reduce the risk of the most ominous vascular complication?",["Use a midline entry about 2 cm above the umbilicus instead","Insert perpendicular to the skin without Z-tracking the needle","Rely on palpating the anterior superior iliac spine alone","Find the inferior epigastric vessels on Doppler and avoid them"],3,"Injury to the inferior epigastric arteries is the most ominous vascular complication; locating them with color or power Doppler using the linear or curvilinear probe before puncture reduces iatrogenic injury. The Z-track technique is used to limit ascitic leak.");
B(28,"abd",2,"During real-time ultrasound-guided paracentesis using a transverse (short-axis) approach, how should the operator keep the needle tip in view?",["Move the probe with the needle; only the tip in the beam shows","Keep the probe fixed, because the whole needle shaft stays visible","Switch to M-mode imaging to follow the needle depth continuously","Tilt the probe away from the needle to create an acoustic shadow"],0,"In the transverse orientation the needle is visible only where it crosses the beam, so the probe must be advanced with the needle to track the tip. The longitudinal approach shows the whole needle but the needle may drift out of the narrow plane.");
B(28,"abd",2,"Midway through a large-volume paracentesis, ascitic flow suddenly stops although a large amount of fluid remains on ultrasound. What is the most appropriate next step?",["Remove the catheter and abort the procedure completely at this point","Look on US for bowel/peritoneum blocking it; reposition or flush","Advance the catheter several centimetres deeper blindly","Apply continuous high negative suction to clear the blockage"],1,"Flow may decrease or stop when bowel or peritoneum occludes the catheter; ultrasound can reveal this, and repositioning the patient or injecting a small volume of saline usually restores flow.");

// Chapter 29 — Ultrasound-Guided Pericardiocentesis
B(29,'peri',2,"A hemodynamically stable patient has had a pericardial effusion for 5 months despite medical therapy. Echo shows a circumferential effusion. Above what diastolic size is pericardiocentesis indicated for chronic fluid accumulation?",["More than 20 mm","More than 10 mm","More than 5 mm","More than 30 mm"],0,"For chronic effusions (>3 months), pericardiocentesis is indicated for a large effusion >20 mm in diastole. Diagnostic drainage of mild to moderate effusions (<20 mm) is not justified because of low yield and relatively high risk, unless tuberculous, bacterial or neoplastic pericarditis is suspected.");
B(29,"peri",3,"A patient with type A aortic dissection develops tamponade with profound hypotension. Cardiac surgery is not immediately available. What is the most appropriate pericardial management?",["Withhold any pericardial drainage, as dissection is an absolute contraindication","Drain small amounts to keep systolic BP ~90 mm Hg as a bridge","Perform complete rapid drainage to fully normalize the blood pressure","Start positive-pressure ventilation and vasopressors and avoid any drainage"],1,"Aortic dissection and free wall rupture are contraindications to needle drainage because rapid decompression and restored arterial pressure may extend the dissection or rupture. If surgery is not immediately available or the patient is unstable, small-volume drainage to keep BP around 90 mm Hg is acceptable as a bridge.");
B(29,"peri",2,"Using the Mayo Clinic ultrasound-guided approach, how is the optimal pericardiocentesis entry site defined?",["Always the subxiphoid site, as it is the safest route in every case","The site nearest the right atrium, so that it is decompressed first","Closest point to the probe, most fluid, no vital organs between","The fifth left intercostal space at the sternal edge in every patient"],2,"Mayo selects the approach purely on echo findings: the point where fluid is closest to the probe and maximal with no intervening organs, which is more often para-apical than subcostal. Echo-selected sites showed higher success and fewer complications than routine subxiphoid puncture.");
B(29,"peri",2,"An operator plans a parasternal pericardiocentesis in the fifth left intercostal space. Which structure is specifically at risk if the needle is inserted more than 1 cm lateral to the sternal margin, and how can it be avoided?",["The LAD artery; avoid it by using the subxiphoid window instead","The right atrium; avoid it by aiming the needle at the left shoulder","The phrenic nerve; avoid it by injecting local anaesthetic deeply","Internal thoracic vessels; see them first with a linear probe"],3,"The parasternal approach risks pneumothorax and internal thoracic vessel puncture if the needle is >1 cm lateral. A linear probe allows visualization and avoidance of the left internal mammary artery, as in the medial-to-lateral in-plane technique.");
B(29,'peri',2,"During a subxiphoid pericardiocentesis, once the needle is beneath the costal cartilage, which needle orientation is recommended?",["15° to 30° to the abdominal wall, aimed toward the left shoulder","45° to 60° to the abdominal wall, aimed toward the right shoulder","Perpendicular to the skin, aimed straight posteriorly","15° to the abdominal wall, aimed medially toward the sternum"],0,"The needle is lowered to 15° to 30° and directed toward the left shoulder. A steeper angle risks entering the peritoneal cavity, and a medial direction increases the risk of right atrial puncture; the subxiphoid path is longer but has lower pneumothorax risk.");
B(29,"peri",2,"During echo-guided pericardiocentesis, bloody fluid is aspirated and the operator is unsure whether the needle tip is in the pericardial space or a cardiac chamber. What is the simplest way to confirm extracardiac position with ultrasound?",["Measure the pH of the aspirate at the bedside with a blood gas","Inject ~5 mL agitated saline; look for bubbles in the pericardium","Advance the needle further until the aspirated fluid clears","Apply color Doppler directly over the needle tip to look for flow"],1,"Injecting agitated saline through the needle and seeing microbubbles in the pericardial space confirms position; bloody aspirate can reflect myocardial puncture or hemorrhagic effusion. Direct ultrasound imaging is the optimal confirmation of needle tip position.");
B(29,'peri',3,"Bloody fluid aspirated during pericardiocentesis clots quickly in the syringe and its hemoglobin equals the patient's peripheral blood hemoglobin. What does this most likely indicate?",["A hemorrhagic pericardial effusion from malignancy","A chronic organized hemopericardium","Intracardiac needle tip position","A traumatic tap of a pericardial vessel only"],2,"Intracardiac blood clots, whereas pericardial aspirate should not, and pericardial fluid has lower hemoglobin than peripheral blood. A fluorescein flush in the conjunctiva after injection also indicates intracardiac placement; direct US imaging remains optimal.");
B(29,'peri',1,"An indwelling pericardial catheter is aspirated every 4 to 6 hours after drainage of tamponade. When can it be removed?",["When drainage falls below 100 mL in 24 hours","After exactly 24 hours regardless of output","When the fluid becomes serous rather than bloody","When drainage decreases to less than 25 mL in 24 hours"],3,"The catheter can be removed once drainage is <25 mL/24 h. Extended drainage (24 to 72 h) reduces recurrence from 27-55% with simple pericardiocentesis to 12-24%; keep the catheter up to 72 h if accumulation exceeds 30 mL in the first 24 h.");
B(29,"peri",2,"Several hours after rapid drainage of 1.8 L of pericardial fluid, a patient develops acute pulmonary edema and cardiogenic shock. What is the most likely diagnosis and the recommended preventive strategy?",["Pericardial decompression syndrome; drain ≤1 L initially","Recurrent tamponade; remove the pericardial catheter at once","Coronary laceration; emergency angiography is needed in all cases","Re-expansion edema of the left lung; drain the left pleural space"],0,"Pericardial decompression syndrome is a paradoxical acute ventricular failure with pulmonary edema hours to days after drainage, occurring in up to 5%, especially after rapid large-volume drainage. The only advice is to remove enough fluid (not >1 L) to normalize CVP and BP and complete removal over the next hours.");
B(29,'peri',3,"A hypotensive patient has a moderate pericardial effusion and a very large left pleural effusion. Echo shows right atrial and right ventricular diastolic collapse. What is the most appropriate initial drainage?",["Emergency subxiphoid pericardiocentesis","Drainage of the pleural effusion","Immediate surgical pericardial window","Positive-pressure ventilation to recruit the left lung"],1,"A large pleural effusion can raise intrapericardial pressure enough to produce echo signs of tamponade; the appropriate therapy is drainage of the pleural effusion. Right atrial collapse is also the most common false-positive tamponade sign in volume-depleted patients.");
B(29,"peri",3,"A patient with severe pulmonary hypertension has a large pericardial effusion, hypotension and pulsus paradoxus, but echo shows no right atrial or right ventricular collapse. How should this be interpreted?",["Tamponade is excluded, so the effusion is hemodynamically insignificant","Absence of chamber collapse confirms constrictive pericarditis instead","High right pressures can prevent collapse; tamponade still possible","The finding indicates hypovolemia, requiring diuresis and observation"],2,"With high right-heart pressures (pulmonary hypertension, PE, RV volume overload), intrapericardial pressure does not exceed right-sided pressures, so RA/RV collapse may be absent despite tamponade, a false-negative echo pattern. Tamponade remains essentially a clinical diagnosis.");
B(29,'peri',2,"A patient with suspected cardiac tamponade is becoming tachypneic. What is the main concern about starting positive-pressure ventilation before drainage?",["It raises Paco2, which lowers pericardial pressure","It has no hemodynamic effect in tamponade","It improves venous return by lowering intrathoracic pressure","Inspiratory rise in intrathoracic pressure can reduce cardiac output by up to 25%"],3,"Positive-pressure ventilation increases intrathoracic pressure and can reduce cardiac output by up to 25% in tamponade, so it should be avoided unless absolutely necessary. Hypercapnia (Paco2 57 mm Hg) raises pericardial pressure 2 to 4 mm Hg, while hypocapnia lowers it.");

// Chapter 30 — Competence, Proficiency, and Training
B(30,'views',2,"An intensivist credentialed in advanced critical care echocardiography (ACCE) is managing several ICU patients. In which situation does the competency framework still advise requesting a formal echocardiogram with cardiology consultation?",["Serial LVOT VTI to guide inotrope titration","Quantifying RV dilation in suspected massive PE","Assessing prosthetic valve function","Estimating dynamic preload sensitivity during ventilation"],2,"Even ACCE-competent intensivists should request formal echo and cardiology input for prosthetic valve function, complex congenital heart disease, cardiac source of systemic embolism, and stress echo. Quantitative hemodynamics, chamber function and preload-sensitivity indices are core ACCE skills.");
B(30,'views',2,"A trainee submits an apical 4-chamber clip for logbook credit. All 4 chambers are seen and both AV valves open and close on-plane, but the LV apex appears rounded and the LV looks short. What is the correct judgement?",["Reject: the LV apex is foreshortened","Accept: all 4 chambers and both AV valves are visible","Accept if the descending aorta is also visible","Reject only if the septum is not perfectly horizontal"],0,"Quality criteria for an A4C include a non-foreshortened LV apex, a vertical septum with the crux centered, on-plane mitral and tricuspid motion, and visible descending aorta. Only studies meeting predefined quality criteria count toward the trainee log; foreshortening also distorts LV function assessment.");
B(30,'rv',2,"A hypotensive ICU patient undergoes a basic-level (CCUS) cardiac scan by a junior fellow. The RV appears possibly enlarged but image quality is limited; fibrinolysis for presumed massive PE is being considered. What is the most appropriate approach?",["Proceed with fibrinolysis, since CCUS favors sensitivity","Repeat a goal-directed CCUS after a fluid bolus and decide on that","Accept the finding if the fellow has logged 30 echo studies","Treat the finding as equivocal and obtain a formal study or urgent expert review"],3,"CCUS is goal-oriented, mostly qualitative and favors specificity over sensitivity: definitive findings can trigger intervention, but equivocal findings require a formal study. Expert remote review is especially important when major decisions such as fibrinolysis rest on the scan; mistaken RV enlargement leading to inappropriate lysis is a cited source of harm.");
B(30,'views',1,"For NBE certification in critical care echocardiography, beyond passing the CCEeXAM, what is the minimum echocardiography experience requirement?",["50 interpreted and 30 personally performed focused cardiac studies","150 complete critical care TTE studies performed and interpreted by the applicant","100 TTE plus 20 TEE studies reviewed by a supervisor","50 ACCE studies per year for 3 consecutive years"],1,"Requirement 5 is at least 150 complete critical care TTE examinations performed and interpreted by the applicant, with a subset reviewed by an appropriately certified supervisor. 50 interpreted/30 performed is the SCCM basic CCUS echo minimum; 50 studies annually (plus 20 TEE if TEE competence is kept) is the SCCM maintenance criterion.");

// Chapter 32 — General Considerations in Pediatric and Neonatal Critical Care Point-of-Care Ultrasound
B(32,'lung',2,"A 1-month-old with a repaired left congenital diaphragmatic hernia has a persistent left upper zone opacity on chest radiograph unresponsive to antibiotics and bronchodilators. Anterior chest ultrasound shows a coarse, homogeneous structure with echogenicity similar to liver beneath the pleural line. What is the most likely explanation?",["Lobar pneumonia with hepatization","Normal prominent thymus","Obstructive atelectasis from a mediastinal mass","Loculated pleural effusion"],1,"Thymus has coarse homogeneous liver-like echogenicity, is large in neonates and can mimic consolidation on radiograph and ultrasound. The pediatric differential of a lung lesion differs radically from adults: thymus is common, whereas obstructive atelectasis from cancer, lymphoma and sarcoidosis are unlikely.");
B(32,'fluid',3,"A 19-month-old in septic shock after cardiac arrest has an LV ejection fraction of about 30% with a dilated LV, normal RV size and function, and a normal-to-slightly decreased IVC:aorta ratio. Epinephrine and milrinone are started. What is the most appropriate fluid strategy?",["Withhold all fluid because of LV systolic dysfunction","Estimate CVP from absolute IVC diameter using adult cut-offs","Give large repeated boluses until the IVC:aorta ratio exceeds 2","Give a careful fluid bolus with serial POCUS of RV and IVC:aorta ratio"],3,"Low LV function alone suggests avoiding fluid, but a normal/low IVC:Ao ratio with adequate RV function indicates possible volume responsiveness; careful boluses with serial RV and IVC:Ao monitoring are appropriate. There are no pediatric standards for absolute IVC size or IVC-to-CVP translation as in adults, so multiple windows must be integrated.");
B(32,'phys',2,"While scanning a crying, tachycardic infant, the cardiac images are blurred by motion. Which adjustment best improves temporal resolution while preserving image quality?",["Reduce depth and sector width to the area of interest, keeping frequency just low enough to penetrate","Increase depth to include the whole thorax and lower the frequency","Switch to the lowest available transducer frequency","Widen the sector to capture the heart as it moves in and out of view"],0,"Frame rate falls with greater depth and lower frequency; narrowing depth and sector to the region of interest raises frame rate. Frequency should be just low enough for adequate penetration, balancing temporal resolution with overall image quality, which matters more in children because of fast heart rates and motion.");
B(32,'views',2,"A PICU is purchasing its first POCUS machine on a limited budget. Which transducer statement is correct for pediatric and neonatal use?",["A large curvilinear probe is the core probe for pediatric abdominal and lung imaging","Neonates require lower-frequency probes to compensate for higher body water content","The pediatric phased array has a smaller footprint and higher frequency and can image many thin children up to 18 years","A single small linear probe suffices for vascular access from infancy to adolescence"],2,"The pediatric phased array (higher MHz, smaller footprint) can image thinner children up to 18 years, so an adult phased array may be unnecessary on a limited budget. Neonates need high-frequency probes, large curvilinear probes are seldom useful due to size, and a small linear probe may not reach femoral vessels in older children.");
B(32,'lung',2,"In a 19-month-old with partially ossified ribs and narrow intercostal spaces, rib shadowing makes B lines difficult to quantify. What technique is recommended?",["Increase gain until the shadows disappear","Rotate the probe parallel to the ribs to scan within the interspace","Switch to a large curvilinear probe at low frequency","Image only the posterior chest with the patient prone"],1,"Narrow rib spaces in young children hinder pleural assessment; rotating the probe parallel to the ribs (intercostal orientation) avoids rib shadowing. A micro-curvilinear or small-footprint linear probe also helps image between ribs. In neonates, incomplete rib ossification instead allows continuous pleural visualization.");

// Chapter 33 — Pediatric Ultrasound-Driven Approach to Shock and Hypotension
B(33,'fluid',2,"A spontaneously breathing 4-year-old with gastroenteritis is tachycardic. A transverse subxiphoid view shows a flattened IVC; maximum IVC diameter 6 mm and maximum aortic diameter 10 mm. How should this be interpreted?",["IVC:aorta ratio 0.6, consistent with hypovolemia","IVC:aorta ratio 0.6, within the normal range","IVC:aorta ratio 1.7, consistent with hypervolemia","The ratio cannot be calculated without a longitudinal view"],0,"IVC:Ao = 6/10 = 0.6. In spontaneously breathing euvolemic children the normal ratio is 1 to 1.4; <0.8 suggests hypovolemia and >1.4 hypervolemia. It is a static measure affected by positive pressure ventilation, intra-abdominal hypertension and right heart failure.");
B(33,'fluid',2,"A mechanically ventilated 6-year-old in septic shock has a longitudinal IVC view showing the vessel distending with each positive-pressure breath, with 25% respiratory variation. How should this be interpreted?",["Not fluid responsive: >50% variation is needed in all children","Uninterpretable because the IVC collapses on inspiration in ventilated patients","Suggests fluid responsiveness: >20% variation is the cut-off in intubated children","Indicates hypervolemia because the IVC distends with inspiration"],2,"In intubated children the IVC distends with inspiration; variation >20% suggests fluid responsiveness, whereas >50% is the cut-off in non-intubated children. Fluid responsiveness is best judged by respiratory variation in aortic peak velocity.");
B(33,'fluid',2,"In a ventilated child in shock, which ultrasound measurement most accurately assesses fluid responsiveness?",["Absolute IVC diameter in the transverse view","IVC:aorta ratio at end-expiration","LV wall thickening in the parasternal long axis","Respiratory variation of LVOT peak velocity by pulsed-wave Doppler in the apical 5-chamber view, >20%"],3,"Pulsed-wave Doppler at the LVOT in the apical 5-chamber view, with >20% inspiratory-expiratory difference in aortic peak velocity, is the most accurate pediatric fluid responsiveness index. The aortic VTI from the same view can be used to estimate and trend cardiac output.");
B(33,'rv',2,"In a child with ARDS and hypotension, the parasternal short-axis view at the mid-papillary level, with papillary muscles horizontal, shows the interventricular septum flattening into the LV during systole. What does this indicate?",["RV volume overload","RV pressure overload","Normal finding in children under 2 years","Artifact from an off-axis view that should be ignored"],1,"Systolic septal flattening or bowing into the LV indicates RV pressure overload; diastolic flattening indicates volume overload. The assessment must be made at the papillary level with the muscles horizontal, since off-axis views can create false septal flattening.");
B(33,'peri',1,"In a parasternal long-axis view of a child in shock, an echo-free fluid collection is seen posterior to the heart. What landmark distinguishes a pericardial from a pleural collection?",["Fluid anterior to the coronary sinus is pleural","Fluid crossing the mitral annulus is pericardial","Fluid anterior to the descending thoracic aorta is pericardial; posterior is pleural","Fluid that varies with respiration is pericardial"],2,"In the PLAX view, fluid anterior to the descending thoracic aorta is pericardial and fluid posterior to it is pleural. The subxiphoid view is ideal for detecting pericardial effusion and may be the only reliable cardiac window during arrest or severe lung disease.");
B(33,'shock',3,"A hypotensive 10-year-old has a distended IVC without respiratory variation. Apical 4-chamber shows an RV larger than the LV with reduced RV function and no pericardial effusion; parasternal short-axis shows septal flattening. Which shock state is most consistent?",["Obstructive shock, for example pulmonary embolism or tension pneumothorax","Hypovolemic shock","Distributive shock with preserved function","Cardiogenic shock from isolated LV failure"],0,"Obstructive shock shows a distended, non-fluid-responsive IVC with RV dilation, septal flattening and possible RV dysfunction (PE, tension pneumothorax) or a moderate-large effusion with RV diastolic collapse (tamponade). The RV should not exceed two-thirds of LV size at any age, with both free walls in view. Hypovolemic and early distributive shock are fluid responsive.");

// Chapter 34 — Neonatal Hemodynamic Considerations: Assessment of the Patent Ductus Arteriosus and Beyond
B(34,'mass',2,"A 26-week preterm infant has a PDA imaged on the high parasternal ductal cut. Measured in 2D at the narrowest point at the pulmonary end, the duct is 2.4 mm. How is this duct classified?",["Small","Large","Hemodynamically insignificant regardless of other markers","Moderate"],3,"PDA size: <1.5 mm small, 1.5 to 3 mm moderate, >3 mm large, measured at the narrowest pulmonary end. Size alone does not define significance; it must be combined with markers of pulmonary overcirculation and systemic steal.");
B(34,'mass',2,"In preterm neonates, which echo finding best correlated with ductal shunt volume measured by cardiac MRI?",["Holodiastolic flow reversal in the descending aorta","LA:Ao ratio greater than 1.5","Ductal diameter greater than 3 mm","Right-to-left (blue) ductal flow on color Doppler"],0,"Holodiastolic reversal of descending aortic flow, obtained distal to the PDA or in the subcostal descending aorta view, best correlated with shunt volume, reflecting diastolic steal. LA:Ao >1.5 correlates with a large shunt but can be falsely reassuring when a left-to-right atrial shunt decompresses the LA.");
B(34,'dia',2,"A 27-week preterm infant with a large left-to-right PDA has mitral inflow pulsed-wave Doppler showing an E wave larger than the A wave (E/A >1). How should this be interpreted?",["Normal maturation of preterm LV diastolic filling","Restrictive physiology from LV hypertrophy","Pseudonormalization from increased pulmonary venous return through the ductal shunt","Evidence of a right-to-left ductal shunt"],2,"Preterm LV filling depends on atrial kick, so normal E/A is <1. A significant left-to-right PDA increases pulmonary venous return, producing pseudonormalized E/A >1, a marker of increased pulmonary blood flow alongside LA:Ao, LVEDD and LVO.");
B(34,'hemo',3,"A hypotensive preterm infant with a large left-to-right PDA has an LV output of 350 mL/kg/min measured from LVOT VTI and aortic diameter. How should this value be interpreted?",["Adequate systemic perfusion; inotropes are not needed","Overestimates systemic blood flow; suggests a significant ductal shunt","Underestimates systemic flow because of the ductal shunt","Reflects systemic venous return, which equals RV output"],1,"A left-to-right ductal shunt increases LVO, so LVO overestimates true systemic flow; LVO >300 mL/kg/min is associated with a significant shunt. A left-to-right atrial shunt instead inflates RVO. Measurement variability (intraobserver up to 22%) requires a standardized method for serial use.");
B(34,'hemo',2,"Why has SVC flow been proposed as a marker of systemic blood flow in preterm neonates, and what limits its routine use?",["It equals total LV output; limited by the need for TEE","It reflects pulmonary blood flow; limited by atrial shunting","It is reliable after the first week; limited only by heart rate","It is unaffected by ductal shunting and largely reflects cerebral flow; limited by poor measurement reproducibility"],3,"SVC flow quantifies upper-body venous return (70-80% cerebral) and avoids the ductal and atrial shunt confounding of LVO/RVO; low SVC flow in the first 48 hours is associated with IVH. Diameter of this compressible vessel is hard to measure reproducibly, especially after the first days when lung hyperinflation interferes, so it is not used routinely.");

// Chapter 35 — Pediatric and Neonatal Thoracic Procedural and Diagnostic Applications
B(35,'lung',2,"A term newborn delivered by cesarean section has tachypnea at 3 hours of life. Lung ultrasound shows compact B lines in the inferior lung fields with an abrupt transition to noncompact B lines in the upper fields. What is the most likely diagnosis?",["Respiratory distress syndrome","Transient tachypnea of the newborn","Meconium aspiration syndrome","Pneumothorax at the lung point"],1,"The \"double lung point\", a sharp demarcation between compact inferior B lines and noncompact superior B lines, was reported with 100% sensitivity and specificity for TTN, which is due to delayed lung fluid clearance. RDS shows confluent B lines apex to base with no spared areas.");
B(35,'lung',2,"A 29-week preterm infant on nasal CPAP has confluent B lines from apex to base bilaterally with no spared areas and a thickened, irregular pleural line. Using the segmental lung ultrasound score (0 to 3 per region), the total is 9. What is the most appropriate interpretation?",["Typical TTN; surfactant is not indicated","Normal postnatal transition; repeat at 24 hours","RDS with a score above the threshold predicting surfactant need","Bronchiolitis pattern; supportive care only"],2,"White lung without spared areas and an abnormal pleural line indicates RDS. A score ≥5 (≥6 in infants <30 weeks) predicted surfactant need with AUC 0.94, outperforming chest radiography. A persistent bilateral white lung after 2 hours of CPAP also strongly predicts noninvasive ventilation failure.");
B(35,'lung',3,"A child on high-frequency oscillatory ventilation desaturates suddenly. Which ultrasound finding can be used to rule IN pneumothorax in this setting?",["Lung point","Barcode sign on M-mode","Absent seashore sign on M-mode","Absence of the usual shimmering lung sliding"],0,"During HFOV, subtidal breaths abolish normal lung sliding, replaced by \"lung shimmy\" synchronous with the piston, and seashore/barcode signs cannot be used. B lines and lung pulse still rule out pneumothorax; lung point is the only sign that rules it in.");
B(35,'lung',3,"A ventilated child undergoes diaphragm ultrasound at the zone of apposition in the midaxillary line (9th–10th interspace). End-expiratory thickness is 1.6 mm and maximal inspiratory thickness is 2.4 mm. What is the diaphragm thickening fraction?",["33%","67%","150%","50%"],3,"Thickening fraction = (Tdi-insp − Tdi-exp)/Tdi-exp = (2.4 − 1.6)/1.6 = 0.5, or 50%. It is effort-dependent and varies with sedation, whereas serial end-expiratory thickness can track ventilator-associated diaphragm atrophy in children.");
B(35,'lung',2,"A term infant born through meconium-stained fluid has respiratory distress. Which lung ultrasound pattern best distinguishes meconium aspiration syndrome from RDS?",["Patchy, asymmetric irregular subpleural consolidations with spared areas that change over time","Uniform confluent B lines from apex to base with no spared areas","Double lung point between upper and lower fields","Isolated A lines with preserved sliding bilaterally"],0,"MAS produces heterogeneous findings: coalescent B lines, irregular subpleural consolidations often more prominent over one hemithorax, spared areas, and shifting atelectasis over time. RDS shows uniform white lung with no spared areas; the double lung point is TTN.");

// Chapter 36 — Pediatric and Neonatal Abdominal Diagnostic Applications
B(36,'abd',2,"A 2-week-old former 32-week preterm neonate with suspected NEC has a radiograph showing paucity of bowel gas. On bedside ultrasound, which color Doppler finding is most sensitive and specific for transmural bowel necrosis?",["Ring pattern of increased flow around the bowel circumference","Absence of blood flow in the bowel wall","Y-shaped increased flow in subserosal mesenteric vessels","Zebra pattern of flow in thickened valvulae"],1,"Absent bowel wall flow on color Doppler had 100% sensitivity and 90% specificity for transmural necrosis, outperforming free air on radiograph (40% sensitivity). Y, ring and zebra hyperemic patterns occur in Bell stage I–II and suggest viable bowel.");
B(36,'abd',1,"Which bowel wall thickness on neonatal abdominal ultrasound is concerning for NEC, and what is the significance of a wall thinner than 1.0 mm?",["> 1.5 mm; thinning is reassuring and indicates resolution","> 3.5 mm; thinning indicates normal collapsed bowel","> 2.5 mm; thinning may indicate necrosis in late NEC","> 2.5 mm; thinning indicates benign pneumatosis coli"],2,"Wall thickness > 2.5 mm is concerning for NEC; thinning < 1.0 mm is not reassuring because it may reflect necrosis, a late stage. Both thickened and thinned walls show increased echogenicity.");
B(36,'abd',2,"In a meta-analysis of bowel ultrasound features in NEC, which finding was NOT associated with need for surgery or death?",["Portal venous gas","Aperistalsis","Complex ascites","Focal fluid collection"],0,"Pneumoperitoneum, aperistalsis, complex ascites and focal fluid collection were strongly associated with surgical NEC or death. PVG, pneumatosis, increased perfusion and simple ascites were not associated with these outcomes.");
B(36,'abd',2,"A neonate with NEC is scanned. Which ultrasound finding is most specific for bowel perforation?",["A small amount of anechoic free fluid in the pelvis","Hyperechoic granular foci within the bowel wall","Dendriform echogenic foci within the liver parenchyma","Focal free fluid between bowel loops with septations or debris"],3,"A small amount of intraperitoneal fluid is common; large or septated fluid suggests perforation, and focal fluid between loops is more specific. Intramural gas and PVG define NEC but do not indicate perforation.");
B(36,'abd',3,"A 7-year-old is hemodynamically stable after blunt abdominal trauma. Based on a randomized trial of 925 children, what is the effect of adding FAST to standard care in this population?",["Significant reduction in missed intra-abdominal injury","Shorter length of stay and lower hospital charges","Increased CT use due to false-positive results","No improvement in clinical care, length of stay, missed injury or charges"],3,"In hemodynamically stable children with blunt trauma, FAST did not improve clinical care; no differences in LOS, missed IAI or charges. FAST is most helpful for decision making when positive in unstable children; pediatric sensitivity for hemoperitoneum is about 66% with specificity 95%.");

// Chapter 37 — Ophthalmic and Neurological Ultrasound for Pediatric and Neonatal Neurocritical Care
B(37,'vasc',1,"When the ultrasound machine lacks an ophthalmic safety preset, which manual settings are required before ocular scanning?",["Power < 30%, MI < 0.23, TI < 1","Power < 50%, MI < 0.5, TI < 2","Power < 30%, MI < 1.9, TI < 1","Power < 10%, MI < 0.1, TI < 0.5"],0,"Ocular safety requires power below 30%, mechanical index below 0.23 and thermal index below 1 to protect the cornea from heat and vibration. Examination time should still be limited, especially with Doppler, even in safety mode.");
B(37,'vasc',2,"A 9-month-old with hydrocephalus has ocular ultrasound. What is the generally accepted upper limit of normal ONSD for this age?",["3 mm","4 mm","5 mm","5.7 mm"],1,"Normative pediatric ONSD upper limits are 4 mm for infants younger than 1 year and 4.5–5 mm for older children. Values above these suggest intracranial hypertension.");
B(37,'vasc',2,"When measuring optic nerve sheath diameter in a child, where is the measurement taken?",["At the lamina cribrosa, at the junction with the globe","1 cm behind the globe, parallel to the nerve","3 mm behind the globe, parallel to the nerve axis","3 mm behind the globe, perpendicular to the nerve"],3,"Measure 3 mm posterior to where the globe and sheath meet, then measure the sheath at 90° to the nerve crossing that mark, consistently using either internal or external edges (internal gives slightly smaller values). A bullseye cross-section confirms a true 90° transection.");
B(37,'vasc',2,"A 4-year-old with severe periorbital edema after facial trauma needs pupillary light reflex assessment. Using ultrasound in the transverse plane through the lens, how is the reflex elicited?",["Shine light into the ipsilateral eye and record direct response in color Doppler","Shine light through the contralateral eyelid and record consensual response in M-mode or B-mode clip","Apply gentle probe pressure to stimulate the oculocardiac reflex","Measure ONSD before and after light exposure"],1,"With depth set at 1–1.5 cm, the anechoic pupil is visualized and a bright light is shone through the contralateral (closed or open) eyelid to elicit the consensual response, quantified with M-mode or B-mode calipers (maximal dilation vs constriction).");
B(37,'vasc',2,"On ocular POCUS, which appearance indicates retinal detachment rather than vitreous hemorrhage or vitreous detachment?",["Wavy strands of variable echogenicity swaying with eye movement","Swaying seaweed appearance separated from the retina","Taut bright linear opacity tethered to the optic disk","Diffuse homogeneous echogenicity filling the vitreous"],2,"Retinal detachment is a taut, bright linear opacity tethered to the optic disk that moves with eye movements. Vitreous hemorrhage shows wavy variably echogenic strands; vitreous detachment looks like swaying seaweed separated from the retina.");
B(37,'vasc',3,"An infant with suspected abusive head trauma and raised ICP has ocular POCUS showing a bulge at the posterior pole where the optic nerve enters. What is the correct interpretation and next step?",["Papilledema/optic nerve sheath invagination from raised ICP; do not mistake for retinal injury and still obtain dilated fundus examination","Retinoschisis; ultrasound confirms abuse and replaces fundoscopy","Retinal detachment; urgent surgical repair without further testing","Vitreous hemorrhage; repeat ultrasound in 24 hours"],0,"Papilledema or invagination of the optic nerve sheath into the posterior pole from raised ICP must not be mistaken for abusive retinal injury. Ocular POCUS should not replace or delay the gold-standard dilated fundus exam (AAP: within 24–72 h).");

// Chapter 38 — Special Considerations in Pediatric and Neonatal Procedural Applications
B(38,'vasc',2,"A 900-g preterm neonate needs ultrasound-guided peripheral arterial access. Which method is NOT sufficient on its own to distinguish the radial artery from an adjacent vein?",["Compressibility on 2D grayscale imaging","Pulsatility on color Doppler","Arterial waveform on pulsed-wave Doppler","Pulsatility on 2D grayscale imaging"],0,"Neonatal distal arteries are easily compressed, so compressibility alone cannot distinguish artery from vein. Use 2D pulsatility, color Doppler pulsatility and PW Doppler waveform. The Seldinger technique is often impossible because the artery is too small for a guidewire.");
B(38,'mass',2,"After umbilical venous catheter insertion in a neonate, ultrasound is used to confirm tip position. What is the optimal tip location and best view?",["Portal sinus; subcostal four-chamber view","Junction of ductus venosus with IVC/right atrium; longitudinal IVC view","Mid right atrium; apical four-chamber view","Hepatic vein confluence; transverse liver view"],1,"The UVC should terminate at the ductus venosus–IVC/RA junction, assessed with a longitudinal IVC view (saline microbubbles confirm the tip). Too low risks hepatic necrosis, ascites and laceration; too high in the RA risks effusion, tamponade and arrhythmias.");
B(38,'mass',2,"For an umbilical arterial catheter secured as a high line, where should the tip lie and how is the aorta confirmed on ultrasound?",["Between the iliac bifurcation and renal arteries; coronal view from the left","At the aortic bifurcation; transverse pelvic view","Immediately below the diaphragm; longitudinal view with color Doppler showing celiac trunk and SMA","At the aortic arch; suprasternal view"],2,"A high UAC tip sits immediately below the diaphragm; fan from the longitudinal IVC view to the left and confirm the aorta by color Doppler of the celiac trunk and SMA. A low line lies between the iliac bifurcation and the renal arteries.");
B(38,'abd',2,"A 2-month-old needs a lumbar puncture. Ultrasound shows the conus medullaris and cauda equina. Why is ultrasound particularly useful in this age group, and what does it add?",["Ossified spinous processes give clear acoustic shadows marking each level","Ultrasound replaces sterile technique by allowing needle-free CSF sampling","It only identifies epidural hematoma after a traumatic tap","Cartilaginous spinous processes allow visualization of the canal, conus level and skin-to-dura depth"],3,"In infants up to about 6 (sometimes 12) months, cartilaginous spinous processes allow imaging of the spinal canal and conus, identification of the L3–L4 interspace and measurement of skin-to-posterior-dura depth (maximum safe depth), which increased nonbloody taps. Landmark first-pass LP success in children is about 67%.");
B(38,'lung',2,"In a neonate after intubation, a midsagittal suprasternal ultrasound view is used. Which statement about ultrasound ETT assessment is correct?",["Absent lung sliding with ventilation is specific for right mainstem intubation","The ETT tip depth can be judged relative to the aorta, carina or right pulmonary artery","End-tidal CO2 confirms correct ETT depth with 100% specificity","Reverse diaphragm movement toward the chest confirms tracheal placement"],1,"The neonatal midsagittal suprasternal view shows the ETT tip relative to aorta, carina or RPA; ultrasound had 86% sensitivity and 96% specificity for deep ETTs. Absent sliding or paradoxical diaphragm motion suggests esophageal intubation but is not specific for mainstem intubation.");

// Chapter 39 — Point-of-Care Ultrasound in the Operating Room
B(39,'abd',1,"For gastric POCUS in a 25-kg child, which probe and patient position are recommended?",["Low-frequency curvilinear probe, supine only","High-frequency linear probe, supine and right lateral decubitus with head up 30–45°","Phased array probe, left lateral decubitus","Curvilinear probe, prone position"],1,"In patients < 40 kg the antrum is superficial and can be imaged with a linear high-frequency probe; curvilinear is used in adults and children > 40 kg. Scan supine and RLD with head elevated 30–45°; RLD is more sensitive because contents move to the dependent antrum.");
B(39,'abd',2,"A 5-year-old with uncertain NPO status has gastric ultrasound. The antrum is empty supine but shows fluid in the right lateral decubitus position. What is the qualitative antral grade?",["Grade 0","Grade 1","Grade 2","Grade 3"],1,"Grade 0: empty in supine and RLD; Grade 1: fluid only in RLD; Grade 2: fluid in both positions. Supine scanning alone can make a stomach with substantial liquid appear empty.");
B(39,'abd',2,"Which gastric ultrasound appearance indicates solid contents in the antrum?",["Distended antrum with strongly hypoechoic center and posterior enhancement","Flattened oval with a target appearance","Heterogeneous contents with acoustic shadowing of the posterior wall","Hyperechoic mobile foci in fluid described as starry night"],2,"Solid contents appear heterogeneous and cause acoustic shadowing. Clear fluid gives a hypoechoic distended antrum with posterior enhancement; fluid mixed with air gives a starry night pattern; an empty antrum is a flattened target-shaped oval.");
B(39,'abd',1,"Which landmarks identify the gastric antrum in the epigastric sagittal plane?",["Spleen and left kidney","Gallbladder and right kidney","Diaphragm and pericardium","Left lobe of liver anteriorly, pancreas and SMA/aorta or IVC posteriorly"],3,"The antrum lies adjacent and slightly deep to the left liver lobe and anterior to the pancreas, with superior mesenteric vessels and aorta or IVC deeper. Probe is just right of midline with the indicator cephalad.");
B(39,'abd',2,"In a pediatric study of elective surgical patients, an at-risk stomach was defined by ultrasound. What was the definition and the approximate incidence found?",["Any solid content or gastric fluid > 1.25 mL/kg; about 1%","Any fluid in the supine position; about 15%","Antral area above adult cut-off; about 7%","Any visible antrum on ultrasound; about 25%"],0,"At-risk stomach was any solid content or fluid volume > 1.25 mL/kg; incidence in elective pediatric surgery was about 1%. Separately, about 7% of fasted patients had solids or > 1.5 mL/kg clear fluid in another study.");
B(39,'abd',2,"Ultrasound-guided caudal anesthesia is planned in a 2-year-old for orchiopexy. Which structure is the needle passed through to reach the epidural space?",["Sacrococcygeal ligament at the sacral hiatus","Ligamentum flavum at L4–L5","Interspinous ligament at S1","Dura at the conus medullaris"],0,"The caudal approach enters the epidural space through the sacrococcygeal ligament (sacral hiatus) attached to the fourth sacral tubercle, with a 20–22 G short-bevel needle in-plane. Caudal block is the most common RA in children < 6 years and anesthetizes spinal nerves below T9.");
B(39,'abd',2,"When ultrasound is used before spinal anesthesia in an infant younger than 9 months, what is identified and marked?",["The lowest lumbar interspace above the conus","The sacral hiatus and dural sac tip","The highest lumbar interspace caudal to the conus medullaris and the skin-to-dura distance","The L1–L2 interspace and ligamentum flavum thickness"],2,"Spinal anesthesia uses preprocedural (not real-time) scanning: measure skin-to-dura distance and mark the highest lumbar interspace caudal to the conus. Poor ossification before 9 months provides large acoustic windows.");
B(39,'abd',2,"During an ultrasound-guided femoral nerve block in a child, where is the femoral nerve located?",["Medial to the femoral vein, superficial to fascia lata","Deep to the femoral artery within the vascular sheath","Lateral to the artery and superficial to the fascia iliaca","Crescent-shaped hyperechoic structure lateral to the artery and deep to the fascia iliaca"],3,"The femoral nerve is crescent-shaped and hyperechoic, lateral to the femoral artery and inferior (deep) to the fascia iliaca; the needle tip is placed posterior to its midsection. It covers anterior thigh, distal femur and knee.");
B(39,'lung',2,"After an ultrasound-guided intercostal nerve block for rib fractures in an adolescent, what postblock ultrasound check is recommended?",["Confirm continued pleural sliding to exclude pneumothorax","Measure ONSD to exclude local anesthetic toxicity","Check diaphragm excursion to exclude phrenic palsy","Confirm intercostal artery flow with color Doppler"],0,"The needle passes through external and halfway through internal intercostal muscles, staying superficial to pleura; postblock ultrasound should show continued pleural sliding to rule out pneumothorax. The nerve lies inferior to the intercostal artery at the lower rib edge.");
B(39,'abd',3,"A rectus sheath block is planned for a midline laparotomy in a 20-kg child. Which statement is correct?",["The target is between the transversalis fascia and peritoneum and provides visceral analgesia","The needle tip is placed deep to the rectus muscle but superficial to the posterior rectus sheath; 0.2 mL/kg is injected; no visceral coverage","The thoracolumbar nerves are visualized directly and injected perineurally","The needle is advanced medial to lateral into the subcutaneous plane"],1,"Rectus sheath block targets the plane deep to rectus abdominis and superficial to the posterior rectus sheath and transversalis fascia, inserted lateral to medial; 0.2 mL/kg injected. It covers midline abdominal skin only; nerves are too small to see.");

function BI(bk,t,d,fid,stem,opts,ans,exp){Q.push({src:'Book',bk,n:fid,t,d,stem,opts,ans,exp,bimg:'bimg/'+fid+'.jpg'});}
// Image questions group 1
BI(1,'abd',1,'C01_F01',"How is the content of the gallbladder in this right upper quadrant image best described?",["Anechoic","Hyperechoic","Isoechoic to liver","Heterogeneous echogenic"],0,"The bile-filled gallbladder appears black (anechoic), contrasting with the hyperechoic gallstone and the relatively hypoechoic liver.");
BI(1,'phys',1,'C01_F02',"What is the main advantage of the ultrasound mode shown in the lower panel?",["Higher depth of penetration","Very high frame rate (temporal resolution)","Measurement of blood flow velocity","Three-dimensional volume reconstruction"],1,"This is M-mode across the mitral leaflet tips: a single scan line displayed over time (x-axis) against depth (y-axis), giving a frame rate orders of magnitude higher than B-mode for measuring rapidly moving structures.");
BI(1,'dop',1,'C01_F03',"In this apical 4-chamber color Doppler image of severe tricuspid regurgitation, why is the regurgitant jet in the right atrium displayed in blue?",["The flow is turbulent","The flow velocity exceeds the Nyquist limit","The flow is moving away from the transducer","Color power Doppler is being used"],2,"Color Doppler encodes direction relative to the probe face; the TR jet travels from the RV back into the RA, away from the apical transducer, so it is displayed in blue.");
BI(1,'dop',2,'C01_F04',"In this pulsed-wave Doppler tracing of mitral inflow, what does the sharp bright envelope with a dark center to the spectral profile indicate?",["Aliasing of the signal","Turbulent flow","Range ambiguity","Laminar flow"],3,"Pulsed-wave Doppler of mitral inflow shows E and A waves above the baseline (flow toward the probe); a crisp envelope with a dark center reflects laminar flow with a narrow velocity spectrum.");
BI(1,'dop',2,'C01_F05',"Panel A shows a pulsed-wave Doppler tracing of the carotid artery with the peaks cut off and displayed below the baseline. Which adjustment produced the corrected tracing in panel B?",["Increasing the pulse repetition frequency and moving the baseline","Increasing the gain","Switching to a lower-frequency linear probe","Increasing the imaging depth"],0,"Panel A shows aliasing: velocities above the Nyquist limit wrap to the other side of the baseline. Increasing PRF (velocity scale), moving the baseline and minimizing depth eliminate aliasing, as in panel B.");
BI(1,'dop',2,'C01_F06',"Using the peak tricuspid regurgitant velocity of 3.28 m/s measured on this continuous-wave Doppler tracing, what is the peak systolic pressure gradient between the RV and RA?",["13 mmHg","53 mmHg","43 mmHg","33 mmHg"],2,"CW Doppler captures the peak TR jet (below the baseline, away from the probe). By the simplified Bernoulli equation, 4 x 3.28^2 = 43 mmHg (the RV-RA gradient); adding RAP 10 mmHg gives an RVSP of about 53 mmHg.");
BI(1,'dop',2,'C01_F07',"This low-velocity spectral tracing was obtained with the sample volume at the lateral mitral annulus. What is its most common clinical application?",["Estimating pulmonary artery systolic pressure","Measuring stroke volume","Evaluating diastolic function","Grading aortic stenosis"],2,"This is tissue Doppler imaging, pulsed-wave Doppler filtered to display the slow velocities of myocardial motion (e' 18 cm/s, E/e' 5.25). Its common application is evaluating diastolic function.");
BI(1,'art',1,'C01_F08',"What do the arrows in this gallbladder image point to?",["Edge artifact","Posterior acoustic enhancement","Reverberation artifact","Acoustic shadowing"],3,"Bright hyperechoic gallstones lie dependently in anechoic bile; because they reflect most of the beam, black vertical bands (acoustic shadows) appear deep to them.");
BI(1,'art',2,'C01_F09',"The arrows point to thin dark vertical lines arising from the lateral borders of this curved vessel. What is the mechanism of this finding?",["Refraction of the beam striking the curved edge at a tangent","Attenuation by a calcified plaque","Reflection between two parallel strong reflectors","Off-axis beams from a strong reflector outside the main beam"],0,"This is edge artifact: refraction at the lateral border of a round structure produces a dark band deep to the edge, which should not be confused with a true acoustic shadow.");
BI(1,'art',2,'C01_F10',"In this TEE image, the arrow points to a linear echo in the center of the vessel at the same depth as a bright echogenic structure lying beside it. What is the most likely explanation?",["Intimal flap of aortic dissection","Side lobe artifact","Mirror image artifact","Reverberation artifact"],1,"Side lobe artifact arises from strong off-axis reflectors outside the main beam that are displayed within an anechoic structure at the same depth as the reflector; it should not be mistaken for a flap.");
BI(1,'art',3,'C01_F11',"In this axial view of the anterior neck, the arrow shows a bright vertical ring-down artifact deep to a hyperechoic line. What is the most likely source?",["Calcified thyroid nodule","Tracheal cartilage","Air tracking through fascial planes from pneumomediastinum","Thrombosed internal jugular vein"],2,"Ring-down artifact arises from resonance of fluid trapped between small gas bubbles, so it marks gas in soft tissue; here it comes from air dissecting through the neck fascial planes from pneumomediastinum.");
BI(1,'views',1,'C01_F12',"What is the main benefit of the probe grip shown?",["It allows greater pressure using the shoulder muscles","It frees the fourth and fifth fingers to adjust gain","It permits rapid sliding between acoustic windows","It anchors the probe so fine movements use the small muscles of hand and wrist"],3,"The tripod grip holds the probe like a pen between thumb, index and middle fingers, with the ring and little fingers and side of the hand braced on the patient. This improves control, reduces fatigue and keeps the probe on a small acoustic window.");
BI(2,'views',1,'C02_F02',"The screen indicator (blue dot) in this parasternal long-axis image is on the right side of the display. What does this represent?",["The standard orientation for echocardiography","A reversed setting that must be corrected","The standard orientation for abdominal ultrasound","An indication that the probe is upside down"],0,"Cardiac imaging conventionally displays the indicator on the right of the screen, whereas most other ultrasound applications place it on the left.");
BI(2,'views',1,'C02_F04',"Of the transducer movements shown, which one changes the imaging plane while the probe stays at the same spot on the skin?",["Rocking","Tilting","Sliding","Neither tilting nor rocking"],1,"Tilting (fanning) sweeps the beam through different planes, whereas rocking moves the probe within the same plane.");
BI(2,'views',1,'C02_F05',"With the transducer placed at the left parasternal border and the indicator pointed toward the patient's right shoulder, which view is obtained?",["Apical 4-chamber view","Parasternal short-axis view","Parasternal long-axis view","Subcostal 4-chamber view"],2,"Left parasternal placement with the indicator toward the right shoulder gives the parasternal long-axis view; rotating toward the left shoulder gives the short-axis view.");
BI(2,'views',1,'C02_F06',"Which echocardiographic view is shown on the right?",["Apical long-axis view","Subcostal 4-chamber view","Apical 5-chamber view","Parasternal long-axis view"],3,"The PLAX view shows the RV anteriorly, the LV, mitral valve, LVOT/aortic root and LA, with the descending aorta in cross-section behind the LA.");
BI(2,'lv',2,'C02_F08',"Which measurement is this M-mode recording through the midventricle in the parasternal long axis mainly used for?",["Septal and inferolateral wall thickness and ventricular shortening","Mitral E-wave and A-wave velocities","Tricuspid annular plane systolic excursion","IVC collapsibility"],0,"M-mode through the midventricle from PLAX allows measurement of ventricular shortening and the thickness of the interventricular septum and inferolateral wall.");
BI(2,'views',2,'C02_F09',"While attempting a parasternal long-axis view, the operator gets this image showing too much of the LV apex. What is the most likely cause?",["Transducer too medial or too superior","Transducer too lateral or too inferior","Indicator pointed toward the left shoulder","Depth set too shallow"],1,"An off-axis PLAX with too much apex results from placing the transducer too laterally or too inferiorly.");
BI(2,'views',2,'C02_F10',"While aiming for a standard parasternal long-axis view, the operator obtains this image of the RV, tricuspid valve and RA. How should it be corrected?",["Rotate the indicator toward the left shoulder","Slide the probe one rib space up","Tilt the tail of the transducer down slightly","Tilt the tail of the transducer up"],2,"This is the right ventricular inflow view, which occurs when the tail is tilted up from a standard PLAX. Tilting the tail down slightly corrects it.");
BI(2,'views',2,'C02_F11',"While aiming for a standard parasternal long-axis view, the operator obtains this image showing the RV outflow tract, pulmonic valve and pulmonary artery. How should it be corrected?",["Tilt the tail of the transducer down","Rotate the indicator toward the left hip","Slide the probe laterally","Tilt the tail of the transducer up"],3,"This is the right ventricular outflow view, which occurs when the tail is tilted down from a standard PLAX. Tilting the tail up corrects it.");
BI(2,'views',1,'C02_F12',"Which landmark seen in this parasternal short-axis image defines it as the midventricular level?",["The anterolateral and posteromedial papillary muscles","The mitral valve leaflets","The aortic valve cusps","Absence of any intracavitary structure"],0,"The midventricular (papillary muscle) PSAX view is defined by the anterolateral (3 o'clock) and posteromedial (7 o'clock) papillary muscles.");
BI(2,'views',1,'C02_F13',"This parasternal short-axis image shows a small circular LV cavity with no papillary muscles or mitral valve. Which level is it?",["Aortic valve level","Apical level","Basal (mitral valve) level","Midventricular level"],1,"The apical PSAX view shows the LV without papillary muscles or mitral valve.");
BI(2,'views',1,'C02_F14',"At what level is this parasternal short-axis image of the LV obtained?",["Apical level","Midpapillary level","Basal (mitral valve) level","Aortic valve level"],2,"In the basal PSAX view, the anterior and posterior mitral valve leaflets are seen within the LV (the fish-mouth appearance).");
BI(2,'views',2,'C02_F15',"This parasternal short-axis view at the level of the aortic valve shows the RA, tricuspid valve, RV and pulmonic valve wrapping around the aortic valve. By what other name is it known?",["Right ventricular outflow view","Apical 5-chamber view","Basal short-axis mitral view","Right ventricular inflow-outflow view"],3,"The PSAX at the aortic valve and basal RV level is also called the RV inflow-outflow view, because the tricuspid inflow and pulmonic outflow are seen in one image.");
BI(2,'rv',3,'C02_F16',"Both parasternal short-axis images seem to show a flattened interventricular septum. The left one is from a patient with pulmonary hypertension. What best explains the right one?",["A normal heart imaged off-axis","Acute RV volume overload","Constrictive pericarditis","Severe LV hypertrophy"],0,"The left image shows true septal flattening from pulmonary hypertension. The right is a normal heart imaged off-axis, which can falsely suggest flattening, so the septum should be confirmed in multiple views.");
BI(2,'views',3,'C02_F17',"An operator attempting an apical 4-chamber view obtains this hybrid image with an elongated rather than circular LV. What is the most likely transducer error?",["Too close to the apex: too lateral or too inferior","Too close to the base: too medial or too superior","Indicator rotated 180 degrees","Tail tilted too far down"],1,"This is a hybrid between PSAX and A4C. Seen while attempting A4C, it means the transducer is too close to the base (too medial or superior). Seen while attempting PSAX, it means the transducer is too close to the apex.");
BI(2,'views',1,'C02_F18',"With the transducer at the point of maximal impulse and the indicator pointed toward the patient's left (3 o'clock), which view is obtained?",["Parasternal long-axis view","Subcostal 4-chamber view","Apical 4-chamber view","Parasternal short-axis view"],2,"The apical window with the indicator to the patient's left gives the A4C view, with the apex at the top of the screen and all 4 chambers shown.");
BI(2,'lv',2,'C02_F19',"In this standard apical 4-chamber view, which LV walls are displayed?",["Anterior and inferior","Anteroseptal and inferolateral","Inferior and lateral","Inferoseptal and anterolateral"],3,"A standard A4C shows the inferoseptal and anterolateral walls of the LV and the lateral wall of the RV, with the aortic valve out of view.");
BI(2,'views',2,'C02_F20',"In this apical 4-chamber view, the heart appears to lean to one side with the RV near the top of the screen. What is the cause?",["Transducer placed too medially","Transducer placed too laterally","Tail of the transducer tilted down","Indicator pointed toward the right shoulder"],0,"An off-axis A4C with the heart leaning and the RV near the top of the screen results from medial placement of the transducer.");
BI(2,'views',2,'C02_F21',"In this apical 4-chamber attempt, the beam is aimed at the inferior heart and the left atrium is foreshortened or absent. What correction should be made?",["Tilt the tail up","Tilt the tail down","Slide the transducer medially","Rotate the indicator clockwise 90 degrees"],1,"Aiming at the inferior heart foreshortens the LA and may show the coronary sinus. Tilting the tail down brings the plane back to the standard A4C.");
BI(2,'views',1,'C02_F22',"Which view is shown?",["Apical 4-chamber view","Apical long-axis view","Apical 5-chamber view","Subcostal 4-chamber view"],2,"The apical 5-chamber view adds the LV outflow tract and aortic root (the fifth chamber) in the center of an A4C-type image.");
BI(2,'lv',2,'C02_F23',"In this apical 2-chamber view, which LV wall is displayed on the right side of the screen?",["Inferior wall","Inferoseptal wall","Inferolateral wall","Anterior wall"],3,"The A2C view shows only the LV and LA. The anterior wall is on the right side of the image and the inferior wall is on the left.");
BI(2,'views',2,'C02_F24',"Which view is shown, taken from the apical window and displaying the LV, LA, aortic outflow and a sliver of RV?",["Apical long-axis view","Apical 2-chamber view","Parasternal long-axis view","Apical 5-chamber view"],0,"The apical long-axis (3-chamber) view shows the LV, LA, LVOT and aorta from the apex, giving a long-axis plane similar to PLAX but with the apex at the top.");
BI(2,'views',1,'C02_F26',"With the transducer below the xiphoid, held flat with an overhand grip and the indicator toward the patient's left, which view is obtained?",["Subcostal IVC long-axis view","Subcostal 4-chamber view","Apical 4-chamber view","Parasternal short-axis view"],1,"Subxiphoid placement with the indicator to the patient's left gives the subcostal 4-chamber view, using the liver as an acoustic window.");
BI(2,'views',1,'C02_F27',"Which acoustic window was used for this image?",["Parasternal","Apical","Subcostal","Suprasternal"],2,"In the subcostal 4-chamber view, the liver is in the near field and the RV is the chamber closest to the transducer, followed by the RA, LV and LA.");
BI(2,'fluid',2,'C02_F28',"What is being assessed with the M-mode cursor placed through the inferior vena cava in short axis?",["Hepatic vein flow reversal","RV free-wall thickness","Aortic pulsatility","IVC collapsibility"],3,"M-mode through the subcostal IVC records changes in its diameter over time, allowing measurement of collapsibility.");
BI(2,'views',2,'C02_F29',"Starting from the subcostal 4-chamber view, how is the transducer moved to the position shown to obtain the IVC long-axis view?",["Tilt the tail up and rotate counterclockwise until the indicator points to the head","Tilt the tail down and rotate clockwise until the indicator points to the feet","Slide to the right midaxillary line with the indicator to the head","Slide to the apex and rotate the indicator to the left shoulder"],0,"From the subcostal 4-chamber position, the tail is tilted up and the probe rotated counterclockwise so the indicator points to the head. The probe should be nearly vertical but still aimed at the heart.");
BI(2,'fluid',2,'C02_F30',"When the IVC is imaged in long axis, why is it important to show it entering the right atrium, as here?",["To measure hepatic vein Doppler flow","To confirm the vessel is not the aorta and to measure at the standardized cavoatrial junction","To estimate the right atrial area","To exclude tricuspid regurgitation"],1,"Showing the IVC entering the RA, often with a hepatic vein joining it, confirms the vessel is not the aorta. It also makes sure diameters are measured near the cavoatrial junction, where they are standardized.");
BI(2,'mass',2,'C02_F31',"While attempting a subcostal IVC long-axis view, the operator records this thick-walled tubular vessel that does not drain into the right atrium. What does this most likely show?",["Hepatic vein","Portal vein","Abdominal aorta mistaken for the IVC","IVC in short axis"],2,"This is the subcostal aorta. The IVC must be seen entering the RA so that the aorta is not mistaken for it, which would make IVC measurements wrong.");
BI(3,'mass',2,'C03_F01',"A patient with atrial fibrillation and an embolic stroke has this transesophageal image of the left atrial appendage. Why is TEE preferred over TTE for this question?",["TEE gives better views of the RV free wall","TEE is less invasive than TTE","TEE is not limited by air in the left mainstem bronchus","TEE images posterior structures such as the left atrial appendage much better"],3,"The image shows a thrombus in the left atrial appendage. TEE shows the LAA, interatrial septum and pulmonary veins far better than TTE, making it the modality of choice for ruling out an intracardiac source of embolus.");
BI(3,'views',1,'C03_F05',"What is the purpose of the maneuver shown while the TEE probe is being inserted?",["Displacing the mandible forward to help the probe pass","Confirming the endotracheal tube position","Preventing the patient from biting the probe","Measuring the depth of probe insertion"],0,"A jaw thrust lifts the mandible and tongue forward, which helps the TEE probe pass into the esophagus; a bite block protects the probe.");
BI(3,'views',3,'C03_F06',"This TEE view is obtained with the probe deep in the stomach, fully anteflexed, at an omniplane angle of 0 degrees. What is its main advantage?",["Best view of the left atrial appendage","Good Doppler alignment with the LV outflow tract and aortic valve","Visualization of the entire descending aorta","Assessment of IVC respirophasic variation"],1,"The deep transgastric long-axis view looks up from the LV apex and aligns the beam well for pulsed-wave Doppler in the LVOT and continuous-wave Doppler across the aortic valve. Stroke volume and cardiac output can be measured from it.");
BI(3,'mass',2,'C03_F07',"This TEE image was obtained while withdrawing the probe to examine the upper thoracic aorta, which is seen in the near field (Ao). Which view is it?",["Upper esophageal main pulmonary arterial view","Midesophageal descending aortic view","Upper esophageal aortic arch view","Midesophageal ascending aortic long-axis view"],2,"As the probe is withdrawn up the esophagus, the transverse aortic arch comes into view. The origin of the left subclavian artery can often be seen and followed from this view.");

// Image questions group 2
BI(4,'lung',1,'C04_F01',"High-frequency lung ultrasound of a healthy anterior chest wall. What is the bright horizontal line indicated by the arrows, lying just deep to and between the rib shadows (asterisks)?",["The pleural line","The first A line","A B line","The diaphragm"],0,"Ribs cast acoustic shadows (asterisks); the hyperechoic line just deep to them is the pleura (arrows). The fainter repeating horizontal lines deeper still are A lines from reverberation in aerated lung.");
BI(4,'lung',1,'C04_F02',"The anterolateral chest is divided into eight zones as shown. In a supine patient with suspected pneumothorax, which zones should be examined first with a high-frequency probe?",["Zones 4 and 8","Zones 1 and 5","Zones 3 and 7","Zones 2 and 6"],1,"Air rises and fluid drops. Zones 1 and 5 (upper anterior) are the least dependent and are checked first for pneumothorax. Zones 4 and 8 are checked for dependent effusion or edema.");
BI(4,'lung',2,'C04_F03',"This anterior lung scan shows repetitive horizontal hyperechoic lines (dashes). Which statement about this pattern is correct?",["It excludes pneumothorax at this rib space","It indicates interstitial syndrome","It also persists in pneumothorax, so lung sliding must be assessed","It indicates a nonaerated, consolidated lung"],2,"These are A lines (A-line profile), which come from reverberation between the pleura and air. Because air still sits against the parietal pleura in a pneumothorax, the A-line profile is preserved there too. Sliding, B lines or a lung point must be assessed to tell the two apart.");
BI(4,'lung',2,'C04_F05',"A trauma patient has absent lung sliding in zone 1. When the probe is slid laterally, the finding shown appears: lung sliding is present on one side of the screen and absent on the other. What does this finding most strongly support?",["Right mainstem intubation","Pleural effusion","Atelectasis","Pneumothorax"],3,"The lung point is the boundary where the visceral pleura moves in and out of contact with the parietal pleura. In the right clinical context it confirms pneumothorax, although pulmonary blebs can mimic it.");
BI(4,'lung',2,'C04_F06',"In an intubated patient with equivocal 2D lung sliding, M-mode at one rib space produces this tracing: periodic granular 'seashore' segments deep to the pleural line (asterisks). What can be concluded at this rib space?",["The pleurae are in contact, so pneumothorax is excluded","Pneumothorax is confirmed","Large pleural effusion is present","Diffuse alveolar-interstitial syndrome is present"],0,"This is the lung pulse: cardiac oscillations carried to the pleural line show up as rhythmic seashore segments. It needs visceral and parietal pleura to be in contact. It is seen in atelectasis or one-lung ventilation, and its presence rules out pneumothorax at that spot.");
BI(4,'lung',2,'C04_F07',"In a lower lateral (dependent) chest scan, hyperechoic vertebral bodies are visible above the diaphragm, as shown. What does this finding indicate?",["Normal aerated lung base","A nonaerated medium (fluid or consolidation) lies between the probe and the spine","Tension pneumothorax","Subcutaneous emphysema"],1,"Aerated lung normally blocks the view of the thoracic spine. When the vertebrae are visible above the diaphragm (spine sign), effusion or consolidation is transmitting sound to them. The sign is nonspecific and needs clinical correlation.");
BI(4,'lung',2,'C04_F08',"A febrile patient has a dependent pleural collection with the appearance shown. What does this appearance most likely indicate?",["Simple transudative effusion","Hemidiaphragm paralysis","Complex effusion that is more likely exudative","Normal lung base"],2,"The fluid contains hyperechoic septations, so this is a complex effusion. Complex effusions with echogenic material or septations are more likely exudative. Most simple anechoic effusions are transudates.");
BI(4,'lung',3,'C04_F09',"Two pleural effusions are shown. In panel A, no lung tissue is seen across the probe footprint. In panel B, lung lies close to the diaphragm and chest wall. What is the main practical implication of panel A?",["Thoracentesis is contraindicated","The effusion is too small to drain","It indicates a loculated empyema","It marks a safe site for ultrasound-guided thoracentesis"],3,"Both panels show a spine sign. When the lung edge is not visible within the probe footprint (panel A, large effusion), the site is considered safe for ultrasound-guided thoracentesis. Small effusions with lung close by (panel B) are harder to drain safely.");
BI(4,'lung',2,'C04_F10',"These panels go from left to right. Which change is shown?",["Progressive accumulation of B lines, reflecting increasing interstitial lung density","Progressive development of pneumothorax","Increasing pleural effusion","Evolving lung consolidation with air bronchograms"],0,"The left panel shows an A-line pattern. The panels to the right show more and more vertical, laser-like B lines that erase the A lines. Three or more B lines in one intercostal space make that region positive; two or more positive regions on each side define diffuse interstitial syndrome, such as pulmonary edema.");
BI(4,'lung',2,'C04_F11',"A hypoxic patient has the lung pattern shown deep to the rib shadows: no A or B lines, and a tissue-like, mixed-echogenicity texture arising from the pleura. What is this pattern?",["Pleural effusion","Lung consolidation (hepatization)","Pneumothorax","Normal lung"],1,"Consolidated or atelectatic lung loses its air and looks like liver tissue ('hepatization'). The differential includes pneumonia, mass, contusion, atelectasis and infarction.");
BI(4,'lung',3,'C04_F12',"Within an area of consolidated lung, the hyperechoic branching foci (arrows) shimmer with respiration on real-time imaging. What does this finding most strongly favor?",["Obstructive atelectasis","Pulmonary edema","Pneumonia","Pneumothorax"],2,"Dynamic air bronchograms are aerated bronchi surrounded by consolidated lung. They move or sparkle with breathing and are highly specific for pneumonia. Static air bronchograms can occur in both atelectasis and pneumonia.");
BI(4,'lung',2,'C04_F13',"What does the arrow point to in this lung ultrasound image?",["Rib acoustic shadow","Lung point","Small pleural effusion","Subpleural consolidation"],3,"The arrow marks a small, irregular hypoechoic area against the pleura (a subpleural consolidation), with a B line arising from it. In the right context it suggests pneumonia, and pulmonary infarcts from PE can look the same.");
BI(5,'abd',1,'C05_F01',"The curvilinear probe is placed in the right midaxillary line with the marker cephalad, as shown. Which FAST window does this produce?",["Hepatorenal recess (Morison's pouch)","Splenorenal recess","Subxiphoid cardiac view","Rectovesical pouch"],0,"The probe sits in the right midaxillary line with the marker cephalad. This gives the RUQ long-axis view of the hepatorenal recess. Sweep from above the diaphragm to the inferior tip of the liver.");
BI(5,'abd',1,'C05_F02',"In the FAST exam of a supine patient, why is the space shown between the liver and right kidney a key window?",["It is the best window for the abdominal aorta","It is the most dependent upper-abdominal space where free fluid collects","It is where pneumoperitoneum is best seen","It is the site of the retroperitoneal great vessels"],1,"In a supine patient, the hepatorenal recess (Morison's pouch) is the most dependent part of the upper abdomen. Free intraperitoneal fluid collects there first.");
BI(5,'abd',2,'C05_F03',"During the RUQ FAST view, why should the scan extend down to the inferior tip of the liver, as shown?",["To measure liver span","To visualize the gallbladder fundus","To check for fluid in the right paracolic gutter","To find the right renal artery"],2,"Free fluid may collect in the paracolic gutter at the inferior liver tip and can be missed if only the hepatorenal interface is scanned.");
BI(5,'abd',2,'C05_F04',"After blunt left-sided trauma, a hypotensive patient has the LUQ window shown. What does anechoic fluid in the indicated space (between spleen and kidney) most suggest?",["Hydronephrosis","Left pleural effusion","Renal cyst","Hemoperitoneum from splenic injury"],3,"The splenorenal recess is the LUQ FAST space where fluid collects. In blunt trauma this commonly means hemoperitoneum from splenic injury.");
BI(5,'abd',2,'C05_F05',"In this transverse bladder view, the uterus and rectum are visible behind the bladder. What does visualizing the uterus (or prostate) mean?",["The beam is angled into the pelvis, so the most dependent pelvic recess is being imaged","The probe is too cephalad and imaging the peritoneum","The bladder is overdistended","The view is inadequate for FAST"],0,"Seeing the uterus or prostate means the beam is directed into the pelvis. Anechoic fluid in the rectouterine (Douglas) or rectovesical pouch, the most dependent pelvic spaces, then means free fluid.");
BI(5,'abd',1,'C05_F07',"A cirrhotic patient is scanned with the curvilinear probe in the right lower quadrant, longitudinal, marker cephalad, fanning side to side, as shown. What is the main purpose of this scan?",["Assessing the appendix","Finding the largest pocket of ascites for paracentesis","Assessing the right kidney","Measuring the iliac arteries"],1,"Both lower quadrants are scanned to find the area with the most free fluid that is clear of bowel loops and vessels before paracentesis.");
BI(5,'abd',2,'C05_F09',"Before paracentesis in a coagulopathic cirrhotic patient, color Doppler over the planned entry site shows the finding indicated. What is the most appropriate action?",["Proceed, since abdominal wall vessels are not a concern","Correct coagulopathy and proceed through this site","Choose another needle track that avoids these vessels","Abandon paracentesis entirely"],2,"Engorged epigastric or periumbilical vessels lie in the planned needle path. In coagulopathic patients with liver disease, color Doppler should be used to plan a track that avoids them and reduces bleeding.");
BI(5,'abd',2,'C05_F10',"The RUQ FAST view in a trauma patient shows the anechoic stripe indicated. Which statement about this finding is correct?",["At least 500 mL is needed to see it","Its anechoic appearance confirms blood","It must be retroperitoneal","Ultrasound cannot reliably distinguish blood from other fluid"],3,"This is a positive RUQ FAST, with free fluid in Morison's pouch. Ultrasound can detect roughly 100–250 mL of peritoneal fluid in Morison's pouch under optimal conditions (smaller volumes in the pelvis), but fluid usually looks anechoic whatever it is, so its composition cannot be determined.");
BI(5,'abd',2,'C05_F14',"An incidental finding during a LUQ FAST view is the round anechoic lesion in the left renal cortex shown. What is the most appropriate next step to characterize it?",["Confirm with consultative ultrasound or CT; POCUS cannot make the final diagnosis","Diagnose a simple cyst and stop further workup","Arrange urgent nephrectomy","Aspirate under ultrasound guidance"],0,"This looks like a renal cyst: well-circumscribed, anechoic and cortical. Color Doppler helps exclude a vessel, but cysts can mimic renal cell carcinoma, so consultative ultrasound or CT is recommended for confirmation.");
BI(5,'abd',2,'C05_F15',"Four kidneys are shown (A-D). Which panel shows moderate hydronephrosis, with the 'bear claw' dilatation of the major and most minor calyces?",["Panel B","Panel C","Panel A","Panel D"],1,"A is normal. B is mild, with prominent collecting ducts. C is moderate, with the bear-claw dilatation of the calyces. D is severe, with markedly dilated sinuses and a thin cortex.");
BI(5,'dop',2,'C05_F17',"Pulsed-wave Doppler is placed on the hilar artery of a renal transplant (panel A). Which index is derived from this trace, and what value suggests allograft dysfunction?",["Pulsatility index above 1.2","Velocity time integral below 10 cm","Resistive index above 0.80","Acceleration time above 70 ms"],2,"Resistive index = (PSV - EDV)/PSV. A value above 0.80 suggests allograft dysfunction. Panel B shows normal continuous flow in the renal vein; absent or reduced venous flow suggests thrombosis.");
BI(5,'abd',2,'C05_F20',"A male trauma patient has the transverse pelvic view shown. Where is the anechoic collection behind the bladder?",["Within the bladder lumen","In the anterior abdominal wall","In the retroperitoneum","In the rectovesical pouch, the most dependent pelvic space"],3,"Fluid between the bladder and rectum in a male lies in the rectovesical pouch (rectouterine pouch in females). This is the most dependent pelvic space and indicates free pelvic fluid.");
BI(5,'abd',2,'C05_F21',"Why does the FAST bladder assessment include a sagittal view like this one, in addition to the transverse view?",["Free peritoneal fluid above the bladder dome may only be seen in the sagittal plane","The sagittal view is needed to measure the prostate","Only the sagittal view shows the rectum","The transverse view cannot detect pelvic fluid"],0,"In the sagittal view, fluid above the dome of the bladder lies within the peritoneal cavity. The transverse view mainly looks into the pelvis, so both views are needed.");
BI(5,'abd',1,'C05_F22',"An ICU patient with a Foley catheter has had falling urine output. Bladder ultrasound shows the image above. What is the most appropriate next step?",["Start furosemide for oliguric AKI","Troubleshoot or replace the obstructed, nondraining Foley catheter","Order a renal biopsy","Give a fluid bolus for prerenal oliguria"],1,"The bladder is large and distended with the Foley balloon inside it. The catheter is not draining (obstructed or malfunctioning), and this is post-catheter retention, not true oliguria.");
BI(5,'abd',2,'C05_F23',"Bladder dimensions are measured in transverse (A) and sagittal (B) planes, as shown. How is bladder volume calculated from these measurements?",["Length x width x height x 0.25","Length x width x 1.5","Length x width x height x 0.77","Pi x radius squared x length"],2,"Volume = L x W x H x a shape correction coefficient (0.77 in this source; about 0.7–0.72 in most POCUS protocols; 0.52 assumes a spherical bladder and tends to underestimate). Measuring directly in two planes is more reliable than automated bladder scanners when ascites is present.");
BI(5,'mass',2,'C05_F25',"This transverse epigastric view shows a vessel arising anteriorly from the aorta and branching into the common hepatic and splenic arteries. What is this configuration called?",["Mickey Mouse sign","Nutcracker sign","Bifurcation sign","Seagull sign"],3,"The celiac trunk splitting into the hepatic and splenic arteries forms the 'seagull' and marks the proximal abdominal aorta. On screen the IVC is to the left of the aorta and the vertebral body lies behind it.");
BI(5,'mass',1,'C05_F29',"While scanning for the abdominal aorta, panel A shows bowel gas causing 'dirty shadowing' that hides deeper structures. What simple maneuver produced the improved image in panel B?",["Jiggling the probe with gentle pressure to displace bowel gas","Switching to the high-frequency linear probe","Reducing the depth","Increasing the far-field gain"],0,"Air-fluid interfaces in bowel cause impedance mismatch and dirty shadowing. Jiggling the probe moves the gas out of the field of view and lets the beam reach the distal aorta.");
BI(5,'mass',2,'C05_F30',"A transverse view of the abdominal aorta is measured as shown (1.66 cm). Which statement about this measurement is correct?",["It should be inner wall to inner wall, so it overestimates the diameter","It is correctly measured outer wall to outer wall and is not aneurysmal","It meets the criterion for AAA","Aortic diameter should only be measured in the longitudinal plane"],1,"The aorta is measured in the transverse plane from outer wall to outer wall. AAA is defined as more than 3 cm, so 1.66 cm is normal.");
BI(5,'mass',2,'C05_F31',"In this transverse view of a dilated aorta, the calipers span the full vessel, including the echogenic material around the central anechoic lumen. Why is this the correct technique?",["Thrombus is not part of the aortic wall","It avoids mistaking the IVC for the aorta","Measuring only the patent lumen inside the mural thrombus would underestimate the diameter","Only the lumen diameter predicts rupture"],2,"This is an AAA (about 6 cm) with mural thrombus. Measuring outer wall to outer wall includes the thrombus. Measuring only the anechoic lumen would falsely underestimate aneurysm size.");
BI(5,'mass',2,'C05_F33',"Two aneurysm shapes are shown: A, a symmetric dilatation; B, an eccentric outpouching from one wall. Which statement about aneurysm B is correct?",["It is the most common infrarenal AAA type","It is best seen in the transverse plane","It always contains a dissection flap","It may be missed if the aorta is scanned in the transverse plane only"],3,"A is fusiform and B is saccular. Saccular aneurysms can be missed in the transverse plane alone, so the aorta must be scanned in both transverse and longitudinal planes.");
BI(5,'mass',3,'C05_F34',"A hypotensive patient with abdominal pain has the transverse mid-aortic image shown, with a linear flap in a dilated aorta below the SMA origin. What is the most appropriate next step?",["Scan the thoracic aorta (parasternal long-axis and suprasternal views); TEE if unstable","Diagnose an isolated abdominal dissection and treat medically","Repeat the FAST exam only","Measure the aorta inner wall to inner wall"],0,"An intimal flap means dissection. The thoracic aorta must be assessed (PLAX and suprasternal views) to tell Stanford A from B. CT or MR angiography suits stable patients, and TEE is often preferred if the patient is unstable.");
BI(5,'abd',2,'C05_F36',"The gallbladder is shown in long and short axis, with wall thickness measured on the anterior wall. Why is the anterior wall used?",["The anterior wall is closer to the liver","Posterior acoustic enhancement can falsely thicken the posterior wall","The posterior wall cannot be seen in the short axis","Gallstones always sit on the anterior wall"],1,"Fluid in the gallbladder causes posterior acoustic enhancement, which can make the posterior wall look falsely thick. Wall thickness is measured on the anterior wall, from outer wall to inner wall.");
BI(5,'abd',2,'C05_F37',"This cross-section of the portal triad has a 'Mickey Mouse' appearance. Which tool best tells the common bile duct apart from the hepatic artery here?",["M-mode","Tissue harmonic imaging","Color flow Doppler","Increasing depth"],2,"Portal vein = head, hepatic artery and CBD = ears. The CBD has no flow on color Doppler, while the hepatic artery and portal vein do.");
BI(5,'abd',2,'C05_F38',"The common bile duct is measured in long axis, as shown. Which statement about this measurement is correct?",["Measure outer wall to outer wall, as for the aorta","A CBD over 4 mm is always pathological, regardless of age","After cholecystectomy the CBD should be under 4 mm","Measure inner wall to inner wall; color Doppler helps exclude the adjacent hepatic artery"],3,"The CBD is measured from inner wall to inner wall. The upper limit is about 4 mm up to age 40, rising 1 mm per decade, and up to 10 mm after cholecystectomy. Color Doppler separates it from the hepatic artery running alongside.");
BI(5,'art',2,'C05_F41',"In panel A, a dependent hypoechoic collection (arrow) is seen in the gallbladder. With further fanning (panel B) it disappears. What is the most likely explanation?",["Side lobe artifact","Biliary sludge","Gallbladder polyp","Pericholecystic fluid"],0,"Sludge stays visible in every view. A dependent 'collection' that disappears on fanning is a side lobe artifact caused by the rounded shape of the gallbladder.");
BI(5,'abd',2,'C05_F42',"A febrile patient with RUQ pain has the gallbladder image shown: anterior wall 5.3 mm, pericholecystic fluid, and shadowing stones in the dependent wall. What is the most likely diagnosis?",["Acalculous cholecystitis","Acute calculous cholecystitis","Uncomplicated cholelithiasis","Biliary sludge only"],1,"An anterior wall thicker than 3 mm, pericholecystic edema and gallstones together indicate acute calculous cholecystitis, especially with a sonographic Murphy sign. Acalculous cholecystitis has the same features without stones or sludge.");
BI(5,'abd',2,'C05_F44',"A subxiphoid longitudinal scan shows the gastric antrum next to the inferior liver tip. Which measurement of this structure, together with age, is used to calculate gastric volume?",["Antral wall thickness","Antral longitudinal length","Antral cross-sectional area","Distance from the inferior liver tip"],2,"This is the gastric antrum. Gastric volume = 27.0 + 14.6 x antral CSA - 1.28 x age. A volume over 1.5 mL/kg raises aspiration risk.");
BI(5,'abd',1,'C05_F45',"After a nasogastric tube is inserted, agitated saline is injected through it while the epigastrium is scanned, and the image shown appears. What is this sign called, and what does it confirm?",["Sparkle sign; full stomach","Seashore sign; tube in the esophagus","Bubble sign; gastric outlet obstruction","Dynamic fogging; tube tip in the stomach"],3,"Bubbles appearing in the gastric antrum during injection of agitated saline ('dynamic fogging') confirm that the NG tube is in the stomach.");
BI(5,'abd',2,'C05_F46',"Before emergent intubation, gastric ultrasound shows the antral contents shown, indicating a full stomach. Besides particulate content, which calculated gastric volume also indicates increased aspiration risk?",["More than 1.5 mL/kg","More than 0.2 mL/kg","More than 5 mL/kg","Any volume over 50 mL"],0,"Particulate 'sparkling' matter in the antrum means a full stomach. Particulate content or a volume over 1.5 mL/kg increases aspiration risk during intubation.");
BI(5,'abd',1,'C05_F47',"For suspected small bowel obstruction, the abdomen is scanned in the systematic pattern shown. Where should this 'lawn mower' sweep begin in a patient with focal tenderness?",["Directly over the point of maximum tenderness","Away from the point of maximal tenderness, moving toward it","In the left upper quadrant only","At the umbilicus only"],1,"Small bowel loops float freely, so the whole abdomen is scanned systematically. Start away from the point of maximal tenderness (or in the RLQ) and work back and forth toward it.");
BI(5,'abd',2,'C05_F48',"A vomiting patient with abdominal distension has the bowel loop shown, with intraluminal particulate material. Which feature best supports mechanical small bowel obstruction rather than ileus?",["Loop diameter under 25 mm with no peristalsis","Bowel wall thickness of 1 mm","Fluid-filled loop over 25 mm with contents moving back and forth","Absence of intraluminal contents"],2,"Mechanical SBO shows noncompressible, fluid-filled loops over 25 mm, often with to-and-fro movement of contents or fecalization. Ileus shows absent or markedly reduced peristalsis, often with dilated loops as well, so loop diameter alone does not separate it from SBO.");

// Image questions group 3
BI(6,'lv',2,'C06_F01',"In this parasternal long-axis image at end-diastole, calipers measure septal thickness, LV internal diameter and posterior wall thickness, and the software reports an EDV of 119 mL from the single internal diameter. When is this volume estimate least reliable?",["When the LV has regional wall motion abnormalities or a geometry that differs from the formula's assumptions","When the measurement is made at end-diastole","When the patient is in sinus rhythm at a normal heart rate","When the internal diameter is measured at the mitral leaflet tips"],0,"The EDV (2D-Teich) is calculated from one linear dimension by the Teichholz formula, which assumes a uniform LV. Regional wall motion abnormalities, conduction abnormalities, chamber enlargement or altered geometry introduce significant error; the Simpson biplane method of disks is more reliable.");
BI(6,'lv',1,'C06_F02',"M-mode is placed through the mitral leaflet tips in the parasternal long-axis view. The calipers measure 1.3 cm. What does this finding indicate?",["Dynamic LVOT obstruction from systolic anterior motion","Depressed LV systolic function with increased E-point septal separation","Severe mitral stenosis with restricted leaflet opening","Normal LV systolic function"],1,"The calipers measure E-point septal separation, the gap between the anterior mitral leaflet at early-diastolic opening and the septum. In normal LV function the leaflet nearly touches the septum; a 13 mm gap (abnormal >7 mm) indicates depressed LV systolic function.");
BI(6,'lv',2,'C06_F03',"In this apical 4-chamber view, the M-mode cursor runs through the lateral mitral annulus and the red arrow marks the systolic excursion. What is being measured, and what value is abnormal?",["TAPSE; abnormal below 17 mm","E-point septal separation; abnormal above 7 mm","MAPSE; below 8 mm suggests EF under 50%","LV fractional shortening; abnormal below 25%"],2,"M-mode through the lateral mitral annulus records the longitudinal base-to-apex excursion of the mitral annular plane (MAPSE), a surrogate for LV longitudinal systolic function. A MAPSE above 10 mm is highly sensitive and specific for EF above 50%, and below 8 mm is associated with EF below 50%.");
BI(6,'lv',1,'C06_F04',"In this apical 4-chamber image, the end-diastolic LV endocardium is traced and the cavity is divided into a stack of disks along the long axis. What else is needed to complete the recommended volumetric assessment?",["A parasternal long-axis LV internal diameter at end-diastole","An M-mode recording of mitral annular excursion","A pulsed-wave Doppler sample in the LVOT","The same tracing in the apical 2-chamber view at end-diastole"],3,"This is the Simpson method of disks in the apical 4-chamber view, giving an EDV of 130 mL. The biplane method also traces the apical 2-chamber view at end-diastole to quantify LV volume.");
BI(6,'lv',2,'C06_F05',"This apical 4-chamber endocardial tracing is made at end-systole. The end-diastolic tracing in the same view gave an LV volume of 130 mL. What is the stroke volume from this view?",["About 49 mL","About 62 mL","About 81 mL","About 130 mL"],2,"The end-systolic tracing gives ESV of about 49 mL. Stroke volume = EDV - ESV = 130 - 49 = about 81 mL, and EF = SV/EDV = about 62%. Combining apical 4- and 2-chamber tracings gives the Simpson biplane volumes and EF.");
BI(6,'hemo',2,'C06_F06',"Pulsed-wave Doppler is recorded from the apical view and the red line traces one systolic envelope. Calipers measure the R-R interval. What other measurement is needed to calculate cardiac output?",["Tricuspid regurgitant peak velocity","LVOT diameter","Mitral E/A ratio","IVC end-expiratory diameter"],1,"The LVOT velocity-time integral (red tracing) multiplied by the LVOT cross-sectional area (from the LVOT diameter) gives stroke volume. Multiplying by the heart rate from the R-R interval gives cardiac output.");
BI(7,'rv',2,'C07_F03',"Panel B shows the same 3D right ventricle sliced at slightly different 4-chamber planes, giving basal diameters of 59, 57 and 55 mm. What is the main lesson for RV size measurement?",["The RV crescent shape makes linear size reliable from any apical plane","The subcostal view always overestimates RV size","Small changes in plane alter linear RV size, so the RV-focused view should maximize the basal diameter","RV size should be measured only in the parasternal long-axis view"],2,"Because the RV wraps around the LV as a crescent, small rotations of the 4-chamber plane change the linear RV dimensions. The RV-focused apical view aims to show the maximal basal dimension and the whole free wall.");
BI(7,'rv',2,'C07_F05',"In a patient with worsening right heart failure, subcostal short-axis images (panel B) show a D-shaped LV with the septum flattened throughout the entire cardiac cycle. What does this pattern indicate?",["Isolated RV volume overload, such as an atrial septal defect","Normal ventricular interdependence during positive-pressure ventilation","Constrictive pericarditis with respiratory septal bounce","RV pressure overload, with loss of the RV crescent shape"],3,"Septal flattening confined to diastole indicates RV volume overload. Flattening that persists through the whole cycle indicates RV pressure overload as the condition worsens, which limits LV filling and reduces stroke volume.");
BI(7,'rv',3,'C07_F07',"Pulsed-wave Doppler in the RVOT of a patient with undifferentiated pulmonary hypertension shows the envelope in panel B, with two distinct systolic peaks. What does this profile most strongly suggest?",["Markedly increased pulmonary vascular resistance with advanced RV dysfunction","Pulmonary hypertension due to left-sided heart disease with normal PVR","Normal RV-pulmonary artery coupling","Severe pulmonic valve stenosis"],0,"Panel B shows mid-systolic notching, a two-peaked envelope from reflected waves. It is associated with markedly increased PVR and advanced RV dysfunction in PAH. Late-systolic notching (panel C) is linked to moderate PVR rise and left heart disease, and panel A is normal.");
BI(8,'fluid',2,'C08_F01',"In a ventilated patient in shock, TEE shows mitral inflow with an E wave smaller than the A wave (left), and the transthoracic LVOT VTI is 10 cm (right). How should these findings be interpreted?",["High LV filling pressure; stop fluids","LV filling pressure not elevated and low stroke volume; fluid is likely tolerated and may increase stroke volume","Normal filling pressure with preserved stroke volume","Dynamic LVOT obstruction; give a beta-blocker"],1,"An E/A ratio of 0.8 or less indicates that LV filling pressure is not elevated, so fluid is likely to be tolerated. A VTI of 10 cm indicates low stroke volume. Serial E/A and VTI can then track the response, and fluids stop when VTI no longer rises or E/A and E/e' shift toward a raised-filling-pressure pattern.");
BI(8,'fluid',3,'C08_F02',"A ventilated patient in shock has pulse pressure variation above 13% (A). TEE in the same patient (B) shows a markedly dilated RV, and the CVP is 19 mm Hg. What is the best interpretation?",["True hypovolemia; give a fluid bolus","LV systolic failure; start an inotrope and give fluid","False-positive PPV caused by RV failure; more fluid is unlikely to help","Tamponade physiology; perform pericardiocentesis"],2,"PPV reflects only a defect in LV preload, whatever its cause. Here the defect comes from RV dilation and failure, not hypovolemia. Echocardiography separates the two, and further fluid often does not help in this setting.");
BI(8,'fluid',2,'C08_F03',"In a ventilated patient with circulatory failure and no spontaneous breaths, TEE at the upper esophageal 90 degree view combines 2D and M-mode of the superior vena cava. The SVC shows no respiratory collapse. What does this suggest?",["Hypovolemia requiring fluid","A gray zone where fluid is decided by risk-benefit","Tension pneumothorax","No need for further fluid"],3,"The SVC stays open throughout tidal ventilation (no respiratory variation), which suggests the patient will not benefit from more volume. Complete collapse suggests hypovolemia, and intermediate variation is a gray zone. A collapsibility index above 36% predicted fluid responsiveness (sensitivity 90%, specificity 100%; Vieillard-Baron 2004).");
BI(8,'fluid',2,'C08_F04',"Serial subcostal M-mode of the IVC at end-expiration in a ventilated patient in shock is shown before fluid (A) and after two fluid boluses (B, C). In panel C the diameter exceeds 25 mm. What is the appropriate interpretation?",["No further fluid is needed","The patient is still fluid responsive","The diameter is in the gray zone and uninformative","Abdominal hypertension is excluded"],0,"An end-expiratory IVC under 10 to 13 mm predicts fluid response, 13 to 25 mm is a gray zone, and over 25 mm predicts no response. Panel C shows an enlarged IVC after two boluses, so fluid should stop. Raised intra-abdominal pressure limits this index.");
BI(8,'fluid',3,'C08_F05',"A ventilated patient with circulatory failure has a small hyperkinetic LV with systolic cavity obliteration (A) and systolic anterior motion of the mitral valve (B). Which finding in panel C argues that hypovolemia is not the main problem?",["Complete inspiratory collapse of the SVC","No respiratory variation of the SVC","A dilated, plethoric IVC","An inverted mitral E/A ratio"],1,"A small LV with systolic exclusion and SAM can occur in hypovolemia or in vasoplegia. Significant SVC respiratory variation is not usually seen in the latter, so the absent SVC variation in panel C points away from simple volume depletion.");
BI(9,'rv',2,'C09_F02',"These images show the ASE thresholds for RV dilation. The right panel shows an RVOT diameter above 30 mm. In which view is that RVOT threshold applied?",["Subcostal 4-chamber view","Parasternal short-axis at the aortic valve level","Parasternal long-axis view","RV-focused apical 4-chamber view"],2,"RV dilation is defined by a basal diameter over 41 mm, mid diameter over 35 mm and length over 83 mm in the RV-focused A4C (left panel). It is also defined by an RVOT over 30 mm in the parasternal long-axis view (right panel), or a proximal RVOT over 35 mm and a distal RVOT over 27 mm in PSAX.");
BI(9,'rv',1,'C09_F03',"A hypotensive patient has this parasternal short-axis view, showing a markedly enlarged RV and a flattened interventricular septum making a D-shaped LV. What does this image demonstrate?",["Concentric LV hypertrophy","Large circumferential pericardial effusion","Severe hypovolemia with a small LV cavity","RV pressure and volume overload with ventricular interdependence"],3,"The dilated RV pushes the septum toward the LV, flattening it into a D shape. This ventricular interdependence reflects RV pressure and volume overload, as seen in massive PE.");
BI(9,'rv',2,'C09_F04',"An RV-focused apical 4-chamber view in a patient with suspected PE shows the sign marked at the RV apex. What does this sign describe, and what is its current diagnostic standing?",["Basal and mid-RV free wall hypokinesis with preserved apical function; suggests acute RV dysfunction but is not pathognomonic for PE","Global RV hypokinesis with apical thrombus; diagnostic of RV infarction","Apical RV akinesis with hyperdynamic base; specific for Takotsubo","Basal RV hyperkinesis with apical dyskinesis; excludes PE"],0,"The McConnell sign is basal and mid-RV hypokinesis with preserved apical contraction. It was first reported as 94% specific for PE, but that is now thought to be overestimated, and it is better seen as a marker of acute RV dysfunction. The shared apex in this image also suggests RV dilation.");
BI(9,'rv',3,'C09_F05',"In a patient with massive PE, RVOT pulsed-wave Doppler shows an acceleration time of 57 ms (A) and the peak tricuspid regurgitation gradient is 45 mm Hg (B). What is the significance of this combination?",["Chronic pulmonary hypertension with RV hypertrophy","A 60/60 sign, supporting acute PE in an RV unable to generate high pressure","Severe pulmonic stenosis","Normal RV-pulmonary artery coupling"],1,"The 60/60 sign is an acceleration time of 60 ms or less with a TR gradient of 60 mm Hg or less. It reflects an acutely afterloaded, unconditioned RV that cannot generate high pressures, and has about 94% reported specificity for PE.");
BI(9,'mass',2,'C09_F06',"A hypotensive patient with suspected PE has subcostal and RV inflow views (A, B) showing a mobile echodensity in the right atrium, plus mobile clot in the right pulmonary artery on PSAX (C). What is the prognostic significance of these findings?",["They are incidental and do not change PE risk","They exclude PE as the cause of hypotension","They indicate chronic thromboembolic disease with low short-term risk","They strongly support PE and are associated with more RV dysfunction, hemodynamic instability and mortality"],3,"The arrows show thrombus in the right atrium and right pulmonary artery. Intracardiac thrombus, stationary or in transit, strongly supports PE and is associated with increased rates of RV dysfunction, hemodynamic instability and mortality. Catheter-associated RA thrombus is present in up to 30% of patients with central lines.");
BI(9,'lung',2,'C09_F07',"Lung ultrasound in a patient with suspected pulmonary embolism shows a small, peripheral, pleural-based hypoechoic consolidation, next to a normal pleural line. What is the most likely explanation in this context?",["Large pleural effusion","Pneumothorax with lung point","Diffuse interstitial syndrome","Pulmonary infarction"],3,"Peripheral, pleural-based consolidations in a patient with suspected PE are consistent with pulmonary infarction. The adjacent pleura is normal.");
BI(9,'vasc',1,'C09_F09',"Transverse ultrasound at the groin shows the common femoral artery and vein without compression (left) and with probe compression (right), where the vein is no longer seen. What does this show?",["Normal compressible vein; no DVT at this level","Occlusive DVT of the common femoral vein","Arterial occlusion","Inadequate compression pressure"],0,"With probe pressure the common femoral vein collapses completely while the artery stays round. Full compressibility excludes DVT at this segment, which is the basis of the point-of-care compression exam.");
BI(9,'vasc',2,'C09_F10',"The probe is placed in the popliteal fossa as shown, with the popliteal vein superficial to the artery. What finding defines a positive compression exam at this site?",["Visible spontaneous echo contrast in the vein","A vein that does not compress despite pressure enough to deform the artery","Absence of color flow in the artery","A vein larger than the artery"],1,"DVT is diagnosed when the vein does not compress despite enough pressure to deform the adjacent artery. Imaging extends about 7 cm past the popliteal crease.");
BI(9,'vasc',1,'C09_F11',"Transverse groin ultrasound shows a normal common femoral vein and artery (left). A compression view (right) shows the vein with echogenic intraluminal material at the arrow. What is the diagnosis?",["Lymph node mimicking a vein","Normal vein with reverberation artifact","Common femoral vein DVT","Common femoral artery atherosclerotic plaque"],2,"The right panel shows a vein that does not collapse under compression and contains visible echogenic thrombus, confirming common femoral vein DVT. Thrombus is not always visible, so noncompressibility is the key criterion.");
BI(9,'vasc',2,'C09_F12',"During a groin compression exam, this oval structure with an echogenic center and internal color flow does not compress. What is it most likely to be?",["Common femoral vein thrombus","Pseudoaneurysm of the femoral artery","Great saphenous vein","Inguinal lymph node"],3,"The structure has a hypoechoic cortex, an echogenic hilum and hilar vascular flow, typical of a lymph node. A noncompressible node can easily be mistaken for thrombus, and color Doppler helps tell nodes apart from vessels.");
BI(9,'vasc',2,'C09_F13',"Pulsed-wave Doppler of the common femoral vein is recorded while the calf is manually squeezed. What result would suggest an occlusive DVT between the calf and the probe?",["Limited or no increase in flow with calf compression","A brisk augmentation of flow with calf compression","Respiratory phasic variation in flow","Pulsatile arterial-type waveform"],0,"Calf squeezing normally augments common femoral venous flow, as shown. An occlusive DVT in between would cause limited or no augmentation. The technique is controversial at the point of care because of low added yield.");
BI(10,'peri',2,'C10_F01',"Parasternal long-axis view shows two echo-free collections, one anterior to the descending thoracic aorta (white arrow) and one posterior to it (yellow arrow). How are they best classified?",["Both are pericardial effusion","White arrow is pericardial effusion; yellow arrow is pleural effusion","White arrow is pleural effusion; yellow arrow is pericardial effusion","Both are pleural effusion"],1,"The descending aorta is the landmark. Pericardial fluid tracks anterior to the descending aorta (white arrow), whereas a left pleural effusion lies posterior to it (yellow arrow).");
BI(10,'peri',2,'C10_F03',"An elderly man has hypotension after a fall. The apical 4-chamber view shows a pericardial effusion with right atrial collapse in late ventricular diastole and early systole. Which statement about this sign is correct?",["It is the most specific sign of tamponade","It occurs only during expiration","It is sensitive but less specific; specificity rises if collapse lasts over 30% of the cardiac cycle","It indicates left atrial compression from a loculated effusion"],2,"The thin-walled, low-pressure RA is usually the first chamber to collapse, during its relaxation phase (late diastole and early systole). RA collapse is sensitive but less specific, and becomes more specific when it lasts over 30% of the cycle. Pericardiocentesis of 850 mL improved this patient.");
BI(10,'peri',2,'C10_F04',"In the same patient, the subcostal view shows a pericardial effusion with right ventricular free wall collapse in diastole. Compared with right atrial collapse, RV diastolic collapse is:",["More sensitive and less specific","Equally sensitive and specific","Only seen in low-pressure tamponade","Less sensitive but more specific"],3,"RV collapse occurs in early diastole, first only during expiration (when right heart filling is lowest) and then throughout the respiratory cycle as tamponade worsens. It is less sensitive than RA collapse but more specific for tamponade.");
BI(10,'peri',3,'C10_F05',"A young tachycardic man with a pericardial effusion has M-mode through the RV and LV at the mitral leaflet tips (PLAX). The arrow marks inward motion of the RV free wall. Why is M-mode useful here?",["It times the RV free wall collapse to early diastole, which is hard to judge on 2D at high heart rates","It measures pericardial fluid volume","It shows respiratory variation of mitral inflow","It assesses the LV ejection fraction"],0,"M-mode has high temporal resolution, so it can confirm that the RV free wall collapses in early diastole even when the patient is tachycardic. That timing indicates tamponade physiology.");
BI(10,'peri',2,'C10_F06',"A woman with pulmonary hypertension and a pericardial effusion has hepatic vein pulsed-wave Doppler from the subcostal view. The arrow shows a prominent reversal wave during expiration. What does this indicate?",["Severe tricuspid stenosis","Expiratory diastolic hepatic flow reversal consistent with tamponade physiology","Normal hepatic venous flow","Portal hypertension"],1,"In tamponade, hepatic venous flow is often abnormal, with blunting or reversal of diastolic flow during expiration. Dilated hepatic veins also confirm raised venous pressure when the IVC is hard to image.");
BI(10,'peri',3,'C10_F11',"A woman with long-standing severe pulmonary hypertension has a large pericardial effusion, a severely dilated RV and a small compressed LV. Tricuspid inflow Doppler shows no significant respiratory variability. Why are the classic right-sided tamponade signs absent?",["Positive pressure ventilation abolishes inflow variation","The effusion is loculated behind the left atrium","High RV pressure exceeds pericardial pressure, so the RV resists collapse and the LV is compressed instead","Hypovolemia lowers the intrapericardial pressure"],2,"While RV pressure stays above intrapericardial pressure, the hypertrophied, high-pressure RV does not collapse. The LV becomes the compressed chamber, and respiratory inflow variability may be absent despite tamponade.");
BI(10,'peri',3,'C10_F12',"A woman with severe LV systolic dysfunction and marked LVH has tamponade, with marked RV collapse on subcostal imaging. Pulsed-wave Doppler shows no respiratory variation of mitral or tricuspid inflow. What explains this?",["Doppler inflow variation is always present in true tamponade","LV dysfunction makes right-sided collapse less sensitive","The effusion must be pleural rather than pericardial","A markedly raised wedge pressure means the pericardium limits RV but not LV filling, so pulsus paradoxus may be absent"],3,"With a high pre-existing PAWP, pericardial pressure mainly affects RV filling, so respiratory inflow variation (pulsus paradoxus) can be absent. RA and RV collapse occur with smaller effusions in LV dysfunction, so chamber collapse is more sensitive here.");

// Image questions group 4
BI(14,'dia',2,'C14_F01',"A ventilated patient is assessed before weaning. Panel C shows the transmitral pulsed-wave Doppler pattern obtained. What does this pattern indicate?",["E/A ratio of 2 or more with short deceleration time: restrictive filling with high LV filling pressure","E/A ratio below 1 with prolonged deceleration time: impaired relaxation with normal filling pressure","Normal diastolic filling pattern in a young patient with compliant ventricle","Pseudonormal filling that requires Valsalva to unmask high pressure"],0,"Panel C shows a tall E wave, small A wave (E/A at least 2) and a short E deceleration time. Per the legend, this restrictive pattern favours high LV filling pressure, unlike panel B (impaired relaxation, E/A <1).");
BI(14,'lung',2,'C14_F02',"In panel C (anatomic M-mode through the right hemidiaphragm, phased-array probe on the anterior-midaxillary line), measurement 1 is 2.7 cm during a normal breath and measurement 2 is 4.4 cm during a deep breath. How should this be interpreted?",["Severe diaphragmatic dysfunction, since excursion is below 5 cm","Diaphragmatic excursion within/above the normal range, arguing against diaphragm paralysis","Thickening fraction below 20%, predicting weaning failure","Paradoxical diaphragmatic motion consistent with phrenic nerve palsy"],1,"Panel C is an anatomic M-mode of diaphragm excursion (2.7 cm quiet, 4.4 cm deep breath). Normal excursion is about 1.5-2.5 cm and <1 cm indicates severe dysfunction, so this is preserved function; thickening fraction is measured on the zone of apposition (panels D-F), not here.");
BI(14,'lung',3,'C14_F03',"This patient has just completed a 1-hour spontaneous breathing trial. Using the regional scores shown in the 12 lung regions, what is the global lung ultrasound score and its implication?",["12; low risk, proceed with extubation","15; intermediate zone, extubation decision depends on clinical judgment","18; high risk of post-extubation failure, optimize aeration before extubation","24; complete loss of aeration, consider ECMO"],2,"Summing the 12 regional scores (0-3 each) gives 18. A global LUS score >17 at the end of the SBT is highly predictive of extubation failure (<13 predicts success), so aeration should be optimized and echocardiography used to look for raised LV filling pressure.");
BI(14,'lung',3,'C14_F04',"At the end of an SBT, lung ultrasound shows posterolateral consolidations and B lines with normal anterior fields (global score 20). Mitral inflow E = 0.75 m/s with E/A <1, and lateral E' = 0.11 m/s. What is the most likely mechanism of aeration loss?",["Cardiogenic pulmonary edema from raised LV filling pressure","Weaning-induced myocardial ischemia with systolic dysfunction","Lung derecruitment without significant diastolic dysfunction","Diaphragmatic paralysis with paradoxical motion"],2,"E/E' is about 6.8 with normal E' and E/A <1: impaired relaxation without increased filling pressure. With dependent posterolateral loss of aeration and normal anterior fields, the mechanism is lung derecruitment, so aeration should be optimized before extubation.");
BI(15,'mass',2,'C15_F02',"During VV ECMO cannulation, subcostal imaging (panel A) shows the return cannula tip 4.8 cm from the IVC-right atrial junction. What should the operator be told?",["Withdraw the cannula 2 cm to avoid the tricuspid valve","Advance the cannula toward the right atrium","The position is ideal; secure the cannula","Remove and re-site the cannula in the internal jugular vein"],1,"Panel A shows the return cannula tip lying in the IVC 4.8 cm short of the RA. The legend states this is too far from the RA and the surgeon was told to advance it; panel B shows the correct position at the IVC-RA junction.");
BI(16,'vasc',2,'C16_F05',"In a patient with severe traumatic brain injury, TCD of the MCA shows the pattern in panel C. If this pattern is persistent and reproducible in all insonated arteries, how is it regarded?",["A normal low-resistance waveform","A reversible high-resistance pattern that requires no action","An irreversible stage of raised ICP preceding circulatory arrest","An artifact caused by excessive wall filter"],2,"Panel C shows oscillating (to-and-fro) flow with diastolic flow reversal, meaning ICP exceeds diastolic BP. The chapter states that if this is persistent and reproducible in all arteries the stage is considered irreversible, progressing to systolic spikes (D) and absent flow (E).");
BI(16,'vasc',2,'C16_F06',"Through a temporal window, the distance from the temporal bone to the third ventricle is measured as shown. How is this measurement used?",["To estimate ICP from third ventricular width alone","To calculate optic nerve sheath diameter","To grade vasospasm using the Lindegaard ratio","To calculate midline shift as the difference between bilateral distances divided by 2"],3,"The image shows transcranial B-mode measurement from the temporal bone to the third ventricle/falx. Midline shift = (difference between the two sides' distances)/2; absence of shift does not exclude raised ICP.");
BI(16,'vasc',2,'C16_F07',"A patient on VA ECMO after cardiac arrest has absent brainstem reflexes. MCA Doppler shows the waveform below with mean velocity around 60 cm/s. What is the best interpretation?",["Nonpulsatile forward flow expected on ECMO, which rules out cerebral circulatory arrest","Loss of pulsatility indicating cerebral circulatory arrest","Reverberating flow consistent with brain death","Severe MCA vasospasm requiring nimodipine"],0,"The spectral trace is continuous and nonpulsatile (indistinct systole/diastole), as expected on VA ECMO, with mean velocity about 60 cm/s, showing intact cerebral perfusion and ruling out circulatory arrest. The circled HITS are microemboli that need further investigation.");
BI(16,'vasc',2,'C16_F08',"Left MCA insonation shows the findings displayed, with a mean flow velocity of 201 cm/s and aliasing on color and spectral Doppler. What is the correct interpretation?",["Normal MCA velocity for a young adult","Hypoperfusion due to shock","Markedly elevated velocity: vasospasm, hyperemia or stenosis, requiring clinical correlation","Cerebral circulatory arrest with systolic spikes"],2,"Normal MCA mean flow velocity is 40-80 cm/s; 201 cm/s is markedly elevated. Raised velocities can reflect vasospasm, hyperemia or stenosis, and clinical correlation is needed to distinguish them.");
BI(17,'abd',1,'C17_F03',"The probe position shown is for the left upper quadrant (splenorenal) FAST view. Why is the probe placed this far posteriorly, and where does LUQ free fluid most commonly collect?",["Spleen is posterior; fluid most often collects between diaphragm and spleen","Spleen is anterior; fluid most often collects at the inferior pole of the kidney","To avoid the stomach; fluid most often collects in the pelvis","To image the aorta; fluid most often collects in the splenorenal recess only"],0,"The splenorenal view is obtained at the left posterior axillary line at the level of the xiphoid because the spleen lies posteriorly. The most common LUQ site for fluid is between the diaphragm and spleen, so the subdiaphragmatic space, splenorenal recess and inferior kidney pole must all be seen.");
BI(17,'abd',1,'C17_F08',"This suprapubic E-FAST view was obtained by rotating the probe from the transverse plane with the indicator toward the head. What does this view add?",["Assessment of bladder wall thickness for cystitis","Visualization of the space posterior to the bladder and fluid between bowel loops","Measurement of bladder volume to guide catheterization","Evaluation of the iliac vessels for DVT"],1,"This is the longitudinal suprapubic view showing bladder, uterus and bowel. Turning the probe longitudinally shows the area posterior to the bladder and allows detection of free fluid between bowel loops.");
BI(17,'lung',2,'C17_F11',"In a trauma patient, lung sliding at this anterior site is hard to appreciate, but the B lines shown arise from the pleural line. What can be concluded?",["Pneumothorax is confirmed at this site","A lung point is present, confirming a small pneumothorax","Pneumothorax is ruled out at this site","The pleural line is not visualized, so the study is non-diagnostic"],2,"The image shows vertical hyperechoic B lines arising from the pleural line. B lines originate at the visceral pleura, so any B line rules out pneumothorax at that location even if sliding is absent.");
BI(18,'mass',1,'C18_F04',"A patient 10 days after a large anterior STEMI has this apical 4-chamber view. What is the most likely finding at the LV apex?",["Apical hypertrophic cardiomyopathy","Prominent apical trabeculation (noncompaction)","Near-field reverberation artifact","Large apical LV thrombus"],3,"The image shows an echogenic mass filling the LV apex in a post-infarct ventricle, consistent with a large apical LV thrombus, a recognized complication of anterior/apical infarction.");
BI(19,'dop',1,'C19_F01',"Panel C shows a TEE mid-esophageal 4-chamber view of a normal mitral valve, but diastolic inflow appears turbulent with a mosaic pattern. What is the explanation?",["Severe mitral stenosis","Inappropriately low color Doppler aliasing velocity (Nyquist limit)","Excessive wall filter","Color gain set too low"],1,"The color scale in panel C is set to about 15 cm/s, so normal inflow exceeds the Nyquist limit and aliases into a mosaic. Valvular color Doppler should use an aliasing velocity of 50-70 cm/s, as in panel A.");
BI(19,'valve',2,'C19_F02',"Panel D shows a zoomed parasternal long-axis view with a dotted line across the LVOT. For the continuity equation, how should this measurement be made?",["At the sinotubular junction in end-diastole","At the tip of the aortic leaflets in diastole","Inner edge to inner edge within 2-5 mm of the aortic leaflet hinge points in mid-systole","Outer edge to outer edge 2 cm below the valve in end-systole"],2,"Panel D measures LVOT diameter in a calcific AS patient. It is measured inner edge to inner edge within 2-5 mm of the hinge points in mid-systole, and the PW sample volume for LVOT TVI is placed at the same level.");
BI(19,'valve',2,'C19_F03',"A patient becomes hypotensive immediately after mitral valve repair. TEE shows the findings in panels A-C, with a late-peaking, dagger-shaped CW signal in panel C. What is the diagnosis?",["Severe calcific aortic stenosis","Paravalvular leak from the annuloplasty ring","Prosthetic mitral stenosis","Systolic anterior motion of the mitral valve with dynamic LVOT obstruction"],3,"Panel A shows the anterior mitral leaflet moving into the LVOT and contacting the septum, panel B shows LVOT turbulence with posteriorly directed MR, and panel C shows a late-peaking dagger-shaped CW profile, typical of dynamic LVOT obstruction (AS gives a more parabolic profile).");
BI(19,'valve',3,'C19_F04',"Using the measurements displayed (LVOT diameter 2.0 cm, LVOT area 3.14 cm², LVOT TVI 20 cm, aortic valve VTI 105.4 cm), what is the aortic valve area?",["About 0.6 cm²","About 1.2 cm²","About 1.6 cm²","About 3.1 cm²"],0,"Continuity equation: AVA = (CSA LVOT x TVI LVOT)/TVI AV = (3.14 x 20)/105.4 = about 0.6 cm², consistent with severe aortic stenosis.");
BI(19,'valve',2,'C19_F05',"Panel C is a TEE mid-esophageal short-axis en-face view of the aortic valve at maximal opening, with color Doppler on the right. What does it show?",["Normal trileaflet valve with laminar flow","Severe aortic stenosis with transvalvular turbulence","Aortic dissection flap within the aortic root","Quadricuspid valve with central regurgitation"],1,"Panel C shows thickened, restricted cusps with a small orifice at maximal opening and a mosaic (turbulent) color pattern. The legend identifies this as severe aortic stenosis, in contrast to the normal valve in panel B.");
BI(19,'valve',1,'C19_F08',"A young woman with exertional dyspnea has the findings shown: a hockey-stick anterior leaflet in diastole (panel A), flow convergence on the atrial side, and a prolonged pressure half-time (panel D). What is the diagnosis?",["Rheumatic mitral stenosis","Mitral annular calcification with calcific stenosis","Hypertrophic cardiomyopathy with SAM","Left atrial myxoma obstructing inflow"],0,"Panel A shows thickened leaflets with restricted excursion and diastolic doming of the anterior leaflet (hockey stick); there is flow acceleration and a prolonged PHT, with planimetry in panel E. These are classic for rheumatic mitral stenosis.");
BI(19,'valve',2,'C19_F09',"Panel D shows two tracings of the mitral inflow CW Doppler in calcific mitral stenosis. What is the effect of the red tracing compared with the green?",["It underestimates the mean gradient by missing the A wave","It correctly measures the PHT for valve area","It overtraces beyond the dense envelope and falsely elevates the mean gradient","It measures the regurgitant volume rather than the gradient"],2,"The green trace follows the high-density signal (mean gradient about 16 mm Hg, severe). The red trace extends past the dense envelope (overtracing), yielding a falsely elevated measurement.");
BI(19,'valve',2,'C19_F11',"A patient with a prosthetic tricuspid valve has the findings shown: turbulent inflow on color (B), mean gradient 12 mm Hg on CW (C), and a dilated IVC (D). What is the interpretation?",["Severe tricuspid regurgitation with RV volume overload","Normal prosthetic function with expected gradient","Pulmonary hypertension from left heart disease","Severe tricuspid (prosthetic) stenosis with raised RA pressure"],3,"Color shows flow acceleration and aliasing, CW shows an elevated mean gradient (12 mm Hg), and the IVC is dilated with reduced inspiratory collapse. Per the legend, this is severe prosthetic tricuspid stenosis causing increased RA pressure.");
BI(19,'valve',2,'C19_F12',"Panel A (parasternal long-axis) shows aortic regurgitation with flow convergence, vena contracta and jet width in the LVOT. Which measurement shown is used as a severity index?",["Jet length into the LV cavity","Ratio of jet width within 1 cm of the vena contracta to LVOT diameter","Jet area relative to left atrial area","Distance from flow convergence to the aortic sinus"],1,"Panel A marks flow convergence, vena contracta (black dotted line) and jet width (yellow arrows). The ratio of jet width measured within 1 cm of the vena contracta to LVOT diameter grades AR severity.");
BI(19,'valve',2,'C19_F13',"In a patient with a bicuspid aortic valve and an eccentric AR jet, panel D shows pulsed-wave Doppler of the descending thoracic aorta. What does the arrowed finding indicate?",["Holodiastolic flow reversal, supporting significant AR","Normal early diastolic reversal seen in all patients","Coarctation of the aorta with diastolic runoff","Patent ductus arteriosus shunt"],0,"Panel D shows large holodiastolic flow reversal in the descending thoracic aorta, a supportive feature of significant AR. Holodiastolic reversal in the abdominal aorta is more specific for severe AR.");
BI(19,'valve',2,'C19_F14',"The CW Doppler profiles of mitral and tricuspid regurgitation are shown. Panels C and F are dense with early peaking and rapid descent. What causes this shape?",["Rapid equalization of ventricular and atrial pressures in severe regurgitation","Low ventricular systolic pressure from LV failure","Poor beam alignment underestimating velocity","Prolonged isovolumic contraction"],0,"Signal density rises with regurgitation severity. The early-peaking, rapidly descending triangular profile in C and F reflects rapid equalization of ventricular and atrial pressures in severe regurgitation.");
BI(19,'valve',3,'C19_F15',"Panel B shows a large flow convergence of mitral regurgitation, and panel C shows its CW profile traced two ways (white and red). Which statement is correct?",["The white trace is correct because it includes all signal","The regurgitation is holosystolic, so the large PISA confirms severe MR","The MR is late systolic, and only the dense red trace should be used to avoid overestimating regurgitant volume","Pressure half-time from this trace grades MR severity"],2,"Panel C shows late systolic (non-holosystolic) MR, so a large convergence may still give a modest regurgitant volume. The VTI should include only the dense signal (red); the white overtrace gives a spuriously high regurgitant volume.");
BI(19,'valve',2,'C19_F16',"Panel A shows pulsed-wave Doppler from a hepatic vein, with the arrowed flow above the baseline during systole. What does this indicate?",["Severe mitral regurgitation","Systolic flow reversal from severe tricuspid regurgitation","Normal hepatic venous flow","Constrictive pericarditis with expiratory reversal"],1,"Panel A shows systolic flow reversal in a hepatic vein (red arrow), a marker of severe tricuspid regurgitation. Panels B and C show the equivalent markers for severe AR (abdominal aorta) and severe MR (pulmonary vein).");
BI(19,'valve',3,'C19_F18',"Using the PISA data shown for aortic regurgitation (aliasing velocity 40 cm/s, PISA radius 0.69 cm, peak AR velocity 455 cm/s, regurgitant TVI 221 cm), what are the EROA and regurgitant volume?",["0.10 cm² and 22 mL","0.40 cm² and 88 mL","0.60 cm² and 133 mL","0.26 cm² and 58 mL"],3,"EROA = (2 x pi x 0.69² x 40)/455 = 0.26 cm²; regurgitant volume = 0.26 x 221 = 58 mL. The Nyquist baseline is shifted toward the jet (panel C) to enlarge the hemisphere for accurate radius measurement.");
BI(19,'valve',1,'C19_F19',"A patient with sudden chest pain and hypotension undergoes TEE, shown in panels A-C (mid-esophageal long- and short-axis views with color). What is the cause of the torrential aortic regurgitation?",["Type A aortic dissection flap prolapsing into and preventing closure of the aortic valve","Infective endocarditis with leaflet perforation","Bicuspid aortic valve with eccentric jet","Ruptured sinus of Valsalva aneurysm into the RV"],0,"Panel A shows a dissection flap from the aortic sinus prolapsing into the valve, panel B shows the flap obstructing valve closure, and panel C shows torrential AR filling the LVOT with a wide vena contracta: acute AR from type A dissection.");
BI(19,'valve',3,'C19_F20',"The mitral annular diameter (4.23 cm, panel A) and PW Doppler TVI at the annulus (panel B) are obtained in a patient with aortic regurgitation. How are they used?",["To calculate mitral valve area by the continuity equation","To calculate mitral inflow stroke volume, which is subtracted from LVOT stroke volume to give AR regurgitant volume","To calculate the AR pressure half-time","To estimate LA pressure using E/e'"],1,"Mitral annular area = pi(D/2)² multiplied by the annular TVI gives mitral stroke volume. In the stroke volume method, AR regurgitant volume = LVOT stroke volume minus mitral annular stroke volume.");
BI(19,'valve',2,'C19_F22',"A patient with acute myocardial infarction has moderate MR (panels A-B). When the heart rate rises to 101/min, the MR worsens and the CW signal changes to panel D. What does the panel D profile represent?",["Mild MR with low-velocity signal","Dynamic LVOT obstruction","V-wave cutoff sign: rapid LV-LA pressure equalization in severe MR","Late systolic MR from mitral valve prolapse"],2,"Panel D shows a dense, early-peaking signal with rapid deceleration (V-wave cutoff sign), indicating severe MR with rapid pressure equalization. Ischemic (Carpentier IIIb) MR changes dynamically with LV loading and function.");
BI(19,'valve',2,'C19_F23',"TEE panel C shows a flail P2 segment of the posterior mitral leaflet. In which direction does the regurgitant jet go (panel D)?",["Posteriorly, toward the flail leaflet","Centrally into the LA","Into the left atrial appendage only","Anteriorly, away from the flail leaflet"],3,"Panels C-D show a flail P2 segment with an anteriorly directed jet and large flow convergence. Jets are usually directed away from the flail or prolapsing leaflet, which helps identify the leaflet involved.");
BI(19,'valve',2,'C19_F24',"Two patients have the same MR regurgitant volume. Patient B's eccentric jet looks smaller on color Doppler than patient A's central jet. Why?",["Patient B has a lower driving pressure across the valve","The Coanda effect makes wall-hugging jets look smaller, so jet area underestimates severity","The Nyquist limit was set higher in patient B","Patient B has a smaller left atrium"],1,"Panel A shows a large central jet and panel B a wall-hugging eccentric jet. The Coanda effect makes eccentric jets look less severe despite equal regurgitant volume, so jet area should not be used alone to grade severity.");
BI(19,'valve',3,'C19_F25',"Panel C (RV inflow view) in a patient with carcinoid heart disease shows a large coaptation gap and relatively laminar tricuspid regurgitant flow. What is the correct interpretation?",["Laminar flow indicates trivial TR","Laminar flow indicates tricuspid stenosis","The jet represents an atrial septal defect","The fixed open leaflets create a large regurgitant orifice, so laminar flow here signals severe TR"],3,"Carcinoid fixes the leaflets open with a large coaptation gap. The very large orifice gives laminar reflux and a short CW signal from rapid RV-RA pressure equalization. This is severe TR, supported by the dilated IVC in panel D.");

// Image questions group 5
BI(20,'valve',2,'C20_F01',"A febrile patient with a bioprosthetic aortic valve and bacteremia undergoes TEE. Besides the vegetation (yellow arrow), what does the heterogeneous periannular thickening (red arrows) extending toward the mitral-aortic intervalvular fibrosa most likely represent?",["Periannular abscess","Normal prosthetic sewing ring","Lambl's excrescence","Papillary fibroelastoma"],0,"TEE LVOT view (A) and biplane imaging (B) show a vegetation on the bioprosthesis plus heterogeneous thickening of the posterior periannular tissue extending into the mitral-aortic intervalvular fibrosa, consistent with periannular abscess complicating prosthetic valve endocarditis.");
BI(20,'valve',2,'C20_F03',"A patient with a bicuspid aortic valve has viridans streptococcal bacteremia. TTE (A) showed a thickened valve without definite vegetation. What do the TEE images (B and C) reveal?",["Isolated mild aortic regurgitation only","Vegetation on the conjoined cusp with perivalvular abscess","Calcified bicuspid valve without infection","Papillary fibroelastoma on the ventricular side"],1,"TEE shows a vegetation on the conjoined right-left cusp (blue arrow) and a thickened aortic annulus (B, red arrow); transgastric imaging (C) shows heterogeneous thickening of the basal anteroseptum consistent with abscess. Both were missed on TTE. This illustrates why TEE is needed when suspicion remains high despite a nondiagnostic TTE.");
BI(20,'valve',2,'C20_F04',"TTE (A, C) and TEE (B, D) images from patients with infective endocarditis are shown. What additional information did TEE provide for the mitral lesion seen on TTE (A)?",["It showed the lesion was a calcified annulus","It excluded vegetation entirely","It showed multiple lesions attached to both anterior and posterior leaflets","It showed the lesion was attached only to the chordae"],2,"TTE (A) shows a single mitral vegetation prolapsing into the atrium; TEE (B) of the same valve shows multiple lesions attached to both the anterior and posterior leaflets. TEE better defines extent and attachment of vegetations.");
BI(20,'valve',2,'C20_F06',"Panel D shows a thin, linear filament about 2 mm long on the aortic valve in a patient being evaluated for endocarditis. Which diagnosis best fits this lesion?",["Papillary fibroelastoma","Infective vegetation","Nonbacterial thrombotic endocarditis","Lambl's excrescence"],3,"The figure shows valvular masses that mimic vegetation. Panel D is a Lambl's excrescence: a thin, linear lesion about 2 mm long on the aortic valve, unlike the bulky, mobile soft-tissue look of a vegetation.");
BI(20,'valve',2,'C20_F07',"A 32-year-old man who injects drugs has S aureus bacteremia. TTE (A, B) shows bulky tricuspid vegetations. Beyond the vegetations, what complication does TEE (C, D) demonstrate?",["Leaflet perforation with perivalvular abscess at the tricuspid base","Pulmonic valve vegetation","Ventricular septal rupture","Right atrial myxoma"],0,"TEE shows large tricuspid vegetations (red arrows), leaflet perforation with regurgitation on color (orange arrow), and a perivalvular abscess at the tricuspid valve base (blue arrows).");
BI(20,'valve',3,'C20_F08',"A patient with aortic valve endocarditis has this TEE showing a saccular outpouching of the anterior mitral leaflet (red arrow). What is the main acute hazard of this lesion?",["Dynamic LVOT obstruction","Rupture causing acute severe mitral regurgitation","Mitral stenosis from leaflet fusion","Complete heart block"],1,"This is a mycotic pseudoaneurysm of the anterior mitral leaflet, caused by an AR jet hitting the leaflet or by infection spreading from the intervalvular fibrosa. If it ruptures, it can cause acute severe MR.");
BI(20,'valve',3,'C20_F09',"Intraoperative TEE in a patient with aortic valve endocarditis shows a thickened region between the aortic and mitral valves with an echolucent cavity (green arrow). What does the echolucent space most likely represent?",["Normal transverse sinus","Left atrial appendage thrombus","Pseudoaneurysm forming within a mitral-aortic intervalvular fibrosa abscess","Dilated coronary sinus"],2,"The image shows a large abscess of the mitral-aortic intervalvular fibrosa. An echolucent region within it is a pseudoaneurysm forming as the abscess cavity breaks down.");
BI(20,'valve',3,'C20_F10',"A patient with aortic valve endocarditis has an echolucent space around the posterior aortic annulus on TEE. Color Doppler (C, E) shows systolic flow from the LVOT directly into this space, which expands in systole. What does this indicate?",["Sterile periannular thickening","Normal paravalvular backflow","Lambl's excrescence","Fistula communicating with the periannular abscess cavity"],3,"Systolic color flow from the LVOT into the echolucent periannular space, which expands in systole, shows a communication (fistula). The TTE had shown only a thickened valve with AR and an apparently intact root.");
BI(20,'valve',2,'C20_F11',"A TEE commissural view (A) of a patient with mitral endocarditis shows vegetations on the posterior leaflet. Color Doppler (B, green arrow) shows a regurgitant jet through the body of the P1 segment. What mechanism of MR is shown?",["Leaflet perforation","Annular dilatation","Restricted leaflet from tethering","Chordal rupture with flail"],0,"Color flow crosses the body of the P1 scallop rather than the coaptation line, which identifies a leaflet perforation. The mechanism of regurgitation matters for surgical planning.");
BI(20,'valve',3,'C20_F12',"3D TEE color Doppler (D) of the mitral valve in a patient with a large anterior-leaflet vegetation shows a jet from the atrial view (yellow arrows) but only trivial transvalvular regurgitation from the ventricular view (blue arrow). What does this demonstrate?",["Paravalvular leak at the sewing ring","Regurgitation through a perforation of the anterior leaflet","Severe central MR from annular dilatation","Flow through an atrial septal defect"],1,"3D imaging shows a perforation of the anterior leaflet through the vegetation. 3D color shows regurgitation through the perforation, with only trivial flow across the coaptation line.");
BI(20,'valve',3,'C20_F13',"TEE in a patient with prosthetic aortic valve endocarditis shows heterogeneous thickening of the posterior annulus extending into the intervalvular fibrosa (A, B). Color Doppler (C) shows no flow into the lesion. Best interpretation?",["Fistula from LVOT to aortic root","Paravalvular dehiscence with severe leak","Periannular abscess without fistula","Normal postoperative thickening only"],2,"The thickened periannular tissue is an abscess. Color Doppler shows no communication between the LVOT and the aortic root, so there is no fistula.");
BI(20,'valve',2,'C20_F14',"In patients with infected prosthetic valves, color Doppler (A, B, D) shows regurgitant jets passing outside the prosthetic sewing ring at sites of abnormal annular motion. What is the diagnosis?",["Normal closing backflow (washing jets)","Prosthetic leaflet thrombosis","Central transvalvular regurgitation","Prosthetic valve dehiscence with paravalvular regurgitation"],3,"The images show dehiscence of infected aortic and mitral prostheses, with color flow passing around the sewing ring (periprosthetic regurgitation) at the sites of dehiscence. This is seen on both TEE and TTE.");
BI(20,'valve',3,'C20_F15',"A patient with a mitral prosthesis presents with heart failure and bacteremia. 3D TEE in the surgeon's view with 3D color (right panel) is shown. What does it demonstrate?",["Two discrete sites of perivalvular regurgitation from focal dehiscence","Normal washing jets within the prosthesis","Left atrial appendage thrombus","Prosthetic leaflet stenosis"],0,"3D TEE localizes focal dehiscence of the mitral prosthesis. 3D color shows 2 separate jets outside the sewing ring (red and blue arrows), which helps plan surgical or percutaneous repair.");
BI(20,'mass',2,'C20_F16',"A bacteremic patient with a cardiac implantable electronic device has these TEE/TTE images showing soft-tissue masses attached to device leads in the RA, RV and SVC. What is the key interpretive limitation?",["Lead masses can be reliably diagnosed as infection by size alone","Lead vegetations look similar to thrombus, so diagnosis needs clinical correlation","TTE is more sensitive than TEE for lead lesions","Masses on leads are always calcification artifacts"],1,"The figure shows lead-associated masses (superinfected thrombus, vegetations) and mimics. Infectious vegetations on leads look echocardiographically similar to thrombus, so the diagnosis must be guided by clinical scenario and pretest probability.");
BI(21,'rv',2,'C21_F02',"A ventilated ARDS patient has this transgastric short-axis view of the LV. At end-systole the septum flattens toward the LV (arrow), producing a D-shaped cavity. What does this indicate?",["LV volume overload","Hypovolemia with small LV cavity","RV pressure overload (acute cor pulmonale)","Constrictive pericarditis"],2,"End-systolic paradoxical septal motion with a D-shaped LV reflects RV systolic pressure overload, the hallmark of acute cor pulmonale in ARDS.");
BI(21,'rv',2,'C21_F03',"A hypotensive ARDS patient has RV dilatation on subcostal TTE (A). TEE M-mode of the SVC (B) shows no respiratory variation during tidal ventilation. What is the most appropriate fluid strategy?",["Give a 500 mL crystalloid bolus","Perform passive leg raise and give fluid if positive","Give fluid guided by IVC diameter","Avoid further fluid expansion; treat RV failure"],3,"A dilated RV with no respiratory variation of the SVC strongly suggests RV failure with no further fluid requirement. Management should target RV failure (norepinephrine, ventilator adjustment, prone positioning) rather than volume.");
BI(21,'mass',1,'C21_F04',"Agitated saline is injected into a hypoxemic ARDS patient and this apical 4-chamber view is obtained. What does the image demonstrate?",["Right-to-left shunt through a patent foramen ovale","Normal pulmonary capillary filtering of bubbles","Left-to-right shunt through a ventricular septal defect","Spontaneous echo contrast from low flow"],0,"Contrast fills the right heart and is also seen in the LA and LV, showing bubbles crossing from right to left through a patent foramen ovale. This is relevant in ARDS because high RV pressures can open a PFO and worsen hypoxemia.");
BI(21,'mass',2,'C21_F05',"In refractory ARDS, TEE midesophageal views before (A) and after (B) starting venovenous ECMO are compared. What effect of VV ECMO is shown?",["Worsening RV dilatation from cannula obstruction","Unloading of the previously dilated RV","New pericardial tamponade","LV distension requiring venting"],1,"Before ECMO the RV was markedly dilated; after VV ECMO began, the RV was unloaded. Correcting hypoxemia and hypercapnia lowers pulmonary vascular resistance. Panel C confirms the venous cannula sits just at the IVC-RA junction.");
BI(22,'lung',1,'C22_F01',"A linear-probe intercostal lung image is shown, and lung sliding was present on the live clip. How should this pattern be interpreted?",["Alveolar-interstitial syndrome","Pneumothorax","Normally aerated lung surface","Subpleural consolidation"],2,"A smooth pleural line between rib shadows with horizontal reverberation (A-line) pattern and lung sliding is the pattern of healthy, normally aerated lung.");
BI(22,'lung',2,'C22_F02',"Lung ultrasound in a febrile hypoxemic patient shows lung tissue with a liver-like echotexture above a pleural effusion. This sonographic finding is most specific for which process?",["Interstitial pulmonary edema","Pneumothorax","Pulmonary embolism","Lobar or translobar alveolar consolidation (pneumonia)"],3,"Sonographic hepatization occurs when consolidated, exudate-filled lung transmits ultrasound like solid tissue and looks like liver. It is specific for lobar or translobar pneumonia.");
BI(22,'lung',2,'C22_F04',"Hyperechoic punctate and branching foci are seen within consolidated lung above an effusion. Which feature of these foci makes them more specific for pneumonia than for atelectasis?",["Dynamic movement with respiration","Their absence on M-mode","Associated anechoic pleural fluid","Their alignment parallel to the pleural line"],0,"These are sonographic air bronchograms within consolidation. Dynamic air bronchograms (which move with respiration) are more specific for pneumonia (about 94%) than for resorptive atelectasis.");
BI(22,'lung',1,'C22_F05',"Lung ultrasound shows well-defined vertical hyperechoic artifacts arising from the pleural line and reaching the bottom of the screen. What do these indicate?",["Normal lung","Increased interstitial and septal fluid (alveolar-interstitial syndrome)","Pneumothorax","Pleural effusion"],1,"These are B lines, generated by thickened interlobular septa. Multiple B lines indicate alveolar-interstitial syndrome, which is seen in pulmonary edema and in early pneumonia.");
BI(22,'lung',2,'C22_F09',"A patient with acute hypoxemic respiratory failure has this lung ultrasound showing coalescent vertical artifacts beneath a pleural line. Which accompanying feature would favor ARDS over cardiogenic pulmonary edema?",["Thin, regular pleural line with homogeneous B lines","Large bilateral pleural effusions","Thickened, irregular pleural line with nonhomogeneous B lines","Preserved lung sliding with E/e' of 16"],2,"The figure shows B lines in ARDS with a thickened pleural line. ARDS typically has pleural thickening over 2 mm, irregularity, nonhomogeneous B lines with spared areas, and subpleural consolidations. CPE shows a thin, regular pleura with homogeneous B lines.");
BI(22,'lung',2,'C22_F11',"In a patient with diffuse bilateral B lines elsewhere, one intercostal space shows this pattern of regular horizontal A lines under a thin pleural line. How does this finding help the differential diagnosis?",["It confirms pneumothorax","It indicates large pleural effusion","It favors cardiogenic pulmonary edema","Spared areas of normal lung favor ARDS over cardiogenic edema"],3,"The image shows normal lung (A-line pattern). In ARDS, involvement is heterogeneous and areas of normal lung are spared. CPE usually produces homogeneous B lines with no spared areas.");
BI(23,'fluid',2,'C23_F01',"In a hypotensive patient, the LV area is traced at end-diastole in the parasternal short-axis view at the papillary muscle level. Which indexed value is considered significant for hypovolemia?",["Less than 5.5 cm²/m²","Less than 10 cm²/m²","Greater than 15 cm²/m²","Less than 2 cm²/m²"],0,"The image shows LVEDA measurement. An LVEDA below 5.5 cm²/m² suggests hypovolemia but usually appears only with severe volume depletion, so a normal value does not exclude fluid responsiveness.");
BI(23,'hemo',2,'C23_F02',"A ventilated patient in shock with normal LV function has this pulsed-wave Doppler of the LVOT. Peak velocity varies minimally from beat to beat. What does this suggest as the cause of shock?",["Hypovolemia","Reduced systemic vascular resistance rather than hypovolemia","Dynamic LVOT obstruction","Severe aortic stenosis"],1,"Minimal respiratory variation in LVOT peak velocity argues against preload dependence. With normal cardiac function, reduced SVR (vasoplegia) is the more likely cause of shock.");
BI(23,'hemo',3,'C23_F03',"A hypotensive patient with a hypercontractile LV has this continuous-wave Doppler through the LVOT, showing a late-peaking, dagger-shaped profile (about 4 m/s). Which intervention is most likely to worsen the hemodynamics?",["Volume resuscitation","Stopping inotropes","Reducing preload (e.g., diuresis or increasing PEEP)","Adding a pure vasoconstrictor"],2,"A dagger-shaped late-peaking LVOT signal indicates dynamic LVOT obstruction, often with SAM and MR. Lowering preload (Valsalva, PEEP, diuresis) narrows the LVOT and worsens the obstruction. Volume often helps.");
BI(23,'lung',1,'C23_F04',"A patient with hypotension after central line insertion has this M-mode over the pleural line, showing horizontal lines above and below the pleura without a granular pattern. What does it suggest?",["Normal lung sliding (seashore sign)","Lung pulse from consolidation","Pleural effusion (sinusoid sign)","Absent lung sliding consistent with pneumothorax"],3,"This is the barcode (stratosphere) sign: lack of lung sliding. Together with absent B lines and absent lung pulse, it strongly suggests pneumothorax.");
BI(24,'shock',2,'C24_F02',"During PEA arrest, a pulse-check subcostal view shows a markedly dilated right heart with a plethoric IVC (panel B). What reversible cause should be suspected?",["Massive pulmonary embolism","Severe hypovolemia","Cardiac tamponade","Tension pneumothorax"],0,"EASY-ALS findings in pseudo-PEA: (A) effusion = tamponade, (B) dilated RV with plethoric IVC = pulmonary embolism, (C) dilated LV = myocardial infarction, (D) small underfilled heart with flat IVC = severe hypovolemia.");
BI(25,'vasc',1,'C25_F01',"A novice is setting up for ultrasound-guided right IJV cannulation as shown. Which probe approach and orientation are demonstrated?",["Long-axis in-plane, marker cephalad","Short-axis out-of-plane, marker toward the operator's left (patient's right)","Oblique view, marker caudad","Short-axis in-plane, marker toward the patient's right"],1,"The screen is in the operator's line of sight (A), and a transverse short-axis (out-of-plane) view is used with the probe marker toward the operator's left (B, yellow arrow). With the operator at the head of the bed this is the patient's right, so the left of the screen matches the operator's left. This is the recommended setup for novices.");
BI(25,'vasc',1,'C25_F02',"Before ultrasound-guided vascular access, the probe indicator and screen indicator are aligned on the same side, as shown. What is the purpose of this alignment?",["It increases needle echogenicity","It switches the image to long axis","Moving the needle to the operator's left produces leftward movement on screen","It reduces depth so the vessel appears larger"],2,"Matching probe and screen orientation markers to the operator's side gives intuitive lateral alignment: directing the needle left moves it left on screen.");
BI(25,'vasc',2,'C25_F03',"Panel A shows the needle entering the skin 1 cm from a transverse probe over an IJV lying about 1 cm deep, for short-axis (out-of-plane) cannulation. What needle angle does this technique use?",["Shallow, about 10° to 20°","Perpendicular to the skin, 90°","Nearly parallel to the skin","Steep, about 45° to 60°"],3,"Short-axis IJV access uses a steep 45° to 60° needle angle (A). The needle tip is then seen as a target sign in the lumen (C), and the guidewire is confirmed in the IJV in short and long axis (B, D) before dilation.");
BI(25,'vasc',2,'C25_F04',"Panel C shows needle insertion into the IJV using the technique in panels A and B. What is the main advantage of this approach?",["The full needle shaft and tip are seen entering the vessel","Carotid artery and IJV are both always visible","It requires no probe manipulation","It eliminates the need to confirm the guidewire"],0,"In the long-axis (in-plane) technique, the needle is visualized along its length entering the IJV in long axis, so the tip position is clear throughout.");
BI(25,'vasc',2,'C25_F06',"For right IJV cannulation the probe is rotated from transverse into the position shown, and the needle (blue arrows) is advanced toward the IJV while the carotid lies deeper. What is the rationale for this oblique view?",["It allows out-of-plane needle visualization only","It shows the vein purely in long axis","It removes the carotid from the field","It permits in-plane needle visualization while keeping the IJV and carotid in near short-axis view"],3,"The oblique view allows in-plane needle visualization toward a nearly short-axis IJV with the nearby carotid in view. It combines benefits of both the short-axis and long-axis approaches.");
BI(25,'vasc',2,'C25_F08',"Short-axis guidance for femoral venous cannulation is shown (FA and CFV labeled, saphenofemoral junction marked). Which technique point is emphasized?",["Shallow needle angle and puncture distal to the saphenofemoral junction","Steep needle angle while avoiding the femoral artery and the saphenofemoral junction","In-plane approach through the femoral artery","Puncture at the inguinal ligament above the vessels"],1,"The figure shows an out-of-plane approach to the CFV with a steep needle angle, avoiding the adjacent femoral artery and the saphenofemoral junction.");
BI(25,'vasc',1,'C25_F12',"During ultrasound-guided peripheral IV placement, panel B shows the needle (N) as a bright structure within the vessel (PV) in cross-section. Which technique produces this view?",["Long-axis in-plane","Oblique in-plane","Doppler-guided blind insertion","Short-axis out-of-plane"],3,"Panels A and B show the out-of-plane (short-axis) technique, where the needle appears as an echogenic dot in the vessel lumen. Panels C and D show the in-plane technique with the needle seen along its length.");
BI(25,'vasc',1,'C25_F14',"Positioning for ultrasound-guided radial arterial line placement is shown. What is the purpose of the roll under the wrist and the system placement in panel C?",["Extend the wrist and allow a clear view of puncture site and screen with minimal head movement","Occlude the ulnar artery for an Allen test","Position the probe in long axis over the ulna","Increase venous filling for easier access"],0,"A roll under the extended wrist positions the radial artery, a linear high-frequency probe gives a transverse view, and the screen is placed so the operator sees both needle and image with minimal head movement.");
BI(25,'vasc',2,'C25_F16',"During out-of-plane radial artery cannulation at a steep (45° to 60°) angle, an echogenic dot (N) is seen above the artery. How should the operator ensure this dot is the needle tip?",["Increase gain until the shaft appears","Fan or slide the probe back toward the needle to find and track the tip","Switch to color Doppler","Advance the needle until a flash is seen without imaging"],1,"Out of plane, the echogenic dot may be the shaft rather than the tip. Fanning or sliding the probe back toward the needle identifies the true tip, which is then followed into the artery.");
BI(25,'vasc',2,'C25_F18',"Before femoral arterial cannulation, a transverse view of the FA and FV is obtained (A) and a survey scan is performed. What is the purpose of the survey scan shown?",["To locate the saphenofemoral junction for puncture","To measure arterial peak velocity","To define the artery's course toward the umbilicus so the needle follows the same path","To compress the femoral vein"],2,"The survey scan shows that the femoral artery runs toward the umbilicus. The needle is aimed along that same path so it stays aligned with the vessel during cannulation.");

// Image questions group 6
BI(26,'lung',2,'C26_F04',"This high-frequency linear-probe image is taken over an intercostal space. What does the bright horizontal line at mid-depth (short blue arrow), deep to the intercostal muscle, represent?",["The rib periosteum casting an acoustic shadow","The parietal and visceral pleurae seen as one line","A reverberation A-line from the skin surface","The deep fascia of the intercostal muscle"],1,"The chest wall layers are skin/subcutaneous tissue, then intercostal muscle and rib (periosteum with hypoechoic rib shadow, red arrows), then the pleural line. Without pleural fluid the parietal and visceral pleurae cannot be separated and appear as a single hyperechoic line.");
BI(26,'lung',2,'C26_F05',"Thoracic ultrasound in a febrile patient shows the effusion illustrated (arrow). Which conclusion is best supported by this appearance?",["The effusion is most likely a transudate from heart failure","It is a hemothorax with a hematocrit sign","The effusion is an exudate and may need more invasive drainage","It is a simple effusion ideal for a single diagnostic tap"],2,"Fibrin strands and septations dividing the fluid into loculations make this a complex septated effusion. Transudates are never complex septated, so it is an exudate; septations in a parapneumonic effusion/empyema may indicate the need for more invasive drainage or surgery.");
BI(26,'lung',2,'C26_F06',"After blunt chest trauma, this right-sided view shows an effusion whose dependent posterior portion is clearly more echogenic than the fluid above it. What does this pattern most suggest?",["Loculated empyema with fibrin septations","Chylothorax from thoracic duct injury","Transudative effusion from fluid resuscitation","Free-flowing dense layering material, most likely blood"],3,"This is the hematocrit sign: echogenicity of pleural fluid is greater in the dependent costophrenic region than superiorly, indicating free-flowing but dense layering material, commonly blood (hemothorax).");
BI(26,'lung',2,'C26_F07',"The calipers in this image measure the maximal separation between the parietal and visceral pleura at the lung base (2.92 cm). Using the Balik method, what is the estimated effusion volume?",["About 584 mL","About 292 mL","About 876 mL","About 1170 mL"],0,"Balik formula: V (mL) = 20 x Sep (mm). Sep = 29.2 mm, so V = 20 x 29.2 = 584 mL. This is the most feasible and reproducible US volume estimate and correlates with the drained volume.");
BI(26,'lung',1,'C26_F10',"During ultrasound-guided pleural catheter insertion with a linear probe, this image is obtained. What does the hyperechoic linear structure (arrows) within the anechoic collection confirm?",["The needle has punctured the diaphragm into the liver","The guidewire lies within the pleural effusion","A septation is tethering the atelectatic lung","Subcutaneous emphysema is tracking along the needle path"],1,"The guidewire appears as a bright linear structure within the anechoic effusion (A), with atelectatic lung floating beside it and the diaphragm (B) deeper. This confirms wire placement before dilation and catheter insertion.");
BI(27,'abd',2,'C27_F04',"This transverse airway view was found by sliding the probe cephalad from the cricoid cartilage until the cricoid disappeared, and the site was marked before intubation. In adults with poorly defined neck landmarks, how does external palpation compare with ultrasound for localizing this structure?",["Palpation and ultrasound are equally accurate","Palpation is more accurate because ultrasound cannot image cartilage","Palpation carries about a 9-fold higher risk of mislocalization","Ultrasound is accurate only in obese patients"],2,"Disappearance of the cricoid in the transverse plane marks the caudal cricothyroid membrane. Pre-marking it is lifesaving when oral intubation fails; in a randomized study of adults with abnormal neck anatomy, palpation had a 9-fold higher risk of inaccurate localization than ultrasound.");
BI(27,'abd',2,'C27_F05',"These transverse laryngeal images, taken through the thyroid cartilage, show the vocal ligaments and arytenoids during abduction and adduction. Which probe adjustment best improves assessment of vocal cord mobility in this plane?",["Rotate to a longitudinal view over the cricoid","Slide caudally to the first tracheal rings","Tilt the probe caudad","Tilt the probe cephalad"],3,"The vocal cords are best seen in the transverse plane using the thyroid cartilage as a window; the hyperechoic vocal ligaments delineate the cords, and adduction toward the midline is seen during phonation. Tilting the probe cephalad improves assessment of mobility.");
BI(27,'abd',2,'C27_F08',"This longitudinal submandibular/anterior neck view is part of a pre-intubation airway assessment. Inability to visualize the structure marked H on sublingual ultrasound predicts which outcome?",["Difficult laryngoscopy (Cormack-Lehane grade 3 or higher)","Postextubation stridor from laryngeal edema","Unrecognized esophageal intubation","Bilateral vocal cord paralysis"],0,"H is the hyoid bone, seen cephalad to the thyroid cartilage with the thyrohyoid membrane and pre-epiglottic space. Failure to visualize the hyoid on sublingual US predicted difficult intubation with sensitivity 70% and specificity 97%.");
BI(27,'abd',1,'C27_F09',"The structure marked E is seen posterolateral to the left thyroid lobe at the level of the first tracheal rings (transverse, left; longitudinal, right). How is its identity best confirmed at the bedside?",["Color Doppler showing pulsatile flow","Visible peristalsis when the patient swallows","Comet-tail artifacts from an air-mucosal interface","Collapse with inspiration on M-mode"],1,"E is the esophagus, lying posterior to the left thyroid lobe at T1-T2 level near the carotid artery. Peristaltic movement in its lumen during swallowing confirms it and is better seen in the longitudinal view.");
BI(27,'abd',2,'C27_F11',"Immediately after emergency intubation of a patient in cardiac arrest, the anterior neck is scanned (transverse left, longitudinal right). What do the paired hyperechoic lines (arrows) indicate?",["Calcified tracheal cartilage rings","Normal air-mucosal interface without a tube","Endotracheal tube within the trachea","Subglottic stenosis from prior intubation"],2,"The ETT within the trachea is seen as paired hyperechoic lines (the tube walls) inside the tracheal air column. Do not confuse this with the 'double tract' sign, a second air-mucosa interface posterolateral to the trachea, which indicates esophageal intubation. Ultrasound confirmation is valuable when capnography is unreliable, such as in cardiac arrest or low-flow states.");
BI(27,'abd',3,'C27_F12',"Before extubation, laryngeal air column width is measured at the vocal cords with the cuff inflated (b) and deflated (c). The column becomes wider and trapezoidal after deflation. What does this suggest?",["High risk of postextubation stridor; give steroids and delay","Esophageal displacement of the endotracheal tube","Bilateral vocal cord paralysis","Adequate air leak around the tube; low stridor risk"],3,"Cuff deflation lets air pass around the tube, widening the air column; this patient did not develop stridor. A small post-deflation air column width (difference of 1.6 mm or less in adults) is associated with postextubation stridor.");
BI(28,'abd',1,'C28_F04',"The skin marks show traditional landmark-based paracentesis sites (midline infraumbilical and bilateral lower quadrants). Which landmark site is generally preferred?",["Left lower quadrant, 3 cm superior and medial to the ASIS","Midline, 2 cm above the umbilicus","Right lower quadrant, directly over the ASIS","Left lateral flank at the mid-axillary line"],0,"Traditional sites are 2 cm below the umbilicus in the midline or 3 cm superior and medial to the ASIS in either lower quadrant, with the left lower quadrant preferred. Ultrasound refines this by locating the largest fluid pocket and avoiding vessels and bowel.");
BI(28,'abd',1,'C28_F05',"A patient with cirrhosis and abdominal distension has this right upper quadrant curvilinear view. What does the anechoic collection surrounding the liver represent?",["Right pleural effusion above the diaphragm","Peritoneal free fluid (ascites)","Subcapsular hepatic hematoma","Distended gallbladder"],1,"Anechoic fluid outlines the liver anteriorly and tracks toward the hepatorenal space, consistent with ascites. The RUQ, LUQ, and pelvis are interrogated to find the largest pocket for paracentesis.");
BI(28,'abd',1,'C28_F07',"This pelvic view is obtained while selecting a paracentesis site. What does it show?",["Distended urinary bladder with debris","Ovarian cyst with solid components","Large-volume ascites with floating bowel loops","Pelvic abscess with gas"],2,"Echogenic bowel loops float within a large anechoic peritoneal collection in the pelvis. Ultrasound identifies the fluid pocket and the proximity of bowel before needle insertion.");
BI(28,'abd',2,'C28_F08',"Before paracentesis, this lower abdominal view shows an anechoic oval structure with a thick wall, surrounded by free fluid. What is the appropriate action?",["Puncture directly into the largest anechoic area shown","Switch to the linear probe and puncture in-plane here","Abandon paracentesis because of loculation","Have the patient void or place a catheter, and avoid this structure"],3,"The central structure is the urinary bladder with ascites around it. The bladder must be avoided; patients should void or have a urinary catheter placed to decompress it before the procedure.");
BI(28,'abd',2,'C28_F10',"While scanning a planned left lower quadrant paracentesis site, color Doppler of the abdominal wall shows the findings displayed. What is the next step?",["Choose a different entry site away from these vessels","Proceed at this site using the Z-track technique","Increase the color gain to confirm venous flow","Use a larger-bore catheter to speed drainage"],0,"Color flow within the abdominal wall identifies the inferior epigastric vessels. Injury to them is the most ominous paracentesis complication, so the entry site should be moved to avoid them.");
BI(28,'abd',2,'C28_F13',"During dynamic paracentesis with the probe in transverse orientation, the needle appears only as the circled bright dot. What is the key technique to avoid losing the needle tip?",["Keep the probe fixed and advance the needle steeply","Advance the probe in tandem with the needle","Increase depth to show the whole abdomen","Switch to color Doppler to track the needle"],1,"In the transverse (out-of-plane) approach only the portion of needle crossing the beam is seen, so the bright dot may be the shaft rather than the tip. Advancing the probe along with the needle keeps the tip in view.");
BI(28,'abd',2,'C28_F15',"During ultrasound-guided paracentesis, the probe is held so that the needle lies in the long axis of the beam (circled). What is the main advantage of this approach?",["Easier to keep the needle within the narrow beam","Only the needle tip is visible, avoiding confusion","The entire needle course is visualized","It needs no sterile probe cover"],2,"The longitudinal (in-plane) approach shows the needle along its entire course, at the cost of difficulty keeping the needle within the thin imaging plane; the probe should be kept still throughout.");
BI(29,'peri',2,'C29_F02',"During ultrasound-guided pericardiocentesis (apical view), agitated saline is injected through the needle and panel b is seen. What does the echogenic cloud (arrow) confirm?",["The needle tip is inside the right ventricle","The needle has entered the left pleural space","Pericardial fluid is clotted blood","The needle tip lies within the pericardial space"],3,"Panel a shows a large circumferential effusion; in panel b, intrapericardial microbubbles from agitated saline verify correct needle position; in panel c, the RV re-expands with no residual effusion after drainage.");
BI(32,'lung',2,'C32_F08',"In an intubated 19-month-old with narrow rib spaces, the linear probe is rotated parallel to the ribs over the right chest. What does this image show?",["A-lines of normally aerated lung","Confluent B-lines","Lung point of a pneumothorax","Hepatized consolidated lung"],1,"Multiple vertical hyperechoic artifacts from the pleural line merge into confluent B-lines. Rotating the probe parallel to the ribs avoids rib shadowing in children's narrow intercostal spaces and improves pleural assessment.");
BI(32,'lung',2,'C32_F10',"In a child, the right chest was first scanned with a curvilinear probe showing lung and an effusion without detail. This linear-array image of the same area is then obtained. What does it reveal at (+)?",["Hepatized lung mimicking liver","Simple anechoic transudate","Complex effusion with septations","Subcutaneous emphysema"],2,"The higher-resolution linear probe shows the effusion is complex with septations, detail not resolved by the curvilinear probe. Transducer choice should match patient size and the area of interest.");
BI(33,'fluid',2,'C33_F01',"Subcostal transverse views of the IVC and aorta are shown in four children. In panel B, the IVC is markedly larger than the aorta. What does this suggest?",["Hypovolemia; give a fluid bolus","Normal volume status","Aortic coarctation","Hypervolemia; avoid further fluid"],3,"Panel A is normal; B shows an enlarged IVC relative to Ao (hypervolemia); C a flattened elliptical IVC and D a small IVC (hypovolemia). The IVC:Ao ratio helps guide fluid decisions in children.");
BI(33,'rv',2,'C33_F02',"Panel B is a parasternal short-axis view in a child with hypoxemia. The RV is markedly dilated and the septum bows into the LV. What is the most likely underlying problem?",["Severe pulmonary hypertension","Hypovolemic shock","Cardiac tamponade","Dilated LV cardiomyopathy"],0,"Septal bowing into the LV with a dilated RV indicates RV pressure overload from severe pulmonary hypertension. Panel A shows a flattened septum, dilated RV, and small pericardial effusion in sepsis-related RV failure with fluid overload.");
BI(33,'rv',3,'C33_F03',"Apical 4-chamber views in a child with pediatric ARDS: panel A before and panel B after treatment. RV and RA dilation have improved. Which treatment was started between A and B?",["Aggressive fluid loading","Inhaled nitric oxide with inotropic support","Pericardiocentesis","Increased PEEP alone"],1,"Panel A shows RV and RA dilation with reduced RV systolic function from pulmonary hypertension. After inhaled nitric oxide and inotropic support, RV and RA dilation improved (panel B).");

// Image questions group 7
BI(34,'hemo',2,'C34_F01',"Panel A shows a caliper measurement in a parasternal long-axis view and panel B a pulsed-wave Doppler trace from an apical 5-chamber view. Combining these two measurements allows calculation of which parameter?",["Stroke volume (LVOT cross-sectional area x VTI)","Aortic valve area by the continuity equation","Peak aortic valve pressure gradient","Left ventricular ejection fraction"],0,"Panel A measures the aortic/LVOT diameter (to derive cross-sectional area) and panel B the aortic velocity-time integral by PW Doppler. Area x VTI gives stroke volume, from which left ventricular output is derived.");
BI(34,'rv',1,'C34_F02',"An M-mode cursor is placed through the lateral tricuspid annulus in an apical 4-chamber view and the systolic excursion is measured (arrow). What does this measurement assess?",["Right ventricular diastolic filling","Right ventricular longitudinal systolic function","Pulmonary artery systolic pressure","Right atrial pressure"],1,"This is TAPSE: M-mode at the lateral tricuspid annulus in the apical 4-chamber view measuring systolic annular excursion, a marker of RV longitudinal systolic function.");
BI(34,'rv',2,'C34_F03',"A continuous-wave Doppler trace of the tricuspid regurgitant jet is shown (peak velocity 4.74 m/s, gradient 90 mm Hg). Assuming right atrial pressure of 5 mm Hg and no pulmonary stenosis, what is the estimated RV systolic pressure?",["About 50 mm Hg","About 70 mm Hg","About 95 mm Hg","About 120 mm Hg"],2,"RVSP = RAP + 4V^2 = 5 + 4 x (4.74)^2 = 5 + 90 = about 95 mm Hg. Without RVOT obstruction this approximates pulmonary artery systolic pressure, indicating marked pulmonary hypertension.");
BI(34,'rv',1,'C34_F04',"A parasternal short-axis view in a neonate shows the interventricular septum flattened so the LV appears D-shaped (arrow). What is the most likely underlying cause?",["Severe left ventricular systolic dysfunction","Hypovolemia with small LV cavity","Large left-to-right ductal shunt with LV volume overload","Elevated pulmonary artery pressure with RV pressure overload"],3,"Septal flattening (D-shaped LV) on PSAX is a semiquantitative sign of pulmonary hypertension, reflecting elevated RV pressure pushing the septum toward the LV.");
BI(34,'lv',1,'C34_F05',"The M-mode cursor shown was positioned through the LV at the papillary-muscle level to obtain end-diastolic and end-systolic dimensions. From which view was it acquired?",["Parasternal short-axis view","Apical 4-chamber view","Subcostal 4-chamber view","Suprasternal long-axis view"],0,"The inset shows a circular LV cross-section, i.e. the parasternal short-axis view; M-mode through it gives LVIDd and LVIDs to calculate fractional shortening, which can also be obtained from PLAX.");
BI(34,'mass',2,'C34_F06',"A preterm infant is being assessed for a ductal shunt. Which echocardiographic window produced these 2D and color Doppler images showing the main pulmonary artery, right pulmonary artery and an adjacent vessel?",["Apical 5-chamber view","High parasternal (ductal) view","Subcostal short-axis view","Parasternal long-axis view"],1,"The figure is a high parasternal view of the ductus arteriosus, displaying the MPA, its branch (RPA) and the PDA alongside it, with color Doppler showing ductal flow.");
BI(34,'mass',2,'C34_F07',"Pulsed-wave Doppler is sampled in the main pulmonary artery of a preterm neonate. In addition to normal systolic forward flow, turbulent flow is seen during diastole (red arrows). What does this finding indicate?",["Pulmonary valve stenosis","Pulmonary regurgitation from pulmonary hypertension","Patent ductus arteriosus","Normal transitional circulation"],2,"Diastolic turbulent flow in the pulmonary artery reflects continuous ductal flow entering the PA, consistent with a patent ductus arteriosus.");
BI(34,'mass',3,'C34_F09',"Mitral inflow PW Doppler in a preterm neonate with a large ductal shunt shows E > A. Why is this finding concerning rather than reassuring?",["It indicates restrictive LV filling from myocarditis","It reflects severe mitral stenosis","It shows the ductus is closing","Increased pulmonary venous return pseudonormalizes the usual preterm E/A < 1"],3,"Preterm LV filling normally depends on atrial kick (E/A < 1). With a large left-to-right PDA, increased pulmonary venous return raises LA filling and pseudonormalizes E/A to > 1, a marker of shunt significance.");
BI(34,'mass',2,'C34_F10',"Pulsed-wave Doppler of the descending aorta is shown in two neonates (A and B). Panel B shows retrograde flow throughout diastole. What does this indicate?",["Hemodynamically significant PDA with ductal steal","Severe aortic stenosis","Coarctation of the aorta","Normal finding in preterm infants"],0,"Panel A shows normal forward descending aortic flow; panel B shows holodiastolic flow reversal, caused by blood being stolen into a hemodynamically significant left-to-right PDA.");
BI(35,'lung',2,'C35_F01',"A term neonate born by cesarean section develops tachypnea shortly after birth. Lateral lung ultrasound shows an abrupt transition between an upper field with sparse B lines and a lower field with compact B lines. What is the most likely diagnosis?",["Respiratory distress syndrome","Transient tachypnea of the newborn","Pneumothorax","Meconium aspiration syndrome"],1,"The sharp boundary between noncompact B lines superiorly and compact B lines inferiorly is the 'double lung point', characteristic of transient tachypnea of the newborn.");
BI(35,'lung',2,'C35_F02',"A term neonate with respiratory distress has this lateral left lung image. Which finding is most prominent?",["Normal A-line pattern with lung sliding","Pleural effusion with floating lung","Large irregular subpleural consolidation with compact B lines","Double lung point"],2,"The image shows a large irregular subpleural consolidation with surrounding compact B lines, as described in meconium aspiration syndrome.");
BI(35,'lung',2,'C35_F03',"A preterm neonate has grunting and retractions. Lateral lung ultrasound shows this pattern throughout all scanned areas. What is the most likely diagnosis?",["Transient tachypnea of the newborn","Pneumothorax","Normal neonatal lung","Respiratory distress syndrome"],3,"Confluent B lines with no spared areas ('white lung') are indicative of respiratory distress syndrome.");
BI(35,'lung',2,'C35_F04',"A young infant with a viral prodrome, cough and increased work of breathing has this lung ultrasound. Which pattern is shown, supporting the clinical diagnosis of bronchiolitis?",["Pleural line abnormalities with compact B lines","Lung point with absent sliding","Anechoic pleural effusion with spine sign","Normal A-lines with lung sliding"],0,"Bronchiolitis findings include an irregular, abnormal pleural line with compact B lines and possible subpleural consolidations; severity of findings correlates with clinical severity.");
BI(35,'dia',1,'C35_F06',"The caliper measurement shown (0.25 cm) is made between two parallel hyperechoic layers in the midaxillary line at the ninth to tenth intercostal space during end-expiration. What is being measured?",["Pleural effusion depth","Diaphragm thickness at the zone of apposition","Intercostal muscle thickness","Diaphragm excursion"],1,"The diaphragm muscle at the zone of apposition appears as a hypoechoic layer between the bright pleural and peritoneal lines; measuring inner to outer border at end-expiration gives resting diaphragm thickness.");
BI(35,'dia',3,'C35_F07',"M-mode at the zone of apposition shows diaphragm thickness of 0.34 cm at maximal inspiration and 0.27 cm at end-expiration. What is the diaphragm thickening fraction?",["About 12%","About 21%","About 26%","About 79%"],2,"Thickening fraction = (Tdi-insp - Tdi-exp)/Tdi-exp = (0.34 - 0.27)/0.27 = about 26%. It is a marker of diaphragm contractility but is effort-dependent.");
BI(35,'dia',1,'C35_F08',"M-mode with a phased array probe in the midclavicular line below the right costal margin shows a positive deflection of 2.2 cm during inspiration. What is being measured?",["Diaphragm thickening fraction","Liver span","IVC collapsibility","Diaphragm excursion"],3,"During inspiration the diaphragm moves toward the probe, producing a positive M-mode deflection; its amplitude is the diaphragmatic excursion.");
BI(36,'abd',2,'C36_F04',"A preterm neonate with feeding intolerance and abdominal distension has this abdominal ultrasound. What is shown (arrows)?",["Dilated fluid-filled bowel loops with abnormally echogenic walls","Normal collapsed bowel with peristalsis","Intussusception with target sign","Free intraperitoneal gas"],0,"Fluid distends the bowel loops and the walls are more echogenic than normal, findings seen in necrotizing enterocolitis.");
BI(36,'abd',2,'C36_F05',"In a neonate with suspected NEC, the bowel wall between the calipers in panel A is measured. Above what thickness is the bowel wall concerning for NEC?",["1.0 mm","2.5 mm","4.0 mm","6.0 mm"],1,"Panel A shows a homogeneously thickened bowel wall, panel B a layered thickened wall. Bowel wall thickness > 2.5 mm is concerning for NEC.");
BI(36,'abd',3,'C36_F06',"A neonate with known NEC shows a bowel loop with heterogeneous contents, surrounding free fluid, and a focal area of wall thinning (arrow). How should the thin segment be interpreted?",["Reassuring sign of resolving edema","Normal peristaltic variation","May indicate bowel necrosis, a late stage of NEC","Artifact from bowel gas"],2,"Bowel wall thinning (< 1 mm) is not reassuring in NEC because it can indicate necrosis; together with free fluid it suggests advanced disease.");
BI(36,'abd',2,'C36_F07',"A preterm neonate with bloody stools has multiple bowel loops containing hyperechoic granular foci within the wall with posterior reverberation artifacts. What do these represent?",["Meconium calcifications","Intraluminal feeds","Free intraperitoneal fluid","Intramural gas (pneumatosis intestinalis)"],3,"Hyperechoic granular foci in the bowel wall with reverberation artifacts are intramural gas, a hallmark of NEC; panel C contrasts intraluminal gas surrounded by thickened wall.");
BI(36,'abd',2,'C36_F08',"In a neonate with NEC, liver ultrasound (panel B) shows multiple linear, branching and punctate echogenic foci within the parenchyma. What is the finding?",["Portal venous gas","Hepatic calcifications from congenital infection","Biliary sludge","Hepatic abscesses"],0,"Panel B shows extensive portal venous gas as echogenic foci in the portal branches; ultrasound can detect it when the radiograph (panel A) shows only a small bubble.");
BI(36,'abd',3,'C36_F10',"A neonate with NEC deteriorates. Ultrasound between the abdominal wall (A) and liver (L) shows fluid containing echogenic debris. What does this suggest?",["Simple transudative ascites","Bowel perforation","Normal physiologic fluid","Subcapsular liver hematoma"],1,"Echogenic free intraperitoneal fluid with debris in a neonate with NEC is suggestive of bowel perforation.");
BI(36,'abd',2,'C36_F11',"In a neonate with NEC, small echogenic foci are seen in the peritoneal space anterior to bowel near the abdominal wall (arrow). What is the most likely finding?",["Intramural gas","Portal venous gas","Free intraperitoneal gas","Calcified meconium"],2,"Free intraperitoneal gas appears as echogenic foci outside the bowel wall, indicating perforation.");
BI(36,'abd',3,'C36_F12',"Color Doppler of thickened bowel loops in a neonate with NEC shows a Y-shaped flow pattern (A) and circumferential ring flow (B). What do these patterns suggest?",["Transmural necrosis","Volvulus","Normal neonatal bowel perfusion","Hyperemic but still viable bowel"],3,"Y and ring hyperemic patterns are not seen in normal neonates; in NEC (Bell stages I-II) they reflect mural vasodilatation and indicate viable bowel.");
BI(36,'abd',3,'C36_F13',"Color Doppler in a neonate with NEC shows two outer bowel loops with hyperemic flow and a central loop with little or no flow, focal wall thinning and intramural gas. What is most likely?",["Necrosis of the central loop","Reactive hyperemia of all three loops","Intussusception","Normal bowel with gas artifact"],0,"Absent flow plus wall thinning and pneumatosis is highly suggestive of necrosis; absent Doppler flow was 100% sensitive for transmural necrosis, and necrotic bowel was confirmed at surgery.");
BI(36,'abd',3,'C36_F14',"Gray-scale (A) and color Doppler (B) of small bowel in a neonate with NEC show a hyperechoic herringbone appearance with hyperemic flow. What does this pattern represent?",["Intramural gas","Thickened valvulae with hyperemia (zebra pattern)","Portal venous gas","Normal neonatal bowel"],1,"Thickened, hyperechoic valvulae produce a gray-scale zebra pattern, and color Doppler shows hyperemic flow in the valvulae; this pattern was not seen in neonates without NEC.");
BI(37,'vasc',1,'C37_F01',"These photos show the technique for ocular ultrasound with a high-frequency linear probe on the closed eyelid. What is the purpose of resting the operator's hand on the face or a towel?",["To allow firm compression for better image quality","To align the probe with the optic nerve at 45 degrees","To stabilize the probe and avoid pressure on the globe","To keep the gel from spreading to the conjunctiva"],2,"The probe is held like a pen with the hand stabilized beside the face so that no pressure is applied to the eye; panels A-C show sagittal, transverse and infant coronal positions.");
BI(37,'vasc',2,'C37_F02',"Ocular ultrasound images are shown. In panel D, line 1 is 3 mm long and line 2 measures 4.3 mm. What does line 2 represent?",["Optic nerve diameter alone","Lens thickness","Retinal thickness","Optic nerve sheath diameter measured 3 mm behind the globe"],3,"ONSD is measured 3 mm posterior to the globe, perpendicular across the optic nerve and sheath (bullseye appearance confirms correct transection); ONSD enlarges with raised intracranial pressure.");
BI(37,'vasc',2,'C37_F03',"In a sedated patient with periorbital swelling, coronal ocular ultrasound shows the pupil measuring 0.37 cm (B) and then 0.15 cm (C). What is being assessed?",["Pupillary light reflex","Optic nerve sheath diameter","Lens dislocation","Anterior chamber depth"],0,"Ultrasound can test the pupillary light reflex when the pupils cannot be directly visualized; the pupil constricts from 0.37 to 0.15 cm with light.");
BI(37,'vasc',2,'C37_F05',"Ocular ultrasound images are shown. In panel B, a taut, bright linear opacity is seen in the posterior globe, tethered to the optic disc (yellow arrows). What is the most likely diagnosis?",["Vitreous detachment","Retinal detachment","Vitreous hemorrhage","Papilledema"],1,"Retinal detachment appears as a taut bright line tethered to the optic disc; vitreous hemorrhage shows wavy strands (C) and vitreous detachment a mobile 'swaying seaweed' membrane not tethered to the disc (D).");
BI(37,'vasc',3,'C37_F06',"An infant presents with lethargy and suspected abusive head trauma. Ultrasound views (B-D) correlate with the fundus photo (A). What do these findings show?",["Papilledema from raised intracranial pressure","Normal infant retina","Retinal hemorrhages with macular retinoschisis","Congenital cataract"],2,"The images show layering retinal hemorrhages over the posterior pole and a macular retinoschisis cavity, ocular manifestations associated with abusive head trauma.");
BI(37,'vasc',3,'C37_F07',"Ocular ultrasound in a child with altered mental status shows the optic nerve sheath bulging into the posterior pole of the globe (arrow). What is this finding most consistent with?",["Retinal hemorrhage from abusive head trauma","Retinal detachment","Normal optic disc","Raised intracranial pressure"],3,"Elevated ICP expands the optic nerve sheath, which can herniate into the back of the eye (papilledema); this should not be mistaken for retinal pathology of abusive head trauma.");
BI(38,'mass',2,'C38_F01',"A neonate has a peripherally inserted central catheter placed via a lower-extremity vein. This long-axis IVC view shows the catheter. Where is the tip located?",["At the IVC-right atrial junction","In the superior vena cava","In the hepatic veins","In the portal vein"],0,"For lower-extremity PICCs the tip is visualized in the longitudinal IVC view; here the catheter is seen at the IVC-atrial junction. Upper-extremity PICCs are checked in the SVC via a high parasternal view.");
BI(38,'mass',2,'C38_F03',"This longitudinal IVC view is used to check an umbilical venous catheter in a neonate. If the catheter were advanced so its tip lay well within the right atrium, which complication would be of greatest concern?",["Hepatic necrosis","Pericardial effusion, tamponade or arrhythmia","Ascites from hepatic laceration","Portal vein thrombosis"],1,"The UVC should terminate in the ductus venosus at its junction with the RA/IVC. Too low risks hepatic necrosis, ascites and laceration; too high in the RA risks pericardial effusion, tamponade and arrhythmias.");
BI(38,'mass',3,'C38_F05',"While confirming a high umbilical arterial catheter, the operator fans from the IVC to this view showing the vessels arising from the abdominal aorta. Where should the tip of a high UAC be?",["At the iliac bifurcation","Between the renal arteries and the bifurcation","In the descending thoracic aorta just above the diaphragm (T6–T9)","At the origin of the superior mesenteric artery"],2,"Visualizing the celiac trunk and SMA confirms the vessel is the aorta. A high line should sit in the descending thoracic aorta at T6–T9, above the celiac, mesenteric and renal artery origins; a low line sits at L3–L4, below the renal arteries and inferior mesenteric artery and above the iliac bifurcation.");
BI(38,'vasc',2,'C38_F07',"Before paracentesis, a linear probe placed in the lower abdomen shows a small pulsatile vessel flanked by two veins in the abdominal wall above the ascites. Why is this structure identified?",["To select the largest fluid pocket","To confirm the fluid is not in the bladder","To guide catheter insertion by Seldinger technique","To avoid puncturing the inferior epigastric artery"],3,"The inferior epigastric artery (pulsatile, flanked by two veins, confirmed with color Doppler) runs about 4–6 cm lateral to the midline, deep to the lateral part of the rectus abdominis; locating it avoids vascular injury.");
BI(38,'abd',2,'C38_F08',"This transverse suprasternal image with a linear probe shows the trachea, esophagus and carotid artery. How is this view used in airway management?",["To watch the trachea and esophagus and confirm ETT placement during insertion","To estimate ETT depth relative to the carina","To measure vocal cord paralysis after extubation","To detect right mainstem intubation"],0,"The transverse suprasternal-tracheal view allows real-time observation of the trachea and esophagus during ETT insertion; a second air-mucosa interface beside the trachea (double tract sign) indicates esophageal intubation — to confirm tracheal rather than esophageal placement.");
BI(38,'abd',2,'C38_F09',"An indirect ultrasound assessment after intubation uses a transverse subxiphoid view to look at diaphragm motion. Which finding during positive pressure ventilation suggests esophageal intubation?",["Bilateral symmetric caudal diaphragm excursion","Absent diaphragm excursion or paradoxical cephalad movement","Unilateral right-sided excursion only","Increased diaphragm thickness"],1,"Bilateral diaphragm excursion supports tracheal placement; absent movement or reverse movement toward the chest with ventilation suggests esophageal intubation, though these signs are not specific.");
BI(39,'abd',1,'C39_F02',"Before urgent sedation, a sagittal epigastric scan shows the antrum as a flattened oval with a target appearance, deep to the liver and superficial to the SMA and IVC. How should this be interpreted?",["Liquid-filled stomach","Solid gastric contents","Empty stomach","Gastric outlet obstruction"],2,"A flat, target-shaped antrum without distension indicates an empty stomach; landmarks are the left liver lobe anteriorly and the SMA and IVC posteriorly.");
BI(39,'abd',2,'C39_F03',"Before sedation, gastric ultrasound shows a heterogeneous echogenic mass within the antrum with acoustic shadowing obscuring the posterior wall. What does this indicate?",["Empty antrum","Clear fluid only","Gastric wall thickening","Solid gastric contents"],3,"Solid contents appear heterogeneous and cause acoustic shadowing behind them, so the posterior antral wall looks less echogenic than usual; this indicates a full stomach.");
BI(39,'abd',2,'C39_F04',"Gastric ultrasound shows a distended antrum with a strongly hypoechoic central cavity and increased echogenicity of structures behind it. What does this indicate?",["Liquid contents with posterior acoustic enhancement","Solid contents with acoustic shadowing","Empty antrum","Air-filled antrum with reverberation"],0,"A liquid-filled antrum is distended, hypoechoic centrally and produces posterior enhancement; gastric content can be graded and quantified by antral cross-sectional area.");
BI(39,'abd',2,'C39_F05',"A sagittal spinal ultrasound in an infant shows a hypoechoic tubular cord surrounded by CSF that tapers caudally into fibrillar strands. What does the tapering caudal end of the cord represent?",["Filum terminale cyst","Conus medullaris","Dural sac termination","Sacral hiatus"],1,"The cord is hypoechoic with hyperechoic pia; its tapering caudal end is the conus medullaris, continuing as the cauda equina. Spinous processes lie dorsal and vertebral bodies ventral.");
BI(39,'abd',2,'C39_F06',"A caudal block is performed under ultrasound in an infant. The needle passes between the posterior and anterior sacrum into the caudal epidural space. Which structure must the needle pierce to reach this space?",["Ligamentum flavum","Supraspinous ligament","Sacrococcygeal ligament","Dura mater"],2,"The sacrococcygeal ligament covers the sacral hiatus, the needle insertion site; the epidural space lies just beneath it.");
BI(39,'abd',2,'C39_F07',"A probe is placed sagittally below the lateral clavicle near the coracoid. Deep to pectoralis major and minor, the axillary artery is seen with cords cephalad and caudad to it. Which block is this?",["Interscalene block","Supraclavicular block","Axillary block","Infraclavicular block"],3,"The infraclavicular block uses a sagittal view below the lateral clavicle; the axillary artery lies deep to pectoralis minor with lateral (superior) and medial (inferior) cords around it.");
BI(39,'abd',2,'C39_F08',"For this lower-limb block, the probe is placed transversely just below the inguinal crease. Where should the needle tip be placed?",["Deep to the fascia iliaca, lateral to the femoral artery","Superficial to the fascia lata, medial to the femoral vein","Within the femoral artery sheath","Deep to the iliacus muscle near the femoral head"],0,"The femoral nerve is a crescent-shaped hyperechoic structure lateral to the femoral artery and beneath the fascia iliaca; local anesthetic is deposited there.");
BI(39,'abd',2,'C39_F09',"A transverse scan at the gluteal crease shows the sciatic nerve deep to gluteus maximus between two bony prominences. Which surface landmarks locate the nerve for this block?",["Ischial tuberosity and anterior superior iliac spine","Midpoint between greater trochanter and ischial tuberosity","Posterior superior iliac spine and coccyx","Popliteal crease and fibular head"],1,"For the subgluteal sciatic block, the nerve lies near the midpoint of a line from the greater trochanter to the ischial tuberosity, deep to gluteus maximus and usually closer to the ischial tuberosity.");
BI(39,'abd',3,'C39_F10',"A transverse scan of the posterior thigh at the popliteal fossa shows the sciatic nerve superficial to the popliteal artery. At what level should injection be made to block both its branches?",["At the popliteal crease over the tibial nerve only","Distal to the fibular head","At the confluence of the tibial and common peroneal nerves","At the gluteal crease"],2,"The probe is moved cephalad until the common peroneal nerve joins the tibial nerve to form the sciatic nerve; injecting at this confluence blocks both branches.");
BI(39,'abd',2,'C39_F11',"A transverse view lateral to the midline shows the rectus abdominis, transversalis fascia and parietal peritoneum above bowel. Where is the target for the needle tip in this block?",["Superficial to the anterior rectus sheath","Within the peritoneal cavity","Between internal oblique and transversus abdominis","Deep to rectus abdominis, superficial to the posterior rectus sheath"],3,"In the rectus sheath block the terminal thoracolumbar nerves are too small to see; local anesthetic is placed in the plane deep to the rectus abdominis but superficial to the posterior rectus sheath.");


